INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-007-209-01', '資治通鑑', 7, 209, '二世皇帝元年', '壬辰', 1, 'narrative', 'heading', '[10]'::jsonb, '冬，十月，戊寅，大赦。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-007-209-02', '資治通鑑', 7, 209, '二世皇帝元年', '壬辰', 2, 'narrative', 'heading', '[4]'::jsonb, '春，二世東行郡縣，李斯從；到碣石，並海，南至會稽；而盡刻始皇所立刻石，旁著大臣從者名，以章先帝成功盛德而還。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-02', 'wu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-02', 'xianyang', 4);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-007-209-03', '資治通鑑', 7, 209, '二世皇帝元年', '壬辰', 3, 'narrative', 'heading', '[7, 8, 9]'::jsonb, '秋，七月，陽城人陳勝、陽夏人吳廣起兵於蘄。是時，發閭左戍漁陽，九百人屯大澤鄉，陳勝、吳廣皆為屯長。會天大雨，道不通，度已失期。失期，法皆斬。陳勝、吳廣因天下之愁怨，乃殺將尉，召令徒屬曰；「公等皆失期當斬，假令毋斬，而戍死者固什六七。且壯士不死則已，死則舉大名耳！王侯將相寧有種乎！」眾皆從之。乃詐稱公子扶蘇、項燕，為壇而盟，稱大楚；陳勝自立為將軍，吳廣為都尉。攻大澤鄉，拔之。收而攻蘄，蘄下。乃令符離人葛嬰將兵徇蘄以東，攻銍、酇、苦、柘、譙，皆下之。行收兵，比至陳，車六七百乘，騎千餘，卒數萬人。攻陳，陳守、尉皆不在，獨守丞與戰譙門中，不勝；守丞死，陳勝乃入據陳。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'qi', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'yuyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'dazexiang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'chen', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'handan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'pei', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-03', 'wu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-007-209-04', '資治通鑑', 7, 209, '二世皇帝元年', '壬辰', 4, 'narrative', 'heading', '[]'::jsonb, '周市自狄還，至魏地，欲立故魏公子寧陵君咎為王。咎在陳，不得之魏。魏地已定，諸侯皆欲立周市為魏王。市曰：「天下昏亂，忠臣乃見。今天下共畔秦，其義必立魏王后乃可。」諸侯固請立市，市終辭不受；迎魏咎於陳，五反，陳王乃遣之，立咎為魏王，市為魏相。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-007-209-04', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-007-209-05', '資治通鑑', 7, 209, '二世皇帝元年', '壬辰', 5, 'narrative', 'heading', '[]'::jsonb, '是歲，二世廢衛君角為庶人，衛絕祀。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-01', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 1, 'narrative', 'heading', '[10, 11]'::jsonb, '冬，十月，泗川監平將兵圍沛公於豐，沛公出與戰，破之，令雍齒守豐。十一月，沛公引兵之薛。泗川守壯兵敗於薛，走至戚，沛公左司馬得殺之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-01', 'feng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-01', 'xue', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-02', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 2, 'narrative', 'heading', '[2]'::jsonb, '周章出關，止屯曹陽，二月餘，章邯追敗之。復走澠池，十餘日，章邯擊，大破之。周文自刎，軍遂不戰。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-02', 'xingyang', 6);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-02', 'aocang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-02', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-03', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 3, 'narrative', 'heading', '[]'::jsonb, '二世數誚讓李斯：「居三公位，如何令盜如此！」李斯恐懼，重爵祿，不知所出，乃阿二世意，以書對曰：「夫賢主者，必能行督責之術者也。故申子曰『有天下而不恣睢，命之曰以天下為桎梏』者，無他焉，不能督責，而顧以其身勞於天下之民，若堯、禹然，故謂之桎梏也。夫不能修申、韓之明術，行督責之道，專以天下自適也；而徒務苦形勞神，以身徇百姓，則是黔首之役，非畜天下者也，何足貴哉！故明主能行督責之術以獨斷於上，則權不在臣下，然後能滅仁義之塗，絕諫說之辯，犖然行恣睢之心，而莫之敢逆。如此，群臣、百姓救過不給，何變之敢圖！」二世說，於是行督責益嚴，稅民深者為明吏，殺人眾者為忠臣，刑者相半於道，而死人日成積於市，秦民益駭懼思亂。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-04', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 4, 'narrative', 'heading', '[]'::jsonb, '趙李良已定常山，還報趙王。趙王復使良略太原。至石邑，秦兵塞井陘，未能前。秦將詐為二世書以招良。良得書未信，還之邯鄲，益請兵。未至，道逢趙王姊出飲，從百餘騎，良望見，以為王，伏謁道旁。王姊醉，不知其將，使騎謝李良。李良素貴，起，慚其從官。從官有一人曰：「天下畔秦，能者先立。且趙王素出將軍下，今女兒乃不為將軍下車，請追殺之！」李良已得秦書，固欲反趙，未決，因此怒，遣人追殺王姊，因將其兵襲邯鄲。邯鄲不知，竟殺趙王、邵騷。趙人多為張耳、陳餘耳目者，以故二人獨得脫。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-04', 'jingxing', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-04', 'handan', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-05', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 5, 'narrative', 'heading', '[]'::jsonb, '陳人秦嘉、符離人朱雞石等起兵，圍東海守於郯。陳王聞之，使武平君畔為將軍，監郯下軍。秦嘉不受命，自立為大司馬，惡屬武平君，告軍吏曰：「武平君年少，不知兵事，勿聽！」因矯以王命殺武平君畔。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-06', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 6, 'narrative', 'heading', '[]'::jsonb, '二世益遣長史司馬欣、董翳佐章邯擊盜。章邯已破伍逢，擊陳柱國房君，殺之。又進擊陳西張賀軍。陳王出監戰。張賀死。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-06', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-07', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 7, 'narrative', 'heading', '[]'::jsonb, '臘月，陳王之汝陰，還，至下城父，其御莊賈殺陳王以降。初，陳涉既為王，其故人皆往依之。妻之父亦往焉，陳王以眾賓待之，長揖不拜。妻之父怒曰：「怙亂僭號，而傲長者，不能久矣！」不辭而去。陳王跪謝，遂不為顧。客出入愈益發舒，言陳王故情。或說陳王曰：「客愚無知，顓妄言，輕威。」陳王斬之。諸故人皆自引去，由是無親陳王者。陳王以朱防為中正，胡武為司過，主司群臣。諸將徇地至，令之不是，輒系而罪之。以苛察為忠，其所不善者，弗下吏，輒自治之。諸將以其故不親附，此其所以敗也。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-07', 'chen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-07', 'dang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-07', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-08', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 8, 'narrative', 'heading', '[]'::jsonb, '魏周市將兵略地豐、沛，使人招雍齒。雍齒雅不欲屬沛公，即以豐降魏。沛公攻之，不克。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-09', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 9, 'narrative', 'heading', '[1]'::jsonb, '趙張耳、陳餘收其散兵，得數萬人，擊李良。良敗，走歸章邯。
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-10', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 10, 'narrative', 'heading', '[]'::jsonb, '東陽寧君、秦嘉聞陳王軍敗，乃立景駒為楚王，引兵之方與，欲擊秦軍定陶下；使公孫慶使齊，欲與之並力俱進。齊王曰：「陳王戰敗，不知其死生，楚安得不請而立王！」公孫慶曰：「齊不請楚而立王，楚何故請齊而立王！且楚首事，當令於天下。」田儋殺公孫慶。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-10', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-11', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 11, 'narrative', 'heading', '[]'::jsonb, '秦左、右校復攻陳，下之。呂將軍走，徼兵復聚，與番盜黥布相遇，攻擊秦左、右校，破之青波，復以陳為楚。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-11', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-12', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 12, 'narrative', 'heading', '[2, 3]'::jsonb, '楚王景駒在留，沛公往從之。張良亦聚少年百餘人，欲往從景駒，道遇沛公，遂屬焉。沛公拜良為廄將。良數以太公兵法說沛公，沛公善之，常用其策。良為他人言，皆不省。良曰：「沛公殆天授！」故遂從不去。沛公與良俱見景駒，欲請兵以攻豐。時章邯司馬屍二將兵北定楚地，屠相，至碭。東陽寧君、沛公引兵西，戰蕭西，不利，還，收兵聚留。二月，攻碭，三日，拔之。收碭兵得六千人，與故合九千人。三月，攻下邑，拔之。還擊豐，不下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-12', 'feng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-12', 'dang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-12', 'xiayi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-13', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 13, 'narrative', 'heading', '[]'::jsonb, '廣陵人召平為陳王徇廣陵，未下。聞陳王敗走，章邯且至，乃渡江，矯陳王令，拜項梁為楚上柱國，曰：「江東已定，急引兵西擊秦！」梁乃以八千人渡江而西。聞陳嬰已下東陽，使使欲與連和俱西。陳嬰者，故東陽令史，居縣中，素信謹，稱為長者。東陽少年殺其令，相聚得二萬人，欲立嬰為王。嬰母謂嬰曰：「自我為汝家婦，未嘗聞汝先世之有貴者。今暴得大名，不祥；不如有所屬。事成，猶得封侯；事敗，易以亡，非世所指名也。」嬰乃不敢為王，謂其軍吏曰：「項氏世世將家，有名於楚，今欲舉大事，將非其人不可。我倚名族，亡秦必矣！」其眾從之，乃以兵屬梁。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-14', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 14, 'narrative', 'heading', '[6]'::jsonb, '英布既破秦軍，引兵而東；聞項梁西渡淮，布與蒲將軍皆以其兵屬焉。項梁眾凡六七萬人，軍下邳。景駒、秦嘉軍彭城東，欲以距梁。梁謂軍吏曰：「陳王先首事，戰不利，未聞所在。今秦嘉倍陳王而立景駒，逆無道！」乃進兵擊秦嘉，秦嘉軍敗走。追之，至胡陵，嘉還戰。一日，嘉死，軍降；景駒走死梁地。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-14', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-14', 'xue', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-14', 'feng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-15', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 15, 'narrative', 'heading', '[7, 8]'::jsonb, '章邯已破陳王，乃進兵擊魏王於臨濟。魏王使周市出，請救於齊、楚。齊王儋及楚將項它皆將兵隨市救魏。章邯夜銜枚擊，大破齊、楚軍於臨濟下，殺齊王及周市。魏王咎為其民約降，約定，自燒殺。其弟豹亡走楚，楚懷王予魏豹數千人，復徇魏地。齊田榮收其兄儋餘兵，東走東阿，章邯追圍之。齊人聞齊王儋死，乃立故齊王建之弟假為王，田角為相，角弟間為將，以距諸侯。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-15', 'donge', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-15', 'puyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-15', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-16', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 16, 'narrative', 'heading', '[]'::jsonb, '郎中令趙高恃恩專恣，以私怨誅殺人眾多，恐大臣入朝奏事言之，乃說二世曰：「天子之所以貴者，但以聞聲，群臣莫得見其面故也。且陛下富於春秋，未必盡通諸事。今坐朝廷，譴舉有不當者，則見短於大臣，非所以示神明於天下也。陛下不如深拱禁中，與臣及侍中習法者待事，事來有以揆之。如此，則大臣不敢奏疑事，天下稱聖主矣。」二世用其計，乃不坐朝廷見大臣，常居禁中。趙高侍中用事，事皆決於趙高。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-16', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-17', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 17, 'narrative', 'heading', '[7, 9, 9]'::jsonb, '項梁已破章邯於東阿，引兵西，北至定陶，再破秦軍。項羽、沛公又與秦軍戰於雍丘，大破之，斬李由。項梁益輕秦，有驕色。宋義諫曰：「戰勝而將驕卒惰者，敗。今卒少惰矣，秦兵日益，臣為君畏之。」項梁弗聽。餘乃使宋義使於齊，道遇齊使者高陵君顯，曰：「公將見武信君乎？」曰：「然。」曰：「臣論武信君軍必敗。公徐行即免死，疾行則及禍。」二世悉起兵益章邯擊楚軍，大破之定陶，項梁死。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-17', 'donge', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-17', 'dingtao', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-17', 'chenliu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-17', 'pengcheng', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-208-18', '資治通鑑', 8, 208, '二世皇帝二年', '癸巳', 18, 'narrative', 'heading', '[]'::jsonb, '章邯已破項梁，以為楚地兵不足憂，乃渡河，北擊趙，大破之。引兵至邯鄲，皆徙其民河內，夷其城郭。張耳與趙王歇走入巨鹿城，王離圍之。陳餘北收常山兵，得數萬人，軍巨鹿北。章邯軍巨鹿南棘原。趙數請救於楚。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-18', 'handan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-208-18', 'julu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-01', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 1, 'narrative', 'heading', '[10]'::jsonb, '冬，十月，齊將田都畔田榮，助楚救趙。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-02', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 2, 'narrative', 'heading', '[]'::jsonb, '沛公攻破東郡尉於成武。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-03', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 3, 'narrative', 'heading', '[11]'::jsonb, '宋義行至安陽，留四十六日不進。項羽曰：「秦圍趙急，宜疾引兵渡河；楚擊其外，趙應其內，破秦軍必矣。」宋義曰：「不然。夫搏牛之虻，不可以破蟣虱。今秦攻趙，戰勝則兵疲，我承其敝；不勝，則我引兵鼓行而西，必舉秦矣。故不如先斗秦、趙。夫被堅執銳，義不如公；坐運籌策，公不如義。」因下令軍中曰：「有猛如虎，狠如羊，貪如狼，強不可使者，皆斬之！」乃遣其子宋襄相齊，身送之至無鹽，飲酒高會。天寒，大雨，士卒凍饑。項羽曰：「將戮力而攻秦，久留不行。今歲饑民貧，士卒食半菽，軍無見糧，乃飲酒高會；不引兵渡河，因趙食，與趙並力攻秦，乃曰『承其敝』。夫以秦之強，攻新造之趙，其勢必舉。趙舉秦強，何敝之承！且國兵新破，王坐不安席，掃境內而專屬於將軍，國家安危，在此一舉。今不恤士卒而徇其私，非社稷之臣也！」
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-04', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 4, 'narrative', 'heading', '[12]'::jsonb, '十二月，沛公引兵至栗，遇剛武侯，奪其軍四千餘人，並之；與魏將皇欣、武滿軍合攻秦軍，破之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-05', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 5, 'narrative', 'heading', '[]'::jsonb, '故齊王建孫安下濟北，從項羽救趙。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-05', 'julu', 5);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-06', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 6, 'narrative', 'heading', '[2, 3, 4, 6, 7]'::jsonb, '春，二月，沛公北擊昌邑，遇彭越，彭越以其兵從沛公。越，昌邑人，常漁巨野澤中，為群盜。陳勝、項梁之起，澤間少年相聚百餘人，往從彭越曰：「請仲為長。」越謝曰：「臣不願也。」少年強請，乃許，與期旦日日出會，後期者斬。旦日日出，十餘人後，後者至日中。於是越謝曰：「臣老，諸君強以為長。今期而多後，不可盡誅，誅最後者一人。」令校長斬之。皆笑曰：「何至於是！請後不敢。」於是越引一人斬之，設壇祭，令徒屬，徒屬皆大驚，莫敢仰視。乃略地，收諸侯散卒，得千餘人，遂助沛公攻昌邑。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'chenliu', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'luoyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'yangzhai', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'wan', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-06', 'xianyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-07', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 7, 'narrative', 'heading', '[]'::jsonb, '王離軍既沒，章邯軍棘原，項羽軍漳南，相持未戰。秦軍數卻，二世使人讓章邯。章邯恐，使長史欣請事。至咸陽，留司馬門三日，趙高不見，有不信之心。長史欣恐，還走其軍，不敢出故道。趙高果使人追之，不及。欣至軍，報曰：「趙高用事於中，下無可為者。今戰能勝，高必疾妒吾功，不能勝，不免於死。願將軍孰計之！」陳餘亦遺章邯書曰：「白起為秦將，南征鄢郢，北坑馬服，攻城略地，不可勝計，而竟賜死。蒙恬為秦將，北逐戎人，開榆中地數千里，竟斬陽周。何者？功多，秦不能盡封，因以法誅之。今將軍為秦將三歲矣，所亡失以十萬數，而諸侯並起滋益多。彼趙高素諛日久，今事急，亦恐二世誅之，故欲以法誅將軍以塞責，使人更代將軍以脫其禍。夫將軍居外久，多內郤，有功亦誅，無功亦誅。且天之亡秦，無愚智皆知之。今將軍內不能直諫，外為亡國將，孤特獨立而欲常存，豈不哀哉！將軍何不還兵與諸侯為從，約共攻秦，分王其地，南面稱孤！此孰與身伏鈇質、妻子為戮乎？」
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-07', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-008-207-08', '資治通鑑', 8, 207, '二世皇帝三年', '甲午', 8, 'narrative', 'heading', '[8, 9]'::jsonb, '初，中丞相趙高欲專秦權，恐群臣不聽，乃先設驗，持鹿獻於二世曰：「馬也。」二世笑曰：「丞相誤邪，謂鹿為馬！」問左右，左右或默，或言馬以阿順趙高，或言鹿者。高因陰中諸言鹿者以法。後群臣皆畏高，莫敢言其過。高前數言「關東盜無能為也」，及項羽虜王離等，而章邯等軍數敗，上書請益助。自關以東，大抵盡畔秦吏，應諸侯，諸侯鹹率其眾西鄉。八月，沛公將數萬人攻武關，屠之。高恐二世怒，誅及其身，乃謝病，不朝見。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-08', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-08', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-008-207-08', 'lantian', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-01', '資治通鑑', 9, 206, '高帝元年', '乙未', 1, 'narrative', 'heading', '[10, 11]'::jsonb, '冬，十月，沛公至霸上。秦王子嬰素車、白馬，系頸以組，封皇帝璽、符、節，降軹道旁。諸將或言誅秦王。沛公曰：「始懷王遣我，固以能寬容。且人已降，殺之不祥。」乃以屬吏。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-01', 'bashang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-01', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-01c', '資治通鑑', 9, 206, '高帝元年', '乙未', 1, 'commentary', 'heading', '[]'::jsonb, '賈誼論曰：秦以區區之地致萬乘之權，招八州而朝同列，百有餘年，然後以六合為家，殽、函為宮。一夫作難而七廟墮，身死人手，為天下笑者，何也？仁誼不施而攻守之勢異也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-02', '資治通鑑', 9, 206, '高帝元年', '乙未', 2, 'narrative', 'heading', '[12, 3]'::jsonb, '項羽既定河北，率諸侯兵欲西入關。先是，諸侯吏卒、繇使、屯戍過秦中者，秦中吏卒遇之多無狀。及章邯以秦軍降諸侯，諸侯吏卒乘勝多奴虜使之，輕折辱秦吏卒。秦吏卒多怨，竊言曰：「章將軍等詐吾屬降諸侯。今能入關破秦，大善；即不能，諸侯虜吾屬而東，秦又盡誅吾父母妻子，奈何？」諸將微聞其計，以告項羽。項羽召黥布、蒲將軍計曰：「秦吏卒尚眾，其心不服，至關不聽，事必危。不如擊殺之，而獨與章邯、長史欣、都尉翳入秦。」於是楚軍夜擊坑秦卒二十餘萬人新安城南。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-02', 'xinan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-02', 'hangu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-02', 'hongmen', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-02', 'bashang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-02', 'xianyang', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-03', '資治通鑑', 9, 206, '高帝元年', '乙未', 3, 'narrative', 'heading', '[1, 2]'::jsonb, '項羽使人致命懷王，懷王曰：「如約。」項羽怒曰：「懷王者，吾家所立耳，非有功伐，何以得專主約？天下初發難時，假立諸侯後以伐秦。然身被堅執銳首事，暴露於野三年，滅秦定天下者，皆將相諸君與籍之力也。懷王雖無功，固當分其地而王之。」諸將皆曰：「善！」春，正月，羽陽尊懷王為義帝，曰：「古之帝者，地方千里，必居上游。」乃徙義帝於江南，都郴。
