INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-04', '資治通鑑', 9, 206, '高帝元年', '乙未', 4, 'narrative', 'heading', '[4]'::jsonb, '漢王怒，欲攻項羽，周勃、灌嬰、樊噲皆勸之。蕭何諫曰：「雖王漢中之惡，不猶愈於死乎？」漢王曰：「何為乃死也？」何曰：「今眾弗如，百戰百敗，不死何為？夫能詘於一人之下而信於萬乘之上者，湯、武是也。臣願大王王漢中，養其民以致賢人，收用巴、蜀，還定三秦，天下可圖也。」漢王曰：「善！」乃遂就國，以何為丞相。漢王賜張良金百鎰，珠二斗；良具以獻項伯。漢王亦因令良厚遺項伯，使盡請漢中地，項王許之。夏，四月，諸侯罷戲下兵，各就國。項王使卒三萬人從漢王之國。楚與諸侯之慕從者數萬人，從杜南入蝕中。張良送至褒中，漢王遣良歸韓；良因說漢王燒絕所過棧道，以備諸侯盜兵，且示項羽無東意。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-04', 'nanzheng', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-05', '資治通鑑', 9, 206, '高帝元年', '乙未', 5, 'narrative', 'heading', '[5, 6, 7]'::jsonb, '田榮聞項羽徙齊王市於膠東，而以田都為齊王，大怒。五月，榮發兵距擊田都，都亡走楚。榮留齊王市，不令之膠東。市畏項羽，竊亡之國。榮怒，六月，追擊殺市於即墨，自立為齊王。是時，彭越在巨野，有眾萬餘人，無所屬。榮與越將軍印，使擊濟北。秋，七月，越擊殺濟北王安。榮遂並王三齊之地，又使越擊楚。項王命蕭公角將兵擊越，越大破楚軍。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-05', 'jimo', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-06', '資治通鑑', 9, 206, '高帝元年', '乙未', 6, 'narrative', 'heading', '[]'::jsonb, '張耳之國，陳餘益怒曰：「張耳與餘，功等也。今張耳王，餘獨侯，此項羽不平！」乃陰使張同、夏說說齊王榮曰：「項羽為天下宰不平，盡王諸將善地，徙故王於丑地。今趙王乃北居代，餘以為不可。聞大王起兵，不聽不義。願大王資餘兵擊常山，復趙王，請以趙為扞蔽！」齊王許之，遣兵從陳餘。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-07', '資治通鑑', 9, 206, '高帝元年', '乙未', 7, 'narrative', 'heading', '[]'::jsonb, '項王以張良從漢王，韓王成又無功，故不遣之國，與俱至彭城，廢以為穰侯；已，又殺之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-07', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-08', '資治通鑑', 9, 206, '高帝元年', '乙未', 8, 'narrative', 'heading', '[]'::jsonb, '初，淮陰人韓信，家貧，無行，不得推擇為吏，又不能治生商賈，常從人寄食飲，人多厭之。信釣於城下，有漂母見信饑，飯信。信喜，謂漂母曰：「吾必有以重報母。」母怒曰：「大丈夫不能自食，吾哀王孫而進食，豈望報乎？」淮陰屠中少年有侮信者曰：「若雖長大，好帶刀劍，中情怯耳。」因眾辱之曰：「信能死，刺我；不能死，出我胯下！」於是信孰視之，俛出胯下，蒲伏。一市人皆笑信，以為怯。及項梁渡淮，信杖劍從之。居麾下，無所知名。項梁敗，又屬項羽，羽以為郎中。數以策干羽，羽不用。漢王之入蜀，信亡楚歸漢，未知名。為連敖，坐當斬。其輩十三人皆已斬，次至信，信乃仰視，適見滕公，曰：「上不欲就天下乎？何為斬壯士？」滕公奇其言，壯其貌，釋而不斬。與語，大說之，言於王。王拜以為治粟都尉，亦未之奇也。信數與蕭何語，何奇之。漢王至南鄭，諸將及士卒皆歌謳思東歸，多道亡者。信度何等已數言王，王不我用，即亡去。何聞信亡，不及以聞，自追之。人有言王曰：「丞相何亡。」王大怒，如失左右手。居一二日，何來謁王。王且怒且喜，罵何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡者耳。」王曰：「若所追者誰？」何曰：「韓信也。」王復罵曰：「諸將亡者以十數，公無所追。追信，詐也。」何曰：「諸將易得耳。至如信者，國士無雙。王必欲長王漢中，無所事信，必欲爭天下，非信無可與計事者。顧王策安所決耳。」王曰：「吾亦欲東耳，安能鬱鬱久居此乎？」何曰：「計必欲東，能用信，信即留；不能用信，終亡耳。」王曰：「吾為公以為將。」何曰：「雖為將，信不留。」王曰：「以為大將。」何曰：「幸甚！」於是王欲召信拜之。何曰：「王素慢無禮。今拜大將，如呼小兒，此乃信所以去也。王必欲拜之，擇良日，齋戒，設壇場，具禮，乃可耳。」王許之。諸將皆喜，人人各自以為得大將。至拜大將，乃韓信也，一軍皆驚。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-08', 'nanzheng', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-08', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-08', 'xinan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-08', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-09', '資治通鑑', 9, 206, '高帝元年', '乙未', 9, 'narrative', 'heading', '[8]'::jsonb, '八月，漢王引兵從故道出，襲雍；雍王章邯迎擊漢陳倉。雍兵敗，還走；止，戰好畤，又敗，走廢丘。漢王遂定雍地，東至咸陽，引兵圍雍王於廢丘，而遣諸將略地。塞王欣、翟王翳皆降，以其地為渭南、河上、上郡。將軍薛歐、王吸出武關，因王陵兵以迎太公、呂后。項王聞之，發兵距之陽夏，不得前。王陵者，沛人也，先聚黨數千人，居南陽，至是始以兵屬漢。項王取陵母置軍中，陵使至，則東鄉坐陵母，欲以招陵。陵母私送使者，泣曰：「願為老妾語陵：善事漢王，漢王長者，終得天下，毋以老妾故持二心。妾以死送使者！」遂伏劍而死。項王怒。烹陵母。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-09', 'chencang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-09', 'feiqiu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-09', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-206-09', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-10', '資治通鑑', 9, 206, '高帝元年', '乙未', 10, 'narrative', 'heading', '[]'::jsonb, '燕王廣不肯之遼東，臧荼擊殺之，並其地。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-11', '資治通鑑', 9, 206, '高帝元年', '乙未', 11, 'narrative', 'heading', '[]'::jsonb, '是歲，以內史沛周苛為御史大夫。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-206-12', '資治通鑑', 9, 206, '高帝元年', '乙未', 12, 'narrative', 'heading', '[]'::jsonb, '項王使趣義帝行，其群臣、左右稍稍叛之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-01', '資治通鑑', 9, 205, '高帝二年', '丙申', 1, 'narrative', 'heading', '[10]'::jsonb, '冬，十月，項王密使九江、衡山、臨江王擊義帝，殺之江中。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-02', '資治通鑑', 9, 205, '高帝二年', '丙申', 2, 'narrative', 'heading', '[]'::jsonb, '陳餘悉三縣兵，與齊兵共襲常山。常山王張耳敗，走漢，謁漢王於廢丘，漢王厚遇之。陳餘迎趙王於代，復為趙王。趙王德陳餘，立以為代王。陳餘為趙王弱，國初定，不之國，留傅趙王；而使夏說以相國守代。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-02', 'feiqiu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-03', '資治通鑑', 9, 205, '高帝二年', '丙申', 3, 'narrative', 'heading', '[]'::jsonb, '張良自韓間行歸漢，漢王以為成信侯。良多病，未嘗特將，常為畫策臣，時時從漢王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-04', '資治通鑑', 9, 205, '高帝二年', '丙申', 4, 'narrative', 'heading', '[]'::jsonb, '漢王如陝，鎮撫關外父老。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-05', '資治通鑑', 9, 205, '高帝二年', '丙申', 5, 'narrative', 'heading', '[]'::jsonb, '河南王申陽降，置河南郡。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-06', '資治通鑑', 9, 205, '高帝二年', '丙申', 6, 'narrative', 'heading', '[11]'::jsonb, '漢王以韓襄王孫信為韓太尉，將兵略韓地。信急擊韓王昌於陽城，昌降。十一月，立信為韓王，常將韓兵從漢王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-07', '資治通鑑', 9, 205, '高帝二年', '丙申', 7, 'narrative', 'heading', '[]'::jsonb, '漢王還都櫟陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-07', 'yueyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-08', '資治通鑑', 9, 205, '高帝二年', '丙申', 8, 'narrative', 'heading', '[]'::jsonb, '諸將拔隴西。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-09', '資治通鑑', 9, 205, '高帝二年', '丙申', 9, 'narrative', 'heading', '[1]'::jsonb, '春，正月，項王北至城陽。齊王榮將兵會戰，敗，走平原，平原民殺之。項王復立田假為齊王。遂北至北海，燒夷城郭、室屋，坑田榮降卒，系虜其老弱、婦女，所過多所殘滅。齊民相聚叛之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-10', '資治通鑑', 9, 205, '高帝二年', '丙申', 10, 'narrative', 'heading', '[]'::jsonb, '漢將拔北地，虜雍王弟平。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-11', '資治通鑑', 9, 205, '高帝二年', '丙申', 11, 'narrative', 'heading', '[3]'::jsonb, '三月，漢王自臨晉渡河。魏王豹降，將兵從；下河內，虜殷王卬，置河內郡。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-12', '資治通鑑', 9, 205, '高帝二年', '丙申', 12, 'narrative', 'heading', '[]'::jsonb, '初，陽武人陳平，家貧，好讀書。里中社，平為宰，分肉食甚均。父老曰：「善，陳孺子之為宰！」平曰：「嗟乎，使平得宰天下，亦如是肉矣！」及諸侯叛秦，平事魏王咎於臨濟，為太僕，說魏王，不聽。人或讒之，平亡去。後事項羽，賜爵為卿。殷王反楚，項羽使平擊降之。還，拜為都尉，賜金二十鎰。居無何，漢王攻下殷。項王怒，將誅定殷將吏。平懼，乃封其金與印，使使歸項王；而挺身間行，杖劍亡，渡河，歸漢王於脩武，因魏無知求見漢王。漢王召入，賜食，遣罷就舍。平曰：「臣為事來，所言不可以過今日。」於是漢王與語而說之。問曰：「子之居楚何官？」曰：「為都尉。」是日，即拜平為都尉，使為參乘，典護軍。諸將盡讙曰：「大王一日得楚之亡卒，未知其高下，而即與同載，反使監護長者！」漢王聞之，愈益幸平。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-13', '資治通鑑', 9, 205, '高帝二年', '丙申', 13, 'narrative', 'heading', '[]'::jsonb, '漢王南渡平陰津，至洛陽新城。三老董公遮說王曰：「臣聞『順德者昌，逆德者亡』；『兵出無名，事故不成』。故曰：『明其為賊，敵乃可服。』項羽為無道，放殺其主，天下之賊也。夫仁不以勇，義不以力，大王宜率三軍之眾為之素服，以告諸侯而伐之，則四海之內莫不仰德，此三王之舉也。」於是漢王為義帝發喪，袒而大哭，哀臨三日，發使告諸侯曰：「天下共立義帝，北面事之。今項羽放殺義帝江南，大逆無道！寡人悉發關中兵，收三河士，南浮江、漢以下，願從諸侯王擊楚之殺義帝者！」使者至趙，陳餘曰：「漢殺張耳，乃從。」於是漢王求人類張耳者斬之，持其頭遺陳餘；餘乃遣兵助漢。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-13', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-14', '資治通鑑', 9, 205, '高帝二年', '丙申', 14, 'narrative', 'heading', '[4]'::jsonb, '田榮弟橫收散卒，得數萬人，起城陽，夏，四月，立榮子廣為齊王，以拒楚。項王因留，連戰，未能下。雖聞漢東，既擊齊，欲遂破之而後擊漢，漢王以故得率諸侯兵凡五十六萬人伐楚。到外黃，彭越將其兵三萬餘人歸漢。漢王曰：「彭將軍收魏地得十餘城，欲急立魏後。今西魏王豹，真魏後。」乃拜彭越為魏相國，擅將其兵略定梁地。漢王遂入城，收其貨寶、美人，日置酒高會。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-14', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-14', 'lingbi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-14', 'pei', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-14', 'xiayi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-15', '資治通鑑', 9, 205, '高帝二年', '丙申', 15, 'narrative', 'heading', '[]'::jsonb, '田橫進攻田假，假走楚，楚殺之。橫遂復定三齊之地。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-16', '資治通鑑', 9, 205, '高帝二年', '丙申', 16, 'narrative', 'heading', '[]'::jsonb, '漢王問群臣曰：「吾欲捐關以東，等棄之，誰可與共功者？」張良曰：「九江王布，楚梟將，與項王有隙；彭越與齊反梁地；此兩人可急使。而漢王之將，獨韓信可屬大事，當一面。即欲捐之，捐之此三人，則楚可破也！」
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-16', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-16', 'xiayi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-17', '資治通鑑', 9, 205, '高帝二年', '丙申', 17, 'narrative', 'heading', '[5]'::jsonb, '五月，漢王至滎陽，諸敗軍皆會，蕭何亦發關中老弱未傅者悉詣滎陽，漢軍復大振。楚起於彭城，常乘勝逐北，與漢戰滎陽南京、索間。楚騎來眾，漢王擇軍中可為騎將者，皆推故奉騎士重泉人李必、駱甲。漢王欲拜之，必、甲曰：「臣故秦民，恐軍不信；願得大王左右善騎者傅之。」乃拜灌嬰為中大夫令，李必、駱甲為左右校尉，將騎兵擊楚騎於滎陽東，大破之，楚以故不能過滎陽而西。漢王軍滎陽，築甬道屬之河，以取敖倉粟。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-17', 'xingyang', 6);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-17', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-17', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-18', '資治通鑑', 9, 205, '高帝二年', '丙申', 18, 'narrative', 'heading', '[]'::jsonb, '周勃、灌嬰等言於漢王曰：「陳平雖美如冠玉，其中未必有也。臣聞平居家時盜其嫂；事魏不容，亡歸楚；不中，又亡歸漢。今日大王尊官之，令護軍。臣聞平受諸將金，金多者得善處，金少者得惡處。平，反覆亂臣也，願王察之！」漢王疑之，召讓魏無知。無知曰：「臣所言者能也，陛下所問者行也。今有尾生、孝己之行，而無益勝負之數，陛下何暇用之乎！楚、漢相距，臣進奇謀之士，顧其計誠足以利國家不耳。盜嫂、受金，又何足疑乎！」漢王召讓平曰：「先生事魏不中，事楚而去，今又從吾游，信者固多心乎！」平曰：「臣事魏王，魏王不能用臣說，故去；事項王，項王不能信人，其所任愛，非諸項，即妻之昆弟，雖有奇士不能用。聞漢王能用人，故歸大王。臣裸身來，不受金無以為資。誠臣計畫有可采乎，願大王用之；使無可用者，金具在，請封輸官，得其骸骨。」漢王乃謝，厚賜，拜為護軍中尉，盡護諸將。諸將乃不敢復言。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-19', '資治通鑑', 9, 205, '高帝二年', '丙申', 19, 'narrative', 'heading', '[]'::jsonb, '魏王豹謁歸視親疾；至則絕河津，反為楚。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-20', '資治通鑑', 9, 205, '高帝二年', '丙申', 20, 'narrative', 'heading', '[6]'::jsonb, '六月，漢王還櫟陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-20', 'yueyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-21', '資治通鑑', 9, 205, '高帝二年', '丙申', 21, 'narrative', 'heading', '[]'::jsonb, '壬午，立子盈為太子；赦罪人。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-22', '資治通鑑', 9, 205, '高帝二年', '丙申', 22, 'narrative', 'heading', '[]'::jsonb, '漢兵引水灌廢丘，廢丘降，章邯自殺。盡定雍地，以為中地、北地、隴西郡。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-22', 'feiqiu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-23', '資治通鑑', 9, 205, '高帝二年', '丙申', 23, 'narrative', 'heading', '[]'::jsonb, '關中大饑，米斛萬錢，人相食。令民就食蜀、漢。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-23', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-24', '資治通鑑', 9, 205, '高帝二年', '丙申', 24, 'narrative', 'heading', '[8]'::jsonb, '秋，八月，漢王如滎陽，命蕭何守關中，侍太子，為法令約束，立宗廟、社稷、宮室、縣邑；事有不及奏決者，輒以便宜施行，上來，以聞。計關中戶口，轉漕、調兵以給軍，未嘗乏絕。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-24', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-25', '資治通鑑', 9, 205, '高帝二年', '丙申', 25, 'narrative', 'heading', '[9]'::jsonb, '漢王使酈食其往說魏王豹，且召之。豹不聽，曰：「漢王慢而侮人，罵詈諸侯、群臣如罵奴耳，吾不忍復見也。」於是漢王以韓信為左丞相，與灌嬰、曹參俱擊魏。漢王問食其：「魏大將誰也？」對曰：「柏直。」王曰：「是口尚乳臭，安能當韓信！騎將誰也？」曰：「馮敬。」曰：「是秦將馮無擇子也，雖賢，不能當灌嬰。」「步卒將誰也？」曰：「項佗。」曰：「不能當曹參。吾無患矣！」韓信亦問酈生：「魏得無用周叔為大將乎？」酈生曰：「柏直也。」信曰：「豎子耳。」遂進兵。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-25', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-009-205-26', '資治通鑑', 9, 205, '高帝二年', '丙申', 26, 'narrative', 'heading', '[9]'::jsonb, '漢之敗於彭城而西也，陳餘亦覺張耳不死，即背漢。韓信既定魏，使人請兵三萬人，願以北舉燕、趙，東擊齊，南絕楚糧道。漢王許之，乃遣張耳與俱，引兵東，北擊趙、代。後九月，信破代兵，禽夏說於閼與。信之下魏破代，漢輒使人收其精兵詣滎陽以距楚。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-26', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-009-205-26', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-01', '資治通鑑', 10, 204, '高帝三年', '丁酉', 1, 'narrative', 'heading', '[10]'::jsonb, '冬，十月，韓信、張耳以兵數萬東擊趙。趙王及成安君陳餘聞之，聚兵井陘口，號二十萬。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-01', 'jingxing', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-01', 'guangwu', 6);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-02', '資治通鑑', 10, 204, '高帝三年', '丁酉', 2, 'narrative', 'heading', '[]'::jsonb, '甲戌晦，日有食之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-03', '資治通鑑', 10, 204, '高帝三年', '丁酉', 3, 'narrative', 'heading', '[11]'::jsonb, '十一月，癸卯晦，日有食之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-04', '資治通鑑', 10, 204, '高帝三年', '丁酉', 4, 'narrative', 'heading', '[12]'::jsonb, '隨何至九江，九江太宰主之，三日不得見。隨何說太宰曰：「王之不見何，必以楚為強，以漢為弱也。此臣之所以為使。使何得見，言之而是，大王所欲聞也；言之而非，使何等二十人伏斧質九江市，足以明王倍漢而與楚也。」太宰乃言之王。王見之。隨何曰：「漢王使臣敬進書大王御者，竊怪大王與楚何親也。」九江王曰：「寡人北鄉而臣事之。」隨何曰：「大王與項王俱列為諸侯，北鄉而臣事之者，必以楚為強，可以托國也。項王伐齊，身負版築，為士卒先。大王宜悉九江之眾，身自將之，為楚前鋒；今乃發四千人以助楚。夫北面而臣事人者，固若是乎？漢王入彭城，項王未出齊也。大王宜悉九江之兵渡淮，日夜會戰彭城下；大王乃撫萬人之眾，無一人渡淮者，垂拱而觀其孰勝。夫托國於人者，固若是乎？大王提空名以鄉楚而欲厚自托，臣竊為大王不取也！然而大王不背楚者，以漢為弱也。夫楚兵雖強，天下負之以不義之名，以其背盟約而殺義帝也。漢王收諸侯，還守成皋、滎陽，下蜀、漢之粟，深溝壁壘，分卒守徼乘塞。楚人深入敵國八九百里，老弱轉糧千里之外。漢堅守而不動，楚進則不得攻，退則不能解，故曰楚兵不足恃也。使楚勝漢，則諸侯自危懼而相救。夫楚之強，適足以致天下之兵耳。故楚不如漢，其勢易見也。今大王不與萬全之漢而自托於危亡之楚，臣竊為大王惑之！臣非以九江之兵足以亡楚也；大王發兵而倍楚，項王必留；留數月，漢之取天下可以萬全。臣請與大王提劍而歸漢，漢王必裂地而封大王；又況九江必大王有也。」九江王曰：「請奉命。」陰許畔楚與漢，未敢洩也。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-04', 'pengcheng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-04', 'chenggao', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-04', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-04c', '資治通鑑', 10, 204, '高帝三年', '丁酉', 4, 'commentary', 'heading', '[]'::jsonb, '荀悅論曰：夫立策決勝之術，其要有三：一曰形，二曰勢，三曰情。形者，言其大體得失之數也；勢者，言其臨時之宜、進退之機也；情者，言其心志可否之實也。故策同、事等而功殊者，三術不同也。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-04c', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-05', '資治通鑑', 10, 204, '高帝三年', '丁酉', 5, 'narrative', 'heading', '[4, 5, 6]'::jsonb, '漢王謂陳平曰：「天下紛紛，何時定乎？」陳平曰：「項王骨鯁之臣亞父、鍾離昧、龍且、周殷之屬，不過數人耳。大王誠能捐數萬斤金，行反間，間其君臣，以疑其心。項王為人，意忌信讒，必內相誅，漢因舉兵而攻之，破楚必矣。」漢王曰：「善！」乃出黃金四萬斤與平，恣所為，不問其出入。平多以金縱反間於楚軍，宣言：「諸將鍾離昧等為項王將，功多矣，然而終不得裂地而王，欲與漢為一，以滅項氏而分王其地。」項王果意不信鍾離昧等。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-05', 'xingyang', 10);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-05', 'pengcheng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-05', 'chenggao', 9);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-05', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-06', '資治通鑑', 10, 204, '高帝三年', '丁酉', 6, 'narrative', 'heading', '[7]'::jsonb, '秋，七月，有星孛於大角。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-07', '資治通鑑', 10, 204, '高帝三年', '丁酉', 7, 'narrative', 'heading', '[]'::jsonb, '臨江王敖薨，子尉嗣。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-08', '資治通鑑', 10, 204, '高帝三年', '丁酉', 8, 'narrative', 'heading', '[8]'::jsonb, '漢王得韓信軍，復大振。八月，引兵臨河，南鄉，軍小脩武，欲復與楚戰。郎中鄭忠說止漢王，使高壘深塹勿與戰。漢王聽其計，使將軍劉賈、盧綰將卒二萬人，騎數百，度白馬津，入楚地，佐彭越，燒楚積聚，以破其業，無以給項王軍食而已。楚兵擊劉賈，賈輒堅壁不肯與戰，而與彭越相保。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-204-09', '資治通鑑', 10, 204, '高帝三年', '丁酉', 9, 'narrative', 'heading', '[9]'::jsonb, '彭越攻徇梁地，下睢陽、外黃等十七城。九月，項王謂大司馬曹咎曰：「謹守成皋。即漢王欲挑戰，慎勿與戰，勿令得東而已。我十五日必定梁地，復從將軍。」羽引兵東行，擊陳留、外黃、睢陽等城，皆下之。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'chenggao', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'chenliu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'aocang', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'nanzheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-204-09', 'jingxing', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-01', '資治通鑑', 10, 203, '高帝四年', '戊戌', 1, 'narrative', 'heading', '[10]'::jsonb, '冬，十月，信襲破齊歷下軍，遂至臨淄。齊王以酈生為賣己，乃烹之；引兵東走高密，使使之楚請救。田橫走博陽，守相田光走城陽，將軍田既軍於膠東。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-01', 'linzi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-01', 'boyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-02', '資治通鑑', 10, 203, '高帝四年', '戊戌', 2, 'narrative', 'heading', '[]'::jsonb, '楚大司馬咎守成皋，漢數挑戰，楚軍不出。使人辱之，數日，咎怒，渡兵汜水。士卒半渡，漢擊之，大破楚軍，盡得楚國金玉、貨賂，咎及司馬欣皆自剄汜水上。漢王引兵渡河，復取成皋，軍廣武，就敖倉食。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'chenggao', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'guangwu', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'aocang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'xinan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-02', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-03', '資治通鑑', 10, 203, '高帝四年', '戊戌', 3, 'narrative', 'heading', '[11]'::jsonb, '韓信已定臨淄，遂東追齊王。項王使龍且將兵，號二十萬，以救齊，與齊王合軍高密。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-03', 'linzi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-03', 'boyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-04', '資治通鑑', 10, 203, '高帝四年', '戊戌', 4, 'narrative', 'heading', '[]'::jsonb, '立張耳為趙王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-05', '資治通鑑', 10, 203, '高帝四年', '戊戌', 5, 'narrative', 'heading', '[]'::jsonb, '漢王疾愈，西入關。至櫟陽，梟故塞王欣頭櫟陽市。留四日，復如軍，軍廣武。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-05', 'yueyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-05', 'guangwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-06', '資治通鑑', 10, 203, '高帝四年', '戊戌', 6, 'narrative', 'heading', '[2]'::jsonb, '韓信使人言漢王曰：「齊偽詐多變，反覆之國也；南邊楚。請為假王以鎮之。」漢王發書，大怒，罵曰：「吾困於此，旦暮望若來佐我，乃欲自立為王！」張良、陳平躡漢王足，因附耳語曰：「漢方不利，寧能禁信之自王乎！不如因而立之，善遇，使自為守。不然，變生。」漢王亦悟，因復罵曰：「大丈夫定諸侯，即為真王耳，何以假為！」春，二月，遣張良操印立韓信為齊王，征其兵擊楚。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-07', '資治通鑑', 10, 203, '高帝四年', '戊戌', 7, 'narrative', 'heading', '[]'::jsonb, '項王聞龍且死，大懼，使盱台人涉往說齊王信曰：「天下共苦秦久矣，相與戮力擊秦。秦已破，計功割地，分土而王之，以休士卒。今漢王復興兵而東，侵人之分，奪人之地；已破三秦，引兵出關，收諸侯之兵以東擊楚，其意非盡吞天下者不休，其不知厭足如是甚也！且漢王不可必，身居項王掌握中數矣，項王憐而活之；然得脫，輒倍約，復擊項王，其不可親信如此。今足下雖自以與漢王為厚交，為之盡力用兵，必終為所禽矣。足下所以得須臾至今者，以項王尚存也。當今二王之事，權在足下，足下右投則漢王勝，左投則項王勝。項王今日亡，則次取足下。足下與項王有故，何不反漢與楚連和，參分天下王之！今釋此時而自必於漢以擊楚，且為智者固若此乎？！」韓信謝曰：「臣事項王，官不過郎中，位不過執戟；言不聽，畫不用，故倍楚而歸漢。漢王授我上將軍印，予我數萬眾，解衣衣我，推食食我，言聽計用，故吾得以至於此。夫人深親我，我倍之不祥；雖死不易！幸為信謝項王！」
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-07', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-08', '資治通鑑', 10, 203, '高帝四年', '戊戌', 8, 'narrative', 'heading', '[7]'::jsonb, '秋，七月，立黥布為淮南王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-09', '資治通鑑', 10, 203, '高帝四年', '戊戌', 9, 'narrative', 'heading', '[8]'::jsonb, '八月，北貉燕人來致梟騎助漢。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-10', '資治通鑑', 10, 203, '高帝四年', '戊戌', 10, 'narrative', 'heading', '[]'::jsonb, '漢王下令：軍士不幸死者，吏為衣衾棺斂，轉送其家。四方歸心焉。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-11', '資治通鑑', 10, 203, '高帝四年', '戊戌', 11, 'narrative', 'heading', '[]'::jsonb, '是歲，以中尉周昌為御史大夫。昌，苛從弟也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-010-203-12', '資治通鑑', 10, 203, '高帝四年', '戊戌', 12, 'narrative', 'heading', '[9]'::jsonb, '項羽自知少助；食盡，韓信又進兵擊楚，羽患之。漢遣侯公說羽請太公。羽乃與漢約，中分天下，割洪溝以西為漢，以東為楚。九月，楚歸太公、呂后，引兵解而東歸。漢王欲西歸，張良、陳平說曰：「漢有天下太半，而諸侯皆附；楚兵疲食盡，此天亡之時也。今釋弗擊，此所謂養虎自遺患也。」漢王從之。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-010-203-12', 'honggou', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-01', '資治通鑑', 11, 202, '高帝五年', '己亥', 1, 'narrative', 'heading', '[10, 11, 12]'::jsonb, '冬，十月，漢王追項羽至固陵，與齊王信、魏相國越期會擊楚；信、越不至，楚擊漢軍，大破之。漢王復堅壁自守，謂張良曰：「諸侯不從，奈何？」對曰：「楚兵且破，二人未有分地，其不至固宜。君王能與共天下，可立致也。齊王信之立，非君王意，信亦不自堅；彭越本定梁地，始，君王以魏豹故拜越為相國，今豹死，越亦望王，而君王不早定。今能取睢陽以北至穀城皆以王彭越，從陳以東傅海與齊王信。信家在楚，其意欲復得故邑。能出捐此地以許兩人，使各自為戰，則楚易破也。」漢王從之。於是韓信、彭越皆引兵來。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-01', 'guling', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-01', 'chen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-01', 'gaixia', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-01', 'wujiang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-01c', '資治通鑑', 11, 202, '高帝五年', '己亥', 1, 'commentary', 'heading', '[]'::jsonb, '太史公曰：羽起隴晦之中，三年，遂將五諸侯滅秦，分裂天下而封王侯，政由羽出；位雖不終，近古以來未嘗有也！及羽背關懷楚，放逐義帝而自立；怨王侯叛己，難矣！自矜功伐，奮其私智而不師古，謂霸王之業，欲以力征經營天下。五年，卒亡其國，身死東城，尚不覺寤而不自責，乃引「天亡我，非用兵之罪也，」豈不謬哉！
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-01c', 'gaixia', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-02', '資治通鑑', 11, 202, '高帝五年', '己亥', 2, 'narrative', 'heading', '[]'::jsonb, '漢王還，至定陶，馳入齊王信壁，奪其軍。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-02', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-03', '資治通鑑', 11, 202, '高帝五年', '己亥', 3, 'narrative', 'heading', '[]'::jsonb, '臨江王共尉不降，遣盧綰、劉賈擊虜之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-04', '資治通鑑', 11, 202, '高帝五年', '己亥', 4, 'narrative', 'heading', '[1]'::jsonb, '春，正月，更立齊王信為楚王，王淮北，都下邳。封魏相國建城侯彭越為梁王，王魏故地，都定陶。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-04', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-05', '資治通鑑', 11, 202, '高帝五年', '己亥', 5, 'narrative', 'heading', '[]'::jsonb, '令曰：「兵不得休八年，萬民與苦甚。今天下事畢，其赦天下殊死以下。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-06', '資治通鑑', 11, 202, '高帝五年', '己亥', 6, 'narrative', 'heading', '[2]'::jsonb, '諸侯王皆上疏請尊漢王為皇帝。二月甲午，王即皇帝位於汜水之陽。更王后曰皇后，太子曰皇太子；追尊先媼曰昭靈夫人。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-06', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-07', '資治通鑑', 11, 202, '高帝五年', '己亥', 7, 'narrative', 'heading', '[]'::jsonb, '帝西都洛陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-07', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-08', '資治通鑑', 11, 202, '高帝五年', '己亥', 8, 'narrative', 'heading', '[5]'::jsonb, '夏，五月，兵皆罷歸家。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-09', '資治通鑑', 11, 202, '高帝五年', '己亥', 9, 'narrative', 'heading', '[]'::jsonb, '詔：「民前或相聚保山澤，不書名數。今天下已定，令各歸其縣，復故爵、田宅；吏以文法教訓辨告，勿笞辱；軍吏卒爵及七大夫以上，皆令食邑，非七大夫已下，皆復其身及戶，勿事。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-10', '資治通鑑', 11, 202, '高帝五年', '己亥', 10, 'narrative', 'heading', '[]'::jsonb, '帝置酒洛陽南宮，上曰：「徹侯、諸將毋敢隱朕，皆言其情。吾所以有天下者何？項氏之所以失天下者何？」高起、王陵對曰：「陛下使人攻城略地，因以與之，與天下同其利；項羽不然，有功者害之，賢者疑之，此其所以失天下也。」上曰：「公知其一，未知其二。夫運籌帷幄之中，決勝千里之外，吾不如子房；填國家，撫百姓，給餉饋，不絕糧道，吾不如蕭何；連百萬之眾，戰必勝，攻必取，吾不如韓信。三者皆人傑，吾能用之，此吾所以取天下者也。項羽有一范增而不能用，此所以為我禽也。」群臣說服。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-10', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-11', '資治通鑑', 11, 202, '高帝五年', '己亥', 11, 'narrative', 'heading', '[]'::jsonb, '彭越既受漢封，田橫懼誅，與其徒屬五百餘人入海，居島中。帝以田橫兄弟本定齊地，齊賢者多附焉；今在海中，不取，後恐為亂。乃使使赦橫罪，召之。橫謝曰：「臣烹陛下之使酈生，今聞其弟商為漢將；臣恐懼，不敢奉詔，請為庶人，守海島中。」使還報，帝乃詔衛尉酈商曰：「齊王田橫即至，人馬從者敢動搖者，致族夷！」乃復使使持節具告以詔商狀，曰：「田橫來，大者王，小者乃侯耳；不來，且舉兵加誅焉！」
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-11', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-12', '資治通鑑', 11, 202, '高帝五年', '己亥', 12, 'narrative', 'heading', '[]'::jsonb, '初，楚人季布為項籍將，數窘辱帝。項籍滅，帝購求布千金；敢有舍匿，罪三族。布乃髡鉗為奴，自賣於朱家。朱家心知其季布也，買置田舍，身之洛陽見籐公，說曰：「季布何罪？臣各為其主用，職耳；項氏臣豈可盡誅邪？今上始得天下，而以私怨求一人，何示不廣也。且以季布之賢，漢求之急，此不北走胡，南走越耳。夫忌壯士以資敵國，此伍子胥所以鞭荊平之墓也。君何不從容為上言之！」滕公待間言於上，如朱家指。上乃赦布，召拜郎中，朱家遂不復見之。
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-12', 'luoyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-12', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-12c', '資治通鑑', 11, 202, '高帝五年', '己亥', 12, 'commentary', 'heading', '[]'::jsonb, '臣光曰：高祖起豐、沛以來，罔羅豪桀，招亡納叛，亦已多矣。及即帝位，而丁公獨以不忠受戮，何哉？夫進取之與守成，其勢不同。當群雄角逐之際，民無定主，來者受之，固其宜也。及貴為天子，四海之內，無不為臣；苟不明禮義以示之，使為臣者，人懷貳心以徼大利，則國家其能久安乎？是故斷以大義，使天下曉然皆知為臣不忠者無所自容；而懷私結恩者，雖至於活己，猶以義不與也。戮一人而千萬人懼，其慮事豈不深且遠哉？子孫享有天祿四百餘年，宜矣！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-12c', 'feng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-13', '資治通鑑', 11, 202, '高帝五年', '己亥', 13, 'narrative', 'heading', '[]'::jsonb, '齊人婁敬戍隴西，過洛陽，脫輓輅，衣羊裘，因齊人虞將軍求見上。虞將軍欲與之鮮衣，婁敬曰：「臣衣帛，衣帛見；衣褐，衣褐見，終不敢易衣。」於是虞將軍入言上，上召見，問之。婁敬曰：「陛下都洛陽，豈欲與周室比隆哉？」上曰：「然。」婁敬曰：「陛下取天下與周異。周之先，自后稷封邰，積德累善，十有餘世，至於太王、王季、文王、武王而諸侯自歸之，遂滅殷為天子。及成王即位，周公相焉，乃營洛邑，以為此天下之中也，諸侯四方納貢職，道里均矣。有德則易以王，無德則易以亡。故周之盛時，天下和洽，諸侯、四夷莫不賓服，效其貢職。及其衰也，天下莫朝，周不能制也；非唯其德薄也，形勢弱也。今陛下起豐、沛，卷蜀、漢，定三秦，與項羽戰滎陽、成皋之間，大戰七十，小戰四十；使天下之民，肝腦塗地，父子暴骨中野，不可勝數，哭泣之聲未絕，傷夷者未起；而欲比隆於成、康之時，臣竊以為不侔也。且夫秦地被山帶河，四塞以為固，卒然有急，百萬之眾可立具也。因秦之故，資甚美膏腴之地，此所謂天府者也。陛下入關而都之，山東雖亂，秦之故地可全而有也。夫與人斗，不搤其亢，拊其背，未能全其勝也。今陛下案秦之故地，此亦扼天下之亢而拊其背也。」帝問群臣，群臣皆山東人，爭言：「周王數百年，秦二世即亡。洛陽東有成皋，西有殽、澠，倍河，鄉伊、洛，其固亦足恃也。」上問張良。良曰：「洛陽雖有此固，其中小不過數百里，田地薄，四面受敵，此非用武之國也。關中左殽、函，右隴、蜀，沃野千里。南有巴、蜀之饒，北有胡苑之利。阻三面而守，獨以一面東制諸侯；諸侯安定，河、渭漕輓天下，西給京師；諸侯有變，順流而下，足以委輸。此所謂金城千里，天府之國也。婁敬說是也。」上即日車駕西，都長安。拜婁敬為郎中，號曰奉春君，賜姓劉氏。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-13', 'luoyang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-13', 'feng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-13', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('tj-011-202-13', 'chenggao', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-14', '資治通鑑', 11, 202, '高帝五年', '己亥', 14, 'narrative', 'heading', '[]'::jsonb, '張良素多病，從上入關，即道引，不食穀，杜門不出，曰：「家世相韓，及韓滅，不愛萬金之資，為韓報讎強秦，天下振動。今以三寸舌為帝者師，封萬戶侯，此布衣之極，於良足矣。願棄人間事，欲從赤松子游耳。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-14c', '資治通鑑', 11, 202, '高帝五年', '己亥', 14, 'commentary', 'heading', '[]'::jsonb, '臣光曰：夫生之有死，譬猶夜旦之必然；自古及今，固未嘗有超然而獨存者也。以子房之明辨達理，足以知神仙之為虛詭矣；然其欲從赤松子游者，其智可知也。夫功名之際，人臣之所難處。如高帝所稱者，三傑而已。淮陰誅夷，蕭何繫獄，非以履盛滿而不止耶！故子房托於神仙，遺棄人間，等功名於外物，置榮利而不顧，所謂明哲保身者，子房有焉。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-15', '資治通鑑', 11, 202, '高帝五年', '己亥', 15, 'narrative', 'heading', '[6]'::jsonb, '六月，壬辰，大赦天下。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-16', '資治通鑑', 11, 202, '高帝五年', '己亥', 16, 'narrative', 'heading', '[7]'::jsonb, '秋，七月，燕王臧荼反；上自將征之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-17', '資治通鑑', 11, 202, '高帝五年', '己亥', 17, 'narrative', 'heading', '[]'::jsonb, '趙景王耳、長沙文王芮皆薨。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-18', '資治通鑑', 11, 202, '高帝五年', '己亥', 18, 'narrative', 'heading', '[9]'::jsonb, '九月，虜藏荼。壬子，立太尉長安侯盧綰為燕王。綰家與上同里，綰生又與上同日；上寵幸綰，群臣莫敢望，故特王之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-19', '資治通鑑', 11, 202, '高帝五年', '己亥', 19, 'narrative', 'heading', '[]'::jsonb, '項羽故將利幾反，上自擊破之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-20', '資治通鑑', 11, 202, '高帝五年', '己亥', 20, 'narrative', 'heading', '[9]'::jsonb, '後九月，治長樂宮。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('tj-011-202-21', '資治通鑑', 11, 202, '高帝五年', '己亥', 21, 'narrative', 'heading', '[]'::jsonb, '項王將鐘離昧，素與楚王信善。項王死後，亡歸信。漢王怨昧，聞其在楚，詔楚捕昧。信初之國，行縣邑，陳兵出入。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-003', '史記', 7, 209, '項羽本紀·秦二世元年七月，', '', 3, 'narrative', 'marker', '[7, 9]'::jsonb, '秦二世元年七月，陳涉等起大澤中。其九月，會稽守通謂梁曰：「江西皆反，此亦天亡秦之時也。吾聞先即制人，後則為人所制。吾欲發兵，使公及桓楚將。」是時桓楚亡在澤中。梁曰：「桓楚亡，人莫知其處，獨籍知之耳。」梁乃出，誡籍持劍居外待。梁復入，與守坐，曰：「請召籍，使受命召桓楚。」守曰：「諾。」梁召籍入。須臾，梁眴籍曰：「可行矣！」於是籍遂拔劍斬守頭。項梁持守頭，佩其印綬。門下大驚，擾亂，籍所擊殺數十百人。一府中皆慴伏，莫敢起。梁乃召故所知豪吏，諭以所為起大事，遂舉吳中兵。使人收下縣，得精兵八千人。梁部署吳中豪傑為校尉、候、司馬。有一人不得用，自言於梁。梁曰：「前時某喪使公主某事，不能辦，以此不任用公。」眾乃皆伏。於是梁為會稽守，籍為裨將，徇下縣。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-003', 'wu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-004', '史記', 7, 209, '項羽本紀·秦二世元年七月，', '', 4, 'narrative', 'carried', '[]'::jsonb, '廣陵人召平於是為陳王徇廣陵，未能下。聞陳王敗走，秦兵又且至，乃渡江矯陳王命，拜梁為楚王上柱國。曰：「江東已定，急引兵西擊秦。」項梁乃以八千人渡江而西。聞陳嬰已下東陽，使使欲與連和俱西。陳嬰者，故東陽令史，居縣中，素信謹，稱為長者。東陽少年殺其令，相聚數千人，欲置長，無適用，乃請陳嬰。嬰謝不能，遂彊立嬰為長，縣中從者得二萬人。少年欲立嬰便為王，異軍蒼頭特起。陳嬰母謂嬰曰：「自我為汝家婦，未嘗聞汝先古之有貴者。今暴得大名，不祥。不如有所屬，事成猶得封侯，事敗易以亡，非世所指名也。」嬰乃不敢為王。謂其軍吏曰：「項氏世世將家，有名於楚。今欲舉大事，將非其人，不可。我倚名族，亡秦必矣。」於是眾從其言，以兵屬項梁。項梁渡淮，黥布、蒲將軍亦以兵屬焉。凡六七萬人，軍下邳。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-005', '史記', 7, 209, '項羽本紀·秦二世元年七月，', '', 5, 'narrative', 'carried', '[]'::jsonb, '當是時，秦嘉已立景駒為楚王，軍彭城東，欲距項梁。項梁謂軍吏曰：「陳王先首事，戰不利，未聞所在。今秦嘉倍陳王而立景駒，逆無道。」乃進兵擊秦嘉。秦嘉軍敗走，追之至胡陵。嘉還戰一日，嘉死，軍降。景駒走死梁地。項梁已幷秦嘉軍，軍胡陵，將引軍而西。章邯軍至栗，項梁使別將朱雞石、餘樊君與戰。餘樊君死。朱雞石軍敗，亡走胡陵。項梁乃引兵入薛，誅雞石。項梁前使項羽別攻襄城，襄城堅守不下。已拔，皆阬之。還報項梁。項梁聞陳王定死，召諸別將會薛計事。此時沛公亦起沛，往焉。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-005', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-005', 'xue', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-005', 'pei', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-006', '史記', 7, 208, '項羽本紀·繫於「立楚懷王孫心」', '', 6, 'narrative', 'event_keyword', '[]'::jsonb, '居鄛人范增，年七十，素居家，好奇計，往說項梁曰：「陳勝敗固當。夫秦滅六國，楚最無罪。自懷王入秦不反，楚人憐之至今，故楚南公曰『楚雖三戶，亡秦必楚』也。今陳勝首事，不立楚後而自立，其勢不長。今君起江東，楚蠭起之將皆爭附君者，以君世世楚將，為能復立楚之後也。」於是項梁然其言，乃求楚懷王孫心民間，為人牧羊，立以為楚懷王，從民所望也。陳嬰為楚上柱國，封五縣，與懷王都盱台。項梁自號為武信君。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-007', '史記', 7, 208, '項羽本紀·繫於「項梁敗死定陶」', '', 7, 'narrative', 'event_keyword', '[]'::jsonb, '居數月，引兵攻亢父，與齊田榮、司馬龍且軍救東阿，大破秦軍於東阿。田榮即引兵歸，逐其王假。假亡走楚。假相田角亡走趙。角弟田閒故齊將，居趙不敢歸。田榮立田儋子市為齊王。項梁已破東阿下軍，遂追秦軍。數使使趣齊兵，欲與俱西。田榮曰：「楚殺田假，趙殺田角、田閒，乃發兵。」項梁曰：「田假為與國之王，窮來從我，不忍殺之。」趙亦不殺田角、田閒以市於齊。齊遂不肯發兵助楚。項梁使沛公及項羽別攻城陽，屠之。西破秦軍濮陽東，秦兵收入濮陽。沛公、項羽乃攻定陶。定陶未下，去，西略地至雝丘，大破秦軍，斬李由。還攻外黃，外黃未下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-007', 'donge', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-007', 'puyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-007', 'dingtao', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-008', '史記', 7, 208, '項羽本紀·繫於「項梁敗死定陶」', '', 8, 'narrative', 'event_keyword', '[]'::jsonb, '項梁起東阿，西，（北）［比］至定陶，再破秦軍，項羽等又斬李由，益輕秦，有驕色。宋義乃諫項梁曰：「戰勝而將驕卒惰者敗。今卒少惰矣，秦兵日益，臣為君畏之。」項梁弗聽。乃使宋義使於齊。道遇齊使者高陵君顯，曰：「公將見武信君乎？」曰：「然。」曰：「臣論武信君軍必敗。公徐行即免死，疾行則及禍。」秦果悉起兵益章邯，擊楚軍，大破之定陶，項梁死。沛公、項羽去外黃攻陳留，陳留堅守不能下。沛公、項羽相與謀曰：「今項梁軍破，士卒恐。」乃與呂臣軍俱引兵而東。呂臣軍彭城東，項羽軍彭城西，沛公軍碭。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-008', 'donge', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-008', 'dingtao', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-008', 'chenliu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-008', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-009', '史記', 7, 208, '項羽本紀·繫於「項梁敗死定陶」', '', 9, 'narrative', 'carried', '[]'::jsonb, '章邯已破項梁軍，則以為楚地兵不足憂，乃渡河擊趙，大破之。當此時，趙歇為王，陳餘為將，張耳為相，皆走入鉅鹿城。章邯令王離、涉閒圍鉅鹿，章邯軍其南，筑甬道而輸之粟。陳餘為將，將卒數萬人而軍鉅鹿之北，此所謂河北之軍也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-009', 'julu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-010', '史記', 7, 208, '項羽本紀·繫於「項梁敗死定陶」', '', 10, 'narrative', 'carried', '[]'::jsonb, '楚兵已破於定陶，懷王恐，從盱台之彭城，并項羽、呂臣軍自將之。以呂臣為司徒，以其父呂青為令尹。以沛公為碭郡長，封為武安侯，將碭郡兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-010', 'dingtao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-010', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-011', '史記', 7, 208, '項羽本紀·繫於「項梁敗死定陶」', '', 11, 'narrative', 'carried', '[]'::jsonb, '初，宋義所遇齊使者高陵君顯在楚軍，見楚王曰：「宋義論武信君之軍必敗，居數日，軍果敗。兵未戰而先見敗徵，此可謂知兵矣。」王召宋義與計事而大說之，因置以為上將軍，項羽為魯公，為次將，范增為末將，救趙。諸別將皆屬宋義，號為卿子冠軍。行至安陽，留四十六日不進。項羽曰：「吾聞秦軍圍趙王鉅鹿，疾引兵渡河，楚擊其外，趙應其內，破秦軍必矣。」宋義曰：「不然。夫搏牛之蝱不可以破蟣蝨。今秦攻趙，戰勝則兵罷，我承其敝；不勝，則我引兵鼓行而西，必舉秦矣。故不如先鬬秦趙。夫被堅執銳，義不如公；坐而運策，公不如義。」因下令軍中曰：「猛如虎，很如羊，貪如狼，彊不可使者，皆斬之。」乃遣其子宋襄相齊，身送之至無鹽，飲酒高會。天寒大雨，士卒凍飢。項羽曰：「將戮力而攻秦，久留不行。今歲饑民貧，士卒食芋菽，軍無見糧，乃飲酒高會，不引兵渡河因趙食，與趙并力攻秦，乃曰『承其敝』。夫以秦之彊，攻新造之趙，其勢必舉趙。趙舉而秦彊，何敝之承！且國兵新破，王坐不安席，埽境內而專屬於將軍，國家安危，在此一舉。今不恤士卒而徇其私，非社稷之臣。」項羽晨朝上將軍宋義，即其帳中斬宋義頭，出令軍中曰：「宋義與齊謀反楚，楚王陰令羽誅之。」當是時，諸將皆慴服，莫敢枝梧。皆曰：「首立楚者，將軍家也。今將軍誅亂。」乃相與共立羽為假上將軍。使人追宋義子，及之齊，殺之。使桓楚報命於懷王。懷王因使項羽為上將軍，當陽君、蒲將軍皆屬項羽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-011', 'julu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-012', '史記', 7, 207, '項羽本紀·繫於「鉅鹿之戰」', '', 12, 'narrative', 'event_keyword', '[]'::jsonb, '項羽已殺卿子冠軍，威震楚國，名聞諸侯。乃遣當陽君、蒲將軍將卒二萬渡河，救鉅鹿。戰少利，陳餘復請兵。項羽乃悉引兵渡河，皆沈船，破釜甑，燒廬舍，持三日糧，以示士卒必死，無一還心。於是至則圍王離，與秦軍遇，九戰，絕其甬道，大破之，殺蘇角，虜王離。涉閒不降楚，自燒殺。當是時，楚兵冠諸侯。諸侯軍救鉅鹿下者十餘壁，莫敢縱兵。及楚擊秦，諸將皆從壁上觀。楚戰士無不一以當十，楚兵呼聲動天，諸侯軍無不人人惴恐。於是已破秦軍，項羽召見諸侯將，入轅門，無不膝行而前，莫敢仰視。項羽由是始為諸侯上將軍，諸侯皆屬焉。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-012', 'julu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-013', '史記', 7, 207, '項羽本紀·繫於「鉅鹿之戰」', '', 13, 'narrative', 'carried', '[]'::jsonb, '章邯軍棘原，項羽軍漳南，相持未戰。秦軍數卻，二世使人讓章邯。章邯恐，使長史欣請事。至咸陽，留司馬門三日，趙高不見，有不信之心。長史欣恐，還走其軍，不敢出故道，趙高果使人追之，不及。欣至軍，報曰：「趙高用事於中，下無可為者。今戰能勝，高必疾妒吾功；戰不能勝，不免於死。願將軍孰計之。」陳餘亦遺章邯書曰：「白起為秦將，南征鄢郢，北阬馬服，攻城略地，不可勝計，而竟賜死。蒙恬為秦將，北逐戎人，開榆中地數千里，竟斬陽周。何者？功多，秦不能盡封，因以法誅之。今將軍為秦將三歲矣，所亡失以十萬數，而諸侯并起滋益多。彼趙高素諛日久，今事急，亦恐二世誅之，故欲以法誅將軍以塞責，使人更代將軍以脫其禍。夫將軍居外久，多內卻，有功亦誅，無功亦誅。且天之亡秦，無愚智皆知之。今將軍內不能直諫，外為亡國將，孤特獨立而欲常存，豈不哀哉！將軍何不還兵與諸侯為從，約共攻秦，分王其地，南面稱孤；此孰與身伏鈇質，妻子為僇乎？」章邯狐疑，陰使候始成使項羽，欲約。約未成，項羽使蒲將軍日夜引兵度三戶，軍漳南，與秦戰，再破之。項羽悉引兵擊秦軍汙水上，大破之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-013', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-014', '史記', 7, 207, '項羽本紀·繫於「鉅鹿之戰」', '', 14, 'narrative', 'carried', '[]'::jsonb, '章邯使人見項羽，欲約。項羽召軍吏謀曰：「糧少，欲聽其約。」軍吏皆曰：「善。」項羽乃與期洹水南殷虛上。已盟，章邯見項羽而流涕，為言趙高。項羽乃立章邯為雍王，置楚軍中。使長史欣為上將軍，將秦軍為前行。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-015', '史記', 7, 206, '項羽本紀·繫於「新安坑卒」', '', 15, 'narrative', 'event_keyword', '[]'::jsonb, '到新安。諸侯吏卒異時故繇使屯戍過秦中，秦中吏卒遇之多無狀，及秦軍降諸侯，諸侯吏卒乘勝多奴虜使之，輕折辱秦吏卒。秦吏卒多竊言曰：「章將軍等詐吾屬降諸侯，今能入關破秦，大善；即不能，諸侯虜吾屬而東，秦必盡誅吾父母妻子。」諸侯微聞其計，以告項羽。項羽乃召黥布、蒲將軍計曰：「秦吏卒尚眾，其心不服，至關中不聽，事必危，不如擊殺之，而獨與章邯、長史欣、都尉翳入秦。」於是楚軍夜擊阬秦卒二十餘萬人新安城南。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-015', 'xinan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-016', '史記', 7, 206, '項羽本紀·繫於「鴻門宴」', '', 16, 'narrative', 'event_keyword', '[]'::jsonb, '行略定秦地。函谷關有兵守關，不得入。又聞沛公已破咸陽，項羽大怒，使當陽君等擊關。項羽遂入，至于戲西。沛公軍霸上，未得與項羽相見。沛公左司馬曹無傷使人言於項羽曰：「沛公欲王關中，使子嬰為相，珍寶盡有之。」項羽大怒，曰：「旦日饗士卒，為擊破沛公軍！」當是時，項羽兵四十萬，在新豐鴻門，沛公兵十萬，在霸上。范增說項羽曰：「沛公居山東時，貪於財貨，好美姬。今入關，財物無所取，婦女無所幸，此其志不在小。吾令人望其氣，皆為龍虎，成五采，此天子氣也。急擊勿失。」');
