INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-017', '史記', 7, 206, '項羽本紀·繫於「鴻門宴」', '', 17, 'narrative', 'carried', '[]'::jsonb, '楚左尹項伯者，項羽季父也，素善留侯張良。張良是時從沛公，項伯乃夜馳之沛公軍，私見張良，具告以事，欲呼張良與俱去。曰：「毋從俱死也。」張良曰：「臣為韓王送沛公，沛公今事有急，亡去不義，不可不語。」良乃入，具告沛公。沛公大驚，曰：「為之柰何？」張良曰：「誰為大王為此計者？」曰：「鯫生說我曰『距關，毋內諸侯，秦地可盡王也』。故聽之。」良曰：「料大王士卒足以當項王乎？」沛公默然，曰：「固不如也，且為之柰何？」張良曰：「請往謂項伯，言沛公不敢背項王也。」沛公曰：「君安與項伯有故？」張良曰：「秦時與臣游，項伯殺人，臣活之。今事有急，故幸來告良。」沛公曰「孰與君少長？」良曰：「長於臣。」沛公曰「君為我呼入，吾得兄事之。」張良出，要項伯。項伯即入見沛公。沛公奉巵酒為壽，約為婚姻，曰：「吾入關，秋豪不敢有所近，籍吏民，封府庫，而待將軍。所以遣將守關者，備他盜之出入與非常也。日夜望將軍至，豈敢反乎！願伯具言臣之不敢倍德也。」項伯許諾。謂沛公曰：「旦日不可不蚤自來謝項王。」沛公曰：「諾。」於是項伯復夜去，至軍中，具以沛公言報項王。因言曰：「沛公不先破關中，公豈敢入乎？今人有大功而擊之，不義也，不如因善遇之。」項王許諾。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-018', '史記', 7, 206, '項羽本紀·繫於「鴻門宴」', '', 18, 'narrative', 'event_keyword', '[]'::jsonb, '沛公旦日從百餘騎來見項王，至鴻門，謝曰：「臣與將軍戮力而攻秦，將軍戰河北，臣戰河南，然不自意能先入關破秦，得復見將軍於此。今者有小人之言，令將軍與臣有郤。」項王曰：「此沛公左司馬曹無傷言之；不然，籍何以至此。」項王即日因留沛公與飲。項王、項伯東嚮坐。亞父南嚮坐。亞父者，范增也。沛公北嚮坐，張良西向侍。范增數目項王，舉所佩玉珪以示之者三，項王默然不應。范增起，出召項莊，謂曰：「君王為人不忍，若入前為壽，壽畢，請以劍舞，因擊沛公於坐，殺之。不者，若屬皆且為所虜。」莊則入為壽，壽畢，曰：「君王與沛公飲，軍中無以為樂，請以劍舞。」項王曰：「諾。」項莊拔劍起舞，項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊。於是張良至軍門，見樊噲。樊噲曰：「今日之事何如？」良曰：「甚急。今者項莊拔劍舞，其意常在沛公也。」噲曰：「此迫矣，臣請入，與之同命。」噲即帶劍擁盾入軍門。交戟之衛士欲止不內，樊噲側其盾以撞，衛士仆地，噲遂入，披帷西向立，瞋目視項王，頭髪上指，目眥盡裂。項王按劍而跽曰：「客何為者？」張良曰：「沛公之參乘樊噲者也。」項王曰：「壯士，賜之巵酒。」則與斗巵酒。噲拜謝，起，立而飲之。項王曰：「賜之彘肩。」則與一生彘肩。樊噲覆其盾於地，加彘肩上，拔劍切而㗖之。項王曰：「壯士，能復飲乎？」樊噲曰：「臣死且不避，巵酒安足辭！夫秦王有虎狼之心，殺人如不能舉，刑人如恐不勝，天下皆叛之。懷王與諸將約曰『先破秦入咸陽者王之』。今沛公先破秦入咸陽，豪毛不敢有所近，封閉宮室，還軍霸上，以待大王來。故遣將守關者，備他盜出入與非常也。勞苦而功高如此，未有封侯之賞，而聽細說，欲誅有功之人。此亡秦之續耳，竊為大王不取也。」項王未有以應，曰：「坐。」樊噲從良坐。坐須臾，沛公起如廁，因招樊噲出。');
