INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-022', '史記', 7, 206, '項羽本紀·漢之元年四月，諸', '', 22, 'narrative', 'marker', '[4]'::jsonb, '漢之元年四月，諸侯罷戲下，各就國。項王出之國，使人徙義帝，曰：「古之帝者地方千里，必居上游。」乃使使徙義帝長沙郴縣。趣義帝行，其群臣稍稍背叛之，乃陰令衡山、臨江王擊殺之江中。韓王成無軍功，項王不使之國，與俱至彭城，廢以為侯，已又殺之。臧荼之國，因逐韓廣之遼東，廣弗聽，荼擊殺廣無終，並王其地。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-022', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-022', 'wuzhong', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-023', '史記', 7, 206, '項羽本紀·漢之元年四月，諸', '', 23, 'narrative', 'carried', '[]'::jsonb, '田榮聞項羽徙齊王市膠東，而立齊將田都為齊王，乃大怒，不肯遣齊王之膠東，因以齊反，迎擊田都。田都走楚。齊王市畏項王，乃亡之膠東就國。田榮怒，追擊殺之即墨。榮因自立為齊王，而西殺擊濟北王田安，并王三齊。榮與彭越將軍印，令反梁地。陳餘陰使張同、夏說說齊王田榮曰：「項羽為天下宰，不平。今盡王故王於醜地，而王其群臣諸將善地，逐其故主趙王，乃北居代，餘以為不可。聞大王起兵，且不聽不義，願大王資餘兵，請以擊常山，以復趙王，請以國為捍蔽。」齊王許之，因遣兵之趙。陳餘悉發三縣兵，與齊并力擊常山，大破之。張耳走歸漢。陳餘迎故趙王歇於代，反之趙。趙王因立陳餘為代王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-023', 'jimo', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-024a', '史記', 7, 206, '項羽本紀·漢之元年四月，諸', '', 24, 'narrative', 'carried', '[]'::jsonb, '是時，漢還定三秦。項羽聞漢王皆已并關中，且東，齊、趙叛之：大怒。乃以故吳令鄭昌為韓王，以距漢。令蕭公角等擊彭越。彭越敗蕭公角等。漢使張良徇韓，乃遺項王書曰：「漢王失職，欲得關中，如約即止，不敢東。」又以齊、梁反書遺項王曰：「齊欲與趙并滅楚。」楚以此故無西意，而北擊齊。徵兵九江王布。布稱疾不往，使將將數千人行。項王由此怨布也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-024b', '史記', 7, 205, '項羽本紀·漢之二年冬，項羽', '', 24, 'narrative', 'marker', '[]'::jsonb, '漢之二年冬，項羽遂北至城陽，田榮亦將兵會戰。田榮不勝，走至平原，平原民殺之。遂北燒夷齊城郭室屋，皆阬田榮降卒，系虜其老弱婦女。徇齊至北海，多所殘滅。齊人相聚而叛之。於是田榮弟田橫收齊亡卒得數萬人，反城陽。項王因留，連戰未能下。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-025', '史記', 7, 205, '項羽本紀·繫於「彭城之戰」', '', 25, 'narrative', 'event_keyword', '[4]'::jsonb, '春，漢王部五諸侯兵，凡五十六萬人，東伐楚。項王聞之，即令諸將擊齊，而自以精兵三萬人南從魯出胡陵。四月，漢皆已入彭城，收其貨寶美人，日置酒高會。項王乃西從蕭，晨擊漢軍而東，至彭城，日中，大破漢軍。漢軍皆走，相隨入穀、泗水，殺漢卒十餘萬人。漢卒皆南走山，楚又追擊至靈壁東睢水上。漢軍卻，為楚所擠，多殺，漢卒十餘萬人皆入睢水，睢水為之不流。圍漢王三匝。於是大風從西北而起，折木發屋，揚沙石，窈冥晝晦，逢迎楚軍。楚軍大亂，壞散，而漢王乃得與數十騎遁去，欲過沛，收家室而西；楚亦使人追之沛，取漢王家：家皆亡，不與漢王相見。漢王道逢得孝惠、魯元，乃載行。楚騎追漢王，漢王急，推墮孝惠、魯元車下，滕公常下收載之。如是者三。曰：「雖急不可以驅，柰何棄之？」於是遂得脫。求太公、呂后不相遇。審食其從太公、呂后閒行，求漢王，反遇楚軍。楚軍遂與歸，報項王，項王常置軍中。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-025', 'pengcheng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-025', 'lingbi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-025', 'pei', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-026', '史記', 7, 205, '項羽本紀·繫於「彭城之戰」', '', 26, 'narrative', 'carried', '[]'::jsonb, '是時呂后兄周呂侯為漢將兵居下邑，漢王閒往從之，稍稍收其士卒。至滎陽，諸敗軍皆會，蕭何亦發關中老弱未傅悉詣滎陽，復大振。楚起於彭城，常乘勝逐北，與漢戰滎陽南京、索閒，漢敗楚，楚以故不能過滎陽而西。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-026', 'xiayi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-026', 'xingyang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-026', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-027a', '史記', 7, 205, '項羽本紀·繫於「彭城之戰」', '', 27, 'narrative', 'carried', '[]'::jsonb, '項王之救彭城，追漢王至滎陽，田橫亦得收齊，立田榮子廣為齊王。漢王之敗彭城，諸侯皆復與楚而背漢。漢軍滎陽，築甬道屬之河，以取敖倉粟。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-027a', 'pengcheng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-027a', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-027a', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-027b', '史記', 7, 204, '項羽本紀·漢之三年，項王數', '', 27, 'narrative', 'marker', '[]'::jsonb, '漢之三年，項王數侵奪漢甬道，漢王食乏，恐，請和，割滎陽以西為漢。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-027b', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-028', '史記', 7, 204, '項羽本紀·漢之三年，項王數', '', 28, 'narrative', 'carried', '[]'::jsonb, '項王欲聽之。歷陽侯范增曰：「漢易與耳，今釋弗取，後必悔之。」項王乃與范增急圍滎陽。漢王患之，乃用陳平計閒項王。項王使者來，為太牢具，舉欲進之。見使者，詳驚愕曰：「吾以為亞父使者，乃反項王使者。」更持去，以惡食食項王使者。使者歸報項王，項王乃疑范增與漢有私，稍奪之權。范增大怒，曰：「天下事大定矣，君王自為之。願賜骸骨歸卒伍。」項王許之。行未至彭城，疽發背而死。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-028', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-028', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-029', '史記', 7, 204, '項羽本紀·繫於「滎陽之圍，紀信誑楚」', '', 29, 'narrative', 'event_keyword', '[]'::jsonb, '漢將紀信說漢王曰：「事已急矣，請為王誑楚為王，王可以閒出。」於是漢王夜出女子滎陽東門被甲二千人，楚兵四面擊之。紀信乘黃屋車，傅左纛，曰：「城中食盡，漢王降。」楚軍皆呼萬歲。漢王亦與數十騎從城西門出，走成皋。項王見紀信，問：「漢王安在？」曰：「漢王已出矣。」項王燒殺紀信。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-029', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-029', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-030', '史記', 7, 204, '項羽本紀·繫於「滎陽之圍，紀信誑楚」', '', 30, 'narrative', 'carried', '[]'::jsonb, '漢王使御史大夫周苛、樅公、魏豹守滎陽。周苛、樅公謀曰：「反國之王，難與守城。」乃共殺魏豹。楚下滎陽城，生得周苛。項王謂周苛曰：「為我將，我以公為上將軍，封三萬戶。」周苛罵曰：「若不趣降漢，漢今虜若，若非漢敵也。」項王怒，烹周苛，井殺樅公。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-030', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-031a', '史記', 7, 204, '項羽本紀·繫於「滎陽之圍，紀信誑楚」', '', 31, 'narrative', 'carried', '[]'::jsonb, '漢王之出滎陽，南走宛、葉，得九江王布，行收兵，復入保成皋。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-031a', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-031a', 'wan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-031a', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-031b', '史記', 7, 203, '項羽本紀·漢之四年，項王進', '', 31, 'narrative', 'marker', '[]'::jsonb, '漢之四年，項王進兵圍成皋。漢王逃，獨與滕公出成皋北門，渡河走修武，從張耳、韓信軍。諸將稍稍得出成皋，從漢王。楚遂拔成皋，欲西。漢使兵距之鞏，令其不得西。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-031b', 'chenggao', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-031b', 'xiuwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-032', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 32, 'narrative', 'event_keyword', '[]'::jsonb, '是時，彭越渡河擊楚東阿，殺楚將軍薛公。項王乃自東擊彭越。漢王得淮陰侯兵，欲渡河南。鄭忠說漢王，乃止壁河內。使劉賈將兵佐彭越，燒楚積聚。項王東擊破之，走彭越。漢王則引兵渡河，復取成皋，軍廣武，就敖倉食。項王已定東海來，西，與漢俱臨廣武而軍，相守數月。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-032', 'donge', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-032', 'chenggao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-032', 'guangwu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-032', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-033', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 33, 'narrative', 'carried', '[]'::jsonb, '當此時，彭越數反梁地，絕楚糧食，項王患之。為高俎，置太公其上，告漢王曰：「今不急下，吾烹太公。」漢王曰：「吾與項羽俱北面受命懷王，曰『約為兄弟』，吾翁即若翁，必欲烹而翁，則幸分我一桮羹。」項王怒，欲殺之。項伯曰：「天下事未可知，且為天下者不顧家，雖殺之無益，秪益禍耳。」項王從之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-034', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 34, 'narrative', 'event_keyword', '[]'::jsonb, '楚漢久相持未決，丁壯苦軍旅，老弱罷轉漕。項王謂漢王曰：「天下匈匈數歲者，徒以吾兩人耳，願與漢王挑戰決雌雄，毋徒苦天下之民父子為也。」漢王笑謝曰：「吾寧鬬智，不能鬬力。」項王令壯士出挑戰。漢有善騎射者樓煩，楚挑戰三合，樓煩輒射殺之。項王大怒，乃自被甲持戟挑戰。樓煩欲射之，項王瞋目叱之，樓煩目不敢視，手不敢發，遂走還入壁，不敢復出。漢王使人閒問之，乃項王也。漢王大驚。於是項王乃即漢王相與臨廣武閒而語。漢王數之，項王怒，欲一戰。漢王不聽，項王伏弩射中漢王。漢王傷，走入成皋。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-034', 'guangwu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-034', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-035', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 35, 'narrative', 'carried', '[]'::jsonb, '項王聞淮陰侯已舉河北，破齊、趙，且欲擊楚，乃使龍且往擊之。淮陰侯與戰，騎將灌嬰擊之，大破楚軍，殺龍且。韓信因自立為齊王。項王聞龍且軍破，則恐，使盱台人武涉往說淮陰侯。淮陰侯弗聽。是時，彭越復反，下梁地，絕楚糧。項王乃謂海春侯大司馬曹咎等曰：「謹守成皋，則漢欲挑戰，慎勿與戰，毋令得東而已。我十五日必誅彭越，定梁地，復從將軍。」乃東，行擊陳留、外黃。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-035', 'chenggao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-035', 'chenliu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-036', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 36, 'narrative', 'carried', '[]'::jsonb, '外黃不下。數日，已降，項王怒，悉令男子年十五已上詣城東，欲阬之。外黃令舍人兒年十三，往說項王曰：「彭越彊劫外黃，外黃恐，故且降，待大王。大王至，又皆阬之，百姓豈有歸心？從此以東，梁地十餘城皆恐，莫肯下矣。」項王然其言，乃赦外黃當阬者。東至睢陽，聞之皆爭下項王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-037', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 37, 'narrative', 'carried', '[]'::jsonb, '漢果數挑楚軍戰，楚軍不出。使人辱之，五六日，大司馬怒，渡兵汜水。士卒半渡，漢擊之，大破楚軍，盡得楚國貨賂。大司馬咎、長史翳、塞王欣皆自剄汜水上。大司馬咎者，故蘄獄掾，長史欣亦故櫟陽獄吏，兩人嘗有德於項梁，是以項王信任之。當是時，項王在睢陽，聞海春侯軍敗，則引兵還。漢軍方圍鐘離眛於滎陽東，項王至，漢軍畏楚，盡走險阻。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-037', 'yueyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-037', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-038', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 38, 'narrative', 'carried', '[]'::jsonb, '是時，漢兵盛食多，項王兵罷食絕。漢遣陸賈說項王，請太公，項王弗聽。漢王復使侯公往說項王，項王乃與漢約，中分天下，割鴻溝以西者為漢，鴻溝而東者為楚。項王許之，即歸漢王父母妻子。軍皆呼萬歲。漢王乃封侯公為平國君。匿弗肯復見。曰：「此天下辯士，所居傾國，故號為平國君。」項王已約，乃引兵解而東歸。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-038', 'honggou', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-039a', '史記', 7, 203, '項羽本紀·繫於「廣武對峙」', '', 39, 'narrative', 'carried', '[]'::jsonb, '漢欲西歸，張良、陳平說曰：「漢有天下太半，而諸侯皆附之。楚兵罷食盡，此天亡楚之時也，不如因其機而遂取之。今釋弗擊，此所謂『養虎自遺患』也。」漢王聽之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-039b', '史記', 7, 202, '項羽本紀·漢五年，漢王乃追', '', 39, 'narrative', 'marker', '[]'::jsonb, '漢五年，漢王乃追項王至陽夏南，止軍，與淮陰侯韓信、建成侯彭越期會而擊楚軍。至固陵，而信、越之兵不會。楚擊漢軍，大破之。漢王復入壁，深塹而自守。謂張子房曰：「諸侯不從約，為之柰何？」對曰：「楚兵且破，信、越未有分地，其不至固宜。君王能與共分天下，今可立致也。即不能，事未可知也。君王能自陳以東傅海，盡與韓信；睢陽以北至穀城，以與彭越：使各自為戰，則楚易敗也。」漢王曰：「善。」於是乃發使者告韓信、彭越曰：「并力擊楚。楚破，自陳以東傅海與齊王，睢陽以北至穀城與彭相國。」使者至，韓信、彭越皆報曰：「請今進兵。」韓信乃從齊往，劉賈軍從壽春并行，屠城父，至垓下。大司馬周殷叛楚，以舒屠六，舉九江兵，隨劉賈、彭越皆會垓下，詣項王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-039b', 'guling', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-039b', 'gaixia', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-040', '史記', 7, 202, '項羽本紀·繫於「垓下之圍」', '', 40, 'narrative', 'event_keyword', '[]'::jsonb, '項王軍壁垓下，兵少食盡，漢軍及諸侯兵圍之數重。夜聞漢軍四面皆楚歌，項王乃大驚曰：「漢皆已得楚乎？是何楚人之多也！」項王則夜起，飲帳中。有美人名虞，常幸從；駿馬名騅，常騎之。於是項王乃悲歌忼慨，自為詩曰：「力拔山兮氣蓋世，時不利兮騅不逝。騅不逝兮可柰何，虞兮虞兮柰若何！」歌數闋，美人和之。項王泣數行下，左右皆泣，莫能仰視。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-040', 'gaixia', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-041', '史記', 7, 202, '項羽本紀·繫於「垓下之圍」', '', 41, 'narrative', 'carried', '[]'::jsonb, '於是項王乃上馬騎，麾下壯士騎從者八百餘人，直夜潰圍南出，馳走。平明，漢軍乃覺之，令騎將灌嬰以五千騎追之。項王渡淮，騎能屬者百餘人耳。項王至陰陵，迷失道，問一田父，田父紿曰「左」。左，乃陷大澤中。以故漢追及之。項王乃復引兵而東，至東城，乃有二十八騎。漢騎追者數千人。項王自度不得脫。謂其騎曰：「吾起兵至今八歲矣，身七十餘戰，所當者破，所擊者服，未嘗敗北，遂霸有天下。然今卒困於此，此天之亡我，非戰之罪也。今日固決死，願為諸君快戰，必三勝之，為諸君潰圍，斬將，刈旗，令諸君知天亡我，非戰之罪也。」乃分其騎以為四隊，四嚮。漢軍圍之數重。項王謂其騎曰：「吾為公取彼一將。」令四面騎馳下，期山東為三處。於是項王大呼馳下，漢軍皆披靡，遂斬漢一將。是時，赤泉侯為騎將，追項王，項王瞋目而叱之，赤泉侯人馬俱驚，辟易數里與其騎會為三處。漢軍不知項王所在，乃分軍為三，復圍之。項王乃馳，復斬漢一都尉，殺數十百人，復聚其騎，亡其兩騎耳。乃謂其騎曰：「何如？」騎皆伏曰：「如大王言。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-042', '史記', 7, 202, '項羽本紀·繫於「項羽自刎烏江」', '', 42, 'narrative', 'event_keyword', '[]'::jsonb, '於是項王乃欲東渡烏江。烏江亭長檥船待，謂項王曰：「江東雖小，地方千里，眾數十萬人，亦足王也。願大王急渡。今獨臣有船，漢軍至，無以渡。」項王笑曰：「天之亡我，我何渡為！且籍與江東子弟八千人渡江而西，今無一人還，縱江東父兄憐而王我，我何面目見之？縱彼不言，籍獨不愧於心乎？」乃謂亭長曰：「吾知公長者。吾騎此馬五歲，所當無敵，嘗一日行千里，不忍殺之，以賜公。」乃令騎皆下馬步行，持短兵接戰。獨籍所殺漢軍數百人。項王身亦被十餘創。顧見漢騎司馬呂馬童，曰：「若非吾故人乎？」馬童面之，指王翳曰：「此項王也。」項王乃曰：「吾聞漢購我頭千金，邑萬戶，吾為若德。」乃自刎而死。王翳取其頭，餘騎相蹂踐爭項王，相殺者數十人。最其後，郎中騎楊喜，騎司馬呂馬童，郎中呂勝、楊武各得其一體。五人共會其體，皆是。故分其地為五：封呂馬童為中水侯，封王翳為杜衍侯，封楊喜為赤泉侯，封楊武為吳防侯，封呂勝為涅陽侯。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-042', 'wujiang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-043', '史記', 7, 202, '項羽本紀·繫於「項羽自刎烏江」', '', 43, 'narrative', 'carried', '[]'::jsonb, '項王已死，楚地皆降漢，獨魯不下。漢乃引天下兵欲屠之，為其守禮義，為主死節，乃持項王頭視魯，魯父兄乃降。始，楚懷王初封項籍為魯公，及其死，魯最後下，故以魯公禮葬項王穀城。漢王為發哀，泣之而去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-044', '史記', 7, 202, '項羽本紀·繫於「項羽自刎烏江」', '', 44, 'narrative', 'carried', '[]'::jsonb, '諸項氏枝屬，漢王皆不誅。乃封項伯為射陽侯。桃侯、平皋侯、玄武侯皆項氏，賜姓劉氏。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-045', '史記', 7, 202, '項羽本紀·繫於「項羽自刎烏江」', '', 45, 'commentary', 'carried', '[]'::jsonb, '太史公曰：『吾聞之周生曰：「舜目蓋重瞳子」，又聞項羽亦重瞳子。羽豈其苗裔邪？何興之暴也？夫秦失其政，陳涉首難，豪傑蠭起，相與并爭，不可勝數。然羽非有尺寸，乘勢起隴畝之中，三年，遂將五諸侯滅秦，分裂天下而封王侯，政由羽出，號為霸王，位雖不終，近古以來未嘗有也。及羽背關懷楚，放逐義帝而自立，怨王侯叛己，難矣。自矜功伐，奮其私智而不師古，謂霸王之業，欲以力征經營天下，五年，卒亡其國，身死東城，尚不覺寤，而不自責，過矣。乃引「天亡我，非用兵之罪也」，豈不謬哉！』');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-007-046', '史記', 7, 202, '項羽本紀·繫於「項羽自刎烏江」', '', 46, 'commentary', 'carried', '[]'::jsonb, '亡秦鹿走，偽楚狐鳴。雲鬱沛谷，劍挺吳城。勳開魯甸，勢合碭兵。卿子無罪，亞父推誠。始救趙歇，終誅子嬰。違約王漢，背關懷楚。常遷上游，臣迫故主。靈壁大振，成皋久拒。戰非無功，天實不與。嗟彼蓋代，卒為凶豎。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-046', 'lingbi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-007-046', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-009', '史記', 8, 209, '高祖本紀·秦二世元年秋，陳', '', 9, 'narrative', 'marker', '[]'::jsonb, '秦二世元年秋，陳勝等起蘄，至陳而王，號為「張楚」。諸郡縣皆多殺其長吏以應陳涉。沛令恐，欲以沛應涉。掾、主吏蕭何、曹參乃曰：「君為秦吏，今欲背之，率沛子弟，恐不聽。願君召諸亡在外者，可得數百人，因劫眾，眾不敢不聽。」乃令樊噲召劉季。劉季之眾已數十百人矣。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-009', 'qi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-009', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-010', '史記', 8, 209, '高祖本紀·繫於「劉邦起兵於沛」', '', 10, 'narrative', 'event_keyword', '[]'::jsonb, '於是樊噲從劉季來。沛令後悔，恐其有變，乃閉城城守，欲誅蕭、曹。蕭、曹恐，踰城保劉季。劉季乃書帛射城上，謂沛父老曰：「天下苦秦久矣。今父老雖為沛令守，諸侯并起，今屠沛。沛今共誅令，擇子弟可立者立之，以應諸侯，則家室完。不然，父子俱屠，無為也。」父老乃率子弟共殺沛令，開城門迎劉季，欲以為沛令。劉季曰：「天下方擾，諸侯并起，今置將不善，壹敗塗地。吾非敢自愛，恐能薄，不能完父兄子弟。此大事，願更相推擇可者。」蕭、曹等皆文吏，自愛，恐事不就，後秦種族其家，盡讓劉季。諸父老皆曰：「平生所聞劉季諸珍怪，當貴，且卜筮之，莫如劉季最吉。」於是劉季數讓。眾莫敢為，乃立季為沛公。祠黃帝，祭蚩尤於沛庭，而釁鼓旗，幟皆赤。由所殺蛇白帝子，殺者赤帝子，故上赤。於是少年豪吏如蕭、曹、樊噲等皆為收沛子弟二三千人，攻胡陵、方與，還守豐。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-010', 'pei', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-010', 'feng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-011', '史記', 8, 208, '高祖本紀·秦二世二年，陳涉', '', 11, 'narrative', 'marker', '[]'::jsonb, '秦二世二年，陳涉之將周章軍西至戲而還。燕、趙、齊、魏皆自立為王。項氏起吳。秦泗川監平將兵圍豐，二日，出與戰，破之。命雍齒守豐，引兵之薛。泗州守壯敗於薛，走至戚，沛公左司馬得泗川守壯，殺之。沛公還軍亢父，至方與，（周市來攻方與）未戰。陳王使魏人周市略地。周市使人謂雍齒曰：「豐，故梁徙也。今魏地已定者數十城。齒今下魏，魏以齒為侯守豐。不下，且屠豐。」雍齒雅不欲屬沛公，及魏招之，即反為魏守豐。沛公引兵攻豐，不能取。沛公病，還之沛。沛公怨雍齒與豐子弟叛之，聞東陽甯君、秦嘉立景駒為假王，在留，乃往從之，欲請兵以攻豐。是時秦將章邯從陳，別將司馬夷將兵北定楚地，屠相，至碭。東陽甯君、沛公引兵西，與戰蕭西，不利。還收兵聚留，引兵攻碭，三日乃取碭。因收碭兵，得五六千人。攻下邑，拔之。還軍豐。聞項梁在薛，從騎百餘往見之。項梁益沛公卒五千人，五大夫將十人。沛公還，引兵攻豐。');
