INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-011', 'xiayi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-012', '史記', 8, 208, '高祖本紀·繫於「立楚懷王孫心」', '', 12, 'narrative', 'event_keyword', '[]'::jsonb, '從項梁月餘，項羽已拔襄城還。項梁盡召別將居薛。聞陳王定死，因立楚後懷王孫心為楚王，治盱臺。項梁號武信君。居數月，北攻亢父，救東阿，破秦軍。齊軍歸，楚獨追北，使沛公、項羽別攻城陽，屠之。軍濮陽之東，與秦軍戰，破之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-012', 'xue', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-012', 'donge', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-012', 'puyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-013', '史記', 8, 208, '高祖本紀·繫於「立楚懷王孫心」', '', 13, 'narrative', 'carried', '[]'::jsonb, '秦軍復振，守濮陽，環水。楚軍去而攻定陶，定陶未下。沛公與項羽西略地至雍丘之下，與秦軍戰，大破之，斬李由。還攻外黃，外黃未下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-013', 'puyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-013', 'dingtao', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-014', '史記', 8, 208, '高祖本紀·繫於「項梁敗死定陶」', '', 14, 'narrative', 'event_keyword', '[]'::jsonb, '項梁再破秦軍，有驕色。宋義諫，不聽。秦益章邯兵，夜銜枚擊項梁，大破之定陶，項梁死。沛公與項羽方攻陳留，聞項梁死，引兵與呂將軍俱東。呂臣軍彭城東，項羽軍彭城西，沛公軍碭。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-014', 'dingtao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-014', 'chenliu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-014', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-015', '史記', 8, 208, '高祖本紀·繫於「項梁敗死定陶」', '', 15, 'narrative', 'carried', '[]'::jsonb, '章邯已破項梁軍，則以為楚地兵不足憂，乃渡河，北擊趙，大破之。當是之時，趙歇為王，秦將王離圍之鉅鹿城，此所謂河北之軍也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-015', 'julu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-016', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 16, 'narrative', 'marker', '[]'::jsonb, '秦二世三年，楚懷王見項梁軍破，恐，徙盱臺都彭城，并呂臣、項羽軍自將之。以沛公為碭郡長，封為武安侯，將碭郡兵。封項羽為長安侯，號為魯公。呂臣為司徒，其父呂青為令尹。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-016', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-017', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 17, 'narrative', 'carried', '[]'::jsonb, '趙數請救，懷王乃以宋義為上將軍，項羽為次將，范增為末將，北救趙。令沛公西略地入關。與諸將約，先入定關中者王之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-018', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 18, 'narrative', 'carried', '[]'::jsonb, '當是時，秦兵彊，常乘勝逐北，諸將莫利先入關。獨項羽怨秦破項梁軍，奮，願與沛公西入關。懷王諸老將皆曰：「項羽為人彊悍猾賊。項羽嘗攻襄城，襄城無遺類，皆阬之，諸所過無不殘滅。且楚數進取，前陳王、項梁皆敗。不如更遣長者扶義而西，告諭秦父兄。秦父兄苦其主久矣，今誠得長者往，毋侵暴，宜可下。今項羽彊悍，今不可遣。獨沛公素寬大長者，可遣。」卒不許項羽，而遣沛公西略地，收陳王、項梁散卒。乃道碭至成陽，與杠裏秦軍夾壁，破（魏）［秦］二軍。楚軍出兵擊王離，大破之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-019', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 19, 'narrative', 'carried', '[]'::jsonb, '沛公引兵西，遇彭越昌邑，因與俱攻秦軍，戰不利。還至栗，遇剛武侯，奪其軍，可四千餘人，并之。與魏將皇欣、魏申徒武蒲之軍并攻昌邑，昌邑未拔。西過高陽。酈食其（謂）［為］監門，曰：「諸將過此者多，吾視沛公大人長者。」乃求見說沛公。沛公方踞床，使兩女子洗足。酈生不拜，長揖，曰：「足下必欲誅無道秦，不宜踞見長者。」於是沛公起，攝衣謝之，延上坐。食其說沛公襲陳留，得秦積粟。乃以酈食其為廣野君，酈商為將，將陳留兵，與偕攻開封，開封未拔。西與秦將楊熊戰白馬，又戰曲遇東，大破之。楊熊走之滎陽，二世使使者斬以徇。南攻潁陽，屠之。因張良遂略韓地轘轅。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-019', 'chenliu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-019', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-020', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 20, 'narrative', 'carried', '[]'::jsonb, '當是時，趙別將司馬卬方欲渡河入關，沛公乃北攻平陰，絕河津。南，戰雒陽東，軍不利，還至陽城，收軍中馬騎，與南陽守齮戰犨東，破之。略南陽郡，南陽守齮走，保城守宛。沛公引兵過而西。張良諫曰：「沛公雖欲急入關，秦兵尚眾，距險。今不下宛，宛從後擊，彊秦在前，此危道也。」於是沛公乃夜引兵從他道還，更旗幟，黎明，圍宛城三匝。南陽守欲自剄。其舍人陳恢曰：「死未晚也。」乃踰城見沛公，曰：「臣聞足下約，先入咸陽者王之。今足下留守宛。宛，大郡之都也，連城數十，人民眾，積蓄多，吏人自以為降必死，故皆堅守乘城。今足下盡日止攻，士死傷者必多；引兵去宛，宛必隨足下後：足下前則失咸陽之約，後又有彊宛之患。為足下計，莫若約降，封其守，因使止守，引其甲卒與之西。諸城未下者，聞聲爭開門而待，足下通行無所累。」沛公曰：「善。」乃以宛守為殷侯，封陳恢千戶。引兵西，無不下者。至丹水，高武侯鰓、襄侯王陵降西陵。還攻胡陽，遇番君別將梅鋗，與皆，降析、酈。遣魏人甯昌使秦，使者未來。是時章邯已以軍降項羽於趙矣。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-020', 'luoyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-020', 'wan', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-020', 'xianyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-021', '史記', 8, 207, '高祖本紀·秦二世三年，楚懷', '', 21, 'narrative', 'carried', '[]'::jsonb, '初，項羽與宋義北救趙，及項羽殺宋義，代為上將軍，諸將黥布皆屬，破秦將王離軍，降章邯，諸侯皆附。及趙高已殺二世，使人來，欲約分王關中。沛公以為詐，乃用張良計，使酈生、陸賈往說秦將，啗以利，因襲攻武關，破之。又與秦軍戰於藍田南，益張疑兵旗幟，諸所過毋得掠鹵，秦人喜，秦軍解，因大破之。又戰其北，大破之。乘勝，遂破之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-021', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-021', 'lantian', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-022', '史記', 8, 206, '高祖本紀·漢元年十月，沛公', '', 22, 'narrative', 'marker', '[10]'::jsonb, '漢元年十月，沛公兵遂先諸侯至霸上。秦王子嬰素車白馬，系頸以組，封皇帝璽符節，降軹道旁。諸將或言誅秦王。沛公曰：「始懷王遣我，固以能寬容；且人已服降，又殺之，不祥。」乃以秦王屬吏，遂西入咸陽。欲止宮休舍，樊噲、張良諫，乃封秦重寶財物府庫，還軍霸上。召諸縣父老豪桀曰：「父老苦秦苛法久矣，誹謗者族，偶語者棄市。吾與諸侯約，先入關者王之，吾當王關中。與父老約，法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。諸吏人皆案堵如故。凡吾所以來，為父老除害，非有所侵暴，無恐！且吾所以還軍霸上，待諸侯至而定約束耳。」乃使人與秦吏行縣鄉邑，告諭之。秦人大喜，爭持牛羊酒食獻饗軍士。沛公又讓不受，曰：「倉粟多，非乏，不欲費人。」人又益喜，唯恐沛公不為秦王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-022', 'bashang', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-022', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-023', '史記', 8, 206, '高祖本紀·繫於「鴻門宴」', '', 23, 'narrative', 'event_keyword', '[11, 12]'::jsonb, '或說沛公曰：「秦富十倍天下，地形彊。今聞章邯降項羽，項羽乃號為雍王，王關中。今則來，沛公恐不得有此。可急使兵守函谷關，無內諸侯軍，稍徵關中兵以自益，距之。」沛公然其計，從之。十一月中，項羽果率諸侯兵西，欲入關，關門閉。聞沛公已定關中，大怒，使黥布等攻破函谷關。十二月中，遂至戲。沛公左司馬曹無傷聞項王怒，欲攻沛公，使人言項羽曰：「沛公欲王關中，令子嬰為相，珍寶盡有之。」欲以求封。亞父勸項羽擊沛公。方饗士，旦日合戰。是時項羽兵四十萬，號百萬。沛公兵十萬，號二十萬，力不敵。會項伯欲活張良，夜往見良，因以文諭項羽，項羽乃止。沛公從百餘騎，驅之鴻門，見謝項羽。項羽曰：「此沛公左司馬曹無傷言之。不然，籍何以生此！」沛公以樊噲、張良故，得解歸。歸，立誅曹無傷。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-023', 'hangu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-023', 'hongmen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-024', '史記', 8, 206, '高祖本紀·繫於「鴻門宴」', '', 24, 'narrative', 'carried', '[]'::jsonb, '項羽遂西，屠燒咸陽秦宮室，所過無不殘破。秦人大失望，然恐，不敢不服耳。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-024', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-025', '史記', 8, 206, '高祖本紀·繫於「鴻門宴」', '', 25, 'narrative', 'carried', '[]'::jsonb, '項羽使人還報懷王。懷王曰：「如約。」項羽怨懷王不肯令與沛公俱西入關，而北救趙，後天下約。乃曰：「懷王者，吾家項梁所立耳，非有功伐，何以得主約！本定天下，諸將及籍也。」乃詳尊懷王為義帝，實不用其命。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-026', '史記', 8, 206, '高祖本紀·繫於「項羽分封十八王」', '', 26, 'narrative', 'event_keyword', '[1]'::jsonb, '正月，項羽自立為西楚霸王，王梁、楚地九郡，都彭城。負約，更立沛公為漢王，王巴、蜀、漢中，都南鄭。三分關中，立秦三將：章邯為雍王，都廢丘；司馬欣為塞王，都櫟陽；董翳為翟王，都高奴。楚將瑕丘申陽為河南王，都洛陽。趙將司馬卬為殷王，都朝歌。趙王歇徙王代。趙相張耳為常山王，都襄國。當陽君黥布為九江王，都六。懷王柱國共敖為臨江王，都江陵。番君吳芮為衡山王，都邾。燕將臧荼為燕王，都薊。故燕王韓廣徙王遼東。廣不聽，臧荼攻殺之無終。封成安君陳餘河閒三縣，居南皮。封梅鋗十萬戶。');
