INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-026', 'wuzhong', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-027', '史記', 8, 206, '高祖本紀·繫於「項羽分封十八王」', '', 27, 'narrative', 'carried', '[4]'::jsonb, '四月，兵罷戲下，諸侯各就國。漢王之國，項王使卒三萬人從，楚與諸侯之慕從者數萬人，從杜南入蝕中。去輒燒絕棧道，以備諸侯盜兵襲之，亦示項羽無東意。至南鄭，諸將及士卒多道亡歸，士卒皆歌思東歸。韓信說漢王曰：「項羽王諸將之有功者，而王獨居南鄭，是遷也。軍吏士卒皆山東之人也，日夜跂而望歸，及其鋒而用之，可以有大功。天下已定，人皆自寧，不可復用。不如決策東鄉，爭權天下。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-027', 'nanzheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-028', '史記', 8, 206, '高祖本紀·繫於「項羽分封十八王」', '', 28, 'narrative', 'carried', '[]'::jsonb, '項羽出關，使人徙義帝。曰：「古之帝者地方千里，必居上游。」乃使使徙義帝長沙郴縣，趣義帝行，群臣稍倍叛之，乃陰令衡山王、臨江王擊之，殺義帝江南。項羽怨田榮，立齊將田都為齊王。田榮怒，因自立為齊王，殺田都而反楚；予彭越將軍印，令反梁地。楚令蕭公角擊彭越，彭越大破之。陳餘怨項羽之弗王己也，令夏說說田榮，請兵擊張耳。齊予陳餘兵，擊破常山王張耳，張耳亡歸漢。迎趙王歇於代，復立為趙王。趙王因立陳餘為代王。項羽大怒，北擊齊。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-029', '史記', 8, 206, '高祖本紀·繫於「還定三秦（陳倉）」', '', 29, 'narrative', 'event_keyword', '[8]'::jsonb, '八月，漢王用韓信之計，從故道還，襲雍王章邯。邯迎擊漢陳倉，雍兵敗，還走；止戰好畤，又復敗，走廢丘。漢王遂定雍地。東至咸陽，引兵圍雍王廢丘，而遣諸將略定隴西、北地、上郡。令將軍薛歐、王吸出武關，因王陵兵南陽，以迎太公、呂后於沛。楚聞之，發兵距之陽夏，不得前。令故吳令鄭昌為韓王，距漢兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-029', 'chencang', 1);
