INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-029', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-029', 'pei', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-030', '史記', 8, 205, '高祖本紀·二年，漢王東略地', '', 30, 'narrative', 'marker', '[1]'::jsonb, '二年，漢王東略地，塞王欣、翟王翳、河南王申陽皆降。韓王昌不聽，使韓信擊破之。於是置隴西、北地、上郡、渭南、河上、中地郡；關外置河南郡。更立韓太尉信為韓王。諸將以萬人若以一郡降者，封萬戶。繕治河上塞。諸故秦苑囿園池，皆令人得田之，正月，虜雍王弟章平。大赦罪人。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-031', '史記', 8, 205, '高祖本紀·二年，漢王東略地', '', 31, 'narrative', 'carried', '[]'::jsonb, '漢王之出關至陜，撫關外父老，還，張耳來見，漢王厚遇之。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-032', '史記', 8, 205, '高祖本紀·二年，漢王東略地', '', 32, 'narrative', 'carried', '[2]'::jsonb, '二月，令除秦社稷，更立漢社稷。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-033', '史記', 8, 205, '高祖本紀·二年，漢王東略地', '', 33, 'narrative', 'carried', '[3]'::jsonb, '三月，漢王從臨晉渡，魏王豹將兵從。下河內，虜殷王，置河內郡。南渡平陰津，至雒陽。新城三老董公遮說漢王以義帝死故。漢王聞之，袒而大哭。遂為義帝發喪，臨三日。發使者告諸侯曰：「天下共立義帝，北面事之。今項羽放殺義帝於江南，大逆無道。寡人親為發喪，諸侯皆縞素。悉發關內兵，收三河士，南浮江漢以下，願從諸侯王擊楚之殺義帝者。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-033', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-034', '史記', 8, 205, '高祖本紀·繫於「彭城之戰」', '', 34, 'narrative', 'event_keyword', '[]'::jsonb, '是時項王北擊齊，田榮與戰城陽。田榮敗，走平原，平原民殺之。齊皆降楚。楚因焚燒其城郭，系虜其子女。齊人叛之。田榮弟橫立榮子廣為齊王，齊王反楚城陽。項羽雖聞漢東，既已連齊兵，欲遂破之而擊漢。漢王以故得劫五諸侯兵，遂入彭城。項羽聞之，乃引兵去齊，從魯出胡陵，至蕭，與漢大戰彭城靈壁東睢水上，大破漢軍，多殺士卒，睢水為之不流。乃取漢王父母妻子於沛，置之軍中以為質。當是時，諸侯見楚彊漢敗，還皆去漢復為楚。塞王欣亡入楚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-034', 'pengcheng', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-034', 'lingbi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-034', 'pei', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-035', '史記', 8, 205, '高祖本紀·繫於「彭城之戰」', '', 35, 'narrative', 'carried', '[]'::jsonb, '呂后兄周呂侯為漢將兵，居下邑。漢王從之，稍收士卒，軍碭。漢王乃西過梁地，至虞。使謁者隨何之九江王布所，曰：「公能令布舉兵叛楚，項羽必留擊之。得留數月，吾取天下必矣。」隨何往說九江王布，布果背楚。楚使龍且往擊之。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-035', 'xiayi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-036', '史記', 8, 205, '高祖本紀·繫於「彭城之戰」', '', 36, 'narrative', 'carried', '[6]'::jsonb, '漢王之敗彭城而西，行使人求家室，家室亦亡，不相得。敗後乃獨得孝惠，六月，立為太子，大赦罪人。令太子守櫟陽，諸侯子在關中者皆集櫟陽為衛。引水灌廢丘，廢丘降，章邯自殺。更名廢丘為槐里。於是令祠官祀天地四方上帝山川，以時祀之。興關內卒乘塞。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-036', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-036', 'yueyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-036', 'feiqiu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-037', '史記', 8, 205, '高祖本紀·繫於「彭城之戰」', '', 37, 'narrative', 'carried', '[]'::jsonb, '是時九江王布與龍且戰，不勝，與隨何閒行歸漢。漢王稍收士卒，與諸將及關中卒益出，是以兵大振滎陽，破楚京、索閒。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-037', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-038', '史記', 8, 204, '高祖本紀·三年，魏王豹謁歸', '', 38, 'narrative', 'marker', '[]'::jsonb, '三年，魏王豹謁歸視親疾，至即絕河津，反為楚。漢王使酈生說豹，豹不聽。漢王遣將軍韓信擊，大破之，虜豹。遂定魏地，置三郡，曰河東、太原、上黨。漢王乃令張耳與韓信遂東下井陘擊趙，斬陳餘、趙王歇。其明年，立張耳為趙王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-038', 'jingxing', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-039', '史記', 8, 204, '高祖本紀·三年，魏王豹謁歸', '', 39, 'narrative', 'carried', '[]'::jsonb, '漢王軍滎陽南，筑甬道屬之河，以取敖倉。與項羽相距歲餘。項羽數侵奪漢甬道，漢軍乏食，遂圍漢王。漢王請和，割滎陽以西者為漢。項王不聽。漢王患之，乃用陳平之計，予陳平金四萬斤，以閒疏楚君臣。於是項羽乃疑亞父。亞父是時勸項羽遂下滎陽，及其見疑，乃怒，辭老，願賜骸骨歸卒伍，未至彭城而死。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-039', 'xingyang', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-039', 'aocang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-039', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-040', '史記', 8, 204, '高祖本紀·繫於「滎陽之圍，紀信誑楚」', '', 40, 'narrative', 'event_keyword', '[]'::jsonb, '漢軍絕食，乃夜出女子東門二千餘人，被甲，楚因四面擊之。將軍紀信乃乘王駕，詐為漢王，誑楚，楚皆呼萬歲，之城東觀，以故漢王得與數十騎出西門遁。令御史大夫周苛、魏豹、樅公守滎陽。諸將卒不能從者，盡在城中。周苛、樅公相謂曰：「反國之王，難與守城。」因殺魏豹。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-040', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-041', '史記', 8, 204, '高祖本紀·繫於「滎陽之圍，紀信誑楚」', '', 41, 'narrative', 'carried', '[]'::jsonb, '漢王之出滎陽入關，收兵欲復東。袁生說漢王曰：「漢與楚相距滎陽數歲，漢常困。願君王出武關，項羽必引兵南走，王深壁，令滎陽成皋閒且得休。使韓信等輯河北趙地，連燕齊，君王乃復走滎陽，未晚也。如此，則楚所備者多，力分，漢得休，復與之戰，破楚必矣。」漢王從其計，出軍宛葉閒，與黥布行收兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-041', 'xingyang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-041', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-041', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-042', '史記', 8, 204, '高祖本紀·繫於「滎陽之圍，紀信誑楚」', '', 42, 'narrative', 'carried', '[]'::jsonb, '項羽聞漢王在宛，果引兵南。漢王堅壁不與戰。是時彭越渡睢水，與項聲、薛公戰下邳，彭越大破楚軍。項羽乃引兵東擊彭越。漢王亦引兵北軍成皋。項羽已破走彭越，聞漢王復軍成皋，乃復引兵西，拔滎陽，誅周苛、樅公，而虜韓王信，遂圍成皋。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-042', 'chenggao', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-042', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-043', '史記', 8, 204, '高祖本紀·繫於「滎陽之圍，紀信誑楚」', '', 43, 'narrative', 'carried', '[]'::jsonb, '漢王跳，獨與滕公共車出成皋玉門，北渡河，馳宿修武。自稱使者，晨馳入張耳、韓信壁，而奪之軍。乃使張耳北益收兵趙地，使韓信東擊齊。漢王得韓信軍，則復振。引兵臨河，南饗軍小修武南，欲復戰。郎中鄭忠乃說止漢王，使高壘深塹，勿與戰。漢王聽其計，使盧綰、劉賈將卒二萬人，騎數百，渡白馬津，入楚地，與彭越復擊破楚軍燕郭西，遂復下梁地十餘城。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-043', 'chenggao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-043', 'xiuwu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-044', '史記', 8, 204, '高祖本紀·繫於「滎陽之圍，紀信誑楚」', '', 44, 'narrative', 'carried', '[]'::jsonb, '淮陰已受命東，未渡平原。漢王使酈生往說齊王田廣，廣叛楚，與漢和，共擊項羽。韓信用蒯通計，遂襲破齊。齊王烹酈生，東走高密。項羽聞韓信已舉河北兵破齊、趙，且欲擊楚，則使龍且、周蘭往擊之。韓信與戰，騎將灌嬰擊，大破楚軍，殺龍且。齊王廣奔彭越。當此時，彭越將兵居梁地，往來苦楚兵，絕其糧食。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-045', '史記', 8, 203, '高祖本紀·四年，項羽乃謂海', '', 45, 'narrative', 'marker', '[]'::jsonb, '四年，項羽乃謂海春侯大司馬曹咎曰：「謹守成皋。若漢挑戰，慎勿與戰，無令得東而已。我十五日必定梁地，復從將軍。」乃行擊陳留、外黃、睢陽，下之。漢果數挑楚軍，楚軍不出，使人辱之五六日，大司馬怒，度兵汜水。士卒半渡，漢擊之，大破楚軍，盡得楚國金玉貨賂。大司馬咎、長史欣皆自剄汜水上。項羽至睢陽，聞海春侯破，乃引兵還。漢軍方圍鐘離眛於滎陽東，項羽至，盡走險阻。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-045', 'chenggao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-045', 'chenliu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-045', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-046', '史記', 8, 203, '高祖本紀·四年，項羽乃謂海', '', 46, 'narrative', 'carried', '[]'::jsonb, '韓信已破齊，使人言曰：「齊邊楚，權輕，不為假王，恐不能安齊。」漢王欲攻之。留侯曰：「不如因而立之，使自為守。」乃遣張良操印綬立韓信為齊王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-047', '史記', 8, 203, '高祖本紀·四年，項羽乃謂海', '', 47, 'narrative', 'carried', '[]'::jsonb, '項羽聞龍且軍破，則恐，使盱臺人武涉往說韓信。韓信不聽。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-048', '史記', 8, 203, '高祖本紀·繫於「廣武對峙」', '', 48, 'narrative', 'event_keyword', '[]'::jsonb, '楚漢久相持未決，丁壯苦軍旅，老弱罷轉馕。漢王項羽相與臨廣武之閒而語。項羽欲與漢王獨身挑戰。漢王數項羽曰：「始與項羽俱受命懷王，曰先入定關中者王之，項羽負約，王我於蜀漢，罪一。秦項羽矯殺卿子冠軍而自尊，罪二。項羽已救趙，當還報，而擅劫諸侯兵入關，罪三。懷王約入秦無暴掠，項羽燒秦宮室，掘始皇帝冢，私收其財物，罪四。又彊殺秦降王子嬰，罪五。詐阬秦子弟新安二十萬，王其將，罪六。項羽皆王諸將善地，而徙逐故主，令臣下爭叛逆，罪七。項羽出逐義帝彭城，自都之，奪韓王地，并王梁楚，多自予，罪八。項羽使人陰弒義帝江南，罪九。夫為人臣而弒其主，殺已降，為政不平，主約不信，天下所不容，大逆無道，罪十也。吾以義兵從諸侯誅殘賊，使刑餘罪人擊殺項羽，何苦乃與公挑戰！」項羽大怒，伏弩射中漢王。漢王傷匈，乃捫足曰：「虜中吾指！」漢王病創臥，張良彊請漢王起行勞軍，以安士卒，毋令楚乘勝於漢。漢王出行軍，病甚，因馳入成皋。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-048', 'guangwu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-048', 'xinan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-048', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-048', 'chenggao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-049', '史記', 8, 203, '高祖本紀·繫於「廣武對峙」', '', 49, 'narrative', 'event_keyword', '[]'::jsonb, '病愈，西入關，至櫟陽，存問父老，置酒，梟故塞王欣頭櫟陽市。留四日，復如軍，軍廣武。關中兵益出。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-049', 'yueyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-049', 'guangwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-050', '史記', 8, 203, '高祖本紀·繫於「廣武對峙」', '', 50, 'narrative', 'carried', '[]'::jsonb, '當此時，彭越將兵居梁地，往來苦楚兵，絕其糧食。田橫往從之。項羽數擊彭越等，齊王信又進擊楚。項羽恐，乃與漢王約，中分天下，割鴻溝而西者為漢，鴻溝而東者為楚。項王歸漢王父母妻子，軍中皆呼萬歲，乃歸而別去。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-050', 'honggou', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-051', '史記', 8, 202, '高祖本紀·繫於「垓下之圍」', '', 51, 'narrative', 'event_keyword', '[]'::jsonb, '項羽解而東歸。漢王欲引而西歸，用留侯、陳平計，乃進兵追項羽，至陽夏南止軍，與齊王信、建成侯彭越期會而擊楚軍。至固陵，不會。楚擊漢軍，大破之。漢王復入壁，深塹而守之。用張良計，於是韓信、彭越皆往。及劉賈入楚地，圍壽春，漢王敗碧陵，乃使使者召大司馬周殷舉九江兵而迎（之）武王，行屠城父，隨（何）劉賈、齊梁諸侯皆大會垓下。立武王布為淮南王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-051', 'guling', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-051', 'gaixia', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-052', '史記', 8, 202, '高祖本紀·五年，高祖與諸侯', '', 52, 'narrative', 'marker', '[]'::jsonb, '五年，高祖與諸侯兵共擊楚軍，與項羽決勝垓下。淮陰侯將三十萬自當之，孔將軍居左，費將軍居右，皇帝在後，絳侯、柴將軍在皇帝後。項羽之卒可十萬。淮陰先合，不利，卻。孔將軍、費將軍縱，楚兵不利，淮陰侯復乘之，大敗垓下。項羽卒聞漢軍之楚歌，以為漢盡得楚地，項羽乃敗而走，是以兵大敗。使騎將灌嬰追殺項羽東城，斬首八萬，遂略定楚地。魯為楚堅守不下。漢王引諸侯兵北，示魯父老項羽頭，魯乃降。遂以魯公號葬項羽穀城。還至定陶，馳入齊王壁，奪其軍。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-052', 'gaixia', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-052', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-053', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 53, 'narrative', 'event_keyword', '[1]'::jsonb, '正月，諸侯及將相相與共請尊漢王為皇帝。漢王曰：「吾聞帝賢者有也，空言虛語，非所守也，吾不敢當帝位。」群臣皆曰：「大王起微細，誅暴逆，平定四海，有功者輒裂地而封為王侯。大王不尊號，皆疑不信。臣等以死守之。」漢王三讓，不得已，曰：「諸君必以為便，便國家。」甲午，乃即皇帝位汜水之陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-053', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-054', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 54, 'narrative', 'carried', '[]'::jsonb, '皇帝曰義帝無後。齊王韓信習楚風俗，徙為楚王，都下邳。立建成侯彭越為梁王，都定陶。故韓王信為韓王，都陽翟。徙衡山王吳芮為長沙王，都臨湘。番君之將梅鋗有功，從入武關，故德番君。淮南王布、燕王臧荼、趙王敖皆如故。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-054', 'dingtao', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-054', 'yangzhai', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-054', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-055', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 55, 'narrative', 'carried', '[]'::jsonb, '天下大定。高祖都雒陽，諸侯皆臣屬。故臨江王驩為項羽叛漢，令盧綰、劉賈圍之，不下。數月而降，殺之雒陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-055', 'luoyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-056', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 56, 'narrative', 'carried', '[5]'::jsonb, '五月，兵皆罷歸家。諸侯子在關中者復之十二歲，其歸者復之六歲，食之一歲。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-057', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 57, 'narrative', 'carried', '[]'::jsonb, '高祖置酒雒陽南宮。高祖曰：「列侯諸將無敢隱朕，皆言其情。吾所以有天下者何？項氏之所以失天下者何？」高起、王陵對曰：「陛下慢而侮人，項羽仁而愛人。然陛下使人攻城略地，所降下者因以予之，與天下同利也。項羽妒賢嫉能，有功者害之，賢者疑之，戰勝而不予人功，得地而不予人利，此所以失天下也。」高祖曰：「公知其一，未知其二。夫運籌策帷帳之中，決勝於千里之外，吾不如子房。鎮國家，撫百姓，給餽馕，不絕糧道，吾不如蕭何。連百萬之軍，戰必勝，攻必取，吾不如韓信。此三者，皆人傑也，吾能用之，此吾所以取天下也。項羽有一范增而不能用，此其所以為我擒也。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-057', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-058', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 58, 'narrative', 'carried', '[6]'::jsonb, '高祖欲長都雒陽，齊人劉敬說，乃留侯勸上入都關中，高祖是日駕，入都關中。六月，大赦天下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-058', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-059', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 59, 'narrative', 'carried', '[10]'::jsonb, '十月，燕王臧荼反，攻下代地。高祖自將擊之，得燕王臧荼。即立太尉盧綰為燕王。使丞相噲將兵攻代。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-008-060', '史記', 8, 202, '高祖本紀·繫於「劉邦即皇帝位」', '', 60, 'narrative', 'carried', '[]'::jsonb, '其秋，利幾反，高祖自將兵擊之，利幾走。利幾者，項氏之將。項氏敗，利幾為陳公，不隨項羽，亡降高祖，高祖侯之潁川。高祖至雒陽，舉通侯籍召之，而利幾恐，故反。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-008-060', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-002', '史記', 48, 209, '陳涉世家·二世元年七月，發', '', 2, 'narrative', 'marker', '[7]'::jsonb, '二世元年七月，發閭左適戍漁陽，九百人屯大澤鄉。陳勝、吳廣皆次當行，為屯長。會天大雨，道不通，度已失期。失期，法皆斬。陳勝、吳廣乃謀曰：「今亡亦死，舉大計亦死，等死，死國可乎？」陳勝曰：「天下苦秦久矣。吾聞二世少子也，不當立，當立者乃公子扶蘇。扶蘇以數諫故，上使外將兵。今或聞無罪，二世殺之。百姓多聞其賢，未知其死也。項燕為楚將，數有功，愛士卒，楚人憐之。或以為死，或以為亡。今誠以吾眾詐自稱公子扶蘇、項燕，為天下唱，宜多應者。」吳廣以為然。乃行卜。卜者知其指意，曰：「足下事皆成，有功。然足下卜之鬼乎！」陳勝、吳廣喜，念鬼，曰：「此教我先威眾耳。」乃丹書帛曰「陳勝王」，置人所罾魚腹中。卒買魚烹食，得魚腹中書，固以怪之矣。又彊令吳廣之次所旁叢祠中，夜篝火，狐鳴呼曰「大楚興，陳勝王」。卒皆夜驚恐。旦日，卒中往往語，皆指目陳勝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-002', 'yuyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-002', 'dazexiang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-003', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '吳廣素愛人，士卒多為用者。將尉醉，廣故數言欲亡，忿恚尉，令辱之，以激怒其眾。尉果笞廣。尉劍挺，廣起，奪而殺尉。陳勝佐之，并殺兩尉。召令徒屬曰：「公等遇雨，皆已失期，失期當斬。藉弟令毋斬，而戍死者固十六七。且壯士不死即已，死即舉大名耳，王侯將相寧有種乎！」徒屬皆曰：「敬受命。」乃詐稱公子扶蘇、項燕，從民欲也。袒右，稱大楚。為壇而盟，祭以尉首。陳勝自立為將軍，吳廣為都尉。攻大澤鄉，收而攻蘄。蘄下，乃令符離人葛嬰將兵徇蘄以東。攻銍、酇、苦、柘、譙皆下之。行收兵。比至陳，車六七百乘，騎千餘，卒數萬人。攻陳，陳守令皆不在，獨守丞與戰譙門中。弗勝，守丞死，乃入據陳。數日，號令召三老、豪傑與皆來會計事。三老、豪傑皆曰：「將軍身被堅執銳，伐無道，誅暴秦，復立楚國之社稷，功宜為王。」陳涉乃立為王，號為張楚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-003', 'dazexiang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-003', 'qi', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-003', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-004', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 4, 'narrative', 'carried', '[]'::jsonb, '當此時，諸郡縣苦秦吏者，皆刑其長吏，殺之以應陳涉。乃以吳叔為假王，監諸將以西擊滎陽。令陳人武臣、張耳、陳餘徇趙地，令汝陰人鄧宗徇九江郡。當此時，楚兵數千人為聚者，不可勝數。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-004', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-005', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 5, 'narrative', 'carried', '[]'::jsonb, '葛嬰至東城，立襄彊為楚王。嬰後聞陳王已立，因殺襄彊，還報。至陳，陳王誅殺葛嬰。陳王令魏人周市北徇魏地。吳廣圍滎陽。李由為三川守，守滎陽，吳叔弗能下。陳王徵國之豪傑與計，以上蔡人房君蔡賜為上柱國。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-005', 'chen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-005', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-006', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 6, 'narrative', 'carried', '[3]'::jsonb, '周文，陳之賢人也，嘗為項燕軍視日，事春申君，自言習兵，陳王與之將軍印，西擊秦。行收兵至關，車千乘，卒數十萬，至戲，軍焉。秦令少府章邯免酈山徒、人奴產子生，悉發以擊楚大軍，盡敗之。周文敗，走出關，止次曹陽二三月。章邯追敗之，復走次澠池十餘日。章邯擊，大破之。周文自剄，軍遂不戰。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-007', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 7, 'narrative', 'carried', '[]'::jsonb, '武臣到邯鄲，自立為趙王，陳餘為大將軍，張耳、召騷為左右丞相。陳王怒，捕系武臣等家室，欲誅之。柱國曰：「秦未亡而誅趙王將相家屬，此生一秦也。不如因而立之。」陳王乃遣使者賀趙，而徙系武臣等家屬宮中，而封耳子張敖為成都君，趣趙兵亟入關。趙王將相相與謀曰：「王王趙，非楚意也。楚已誅秦，必加兵於趙。計莫如毋西兵，使使北徇燕地以自廣也。趙南據大河，北有燕、代，楚雖勝秦，不敢制趙。若楚不勝秦，必重趙。趙乘秦之獘，可以得志於天下。」趙王以為然，因不西兵，而遣故上谷卒史韓廣將兵北徇燕地。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-007', 'handan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-008', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 8, 'narrative', 'carried', '[]'::jsonb, '燕故貴人豪傑謂韓廣曰：「楚已立王，趙又已立王。燕雖小，亦萬乘之國也，願將軍立為燕王。」韓廣曰：「廣母在趙，不可。」燕人曰：「趙方西憂秦，南憂楚，其力不能禁我。且以楚之彊，不敢害趙王將相之家，趙獨安敢害將軍之家！」韓廣以為然，乃自立為燕王。居數月，趙奉燕王母及家屬歸之燕。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-009', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 9, 'narrative', 'carried', '[]'::jsonb, '當此之時，諸將之徇地者，不可勝數。周市北徇地至狄，狄人田儋殺狄令，自立為齊王，以齊反擊周市。市軍散，還至魏地，欲立魏後故甯陵君咎為魏王。時咎在陳王所，不得之魏。魏地已定，欲相與立周市為魏王，周市不肯。使者五反，陳王乃立甯陵君咎為魏王，遣之國。周市卒為相。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-010', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 10, 'narrative', 'carried', '[]'::jsonb, '將軍田臧等相與謀曰：「周章軍已破矣，秦兵旦暮至，我圍滎陽城弗能下，秦軍至，必大敗。不如少遺兵，足以守滎陽，悉精兵迎秦軍。今假王驕，不知兵權，不可與計，非誅之，事恐敗。」因相與矯王令以誅吳叔，獻其首於陳王。陳王使使賜田臧楚令尹印，使為上將。田臧乃使諸將李歸等守滎陽城，自以精兵西迎秦軍於敖倉。與戰，田臧死，軍破。章邯進兵擊李歸等滎陽下，破之，李歸等死。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-010', 'xingyang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-010', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-011', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 11, 'narrative', 'carried', '[]'::jsonb, '陽城人鄧說將兵居郯，章邯別將擊破之，鄧說軍散走陳。铚人伍徐將兵居許，章邯擊破之，伍徐軍皆散走陳。陳王誅鄧說。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-011', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-012', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 12, 'narrative', 'carried', '[]'::jsonb, '陳王初立時，陵人秦嘉、铚人董緶、符離人朱雞石、取慮人鄭布、徐人丁疾等皆特起，將兵圍東海守慶於郯。陳王聞，乃使武平君畔為將軍，監郯下軍。秦嘉不受命，嘉自立為大司馬，惡屬武平君。告軍吏曰：「武平君年少，不知兵事，勿聽！」因矯以王命殺武平君畔。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-013', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 13, 'narrative', 'carried', '[]'::jsonb, '章邯已破伍徐，擊陳，柱國房君死。章邯又進兵擊陳西張賀軍。陳王出監戰，軍破，張賀死。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-013', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-014', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 14, 'narrative', 'carried', '[]'::jsonb, '臘月，陳王之汝陰，還至下城父，其御莊賈殺以降秦。陳勝葬碭，謚曰隱王。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-015', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 15, 'narrative', 'carried', '[]'::jsonb, '陳王故涓人將軍呂臣為倉頭軍，起新陽，攻陳下之，殺莊賈，復以陳為楚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-015', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-016', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 16, 'narrative', 'carried', '[]'::jsonb, '初，陳王至陳，令铚人宋留將兵定南陽，入武關。留已徇南陽，聞陳王死，南陽復為秦。宋留不能入武關，乃東至新蔡，遇秦軍，宋留以軍降秦。秦傳留至咸陽，車裂留以徇。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-016', 'chen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-016', 'wuguan', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-016', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-017', '史記', 48, 209, '陳涉世家·繫於「大澤鄉起義」', '', 17, 'narrative', 'carried', '[]'::jsonb, '秦嘉等聞陳王軍破出走，乃立景駒為楚王，引兵之方與，欲擊秦軍定陶下。使公孫慶使齊王，欲與并力俱進。齊王曰：「聞陳王戰敗，不知其死生，楚安得不請而立王！」公孫慶曰：「齊不請楚而立王，楚何故請齊而立王！且楚首事，當令於天下。」田儋誅殺公孫慶。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-017', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-018', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 18, 'narrative', 'event_keyword', '[]'::jsonb, '秦左右校復攻陳，下之。呂將軍走，收兵復聚。鄱盜當陽君黥布之兵相收，復擊秦左右校，破之青波，復以陳為楚。會項梁立懷王孫心為楚王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-018', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-019', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 19, 'narrative', 'carried', '[6]'::jsonb, '陳勝王凡六月。已為王，王陳。其故人嘗與庸耕者聞之，之陳，扣宮門曰：「吾欲見涉。」宮門令欲縛之。自辯數，乃置，不肯為通。陳王出，遮道而呼涉。陳王聞之，乃召見，載與俱歸。入宮，見殿屋帷帳，客曰：「夥頤！涉之為王沈沈者！」楚人謂多為夥，故天下傳之，夥涉為王，由陳涉始。客出入愈益發舒，言陳王故情。或說陳王曰：「客愚無知，顓妄言，輕威。」陳王斬之。諸陳王故人皆自引去，由是無親陳王者。陳王以朱房為中正，胡武為司過，主司群臣。諸將徇地，至，令之不是者，系而罪之，以苛察為忠。其所不善者，弗下吏，輒自治之。陳王信用之。諸將以其故不親附，此其所以敗也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-019', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-020', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 20, 'narrative', 'carried', '[]'::jsonb, '陳勝雖已死，其所置遣侯王將相竟亡秦，由涉首事也。高祖時為陳涉置守冢三十家碭，至今血食。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-021', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 21, 'commentary', 'carried', '[]'::jsonb, '褚先生曰：地形險阻，所以為固也；兵革刑法，所以為治也。猶未足恃也。夫先王以仁義為本，而以固塞文法為枝葉，豈不然哉！吾聞賈生之稱曰：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-022', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 22, 'commentary', 'carried', '[]'::jsonb, '孝公既沒，惠文王、武王、昭王蒙故業，因遺策，南取漢中，西舉巴蜀，東割膏腴之地，收要害之郡。諸侯恐懼，會盟而謀弱秦。不愛珍器重寶肥饒之地，以致天下之士。合從締交，相與為一。當此之時，齊有孟嘗，趙有平原，楚有春申，魏有信陵：此四君者，皆明知而忠信，寬厚而愛人，尊賢而重士。約從連衡，兼韓、魏、燕、趙、宋、衛、中山之眾。於是六國之士有甯越、徐尚、蘇秦、杜赫之屬為之謀，齊明、周聚、陳軫、邵滑、樓緩、翟景、蘇厲、樂毅之徒通其意，吳起、孫臏、帶他、兒良、王廖、田忌、廉頗、趙奢之倫制其兵。嘗以什倍之地，百萬之師，仰關而攻秦。秦人開關而延敵，九國之師遁逃而不敢進。秦無亡矢遺鏃之費，而天下固已困矣。於是從散約敗，爭割地而賂秦。秦有餘力而制其獘，追亡逐北，伏尸百萬，流血漂櫓，因利乘便，宰割天下，分裂山河，彊國請服，弱國入朝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-022', 'nanzheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-023', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 23, 'commentary', 'carried', '[]'::jsonb, '施及孝文王、莊襄王，享國之日淺，國家無事。及至始皇，奮六世之餘烈，振長策而御宇內，吞二周而亡諸侯，履至尊而制六合，執敲樸以鞭笞天下，威振四海。南取百越之地，以為桂林、象郡，百越之君俛首系頸，委命下吏。乃使蒙恬北筑長城而守藩籬，卻匈奴七百餘里，胡人不敢南下而牧馬，士亦不敢貫弓而報怨。於是廢先王之道，燔百家之言，以愚黔首。墮名城，殺豪俊，收天下之兵聚之咸陽，銷鋒鍉，鑄以為金人十二，以弱天下之民。然後踐華為城，因河為池，據億丈之城，臨不測之谿以為固。良將勁弩，守要害之處，信臣精卒，陳利兵而誰何。天下已定，始皇之心，自以為關中之固，金城千里，子孫帝王萬世之業也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('sj-048-023', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-024', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 24, 'commentary', 'carried', '[]'::jsonb, '始皇既沒，餘威振於殊俗。然而陳涉甕牖繩樞之子，甿隸之人，而遷徙之徒也。材能不及中人，非有仲尼、墨翟之賢，陶朱、猗頓之富也。躡足行伍之閒，俛仰仟佰之中，率罷散之卒，將數百之眾，轉而攻秦。斬木為兵，揭竿為旗，天下雲會響應，贏糧而景從，山東豪俊遂并起而亡秦族矣。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('sj-048-025', '史記', 48, 208, '陳涉世家·繫於「立楚懷王孫心」', '', 25, 'commentary', 'carried', '[]'::jsonb, '且天下非小弱也；雍州之地，殽函之固自若也。陳涉之位，非尊於齊、楚、燕、趙、韓、魏、宋、衛、中山之君也；鉏耰棘矜，非銛於句戟長鎩也；適戍之眾，非儔於九國之師也；深謀遠慮，行軍用兵之道，非及鄉時之士也。然而成敗異變，功業相反也。嘗試使山東之國與陳涉度長絜大，比權量力，則不可同年而語矣。然而秦以區區之地。致萬乘之權，抑八州而朝同列，百有餘年矣。然後以六合為家，殽函為宮。一夫作難而七廟隳，身死人手，為天下笑者，何也？仁義不施，而攻守之勢異也。}}');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-001', '前漢演義', 9, 209, '第9回·秦二世元年', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說秦二世屠戮宗室，連及親舊，差不多將手足股肱，盡行斲去。他尚得意洋洋，以為從此無懮，可以窮極歡娛，肆行無忌，因此再興土木，重征工役，欲將阿房宮趕築完竣，好作終身的安樂窩。乃即日下詔道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-002', '前漢演義', 9, 209, '第9回·秦二世元年', '', 2, 'narrative', 'carried', '[]'::jsonb, '先帝謂咸陽朝廷過小，故營阿房宮為室堂，未就而先帝崩，暫輟工作，移築先陵，今驪山陵工已畢，若舍阿房宮而弗就，則是章先帝舉事過也。朕承先志，不敢怠遑，其復作阿房宮，毋忽！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-002', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-003', '前漢演義', 9, 209, '第9回·秦二世元年', '', 3, 'narrative', 'carried', '[]'::jsonb, '這詔下後，阿房宮內，又聚集無數役夫，日夕營繕，忙個不了。二世尚恐臣下異心，或有逆謀，特號令四方，募選才勇兼全的武士，入宮屯衛，共得五萬人。於是畜狗馬，豢禽獸，命內外官吏，隨時貢獻，上供宸賞，官吏等無不遵從。但宮內的婦女僕從，本來不少，再加那築宮的匠役，衛宮的武人，以及狗馬禽獸等類，沒一個不需食品，沒一種不借芻糧，咸陽雖大，怎能產得出許多芻粟，足供上用？那二世卻想得妙策，令天下各郡縣，籌辦食料，隨時運入咸陽，不得間斷，並且運夫等須備糧草，不得在咸陽三百里內，購食米谷，致耗京畿食物。各郡縣接奉此詔，不得不遵旨辦理。但官吏怎有餘財，去買芻米？無非是額外加征，取諸民間。百姓迭遭暴虐，已經困苦不堪，此次更要加添負擔，今日供粟菽，明日供芻藁，累得十室九空，家徒四壁，甚至賣男鬻女，賠貼進去。正是普天愁怨，遍地哀鳴，二世安處深宮，怎知民間苦況？還要效乃父始皇故事，調發民夫，出塞防胡。為此一道苛令，遂致亂徒四起，天下騷擾，秦朝要從此滅亡了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-003', 'xianyang', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-004', '前漢演義', 9, 209, '第9回·秦二世元年', '', 4, 'narrative', 'carried', '[]'::jsonb, '承上啟下，線索分明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-005', '前漢演義', 9, 209, '第9回·秦二世元年', '', 5, 'narrative', 'carried', '[]'::jsonb, '且說陽城縣中有一農夫，姓陳名勝字涉，少時家貧，無計謀生，不得已受僱他家，做了一個耕田傭。他雖寄人籬下，充當工役，志向卻與眾不同。一日在田內耦耕，扶犁叱牛，呼聲相應，約莫到了日昃的時候，已有些筋疲力乏，便放下犁耙，登壟坐著，望空唏噓。與他合作的傭人，見他懊恨情形，還道是染了病症，禁不住疑問起來。陳勝道：「汝不必問我，我若一朝得志，享受富貴，卻要汝等同去安樂，不致相忘！」勝雖具壯志，但只圖富貴，不務遠大，所出無成。傭人聽了，不覺冷笑道：「汝為人傭耕，與我等一樣貧賤。想甚麼富貴呢？」陳勝長歎道：「咄！咄！燕雀怎知鴻鵠志哩！」說著，又歎了數聲。看看紅日西沈，乃下壟收犁，牽牛歸家。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-006', '前漢演義', 9, 209, '第9回·二世元年七月', '', 6, 'narrative', 'marker', '[7]'::jsonb, '至二世元年七月，有詔頒到陽城，遣發閭左貧民，出戍漁陽。秦俗民居，富強在右，貧弱在左，貧民無財輸將，不能免役，所以上有征傜，只好冒死應命。陽城縣內，由地方官奉詔調發，得閭左貧民九百人，充作戍卒，令他北行。這九百人內，陳勝亦排入在內，地方官按名查驗，見勝身材長大，氣宇軒昂，便暗加賞識，拔充屯長。又有一陽夏人吳廣，軀幹與勝相似，因令與勝並為屯長，分領大眾，同往漁陽。且發給川資，預定期限，叫他努力前去，不得在途淹留。陳吳兩人當然應命，地方官又恐他難恃，特更派將尉二員，監督同行。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-006', 'yuyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-007', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 7, 'narrative', 'event_keyword', '[2]'::jsonb, '好幾日到了大澤鄉，距漁陽城尚數千里，適值天雨連綿，沿途多阻。江南北本是水鄉，大澤更為低窪，一望瀰漫，如何過去？沒奈何就地駐紮，待至天色晴霽，方可啟程。偏偏雨不肯停，水又增漲，惹得一班戍卒，進退兩難，互生嗟怨。勝與廣雖非素識，至此已做了同事，卻是患難與共，沆瀣相投，因彼此密議道：「今欲往漁陽，前途遙遠，非一二月不能到達。官中期限將至，屈指計算，難免逾期，秦法失期當斬，難道我等就甘心受死麼？」廣躍起道：「同是一死，不若逃走罷！」勝搖首道：「逃走亦不是上策。試想你我兩人，同在異地，何處可以投奔？就是有路可逃，亦必遭官吏毒手，捕斬了事。走亦死，不走亦死，倒不如另圖大事，或尚得死中求生，希圖富貴。」希望已久，正好乘此發作。廣矍然道：「我等無權無勢，如何可舉大事？」勝答說道：「天下苦秦已久，只恨無力起兵。我聞二世皇帝，乃是始皇少子，例不當立。公子扶蘇，年長且賢，從前屢諫始皇，觸怒乃父，遂致遷調出外，監領北軍。二世篡立，起意殺兄，百姓未必盡知，但聞扶蘇賢明，不聞扶蘇死狀。還有楚將項燕，嘗立戰功，愛養士卒，楚人憶念勿衰，或說他已死，或說他出亡。我等如欲起事，最好托名公子扶蘇，及楚將項燕，號召徒眾，為天下倡。我想此地本是楚境，人心深恨秦皇，定當聞風響應，前來幫助，大事便可立辦了。」借名號召，終非良圖。廣也以為然，但因事關重大，不好冒昧從事，乃決諸卜人，審問吉凶。卜人見勝廣趨至，面色匆匆，料他必有隱衷，遂詳問來意，以便卜卦。勝廣未便明言，惟含糊說了數語。卜人按式演術，焚香布卦，輪指一算，便向二人說道：「足下同心行事，必可成功，只後來尚有險阻，恐費周折，足下還當問諸鬼神。」已伏下文。勝廣也不再問，便即告別。途中互相告語道：「卜人欲我等問諸鬼神，敢是教我去祈禱麼？」想了一番，究竟陳勝較為聰明，便語吳廣道：「是了！是了！楚人信鬼，必先假托鬼神，方可威眾，卜人教我，定是此意。」吳廣道：「如何辦法？」勝即與廣附耳數語，約他分頭行事。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-007', 'dazexiang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-007', 'yuyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-008', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 8, 'narrative', 'carried', '[]'::jsonb, '翌日上午，勝命部卒買魚下膳，士卒奉令往買，揀得大魚數尾，出資購歸。就中有一魚最大，腹甚膨脹，當由部卒用刀剖開，見腹中藏著帛書，已是驚異。及展開一閱，書中卻有丹文，仔細審視，乃是陳勝王三字，免不得擲刀稱奇。大眾聞聲趨集，爭來看閱，果然字跡無訛，互相驚訝。當有人報知陳勝，勝卻喝著道：「魚腹中怎得有書？汝等敢來妄言！曾知朝廷大法否？」做作得妙！部卒方才退去，烹魚作食，不消細說。但已是嘖嘖私議，疑信相參。到了夜間，部卒雖然睡著，尚談及魚腹中事，互相疑猜。忽聞有聲從外面傳來，彷彿是狐嗥一般，大眾又覺有異，各住了口談，靜悄悄的聽著。起初是聲浪模糊，不甚清楚，及凝神細聽，覺得一聲聲象著人語，約略可辨。第一聲是大楚興，第二聲是陳勝王。眾人已辨出聲音，仗著人多勢旺，各起身出望，看個明白。營外是一帶荒郊，只有西北角上，古木陰濃，並有古祠數間，為樹所遮，合成一團。那聲音即從古祠中傳出，順風吹來，明明是大楚興，陳勝王二語。更奇怪的是叢樹中間，隱約露出火光，似燈非燈，似燐非燐，霎時間移到那邊，霎時間又移到這邊，變幻離奇，不可測摸。過了半晌，光已漸滅，聲亦漸稀了。敘筆亦奇。大眾本想前去探察，無如時當夜半，天色陰沈得很，路中又泥滑難行，再加營中有令，不准夜間私出，那時只好回營再睡。越想越奇，又驚又恐，索性都做了反舌無聲，一同睡熟了。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-009', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 9, 'narrative', 'event_keyword', '[]'::jsonb, '看官欲知魚書狐嗥的來歷，便是陳勝吳廣兩人的詭計。倒戟而出。陳勝先私寫帛書，夜間偷出營門，尋得漁家魚網中，蓄有大魚，料他待旦出售，便將帛書塞入魚口。待魚汲入腹中，勝乃悄悄回營。大澤鄉本乏市集，自經屯卒留駐，各漁家得了魚蝦，統向營中兜銷，所以這魚即被營兵買著，得中勝計。至若狐嗥一節，也是陳勝計劃，囑令吳廣乘夜潛出，帶著燈籠，至古祠中偽作狐嗥，惑人耳目。古祠在西北角上，連日天雨，西北風正吹得起勁，自然傳入營中，容易聽見。後人把疑神見鬼等情，說做篝火狐鳴，便是引用陳勝吳廣的古典。陳勝既行此二策，即與吳廣暗察眾情，多是背地私語，以訛傳訛，有的說是魚將化龍，故有此變，有的說是狐已成仙，故能預知。只勝廣兩人，相視而笑，私幸得計。好在營中的監督大員，雖有將尉二員，卻是一對糊塗蟲，他因天雨難行，無法消遣，只把那杯中物作為好友，鎮日裡兩人對飲，喝得酩酊大醉，便即睡著，醒來又是飲酒，醉了又睡，無論甚麼事情，一概不管，但令兩屯長自去辦理，無暇過問。勝廣樂得設法擺佈，又在營中買動人心，一衣一食，都與部卒相同，毫不剋扣。部卒已願為所用，更兼魚書狐鳴種種怪異，尤足聳動觀聽，益令大眾傾心。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-009', 'dazexiang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-010', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 10, 'narrative', 'carried', '[]'::jsonb, '陳勝見時機已至，又與吳廣定謀，乘著將尉二人酒醉時，闖入營帳，先由廣趨前朗說道：「今日雨，明日又雨，看來不能再往漁陽。與其逾限就死，不如先機遠揚，廣特來稟知，今日就要走了。」將尉聽著，勃然怒道：「汝等敢違國法麼？欲走便斬！」廣毫不驚慌，反信口揶揄道：「公兩人監督戍卒，奉令北行，責任很是重大，如或愆期，廣等原是受死，難道公兩人尚得生活麼？」這數句話很是利害，惹得一尉用手拍案，連聲呼笞。一尉還要性急，索性拔出佩劍，向廣揮來。廣眼明手快，飛起一腳，竟將劍踢落地上，順手把劍拾起，搶前一步，用劍砍去，正中將尉頭顱，劈分兩旁，立即倒斃。還有一尉未死，咆哮得很，也即拔劍刺廣。廣又持劍格鬥，一往一來，才經兩個回合，突有一人馳至將尉背後，喝一聲著，已把將尉劈倒，接連又是一刀，結果性命。這人為誰？便是主謀起事的陳勝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-010', 'yuyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-011', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 11, 'narrative', 'carried', '[]'::jsonb, '勝廣殺死二尉，便出帳召集眾人，朗聲與語道：「諸君到此，為雨所阻，一住多日，待到天晴，就使星夜前進，也不能如期到漁。失期即當斬首，僥倖遇赦，亦未必得生。試想北方寒冷，冰天雪窖，何人禁受得起？況胡人專喜寇掠，難保不乘隙入犯。我等既受風寒，又攖鋒刃，還有甚麼不死！丈夫子不死便罷，死也要死得有名有望﹔能夠冒死舉事，才算不虛此一生。王侯將相，難道必有特別種子麼？」大眾見他語言慷慨，無不感動，但還道二尉尚存，一時未敢承認，只管向帳內探望，似有顧慮情狀。勝廣已經窺透，又向眾直言道：「我兩人不甘送死，並望大眾統不枉死，所以決計起事，已將二尉殺死了。」大眾到此，才齊聲應道：「願聽尊命！」勝廣大喜，便領眾人入帳，指示二尉屍首，果然血肉模糊，身首異處。當由陳勝宣令，梟了首級，用竿懸著。一面指揮大眾，在營外闢地為壇，眾擎易舉，不日告成。就將二尉頭顱，做了祭旗的物品。旗上大書一個楚字。陳勝為首，吳廣為副，餘眾按次並列，對著大旗，拜了幾拜，又用酒為奠。奠畢以後，並將二尉頭上的血瀝，滴入酒中，依次序飲，大眾喝過同心酒，當然對旗設誓，願奉陳勝為主，一同造反。勝便自稱將軍，廣為都尉，登壇上坐，首先發令，定國號為大楚。再命大眾各袒右臂，作為記號。一面草起檄文，詐稱公子扶蘇，及楚將項燕，已在軍中，分作主帥。項燕與秦為仇，死於楚難，假使不死，寧有擁戴扶蘇之理。陳勝雖智，計亦大謬。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-012', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 12, 'narrative', 'event_keyword', '[]'::jsonb, '檄文既發，就率眾出略大澤鄉。鄉中本有三老，又有嗇夫，見第二回。聽得陳勝造反，早已逃去。勝即把大澤鄉占住，作為起事的地點。居民統皆散走，家中留有耜頭鐵耙等類，俱被大眾掠得，充作兵器，尚苦器械不足，再向山中斬木作棍，截竹為旗。忙碌了好幾日，方得粗備軍容。老天卻也奇怪，竟放出日光，掃除雲翳，接連晴了半個月，水勢早退，地上統乾乾燥燥，就是最低窪的地方，也已滴水不留。老天非保佑陳勝，實是促秦之亡。大眾以為果得天助，格外抖擻精神，專待出發。各處亡命之徒，復陸續趨集，來做幫手。於是陳勝下令，麾眾北進。原來大澤鄉屬蘄縣管轄，勝既出兵略地，不得不先攻蘄縣。蘄縣本非險要，守兵寥寥無幾，縣吏又是無能，如何保守得住？一聞勝眾將至，城內已驚惶得很，結果是吏逃民降。勝眾不煩血刃，便已安安穩穩的據住縣城。再令符離人葛嬰，率眾往略蘄東，連下銍鄼苦柘及譙縣，聲勢大震。沿路收得車馬徒眾，均送至蘄縣，歸勝調遣。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-012', 'dazexiang', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-012', 'qi', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-013', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 13, 'narrative', 'carried', '[]'::jsonb, '勝復大舉攻陳，有車六七百乘，騎兵千餘，步卒數萬人，一古腦兒趨集城下。適值縣令他出，只有縣丞居守，他卻硬著頭皮，招集守兵，開城搦戰。勝眾一路順風，勢如破竹，所有生平氣力，未曾施展，完全是一支生力軍。此次到了陳縣，忽見城門大開，竟擁出數百人馬，前來爭鋒，勝眾各摩拳擦掌，一擁齊上，前驅已有刀槍，亂砍亂戳，凶橫得很。後隊尚是執著木棍，及耜頭鐵耙等類，橫掃過去。守兵本是單弱，不敢出戰，但為縣丞所逼，沒奈何出城接仗。偏碰著了這班暴徒，情形與瘈犬相似，略一失手，便被打翻，稍一退步，便被衝倒，數百兵馬，死的死，逃的逃，縣丞見不可敵，也即奔還。那知勝眾緊緊追入，連城門都不及關閉。害得縣丞無路可奔，不得不翻身拚命，畢竟勢孤力竭，終為勝眾所殺。縣丞身食秦祿，不得謂非忠良。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-013', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-014', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 14, 'narrative', 'carried', '[]'::jsonb, '勝與吳廣聯轡入城，也想收拾人心，禁止侵掠，各處張貼榜示，居然說是除殘去暴，伐罪弔民。過了數日，復號召三老豪傑共同議事，三老豪傑聞風來會，由勝溫顏召入，問及善後事宜。但聽得眾人齊聲道：「將軍披堅執銳，伐無道，誅暴秦，復立楚國社稷，功無與比，應即稱王，以副民望。」這數句話正中勝意，只一時不便應允，總要退讓數語，方可自表謙恭。當下說了幾句假話，引起三老豪傑的嘩聲，彼譽此頌，一再勸進。勝正要允諾，忽外面有人入報，說有大梁二士，前來求見。勝問過姓名，便向左右道：「這二人也來見我麼？我素聞二人賢名，今得到此，事無不成了。」說著即命左右出迎，且親自起座，下階佇候。正是：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-015', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 15, 'aside', 'carried', '[]'::jsonb, '飾禮寧知真下士？偽恭但欲暫欺人。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-016', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 16, 'aside', 'carried', '[]'::jsonb, '畢竟大梁二士姓甚名誰，容待下回詳報。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-009-017', '前漢演義', 9, 209, '第9回·繫於「大澤鄉起義」', '', 17, 'commentary', 'carried', '[]'::jsonb, '暴秦之季，發難者為陳勝吳廣，而陳勝尤為首謀。是勝之起事，實暴秦存亡之一大關鍵也。勝一耕傭，獨具大志，不可謂非軼類材。但觀其魚腹藏書，及篝火狐鳴之術，亦第足以欺愚夫，而不足以服梟杰。況其徒貪富貴，孳孳為利，子輿氏所謂蹠之徒者，勝其有焉。惟因暴秦無道，為民所嫉，史家所以大書曰﹔陳勝吳廣，起兵於蘄，實則皆為叛亂之首而已。殺將驅卒，斬木揭竿，亂秦有餘，平秦不足。本書之不予勝廣，其好治抑亂之心，已寓言中，正不徒以文字見長也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-009-017', 'qi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-001', '前漢演義', 10, 209, '第10回·繫於「大澤鄉起義」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說大梁二士來謁陳勝，一個叫作張耳，一個叫作陳餘。兩人俱籍隸大梁，家居不遠。張耳年長，陳餘年少，所以餘事耳如父，耳亦待餘如子弟，兩人誓同生死，時人稱為刎頸交。耳曾為魏公子門客，後因犯事出奔，避居外黃，外黃有一富家女，生得美貌如花，豔名鵲起，偏偏嫁了一個庸奴，免不得夫妻反目，時有怨聲。一日又復噪鬧，甚至互哄，富家女身材嫋娜，怎禁得起乃夫老拳！如花美眷，不知溫存，還想飽以老拳，真是庸奴。急不暇擇，逃出夫家，竟潛至父執家中，匿身避禍。父執見他淚容滿面，楚楚可憐，遂與富家女說道：「汝果不欲適庸奴，何妨再求賢夫。我意中卻有一人，未知汝可願否？」富家女當然心動，含糊答應。父執復令女在屏後立著，親判妍媸，自己出外一走。不到片時，已引入一個俊俏郎君，故意的高聲與語。女從屏後露出半面，約略相窺，果然是溫文爾雅，與前夫大不相同。及父執送客出門，入與女語﹔女問及來客姓名，才知是大梁人張耳，芳心欲醉，恨不得即與並頭。父執願為玉成，即往與女父熟商，令女改嫁張耳。女父本來溺愛，悔為女誤配匪人，至此願出巨資，給女前夫，與他離婚。女夫與女不和，樂得取錢棄女，聽他轉嫁。呆鳥。俏佳人終偶才郎，錯姻緣幸得改正，不但富家女心滿意足，就是亡命徒張耳，得此意外奇逢，也是樂不勝言。還有一樁極好的機緣，張耳既得美婦，又得婦財，索性結交遠客，廣為延譽，聲名漸達魏廷。魏主竟不記前愆，反用耳為外黃令，銅章墨綬，儼然一百里小侯了。富家女得做縣令夫人，應更愜意。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-002', '前漢演義', 10, 209, '第10回·繫於「大澤鄉起義」', '', 2, 'narrative', 'carried', '[]'::jsonb, '陳餘少好讀書，並喜遊覽，偶至趙國苦陘地方，得邀富人公乘氏賞識，也願招他為婿。女貌頗亦不俗，陳餘自然樂允，擇日成禮。兩小無猜，又是一對好夫妻。張陳兩人，想都是紅鸞星照命。及魏被秦滅，張耳失官，仍在外黃居住，陳餘亦挈妻還鄉。不料秦朝竟懸出賞格，購緝兩人，賞格上面，煌煌寫著，獲張耳賞千金，獲陳餘賞五百金。二人不知何因，但情急逃生，不得已移名改姓，避居陳縣，充當裡正監門。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-002', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-003', '前漢演義', 10, 209, '第10回·繫於「大澤鄉起義」', '', 3, 'narrative', 'carried', '[]'::jsonb, '仔細探聽，方知秦令購緝，實恐二人多才，重複興魏，所以務欲翦除。張耳得此消息，時常戒勉陳餘，須要謹慎小心，毋得敗露真情，陳餘亦格外記著。冤冤相湊，竟為著一些小事，觸怒裡吏，裡吏將加餘笞罪。餘不肯忍耐，起身欲走，可巧張耳在旁，慌忙把足躡餘，使他受笞。及笞畢吏去。耳引餘至桑下，悄悄與語道：「我與汝曾已說過，汝奈何失記！區區小辱，不甘忍受，乃欲與裡吏拚命，死何足惜！」餘始悔悟謝過。復由耳想出一計，用著監門名義，號令裡中，叫他訪拿張耳陳餘。裡人怎知詐謀？心下貪賞，還往四處尋緝。其實張陳二人，原在眼前，反被他用計瞞過了。卻是好計。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-004', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 4, 'narrative', 'event_keyword', '[]'::jsonb, '至勝廣入陳，張耳陳餘，乃踵門求見。勝也聞得二人大名，嘗遭秦忌，因此亟欲一見，特地下階佇候，表明敬意。待二人既入，向勝行禮，勝忙與答揖，引至座前，令他分坐兩旁，然後與議軍情，並談及稱王意見。張耳答道：「秦為無道，破人國家，滅人社稷，絕人後嗣，疲民力，竭民財，暴虐日甚。今將軍瞋目張膽，萬死不顧一生，為天下驅除殘賊，真是絕大的義舉。惟現方發跡至陳，亟欲以王號自娛，竊為將軍不取！願將軍毋急稱王，速引兵西向，直指秦都。一面立六國後人，自植黨援，俾益秦敵。敵多力自分，與眾兵乃強，將見野無交兵，縣無守城，誅暴秦，據咸陽，號令諸侯，諸侯轉亡為存，無不感戴，將軍再能懷柔以德，天下自相率悅服，帝業也可成就了，還要稱王何用！」說到此處，見陳勝默默無言，似有不悅情狀。正想開言再勸，那陳餘已接入道：「將軍不欲平定四海，倒也罷了，如有志安邦，宜圖大計。若僅據一隅，便擬稱王，恐天下都疑及將軍，懷挾私意，待至人情失望，遠近灰心，將軍悔也無及了！」陳勝沈吟半晌，方才說出一語道：「容待再議。」兩人見話不投機，本想就此告辭，只因途中多阻，不能不暫時安身，再作計較，乃留住陳勝麾下，充作參謀。勝竟自立為王，國號張楚，隱寓張大楚國的意思。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-004', 'chen', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-004', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-005', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 5, 'narrative', 'carried', '[]'::jsonb, '是時河南諸郡縣，苦秦苛法，豪民多戕殺官吏，起應陳勝。勝乃使吳廣為假王，監督諸將，西攻滎陽。廣已出發，張耳陳餘，也想乘此外出，離開陳邑，遂由張耳暗囑陳餘，令他向勝獻計道：「大王舉兵梁楚，志在西討，入關建業，若要顧及河北，想尚未遑，臣嘗游趙地，素知河北地勢，並結交豪傑多人，今願請奇兵，北略趙地，既足牽制秦軍，復足撫定趙民，豈不是一舉兩得麼？」也想飛去。勝聽餘言，卻也稱為奇計，但因他新來歸附，總難深信，乃特選故人武臣為將軍，邵騷為護軍，督同張耳陳餘二人，領兵三千，往徇趙地。耳與餘不給重任，但使他為左右校尉，作為武臣的幫辦。二人別有隱衷，不暇計及官職大小，欣然領命，渡河北去。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-005', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-006', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 6, 'narrative', 'event_keyword', '[]'::jsonb, '勝將葛嬰，未曾至陳，獨率部往略九江。行至東城，遇著楚裔襄疆，一見如故，竟不待勝命，擅立襄疆為楚王。嗣得陳勝文書，內有張楚王字樣，始知勝已稱王，不能另立襄疆，自悔一時鹵莽，潛圖變計。湊巧陳勝命令，又復頒到，叫他領兵還陳，他越恐陳勝動疑，竟將襄疆殺死，持首還報。果然勝已聞知，待嬰到後，立即傳嬰入見，數責罪狀，喝令斬首。左右將嬰推出，一刀兩段，死於非命。嬰已悔過，罪不至死。部眾見嬰慘死，未免寒心，互相私議。勝尚以為令出法行，可無他慮，復遣汝陰人鄧宗，東略九江，魏人周市，北徇魏地。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-006', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-007', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 7, 'narrative', 'carried', '[]'::jsonb, '會接吳廣軍報，說是進攻滎陽，不能得勝，現由秦三川守李由，堅守滎陽城，非再行發兵，難下此城等語。勝乃召集謀士，申議攻秦方法。上蔡人蔡賜，本為房邑君長，獻議勝前，請派名將西行，逕入函谷關，直搗咸陽。勝依了賜議，並封他為上柱國。一面訪求良將，得著陳人周文，召入與語。文自述履歷，謂曾事春申君黃歇，又為項燕軍占驗吉凶，素諳軍事。勝即大喜，特給將軍印信，使他西行攻秦。周文奉命就道，沿途收集壯士，編入隊伍，眾至數十萬，長驅西進，直薄函谷關。關中守吏，飛章告急，誰知秦廷裡面，好象沒人一般，任他如何急報，總不聞有將士出援。原來二世恣意淫樂，朝政俱歸趙高把持，高專事煬蔽，凡遇外面奏報，一律擱起，不使二世得聞，所以陳勝起兵，已有數月，二世全然不知。會有使臣從東方回來，面謁二世，奏稱陳勝造反，郡縣多叛，請即遣將討平。二世還道他是妄言欺主，命將使臣下獄。嗣是他使還京，由二世問及亂事，俱答稱么麼小丑，不足有為，現已由各郡守尉，四面兜捕，即可蕩平，陛下盡可放心。二世大喜，把亂事置諸度外，毫不提及，朝廷得過且過，也不敢瀆陳外事，上下相蒙，亂端益熾，直至周文入關，秦廷尚視若無事，這真叫做糊塗世界呢。不如是，不足致亡。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-007', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-007', 'hangu', 2);
