INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-008', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 8, 'narrative', 'carried', '[]'::jsonb, '且說周文一路進兵，攻城掠地，所向無前，當然派人至陳，一再報捷，陳勝喜如所望，遂輕視秦室，不復設備。博士孔鮒，系孔夫子的八世孫，曾持家傳禮器，詣陳謁勝，勝因留為博士。至此獨進諫道：「臣聞兵法有言：不恃敵不攻我，但恃我不可攻，今大王恃敵不攻，未知所以自恃的道理﹔倘或敵人驟至，無法抵禦，一有蹉跌，全局瓦解，雖悔也是遲了！」勝不肯從，惟專望各路捷音，好去做那關中皇帝。怎知福為禍倚，樂極悲生，那四面八方的警報，已是陸續到來。第一路的警信，就是出徇趙地的武臣等軍﹔第二路的警信，乃是進攻秦都的周文等軍，小子只有一枝禿筆，不能雙管齊下，只好依次敘述，先後說明。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-008', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-009', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 9, 'narrative', 'carried', '[]'::jsonb, '自武臣等率兵北去，從白馬津渡河，所過諸縣，偏諭豪傑，無非說是暴秦無道，勞役百姓，繩以重法，迫以苛征，今由陳王起義，天下響應，我等奉令北渡，前來招安，諸君皆為豪士，理應並力同心，共除暴秦云云。豪傑等正苦秦暴，聽了這番名正言順的話兒，還有甚麼不服，當即願為前導，分趨各城，城中守吏，多被殺死。接連得了十座城池，人數亦越聚越多，渡河時只有三千人，至是卻多了好幾萬名。當下推武臣為武信君，再出招諭。偏是餘城不屈，各募兵民拒守，武臣因諸城無關險要，竟引眾趨向東北，獨攻范陽。范陽令徐公，有志保城，也即繕甲厲兵，準備抵禦，偏有一個辯士蒯徹，入見徐公，先說出一個弔字，後說出一個賀字。便是說客口脗。惹得徐公莫明其妙，不得不驚問理由。蒯徹道：「徹聞公將死，故來弔公﹔但公得徹一言，便有生路，故又復賀公。」徐公道：「君不必故作疑團，正好明白說來。」徹又道：「足下為范陽令，已十餘年，殺人父，孤人子，斷人足，黔人首，想已不可勝數。百姓無不懷怨，但恐秦法嚴重，未敢剸刃公腹，致滅全家。今天下大亂，秦法不行，足下豈尚得自全？一旦敵臨城下，百姓必乘機報仇，刃及公胸，這豈不是可弔麼？幸虧徹來見公，為公定計，俟武信君尚未到來，即由徹先去游說，為公效力，使公轉禍為福，這又便是可賀了！」徐公喜道：「君言甚善，請即為我往說武信君！」蒯徹因即前往，求見武臣。武臣方招致豪傑，當然許見。蒯徹進言道：「足下到此，必待戰勝然後略地，攻破然後入城，未免過勞。徹有一計，可不攻而得城，不戰而得地，但教一紙檄文，便足略定千里，未知足下願聞否？」武臣急問道：「果有此計，怎不願聞！」蒯徹道：「今范陽令聞公攻城，正擬整頓兵馬，守城拒敵，惟城中士卒不多，該令又逡巡畏死，貪戀祿位，目下不肯歸降，實因公前下十城，見吏即誅，降亦死，守亦死，故不得不拚死圖存。就使范陽少年，嫉吏如仇，起殺范陽令，亦必據城拒公，不甘就死。為公設法，不若赦范陽令，並給侯印，該令喜得富貴，自願開城出降，范陽少年亦不敢殺令，是全城便唾手可下了。公再使該令乘朱輪，坐華轂，徇行燕趙郊野，燕趙吏民，孰不欣羨，必爭先降公。公得不攻而取，不戰而服，這就所謂傳檄可定呢！」面面俱到，真好口才。武臣點首稱善，便令刻就侯印，交徹齎賜范陽令。范陽令徐公，大喜過望，即開城迎武臣軍。武臣復如徹言，特給徐公高車駟馬，往撫燕趙，趙地果聞風趨附，不到旬月，已平定了三十餘城，乘勢入邯鄲縣。適有周文敗報，自西傳來，又探得陳勝部將，多因讒毀得罪，武臣不免疑懼。張耳陳餘，更生異謀。他本怨陳勝不用己言，復只得了左右校尉的名目，未綰兵符，因此乘隙生心，遂進說武臣道：「陳王起兵蘄縣，才得陳地，便自稱為王，不願立六國後裔，居心可知。今將軍率三千人，下趙數十城，偏居河北，若非稱王，何由鎮撫，況陳王好信讒言，妒功忌能，將軍功高益危，不如南面稱王，脫離陳王羈絆，免得意外受禍。時不可失，願將軍勿疑！」武臣聽了稱王二字，豈有不喜歡的道理，當下在邯鄲城外，群地為壇，也居然堂皇高坐，朝見僚屬，竟稱孤道寡起來。武臣自為趙王，授陳餘為大將軍，張耳為右丞相，邵騷為左丞相，且使人報知陳勝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-009', 'handan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-010', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 10, 'narrative', 'carried', '[]'::jsonb, '勝得報後，怒不可遏，即欲飭拘武臣家屬，盡行屠戮，更發兵往擊武臣。獨上柱國蔡賜入諫道：「秦尚未滅，先殺武臣家屬，是又增出一秦，為大王敵，大王東西受攻，必遭牽制，如何得成大業！今不若遣使往賀，暫安彼心，並令他從速攻秦，遙援周文，是東顧既可無懮，西略便為得勢。滅秦以後，圖趙未遲，何必急急哩！」陳勝乃轉怒為喜，但將武臣家屬，徙入王宮，把他軟禁。並封張耳子敖為成都君，派人賀趙，乘便報聞。張耳陳餘，見了勝使，早已瞧透勝意，表面上佯與為歡，背地裡卻私語武臣道：「大王據趙稱尊，必為陳王所忌，今遣使來賀，明明是懷著詭謀，使我並力滅秦，然後再北向圖我。大王不如虛與周旋，優待來使，至來使去後，盡管北收燕代，南取河內。若得南北兩方，盡為趙有，楚雖勝秦，也必不敢制趙，反且與我修和，大王卻好沈著觀變，坐定中原了。」計亦甚是。武臣也稱好計，款待勝使，厚禮遣歸。隨即使韓廣略燕，李良略常山，張黶略上黨，三路出發，獨不遣一卒西向。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-011', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 11, 'narrative', 'carried', '[]'::jsonb, '那時攻入秦關的周文，孤軍無助，竟被秦將章邯擊退，敗走出關。章邯為秦少府，官名。頗有智勇，因聞周文攻入關中，直至戲地，不由的憤激得很，意欲入宮詳陳。可巧警報與雪片相似，飛達咸陽，連趙高也覺吃驚，不得不據實奏明。二世至此，方才似夢初覺，嚇出一身冷汗，急召文武百官，入朝會議。自己也親出御朝，詢問禦敵方法。百官都面面相覷，莫敢發言，獨章邯出班奏道：「賊眾已近，亟須征剿，若要征集將士，已恐不及，臣請赦免驪山徒犯，盡給兵器，由臣統領前去，奮力一擊，當可退賊。」二世已焦急萬分，只望有人解懮，幸得章邯替他畫策，並請效力，當然喜逐顏開，褒獎了好幾語。一面頒詔大赦，即命章邯為將軍，招集驪山役徒，編製成軍，出都退敵。章邯確是有些能力，挑選丁壯，作為前驅，自居中堅調度，老弱派充後隊，管領輜重。待至戲地相近，又曉諭大眾，有進無退，進即重賞，退即斬首。兵役都是犯人出身，本來是不甚怕死，此次得了將令，都望賞賜，當即拚命殺出，衝入周文營中。周文自東至西，沿途未遇大敵，總道是秦人無用，意存輕視。不料章邯兵到，勢似潮湧，一時招架不住，只好倒退，那秦兵得佔便宜，越加厲害，殺得周軍七零八落，東逃西散。周文無法禁遏，也跑出函谷關去了，小子有詩歎道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-011', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-010-011', 'hangu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-012', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 12, 'narrative', 'carried', '[]'::jsonb, '孤軍轉戰入函關，一敗頹然即遁還﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-013', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 13, 'aside', 'carried', '[]'::jsonb, '銳進由來防速退，先賢名論總難刪。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-014', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 14, 'narrative', 'carried', '[]'::jsonb, '秦兵大捷，關內粗安，偏東方復迭出異人，與秦為難。就中更有個真命天子，乘時崛起，奮發有為。欲知他姓名履歷待至下回再詳。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-010-015', '前漢演義', 10, 209, '第10回·繫於「陳勝稱王，號張楚」', '', 15, 'commentary', 'carried', '[]'::jsonb, '張耳陳餘，號稱賢者，實亦策士之流亞耳。當其進謁陳勝，諫阻稱王，請勝西向，為勝計不可謂不忠。及勝不從忠告，便起異心，徇趙之計，出自二人，武臣為將，二人為副，渡河北赴，連下趙城，向時之阻勝稱王者，乃反以王號推武臣，何其自相矛盾若此？彼且曰：「為勝計，不宜稱王﹔為武臣計，正應稱王。」此即辯士之利口，熒惑人聽，實則無非為一己計耳。始欲助勝，繼即圖勝，纖芥之嫌，視若仇敵，策士之不可恃也如此。然二人之不克有成，亦於此可見矣。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-001', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 1, 'narrative', 'marker', '[9]'::jsonb, '卻說秦二世元年九月，江南沛縣地方，有個豐鄉陽裡村，出了一位真命天子，起兵靖亂，後來就是漢朝高祖皇帝，姓劉名邦字季。父名執嘉，母王氏，名叫含始。執嘉生性長厚，為裡人所稱美，故年將及老，時人統稱為太公。王氏與太公年齡相等，因亦呼為劉媼。劉媼嘗生二子，長名伯，次名仲，伯仲生時，無甚奇異，到了第三次懷孕，卻與前二胎不同。相傳劉媼有事外出，路過大澤，自覺腳力過勞，暫就堤上小坐，閉目養神，似寐非寐，驀然見一個金甲神人，從天而下，立在身旁，一時驚暈過去，也不知神人作何舉動。此亦與姜嫄履拇同一怪誕，大抵中國古史，好談神話，故有此異聞。惟太公在家，記念妻室，見他久出未歸，免不得自去追尋。剛要出門，天上忽然昏黑，電光閃閃，雷聲隆隆，太公越覺著急，忙攜帶雨具，三腳兩步，趨至大澤。遙見堤上睡著一人，好似自己的妻房，但半空中有雲霧罩住，迴環浮動，隱約露出鱗甲，象有蛟龍往來。當下疑懼交乘，又復停住腳步，不敢近前。俄而雲收霧散，天日復明，方敢前往審視，果然是妻室劉媼，欠伸欲起，狀態朦朧，到此不能不問。偏劉媼似無知覺，待至太公問了數聲，方睜眼四顧，開口稱奇。太公又問她曾否受驚，劉媼答道：「我在此休息，忽見神人下降，遂至驚暈，此後未知何狀。今始醒來，才知乃是一夢。」太公複述及雷電蛟龍等狀，劉媼全然不知，好一歇神氣復原，乃與太公俱歸。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-002', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 2, 'narrative', 'carried', '[10]'::jsonb, '不意從此得孕，過了十月，竟生一男。難道是神人所生麼？長頸高鼻，左股有七十二黑痣。太公知為英物，取名為邦，因他排行最小，就以季為字。太公家世業農，承前啟後，無非是春耕夏耘，秋收冬獲等事。伯仲二子，亦就農業，隨父營生。獨劉邦年漸長大，不喜耕稼，專好浪遊。太公屢戒勿悛，只好聽他自由。惟伯仲娶妻以後，伯妻素性慳吝，見邦身長七尺八寸，正是一個壯丁，奈何勤吃懶做，坐耗家產，心中既生厭恨，口中不免怨言。太公稍有所聞，索性分析產業，使伯仲挈眷異居。邦尚未娶妻，仍然隨著父母。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-003', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 3, 'narrative', 'carried', '[]'::jsonb, '光陰易過，倏忽間已是弱冠年華，他卻不改舊性，仍是終日遊蕩，不務生產。又往往取得家財，結交朋友，徵逐酒食。太公本說邦秉資奇異，另眼相看，至此見他年長無成，乃斥為無賴，連衣食都不願周給。邦卻怡然自得，不以為意，有時恐乃父叱逐，不敢回家，便至兩兄家內棲身。兩兄究係同胞，卻也呼令同食，不好漠視。那知伯忽得疾，竟致逝世，伯妻本厭恨小叔，自然不願續供了。邦胸無城府，直遂逕行，不管她憎嫌與否，仍常至長嫂家內索食。長嫂嘗借口孤寡，十有九拒，邦尚信以為真。一日更偕同賓客數人，到長嫂家，時正晌午，長嫂見邦復至，已恐他來擾午餐，討厭得很，再添了許多朋友，越覺不肯供給，雙眉一皺，計上心來，急忙趨入廚房，用瓢刮釜，佯示羹湯已盡，無從取供。邦本招友就食，乘興而來，忽聞廚中有刮釜聲，自悔來得過遲，未免失望。友人倒也知趣，作別自去。邦送友去後，回到長嫂廚內，探視明白，見釜上蒸氣正濃，羹湯約有大半鍋，才知長嫂逞刁使詐，一聲長歎，掉頭而出。不與長嫂爭論，便是大度。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-004', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 4, 'narrative', 'carried', '[]'::jsonb, '嗣是絕跡不至嫂家，專向鄰家兩酒肆中，做了一個長年買主。有時自往獨酌，有時邀客共飲。兩酒肆統是婦人開設，一呼王媼，一呼武婦。史記作負，負與婦通。二婦雖是女流，卻因邦為毗鄰少年，也不便斤斤計較﹔並且邦入肆中，酤客亦皆趨集，統日計算，比往日得錢數倍，二主婦暗暗稱奇，所以邦要賒酒，無不應允。邦生平最嗜杯中物，見二肆俱肯賒給，樂得盡情痛飲，往往到了黃昏，尚未回去，還要痛喝幾杯。待至醉後懶行，索性假寐座上，鼾睡一宵。王媼武婦，本擬喚他醒來，促令回家，誰知他頭上顯出金龍，光怪離奇，不可逼視。那時二婦愈覺希罕，料邦久後必貴，每至年終結帳，也不向邦追索。邦本阮囊羞澀，無從償還，歷年宕帳，一筆勾銷罷了。兩婦都也慷慨。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-005', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 5, 'narrative', 'carried', '[]'::jsonb, '但邦至弱冠後，非真絕無知識，也想在人世間，做些事業，幸喜交遊漸廣，有幾人替他謀划，教他學習吏事。他一學便能，不多時便得一差，充當泗上亭長。亭長職務，掌判斷裡人獄訟，遇有大事，乃詳報縣中，因此與一班縣吏，互相往來。最莫逆的就是沛縣功曹，姓蕭名何，與邦同鄉，熟諳法律。何為三杰之一，故特筆敘出。次為曹參夏侯嬰諸人，每過泗上，邦必邀他飲酒，暢談肺腑，脫略形骸。蕭何為縣吏翹楚，尤相關切，就使劉邦有過誤等情，亦必代為轉圜，不使得罪。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-006', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 6, 'narrative', 'carried', '[]'::jsonb, '會邦奉了縣委，西赴咸陽，縣吏各送贐儀，統是當百錢三枚，何獨饋五枚。及邦既入咸陽城，辦畢公事，就在都中閒逛數日。但見城闕巍峨，市廛輻湊，車馬冠蓋，絡繹道旁，已覺得眼界一新，油然生感。是時始皇尚未逝世，坐了鑾駕，巡行都中。邦得在旁遙觀，端的是聲靈赫濯，冠冕堂皇，至御駕經過，邦猶徘徊瞻望，喟然歎息道：「大丈夫原當如是哩！」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-011-006', 'xianyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-007', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 7, 'narrative', 'carried', '[]'::jsonb, '人人想做皇帝，無怪劉季。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-008', '前漢演義', 11, 209, '第11回·秦二世元年九', '', 8, 'narrative', 'carried', '[]'::jsonb, '既而出都東下，回縣銷差，仍去做泗上亭長。約莫過了好幾年，邦年已及壯了，壯猶無室，免不得悵及鰥居。況邦原是好色，怎能忍耐得住？好在平時得了微俸，除沽酒外，尚有少許餘蓄，遂向娼寮中尋花問柳，聊做那蜂蝶勾當。裡人豈無好女？只因邦向來無賴，不願與婚。邦亦並不求偶，還是混跡平康，隨我所欲，費了一些纏頭資，倒省了多少養婦錢。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-009', '前漢演義', 11, 209, '第11回·繫於「劉邦起兵於沛」', '', 9, 'narrative', 'event_keyword', '[]'::jsonb, '會由蕭何等到來晤談，述及單父單音善，父音斧。縣中，來了一位呂公，名父字叔平，與縣令素來友善。此次避仇到此，挈有家眷，縣令顧全友誼，令在城中居住，凡為縣吏，應出資相賀云云。邦即答道：「貴客辱臨，應該重賀，邦定當如約。」說畢，大笑不止。已寓微旨。何亦未知邦懷何意，匆匆別去。越日，邦踐約進城，訪得呂公住處，昂然逕入。蕭何已在廳中，替呂公收受賀儀，一見劉邦到來，便宣告諸人道：「賀禮不滿千錢，須坐堂下！」明明是戲弄劉邦。劉邦聽著，就取出名刺，上書賀錢盈萬，因即繳進。當有人持刺入報，呂公接過一閱，見他賀禮獨豐，格外驚訝，便親自出迎，延令上坐。端詳了好一會，見他日角鬥胸，龜背龍股，與常人大不相同，不由的敬禮交加，特別優待。蕭何料邦乏錢，從旁揶揄道：「劉季專好大言，恐無實事。」呂公明明聽見，仍不改容，待至酒肴已備，竟請邦坐首位。邦並不推讓，居然登席，充作第一位嘉賓。大眾依次坐下，邦當然豪飲，舉杯痛喝，興致勃然。到了酒闌席散，客俱告辭，呂公獨欲留邦，舉目示意。邦不名一錢，也不加懮，反因呂公有款留意，安然坐著。呂公既送客出門，即入語劉邦道：「我少時即喜相人，狀貌奇異，無一如季，敢問季已娶婦否？」邦答稱尚未。呂公道：「我有小女，願奉箕帚，請季勿嫌。」邦聽了此言，真是喜從天降，樂得應諾。當即翻身下拜，行舅甥禮，並約期親迎，歡然辭去。呂公入告妻室，已將娥姁許配劉季。娥姁即呂女小字，單名為雉。呂媼聞言動怒道：「君謂此兒生有貴相，必配貴人，沛令與君交好，求婚不允，為何無端許與劉季？難道劉季便是貴人麼？」呂公道：「這事非兒女子所能知，我自有慧鑒，斷不致誤！」呂媼尚有煩言，畢竟婦人勢力，不及乃夫，只好聽呂公備辦妝奩，等候吉期。轉瞬間吉期已屆，劉邦著了禮服，自來迎婦。呂公即命女雉裝束齊整，送上彩輿，隨邦同去。邦回轉家門，迓女下輿，行過了交拜禮，謁過太公劉媼，便引入洞房。揭巾覷女，卻是儀容秀麗，豐彩逼人，不愧英雌。頓時惹動情腸，就攜了呂女玉手，同上陽台，龍鳳諧歡，熊羆葉夢。過了數年，竟生了一子一女，後文自有表見，暫且不及報名。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-010', '前漢演義', 11, 209, '第11回·繫於「劉邦起兵於沛」', '', 10, 'narrative', 'carried', '[]'::jsonb, '只劉邦得配呂女，雖然相親相愛，備極綢繆，但他是登徒子一流人物，怎能遂不二色？況從前在酒色場中，時常廝混，免不得藕斷絲連，又去閒逛。湊巧得了一個小家碧玉，楚楚動人，詢明姓氏，乃係曹家女子，彼此敘談數次，竟弄得郎有情，女有意，合成一場露水緣，曹女卻也有識。她卻比呂女懷妊，還要趕早數月，及時分娩，就得一男。裡人多知曹女為劉邦外婦，邦亦並不諱言，只瞞著一個正妻呂雉，不使與聞。已暗伏呂雉之妒。待呂氏生下一子一女，曹女尚留住母家，由邦給資贍養，因此家中只居呂婦，不居曹妾。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-011', '前漢演義', 11, 209, '第11回·繫於「劉邦起兵於沛」', '', 11, 'narrative', 'carried', '[]'::jsonb, '邦為亭長，除乞假歸視外，常住亭中。呂氏但挈著子女，在家度日。劉家本非富貴，只靠著幾畝田園，作為生活，呂氏嫁夫隨夫，暇時亦至田間刈草，取做薪芻。適有一老人經過，顧視多時，竟向呂氏乞飲。呂氏憐他年老，回家取湯給老人，老人飲罷，問及呂氏家世，呂氏略述姓氏，老人道：「我不意得見夫人，夫人日後必當大貴。」呂氏不禁微哂，老人道：「我素操相術，如夫人相貌，定是天下貴人。」當時何多相士。呂氏將信將疑，又引子至老人前，請他相視，老人撫摩兒首，且驚且語道：「夫人所以致貴，便是為著此兒。」又顧幼女道：「此女也是貴相。」說畢自去。適值劉邦歸家，由呂氏具述老人言語，邦問呂氏道：「老人去了，有多少時候？」呂氏道：「時候不多，想尚未遠。」邦即搶步追去，未及里許，果見老人躑躅前行。便呼語道：「老丈善相，可為我一看否？」老人聞言回顧，停住腳步，即將邦上下打量一番，便道：「君相大貴，我所見過的夫人子女，想必定是尊眷。」邦答聲稱是。老人道：「夫人子女，都因足下得貴，嬰兒更肖足下，足下真貴不可言。」邦喜謝道：「將來果如老丈言，決不忘德！」老人搖首道：「這也何足稱謝。」一面說，一面轉身即行，後來竟不知去向。至劉邦興漢，遣人尋覓，亦無下落，只得罷了。惟當時福運未至，急切不能發跡，只好暫作亭長，靜待機會。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-012', '前漢演義', 11, 209, '第11回·繫於「劉邦起兵於沛」', '', 12, 'narrative', 'carried', '[]'::jsonb, '閒居無事，想出一種冠式，擬用竹皮制成。手下有役卒兩名，一司開閉埽除，一司巡查緝捕，當下與他商議，即由捕盜的役卒，謂薛地頗有冠師，能作是冠，邦便令前去。越旬餘見他返報，呈上新冠，高七寸，廣三寸，上平如板，甚合邦意。邦就戴諸首上，稱為劉氏冠。後來垂為定制，必爵登公乘，才得將劉氏冠戴著。這乃是漢朝特制，為邦微賤時所創出，後人號為鵲尾冠，便是劉邦的遺規了。敘入此事，見漢朝創制之權輿。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-013', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 13, 'narrative', 'marker', '[]'::jsonb, '二世元年，秦廷頒詔，令各郡縣遣送罪徒，西至驪山，添築始皇陵墓。沛縣令奉到詔書，便發出罪犯若干名，使邦押送前行。邦不好怠玩，就至縣中帶同犯人，向西出發。一出縣境，便逃走了好幾名，再前行數十里，又有好幾個不見，到晚間投宿逆旅，翌晨起來，又失去數人。邦孑然一身，既不便追趕，又不能禁壓，自覺沒法處置，一路走，一路想，到了豐鄉西面的大澤中，索性停住行蹤，不願再進。澤中有亭，亭內有人賣酒，邦嗜酒如命，怎肯不飲，況胸中方愁煩得很，正要借那黃湯，灌澆塊壘，當即覓地坐下，並令大眾都且休息，自己呼酒痛飲，直喝到紅日西沈，尚未動身。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-014', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 14, 'narrative', 'carried', '[]'::jsonb, '既而酒興勃發，竟抽身語眾道：「君等若至驪山，必充苦役，看來終難免一死，不得還鄉，我今一概釋放，給汝生路，可好麼？」大眾巴不得有此一著，聽了邦言，真是感激涕零，稱謝不置。邦替他一一解縛，揮手使去，眾又恐劉邦得罪，便問邦道：「公不忍我等送死，慨然釋放，此恩此德，誓不忘懷，但公將如何回縣銷差？敢乞明示。」邦大笑道：「君等皆去，我也只好遠揚了，難道還去報縣，尋死不成？」道言至此，有壯士十數人，齊聲語邦道：「如劉公這般大德，我數人情願相從，共同保衛，不敢輕棄。」邦乃申說道：「去也聽汝，從也聽汝。」於是十數人留住不行，餘皆向邦拜謝，踴躍而去。劉邦膽識，可見一斑。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-015', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 15, 'narrative', 'carried', '[]'::jsonb, '邦乘著酒興，戴月夜行，壯士十餘人，前後相從。因恐被縣中知悉，不敢履行正道，但從澤中覓得小徑，魚貫而前。小徑中最多荊莽，又有泥窪，更兼夜色昏黃，不便急走。邦又醉眼模糊，慢慢兒的走將過去，忽聽前面嘩聲大作，不禁動了疑心。正要呼問底細，那前行的已經轉來，報稱大蛇當道，長約數丈，不如再還原路，另就別途。邦不待說畢，便勃然道：「咄！壯士行路，豈畏蛇蟲？」說著，獨冒險前進。才行數十步，果見有大蛇橫架澤中，全然不避，邦拔劍在手，走近蛇旁，手起劍落，把蛇劈作兩段。復用劍撥開死蛇，辟一去路，安然趨過。行約數里，忽覺酒氣上湧，竟至昏倦，就擇一僻靜地方，坐下打盹，甚且臥倒地上，夢游黑甜鄉。待至醒悟，已是雞聲連唱，天色黎明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-016', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 16, 'narrative', 'carried', '[]'::jsonb, '適有一人前來，也是豐鄉人氏，認識劉邦，便與語道：「怪極！怪極！」邦問為何事？那人道：「我適遇著一個老嫗，在彼處野哭，我問他何故生悲？老嫗謂人殺我子，怎得不哭？我又問他子何故被殺，老嫗用手指著路旁死蛇，又向我嗚咽說著，謂我子系白帝子，化蛇當道，今被赤帝子斬死，言訖又淚下不止。我想老嫗莫非瘋癲，把死蛇當做兒子，因欲將她笞辱，不意我手未動，老嫗已經不見。這豈不是一件怪事？」邦默然不答，暗思蛇為我殺，如何有白帝赤帝等名目，語雖近誕，總非無因，將來必有征驗，莫非我真要做皇帝麼？想到此處，又驚又喜，那來人還道他酒醉未醒，不與再言，掉頭逕去。邦亦不復回鄉，自與十餘壯士，趨入芒碭二山間，蟄居避禍去了。小子有詩詠道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-017', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 17, 'narrative', 'carried', '[]'::jsonb, '不經冒險不成功，仗劍斬蛇氣獨雄﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-018', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 18, 'aside', 'carried', '[]'::jsonb, '漫說帝王分赤白，乃公原不與人同。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-019', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 19, 'narrative', 'carried', '[]'::jsonb, '劉邦避居芒碭山間，已有數旬，忽然來了一個婦人，帶了童男童女，尋見劉邦。欲知此婦為誰，請看下回便知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-011-020', '前漢演義', 11, 209, '第11回·二世元年，秦', '', 20, 'commentary', 'carried', '[]'::jsonb, '本回敘劉季微賤時事，脫胎《高祖本紀》，旁彩史漢各傳，語語皆有來歷，並非向壁虛造。惟史官語多忌諱，往往於劉季所為，舍瑕從善，經本回一一直敘，才得表明真相，不沒本來。蓋劉季本一酒色徒，其所由得成大業者，遊蕩之中，具有英雄氣象，後來老成練達，知人善任，始能一舉告成耳。若劉媼之感龍得孕，老嫗之哭蛇被斬，不免為史家附會之詞﹔然必謂竟無此事，亦不便下一斷筆。有聞必錄，抑亦述史者之應有事也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-001', '前漢演義', 12, 209, '第12回·二世元年，秦', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說芒碭二山，本來是幽僻的地方，峰回路轉，谷窈林冥。劉邦與壯士十餘人，寄身此地，無非為避禍起見，並恐被人偵悉，隨處遷移，蹤跡無定。偏有一婦人帶著子女，前來尋邦，好象河東熟路，一尋就著。邦瞧將過去，不是別人，正是那妻室呂氏。夫妻父子，至此聚首，正是夢想不到的事情。邦驚問原委，呂氏道：「君背父母，棄妻孥，潛身岩谷，只能瞞過別人，怎能瞞妾？」邦聞言益驚，越要詳問。呂氏道：「不瞞君說，無論君避在何地，上面總有雲氣蓋著，妾善望雲氣，所以知君下落，特地尋來。」父善相人，女善望氣，確是呂家特色。邦欣然道：「有這等事麼？我聞始皇常言，東南有天子氣，所以連番出巡，意欲厭勝，莫非始皇今死，王氣猶存，我劉邦獨能當此麼？」始皇語借口敘出，可省筆墨。呂氏道：「苦盡甘來，安知必無此事。但今日是甘尚未回，苦楚已吃得夠了。」說著，兩眼兒已盈盈欲淚，邦忙加勸慰，並問他近時苦況。待呂氏說明底細，邦亦不禁淚下盈眶。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-002', '前漢演義', 12, 209, '第12回·二世元年，秦', '', 2, 'narrative', 'carried', '[]'::jsonb, '原來邦西行後，縣令待他復報，久無消息。嗣遣役吏出外探聽明白，才知邦已縱放罪徒，逃走了去。當下派役搜查邦家，亦無著落，此時邦父太公，已令邦分居在外，倖免株連。只呂氏連坐夫罪，竟被縣役拘送至縣，監禁起來。秦獄本來苛虐，再經呂氏手頭乏錢，不能賄托獄吏，獄吏遂倚勢作威，任意凌辱。且因呂氏華色未衰，往往在旁調戲，且笑且嘲。呂氏舉目無親，沒奈何耐著性子，忍垢蒙羞，巧有一個小吏任敖，也在沛縣中看管獄囚，平時與劉邦曾有交誼，一聞邦妻入獄，便覺有心照顧，雖然呂氏不歸他看管，究竟常好探視，許多便當。某夕又往視呂氏，甫至獄門，即有泣聲到耳。他便停步細聽，復聞獄吏吆喝聲，嫚侮聲，謔浪笑敖，語語難受。頓時惱動俠腸，大踏步跨入門內，掄起拳頭，就向該獄吏擊去。獄吏猝不及防，竟被他毆了數拳，打得頭青目腫，兩下裡扭做一團，往訴縣令。縣令登堂審問，彼此各執一詞，一說是獄吏無禮，調戲婦女，一說是任敖可惡，無端辱毆。縣令見他各有理由，倒也不好遽判曲直，只好召入功曹蕭何，委令公斷。蕭何謂獄吏知法犯法，情罪較重，應該示懲。任敖雖屬粗莽，心實可原，宜從寬宥。左袒任敖，就是隱護呂氏。這讞案一經定出，縣令亦視為至公，把獄吏按律加罰。獄吏挨了一頓白打，還要加受罪名，真是自討苦吃，俯首退下，連呼晦氣罷了。誰教你凌辱婦人？蕭何更為呂氏解免，說他身為女流，不聞外事，乃夫有過，罪不及妻，不如釋出呂氏，較示寬大等語。縣令也得休便休，就將呂氏釋放還家。呂氏既至家中，不知如何探悉乃夫，竟挈子女尋往芒碭，得與劉邦相遇。據呂氏謂望知雲氣，或果有此慧眼，亦未可知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-003', '前漢演義', 12, 209, '第12回·二世元年，秦', '', 3, 'narrative', 'carried', '[]'::jsonb, '邦已會晤妻孥，免得憶家，索性在芒碭山中，尋一幽谷，作為家居。後世稱芒碭山中有皇藏峪，便是因此得名，這且不必絮述。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-004', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 4, 'narrative', 'event_keyword', '[9]'::jsonb, '且說陳勝起兵蘄州，傳檄四方，東南各郡縣，往往戕殺守令，起應陳勝。沛縣與蘄縣相近，縣令恐為勝所攻，亦欲舉城降勝。蕭何曹參獻議道：「君為秦吏，奈何降盜？且恐人心不服，反致激變，不若招集逋亡，收得數百人，便可壓制大眾，保守城池。」縣令依議，乃遣人四出招徠。蕭何又進告縣令，謂劉季具有豪氣，足為公輔，若赦罪召還，必當感激圖報。縣令也以為然，遂使樊噲往召劉邦。噲亦沛人，素有膂力，家無恒產，專靠著屠狗一業，當做生涯，娶妻呂嬃，就是呂公的少女，呂雉的胞妹。噲得呂嬃為妻，想亦由呂公識相，特配以女，好與劉邦做成一對特別連襟。縣令因他與邦有親，故叫他召邦。果然噲已知邦住處，竟至芒碭山中，與邦相見，具述沛令情意。邦在山中已八九月，收納壯士，約有百人，既聞沛令相招，便帶領家屬徒眾，與噲同詣沛縣。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-005', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 5, 'narrative', 'carried', '[]'::jsonb, '行至中途，驀見蕭何曹參，狼狽前來。當即驚問來意，蕭曹二人齊聲道：「前請縣令召公，原期待公舉事，不意縣令忽有悔意，竟疑我等召公前來，將有他變，特下令閉守城門，將要誅我兩人，虧得我兩人聞風先逃，逾城而出，尚得苟延生命。現只有速圖良策，保我家眷了。」邦笑答道：「承蒙兩公不棄，屢次照拂，我怎得不思報答？幸部眾已有百人，且到城下察看形勢，再作計較。」蕭曹二人，遂與邦復返，同至沛縣城下。城門尚是關著，無從闖入。蕭何道：「城中百姓，未必盡服縣令，不若先投書函，叫他殺令自立，免受秦毒。可惜城門未開，無法投遞，這卻如何是好？」劉邦道：「這有何難？請君速即繕書，我自有法投入。」蕭何聽著，急忙草就一書，遞與劉邦。邦見上面寫著道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-005', 'pei', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-006', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 6, 'narrative', 'event_keyword', '[]'::jsonb, '天下苦秦久矣！今沛縣父老，雖為沛令守城，然諸侯並起，必且屠沛。為諸父老計，不若共誅沛令，改擇子弟可立者以應諸侯，則家室可完！不然，父子俱屠無益也。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-006', 'pei', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-007', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 7, 'narrative', 'carried', '[]'::jsonb, '邦約略閱過，便道：「寫得甚好！」便將書加封，自帶弓箭，至城下呼守卒道：「爾等毋徒自苦，請速看我書，便可保住全城生命。」說罷，即把書函系諸箭上，用弓搭著，颼的一聲，已將箭乾射至城上。城上守卒，見箭上有書，取過一閱，卻是語語有理，便下城商諸父老。父老一體贊成，竟率子弟們攻入縣署，立把縣令殺死，然後大開城門，迎邦入城。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-008', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 8, 'narrative', 'event_keyword', '[]'::jsonb, '邦集眾會議，商及善後方法，眾願推邦為沛令，背秦自主。邦慨然道：「天下方亂，群雄並起，今若置將不善，一敗塗地，悔何可追？我非敢自愛，恐德薄能鮮，未能保全父老子弟，還請另擇賢能，方足圖謀大事。」眾見邦有讓意，因更推蕭何曹參，蕭曹統是文吏出身，未嫻武事，只恐將來無成，誅及宗族，因力推劉邦為主，自願為輔。邦仍然推辭，諸父老同聲說道：「平生素聞劉季奇異，必當大貴，且我等已問過卜筮，莫如季為最吉，望勿固辭！」邦還想讓與別人，偏大眾俱不敢當，只好毅然自任，應允下去。眾乃共立劉邦為沛公，是時劉邦年已四十有八了。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-009', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 9, 'narrative', 'carried', '[9]'::jsonb, '九月初吉，邦就沛公職，祠黃帝，祭蚩尤，殺牲釁鼓，特制赤旗赤幟，張掛城中。他因前時斬蛇，老嫗夜哭，有赤帝子斬白帝子語，故旗幟概尚赤色。即授蕭何為丞，曹參為中涓，樊噲為舍人，夏侯嬰為太僕，任敖等為門客。部署既定，方議出兵。看官聽說！自劉邦做了沛公，史家統稱沛公二字，作為代名，小子此後敘述，也即稱為沛公，不稱劉邦了。沛公令蕭何曹參，收集沛中子弟，得二三千人，出攻胡陵方與，俱縣名，方音旁，與音豫。命樊噲夏侯嬰為統將，所過無犯。胡陵方與二守令，不敢出戰，但閉城守著。噲與嬰正擬進攻，忽接到沛公命令，乃是劉媼去世，宜辦理喪葬，未遑治兵，因召二人還守豐鄉。二人不好違命，只得率眾還豐。沛公至豐治喪，暫將軍事擱起。那故楚會稽郡境內，又出了項家叔姪，戕吏起事，集得子弟八千人，橫行吳中。敘出項氏叔姪，筆亦不苟。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-009', 'feng', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-009', 'wu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-010', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 10, 'narrative', 'carried', '[]'::jsonb, '看官欲知他叔姪姓名，便是項梁項籍。項梁本下相縣人，即楚將項燕子，燕為秦將王翦所圍，兵敗自殺，楚亦隨亡。梁既遭國難，復念父仇，常思起兵報復，只因秦方強盛，自恨手無寸鐵，不能如願。有姪名籍，表字子羽，少年喪父，依梁為生。梁令籍學書，歷年無成，改令學劍，仍復無成。梁不禁大怒，呵叱交加，籍答說道：「學書有甚麼大用？不過自記姓名。學劍雖稍足護身，也只能敵得一人。一人敵何如萬人敵，籍願學萬人敵呢！」有志如此，也好算是英雄。梁聽了籍言，怒氣漸平，方語籍道：「汝有此志，我便教汝兵法。」籍情願受教。梁祖世為楚將，受封項地，故以項為姓。家中雖遭喪亂，尚有祖傳遺書，未曾毀滅，遂一律取出，教籍閱讀。籍生性粗莽，展卷時卻很留心，漸漸的倦怠起來，不肯研究，所以兵法大意，略有所知，終未能窮極底蘊。籍之終於無成者，便由此夫。梁知他的本性難移，聽他蹉跎過去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-011', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 11, 'narrative', 'carried', '[]'::jsonb, '既而梁為仇家所訐，株連成獄，被系櫟陽縣中。幸與蘄縣獄掾曹無咎，素相認識，作書請托，得無咎書，投遞獄掾司馬欣，替梁緩頰，梁才得減罪，出獄還家。惟梁是將門遺種，怎肯受人搆陷，委屈了事？冤冤相湊，那仇人被梁遇著，由梁與他評論曲直，仇人未肯認過，惹起梁一番鬱憤，竟把仇人拳打足踢，毆死方休。一場大禍，又復闖出，自恐殺人坐罪，為吏所捕，不得已帶同項籍，避居吳中。吳中士大夫，未知項梁來歷，梁亦隱姓埋名，偽造氏族，出與士大夫交際，遇事能斷，見義必為，竟得吳人信從，相率悅服。每遇地方興辦大工，及豪家喪葬等事，輒請梁為主辦。梁約束徒眾，派撥役夫，俱能井井有條，差不多與行軍相似，吳人越服他才識，願聽指揮。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-011', 'yueyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-011', 'wu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-012', '前漢演義', 12, 209, '第12回·繫於「劉邦起兵於沛」', '', 12, 'narrative', 'carried', '[]'::jsonb, '當秦始皇東巡時，渡浙江，游會稽，梁與籍隨著大眾，往看鑾駕。大眾都盛稱天子威儀，一時無兩，獨籍指語叔父道：「他！句他雖然是個皇帝，據姪兒看來，卻可取得，由我代為呢！」與劉季語異心同。梁聞言大驚，忙舉手掩住籍口道：「休得胡言，倘被聽見，罪及三族了！」籍才不復說，與梁同歸。時籍年已逾冠，身長八尺，悍目重瞳，力能扛鼎，氣可拔山，所有三吳少年，無一能與籍比勇，個個憚籍。梁見籍藝力過人，也料他不在人下，因此陰蓄大志，潛養死士數十人，私鑄兵器，靜待時機。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-012', 'wu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-013', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 13, 'narrative', 'event_keyword', '[]'::jsonb, '到了陳勝發難，東南擾攘，梁正思起應，忽由會稽郡守殷通，差人前來，召梁入議。梁奉召即往，謁見郡守，殷通下座相迎，且引入密室，低聲與語道：「蘄陳失守，江西皆叛，看來是天意亡秦，不可禁止了。我聞先發制人，後發為人所制，意欲乘機起事，君意以為何如？」這一席話，正中項梁心坎，便即笑顏相答，一力贊成。殷通又道：「行兵須先擇將，當今將才，宜莫如君。還有勇士桓楚，也是一條好漢，可惜他犯罪逃去，不在此地。」梁答道：「桓楚在逃，他人都無從探悉，惟姪兒項籍，頗知楚住處。若召楚前來，更得一助，事無不成了！」殷通喜道：「令姪既知桓楚行蹤，不得不煩他一往，叫楚同來。」梁又說道：「明日當囑籍進謁，向公聽令。」說著，即起身告辭，逕回家中，私下與籍計議多時，籍一一領教。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-013', 'wu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-014', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 14, 'narrative', 'event_keyword', '[]'::jsonb, '翌日早起，梁令籍裝束停當，暗藏利劍，隨同前往。既至郡衙，即囑籍靜候門外，待宣乃入。並申誡道：「毋得有誤！」話裡藏刀。籍唯唯如命。梁即入見郡守殷通，報稱姪兒已到，聽候公命。殷通道：「現在何處？」梁答道：「籍在門外，非得公命，不敢擅入。」殷通聞言，忙呼左右召籍。籍在外佇候傳呼，一聞內召，便趨步入門，直至殷通座前。通見籍軀幹雄偉，狀貌粗豪，不由的喜歡得很，便向梁說道：「好一位壯士，真不愧項君令姪。」梁微笑道：「一介蠢夫，何足過獎。」殷通乃命籍往召桓楚，梁在旁語籍道：「好行動了。」口中說著，眼中向籍一瞅。籍即拔出懷中藏劍，搶前一步，向通砍去，首隨劍落，屍身倒地。殷通的魂靈兒恐尚莫名其妙。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-015', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 15, 'narrative', 'carried', '[]'::jsonb, '梁俯檢屍身，取得印綬，懸諸腰間。復將通首級拾起，提在手中，與項籍一同出來。行未數步，就有許多武夫，各持兵器，把他攔住。籍有萬夫不當的勇力，看那來人不過數百，全不放在心裡，一聲叱咤，舉劍四揮，劍光閃處，便有好幾個頭顱，隨劍落地。眾武夫不敢近籍，一步步的倒退下去。籍索性大展武藝，仗著一柄寶劍，向前奮擊，復殺死了數十人，嚇得餘眾四散奔逃，不留一人。府中文吏，越覺心慌，統在別室中躲著，不敢出頭。還是項梁自去找尋，叫他無恐，盡至外衙議事。於是陸續趨出，戰兢兢的到了梁前。梁婉言曉諭，無非說是秦朝暴虐，郡守貪橫，所以用計除奸，改圖大事。眾人統皆驚惶，怎敢說一個不字，只好隨聲應諾，暫保目前。梁又召集城中父老，申說大意，父老等不敢反抗，同聲應命。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-016', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 16, 'narrative', 'carried', '[]'::jsonb, '全城已定，派吏任事。梁自為將軍，兼會稽郡守，籍為偏將，遍貼文告，招募兵勇。當有丁壯逐日報名，編入軍籍，復訪求當地豪士，使為校尉，或為候司馬。有一人不得充選，竟效那毛遂故事，侈然自薦。項梁道：「我非不欲用君，只因前日某處喪事，使君幫辦，君尚未能勝任，今欲舉大事，關係甚巨，豈可輕易用人！君不如在家安身，尚可無患。」這一席話，說得那人垂頭喪氣，懷慚自去。眾益稱項梁知人，相偕畏服。梁即使籍往徇下縣。籍引兵數百，出去招安，到處都怕他英名，無人與抗，或且投效馬前，願隨麾下，籍並收納，計得士卒八千人，統是膂力方剛，強壯無比。籍年方二十有四，做了八千子弟的首領，越顯出一種威風。他表字叫做子羽，因嫌雙名累墜，減去一字，獨留羽字，自己呼為項羽，別人亦叫他項羽，所以古今相傳，反把項羽二字出名，小子後文敘述，也就改稱項羽了。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-012-016', 'wu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-017', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 17, 'narrative', 'carried', '[]'::jsonb, '欲成大業在開端，有勇非難有德難﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-018', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 18, 'aside', 'carried', '[]'::jsonb, '一劍敢揮賢郡守，發硎先已太兇殘。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-019', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 19, 'aside', 'carried', '[]'::jsonb, '項氏略定江東，同時又有幾個草頭王，霸據一方。欲知姓名履歷，容至下回再詳。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-012-020', '前漢演義', 12, 209, '第12回·繫於「項梁、項籍起兵於吳」', '', 20, 'commentary', 'carried', '[]'::jsonb, '劉項起兵，跡似相同，而情則互異。沛令從蕭何言，往召劉邦，設非後來之翻悔，則亦不至自殺其身。且殺令者為沛中父老，非真邦親手下刃也。若項梁之赴召，明明為郡守之誠意，梁正不妨依彼舉事，為君父復仇，何必計囑項籍，無端下刃乎！況仇為秦皇，無關郡守，殺之尤為無名，適以見其貪詐耳。觀此而劉項之仁暴，即此而分，即劉項之成敗，從此而定。老夫劉邦之退讓鳴恭，項梁之專橫自立，蓋第為一節之見端，猶其小焉者也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-001', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說陳勝為張楚王，曾遣魏人周市，北略魏地。見前文第十回。市引兵至狄城，狄令擬嬰城固守。適有故齊王遺族田儋，充當城守，獨與從弟田榮田橫等，潛謀自立。當即想出一法，佯把家奴縛住，說他有通敵情事，押解縣署，自率少年同往，請縣令定罪加誅。縣令不知是計，貿然出訊，被田儋拔出寶劍，砍死縣令，也與項梁相類，怪不得與梁同死。遂招豪吏子弟，當面曉諭道：「諸侯皆背秦自立，我齊人如何落後？況齊為古國，由田氏為主百數十年，儋為田氏後裔，理應王齊，光復舊物。」大眾各無異言，儋遂自稱齊王，募兵數千，出擊周市。周市經過魏地，未遇劇戰，猛見齊人奮勇前來，料知不便輕敵，遂即引兵退還。儋既擊退周市軍，威名漸震，便遣榮橫等分出招撫，示民恢復。齊人正因秦法暴虐，追懷故國，聞得田儋稱王，自然踴躍投誠，不勞兵革。惟周市退還魏地，魏人亦欲推市為王，市慨然道：「天下昏亂，乃見忠臣，市本魏人，應該求立魏王遺裔，才好算是忠臣呢。」會聞魏公子咎，投效陳勝麾下，市即遣使往迎。勝不肯將咎放歸，再經市再三固請，直至使人往復五次，方得陳勝允許，命咎返魏，立為魏王。市為魏相，輔咎行政。於是楚趙齊魏已成四國。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-002', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 2, 'narrative', 'carried', '[]'::jsonb, '同時尚有燕王出現，看官道是何人？原來就是趙將韓廣。見前文第十回。趙王武臣，使韓廣略燕，廣一入燕境，各城望風歸附，燕地大定。燕人且欲奉廣為王，廣也欲據燕稱尊﹔但因家屬居趙，並有老母在堂，不忍致死，所以對眾告辭，未敢相從。燕人說道：「當今楚王最強，尚不敢害趙王家屬，趙王豈敢害將軍老母？盡請放心，不妨自主。」廣見燕人說得有理，便自稱燕王。趙王武臣，得知此信，遂與張耳陳餘商議，兩人意見，以為殺一老嫗，無甚益處，不如遣令歸燕，示彼恩惠，然後乘他不防，再行攻燕未遲。武臣依議，遣人護送廣母，並廣妻子，一同赴燕。廣得與骨肉相見，當然大喜，厚待趙使，遣令歸謝。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-003', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 3, 'narrative', 'carried', '[]'::jsonb, '武臣便欲侵燕，親率張耳陳餘諸人，出駐燕趙交界的地方。早有探馬報知韓廣，廣恐趙兵入境，急令邊境戒嚴，增兵防守。張耳陳餘，覘知燕境有備，擬請武臣南歸，徐作後圖。偏武臣志在得燕，未肯空回，耳餘也無可如何，只好隨著武臣，仍然駐紮。惟彼此分立營帳，除有事會議外，各守各營，未嘗同住。武臣獨發生異想，竟思潛入燕界，窺探虛實，只恐耳餘二人諫阻，不願與議，自己放大了膽，改裝易服，扮做平民模樣，挈了僕從數名，竟出營門，偷入燕境。燕人日夕巡邏，遇有閒人出入，都要盤查底細，方才放過。冒冒失失的趙王武臣，不管甚麼好歹，闖將進去，即被燕人攔住，向他究詰。武臣言語支吾，已為燕人所疑，就中還有韓廣親卒，奉令助守，明明認得武臣，大聲叫道：「這就是趙王。快快拿住！」道言未絕，守兵都想爭功，七手八腳，來縛武臣，武臣還想分辯，那鐵鏈已套上頭頸，好似鳳陽人戲猢猻，隨手牽去。咎由自取。餘外僕從，多半被拘，有兩三個較為刁猾，轉身就走，奔還趙營，報知張耳陳餘。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-004', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 4, 'narrative', 'carried', '[]'::jsonb, '耳餘兩人，統吃了一大驚，尋思沒法營救，互商多時，別無他策，只有選派辯士，往說燕王韓廣，願將金銀珍寶，贖回趙王。及去使返報，述及燕王索割土地，必須將趙國一半，讓與了他，方肯放還趙王。張耳道：「我國土地，也沒有甚麼闊大，若割去一半，便是不成為國了。這事如何允許！」陳餘道：「廣本趙臣，奈何無香火情﹔況從前送還家眷，亦應知感，今當致書詰責，令彼知省，萬不得已，亦只能許讓一二城，怎得割界一半呢？」書生迂論。張耳躊躇一會，委實沒法，乃依陳餘言，寫好書信，復遣使齎去。那知待了數日，杳無複音，再派數人往探消息，仍不見報。到後來逃回一人，說是燕王韓廣，貪虐得很，非但不允所請，反把我所遣各使，陸續殺死。頓時惱動了張耳陳餘，恨不即驅動大眾，殺入燕境，把韓廣一刀兩段。但轉想投鼠忌器，如欲與燕開戰，勝負未可預料，倒反先送了趙王性命。兩人搔頭挖耳，思想了兩三日，終沒有甚麼良策，忽帳外有人入報道：「大王回來了！」張耳陳餘，又驚又疑，急忙出營探望。果見趙王武臣，安然下車，後面隨一御人，從容入帳。二人似夢非夢，不得不上前相迎，擁入營中，詳問情狀。我亦急欲問明。武臣微笑道：「兩卿可問明御夫。」二人旁顧御者，御者便將救王計策，說明底細。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-005', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 5, 'narrative', 'carried', '[]'::jsonb, '原來御人本趙營廝卒，不過在營充當火夫，炊爨以外，別無他長。自聞趙王被掠，張陳兩將相，束手無策，他卻顧語同儕道：「我若入燕，包管救出我王，安載回來！」同儕不禁失笑道：「汝莫非要去尋死不成？試想使人十數，奉命赴燕，都被殺死，汝有甚麼本領，能救我王？」廝卒不與多言，竟換了一番裝束，悄悄馳往燕營，燕兵即將他拘住，廝卒道：「我有要事來報汝將軍，休得無禮！」燕兵不知他有何來歷，倒也不敢加縛，好好的引他入營。廝卒一見燕將，作了一個長揖，便開口問燕將道：「將軍知臣何為而來？」燕將道：「汝系何人？」廝卒道：「臣系趙人。」直認不諱，確是有膽有識。燕將道：「汝既是趙人，無非來做說客，想把趙王迎歸。」廝卒道：「將軍可知張耳陳餘為何等人？」颺開一筆妙。燕將道：「頗有賢名，今日想亦無策了。」廝卒道：「將軍可知兩人的志願否？」燕將道：「也不過欲得趙王。」廝卒啞然失笑，吃吃有聲，好做作。燕將怒道：「何事可笑！」廝卒道：「我笑將軍未知敵情，我想張耳陳餘，與武臣並轡北行，唾手得趙數十城。他兩人豈不想稱王？但因初得趙地，未便分爭，論起年齡資格，應推武臣為王，所以先立武臣，暫定人心。今趙地已定，兩人方想平分趙地，自立為王。可巧趙王武臣，為燕所拘，這正是天假機緣，足償彼願。佯為遣使，求歸趙王，暗中巴不得燕人下手，立把趙王殺死，他好分趙自立，一面合兵攻燕，借口報仇，人心一奮，何戰不克？將軍若再不知悟，中他詭計，眼見得燕為趙滅了！」三寸舌賢於十萬師。燕將聽了，頻頻點首，待廝卒說罷，便道：「據汝說來，還是放還趙王為妙。」正要你說出這句。廝卒道：「放與不放，權在燕國，臣何敢多口！又作一颺愈妙。但為燕國計，不如放還趙王，一可打破張陳詭謀，二可永使趙王感激，就使張陳逞刁，有趙王從中牽制，還有何暇圖燕呢！」明明為自己計，反說為燕國計，真好利口。燕將乃進白韓廣，廣也信為真情，遂放出趙王武臣，依禮相待，並給車一乘，使廝卒御王還趙。張耳陳餘，窮思極索，反不及廝卒一張利口，也覺驚歎不置。趙王武臣，乃拔營南歸，馳回邯鄲。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-005', 'handan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-006', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 6, 'narrative', 'carried', '[]'::jsonb, '適趙將李良，自常山還報，謂已略定常山，因來復命。趙王復使良往略太原，進至井陘。井陘為著名關塞，險要得很，秦用重兵扼守，阻住良軍。良引兵到了關下，正擬進攻，偏有秦使到來，遞入一書，書面並不加封，由良順手取出一紙，但見上面寫著，竟是秦二世的諭旨。略云：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-006', 'jingxing', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-007', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 7, 'narrative', 'carried', '[]'::jsonb, '皇帝賜諭趙將李良：良前曾事朕，得膺貴顯，應知朕待遇之隆，不應相負。今乃背朕事趙，有乖臣誼，若能翻然知悔，棄趙歸秦，朕當赦良罪，並予貴爵，朕不食言！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-008', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 8, 'narrative', 'carried', '[]'::jsonb, '李良看罷，未免心下加疑。他本做過秦朝的官員，只因位居疏遠，乃歸附趙國，願事趙王。此次由二世來書，許賜官爵，究竟是事趙呢？還是事秦呢！那知這封書信，並不由二世頒給，乃是守關秦將，假托二世諭旨，誘惑李良，且故意把書不封，使他容易漏泄，傳入趙王耳中，令彼相疑，這就叫做反間計呢。李良不知是計，想了多時，方得著一條主意。當下遣回秦使，自引兵逕回邯鄲，且到趙王處申請添兵，再作計較。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-008', 'handan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-009', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 9, 'narrative', 'carried', '[]'::jsonb, '一路行來，距邯鄲只十餘里，遙見有一簇人馬，吆喝前來，當中擁著鑾輿，前後有羽扇遮蔽，男女僕從，環繞兩旁，彷彿似王者氣象。暗想這種儀仗，除趙王外還有何人？遂即一躍下馬，伏謁道旁，那車馬疾馳而至，頃刻間已到李良面前，良不敢抬頭，格外俯伏，口稱臣李良見駕。道言甫畢，即聽車中傳呼，令他免禮。良才敢昂起頭來，約略一瞧，車中並不是趙王，乃是一個華裝炫服的婦人。正要開口啟問，那車馬已似風馳電掣一般，向前自去。李良勃然起立，顧問從吏道：「適才經過的車中，究係何人坐著？」有數人認得是趙王胞姊，便據實相答。良不禁羞慚滿面，且愧且忿道：「王姊乃敢如此麼？」旁有一吏接口道：「天下方亂，群雄四起，但教才能邁眾，便可稱尊。將軍威武出趙王右，趙王尚且優待將軍，不敢怠慢，今王姊乃一女流，反敢昂然自大，不為將軍下車，將軍難道屈身婦女，不思雪恥麼？」這數語激動李良怒氣，越覺憤憤不平，便下令道：「快追上前去，拖落此婦，一泄我恨！」說著，便奮身上馬，加鞭疾走。部眾陸續繼進，趕了數里，竟得追著王姊的車馬，就大聲呼喝道：「大膽婦人，快下車來！」王姊車前的侍從，本沒有什麼驍勇，不過擺個場面，表示雌威。既見李良引眾趕來，料他不懷好意，統嚇得戰戰兢兢。有幾個膽子稍大的，還道李良不識王姊，因此撒野，遂撐著喉嚨，朗聲答道：「王姊在此，汝是何人，敢來戲侮？」李良叱道：「甚麼王姊不王姊？就使趙王在此，難道敢輕視大將不成！」一面說，一面拔出佩劍，橫掠過去，砍倒了好幾人。部眾又揚聲助威，霎時間把王姊侍從，盡行嚇散。王姊素來嗜酒，此次出遊郊外，正是為飲酒起見。她已喝得醉意醺醺，所以前遇李良，視作尋常小吏，未嘗下車。邯鄲城內豈無美酒，且身為王姊，何求不得，必要出城覓飲，真是自來送死！偏偏弄成大錯，狹路中碰著冤家，竟至侍從逃散，單剩了孤身隻影，危坐車中。正在沒法擺佈，見李良已躍下了馬，伸出蒲扇一般的大手，向她一抓。她便身不由主，被良抓出，摔在地上，跌得一個半死半活。是喝酒的回味。發也散了，身也疼了，淚珠兒也流下來了，索性拚著一死，痛罵李良。良正忿不可耐，怎忍被她辱罵？便舉劍把她一揮，斷送性命。好去做女酒鬼了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-009', 'handan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-010', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 10, 'narrative', 'carried', '[]'::jsonb, '王姊既死，良已知闖了大禍，還是先發制人，乘著趙王尚未知曉，一口氣跑到邯鄲。邯鄲城內的守兵，見是李良回來，當然放他進城，他竟馳入王宮，去尋趙王武臣。武臣毫不預防，見良引眾進來，不知為著何事，正要向良問明，良已把劍砍到，一時不及閃避，立被劈死。宮中衛兵，突然遭變，統皆逃去。良又搜殺宮中，把趙王武臣家眷，一體屠戮，再分兵出宮，往殺諸大臣，左丞相邵騷，也冤冤枉枉的死於非命。不良如此，如何名良！只右丞相張耳，大將軍陳餘，已得急足馳報，溜出城門，不遭毒手。兩人素有聞望，為眾所服，所以城中逃出的兵民，陸續趨附。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-010', 'handan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-011', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 11, 'narrative', 'carried', '[]'::jsonb, '才過了一二日，已聚了數萬人，兩人便想編成隊伍，再入邯鄲，替趙王武臣報仇，適有張耳門客，為耳獻謀道：「公與陳將軍，均系梁人，羈居趙地，趙人未必誠心歸附。為兩公計，不如訪立趙後，由兩公左右夾輔，導以仁義，廣為號召，方可掃平亂賊，得告成功。」張耳也覺稱善，轉告陳餘，餘亦贊成。乃訪得故趙後裔，叫做趙歇，立為趙王，暫居信都。那李良已據住邯鄲，脅迫居民，奉他為主，遂部署徒眾，增募兵勇，約得一二萬人，即擬往攻張耳陳餘，會聞張陳復立趙王歇，傳檄趙地，料他必來報復，還是趕早發兵，往攻信都，較佔先著。主見已定，當即率兵前往，倍道亟進。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-011', 'handan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-012', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 12, 'narrative', 'carried', '[]'::jsonb, '張耳陳餘，正思出擊邯鄲，巧值李良自來討戰，便由張耳守城，陳餘出敵。安排妥當，餘即領兵二萬，開城前行，約越數里，已與李良相遇。兩陣對圓，兵刃相接，彼此才經戰鬥，李良麾下的人馬，已多離叛，四散奔逃。看官聽說！師直為壯，曲為老，本是兵法家的恒言。李良已為趙臣，無端生變，入弒趙王，並把趙王家眷，屠戮殆盡，這乃大逆不道的行為。時局雖亂，公論難逃，人人目李良為亂賊，不過邯鄲城內的百姓，無力抵禦，只好勉強順從。良尚自鳴得意，引眾攻入，怎能不溃？張耳陳餘，本來是有些名聲，更且此番出師，純然為主報仇，光明坦白，又擁立一個趙歇，不沒趙後，足慰趙人想望，因此同心同德，一古腦兒殺將上去。李良抵當不住，部眾四竄，各自逃生。陳餘見良軍敗退，趁勢追擊，殺得良軍七零八落，人仰馬翻。李良也逃命要緊，奔回邯鄲。尚恐陳餘前來攻城，支持不住，不若依了秦二世的來書，投降秦朝。當下派將守城，自率親兵數百人，逕至秦將章邯營中，屈膝求降去了。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-013-012', 'handan', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-013', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 13, 'narrative', 'carried', '[]'::jsonb, '人心叵測最難防，挾刃公然弒趙王﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-014', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 14, 'aside', 'carried', '[]'::jsonb, '只是輿情終未服，戰場一鼓便逃亡。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-015', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 15, 'aside', 'carried', '[]'::jsonb, '欲知章邯駐兵何地，待至下回敘明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-013-016', '前漢演義', 13, 209, '第13回·繫於「陳勝稱王，號張楚」', '', 16, 'commentary', 'carried', '[]'::jsonb, '趙王武臣，為燕所拘，張耳陳餘二人，竭畢生之智力，終不能迎還趙王，而大功反出一廝卒，可見皂隸之中，未嘗無才，特為君相者不善訪求耳。史稱廝卒御歸趙王，不錄姓氏，良由廝卒救王以後，未得封官，仍然湮沒不彰，故姓氏無從考據耳。夫有救主之大功，而不知特別超擢，此趙王武臣之所以終亡也。趙王姊出城游宴，得罪李良，既致殺身，並致亡國，古今來之破家復國者，往往由於婦人之不賢，然亦由君主之不知防閒，任彼所為，因至釀成巨釁。故武臣之死，釁由王姊，實即武臣自取之也，於李良乎何誅！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-001', '前漢演義', 14, 209, '第14回·繫於「陳勝稱王，號張楚」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說秦將章邯，自擊退周文後，追逐出關。文退至曹陽，又被章邯追到，不得不收眾與戰。那知軍心已散，連戰連敗，再奔入澠池縣境，手下已將散盡，那章邯還不肯罷休，仍然追殺過來。文勢窮力竭，無可奈何，便即拚生自刎，報了張楚王的知遇。士為知己者死，還算不負。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-002', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 2, 'narrative', 'marker', '[]'::jsonb, '時已為秦二世二年了，章邯遣使奏捷，二世更命長史司馬欣，都尉董翳，領兵萬人，出助章邯，囑邯進擊群盜，不必還朝。邯乃引兵東行，逕向滎陽進發。滎陽為楚假王吳廣所圍，數月未下。見前文第十回。及周文戰死，與章邯進兵的消息，陸續傳來，吳廣尚沒有他法，仍然頓屯城下，照舊駐紮。部將田臧李歸等，私下謀議道：「周文軍聞已敗溃了，秦兵旦暮且至，我軍圍攻滎陽，至今未克，若再不知變計，恐秦兵一到，內外夾攻，如何支持！現不若少留兵隊，牽制滎陽，一面悉銳前驅，往御秦軍，與決一戰，免致坐困。今假王驕不知兵，難與計議，看來只有除去了他，方好行事。」除去吳廣，亦未必遂能成功。於是決計圖廣，捏造陳王命令，由田臧李歸兩人齎入，直至廣前。廣下座接令，只聽得田臧厲聲道：「陳王有諭，假王吳廣，逗留滎陽，暗蓄異謀，應即處死！」說到死字，不待吳廣開口，便拔出佩刀，向廣砍去。廣只赤手空拳，怎能抵禦，況又未曾防著，眼見得身受刀傷，不能動彈。再經李歸搶上一步，剁下一刀，自然斃命。隨即梟了廣首，出示大眾，尚說是奉命誅廣，與眾無干。大眾統被瞞過，無復異言。也是廣平日不得眾心之過。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-002', 'xingyang', 5);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-003', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 3, 'narrative', 'carried', '[]'::jsonb, '田臧刁猾得很，即繕就一篇呈文，誣廣如何頓兵，如何謀變，說得情形活現，竟派人持廣首級，與呈文並達陳王。陳勝與吳廣同謀起兵，資格相等，本已暗蓄猜疑，既得田臧稟報，快意的了不得，還要去辨甚麼真假？當即遣還來使，另派屬吏齎著楚令尹印信，往賜田臧，且封臧為上將。臧對使受命，喜氣洋洋，一俟使人去訖，便留李歸等圍住滎陽，自率精兵西行，往敵秦軍。到了敖倉，望見秦軍漫山遍野，飛奔前來，旗械鮮明，兵馬雄壯，畢竟是朝廷將士，比眾不同，楚兵都有懼色，就是田臧也有怯容，沒奈何排成隊伍，準備迎敵。秦將章邯，素有悍名，每經戰陣，往往身先士卒，銳厲無前，此次馳擊楚軍，也是匹馬當先，親自陷陣。秦軍踴躍隨上，立將楚陣衝破，左右亂攪，好似虎入羊群，所向披靡。田臧見不可敵，正想逃走，恰巧章邯一馬突入，正與田臧打個照面，臧措手不及，被章邯手起一刀，劈死馬下。好與吳廣報仇。楚軍失了主帥，紛紛亂竄，晦氣的個個送終，僥倖的還算活命。章邯乘勝前進，直抵滎陽城下。李歸等聞臧敗死，已似攝去魂魄一般，茫無主宰，既與秦軍相值，不得不開營一戰。那秦軍確是利害，長槍大戟，無人敢當，再加章邯一柄大刀，旋風飛舞，橫掃千軍。李歸不管死活，也想挺槍與戰，才經數合，已由章邯大喝一聲，把好頭顱劈落地上，一道靈魂，馳入鬼門關，好尋著密友田臧，與吳廣同對冥簿去了。貪狡何益。餘眾或死或降，不消細敘。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-003', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-003', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-004', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 4, 'narrative', 'carried', '[]'::jsonb, '且說章邯陣斬二將，解滎陽圍，複分兵攻郯，逐去守將鄧說，自引兵進擊許城。許城守將伍徐，亦戰敗逃還，與鄧說同至陳縣，進見陳勝。勝查訊兩人敗狀，情跡不同，伍徐寡不敵眾，尚可曲原﹔獨鄧說不戰即逃，有忝職守，因命將他出，置諸死刑。遂命上柱國蔡賜，引兵御章邯軍，武平君畔，出使監郯下軍。時陵縣人秦嘉，銍縣人董■，符離縣人朱雞石，取慮縣人鄭布，徐縣人丁疾等，各糾集鄉人子弟，攻東海郡，屯兵郯下。武平君畔奉使至郯，欲借楚將名目，招撫各軍，秦嘉不肯受命，自立為大司馬，且遍告軍吏道：「武平君尚是少年，曉得甚麼兵事，我等難道受他節制麼？」說著，即率軍吏攻畔。畔麾下只數百人，怎能敵得過秦嘉，急切無從逃避，竟被殺死。就是上柱國蔡賜，與章邯軍交戰一場，也落得大敗虧輸，為邯所殺。邯長驅至陳，陳境西偏，有楚將張賀駐守，賀聞秦軍殺到，飛報陳勝，請速濟師。勝至此才覺驚惶，急忙調集將吏，呼令出援。偏是眾叛親離，無人效命，害得陳勝倉皇失措，只好帶領親卒千人，自往援應。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-004', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-004', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-005', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 5, 'narrative', 'carried', '[]'::jsonb, '原來勝自田間起兵，所有從前耕傭，多半與勝相識，且因勝有富貴不忘的約言，所以聞勝為王，統想攀鱗附翼，博取榮華。癩蝦蟆想吃天鵝肉。當下結伴至陳，叩門求見。門吏見他面目黧黑，衣衫襤褸，已是討厭得很，便即喝問何事？大眾也不曉得甚麼稱呼，但說是要見陳涉。門吏怒叱道：「大膽鄉愚，敢呼我王小字！」一面說，一面就顧令兵役，拿下眾人。還虧眾人連忙聲辯，說是陳王故交，總算門吏稍留情面，飭令免拿，但將他攆逐出去。大眾碰了一鼻子灰，心尚未死，鎮日裡在王宮附近，佇候陳勝出來，好與他見面扳談。果然事有湊巧，陳王整駕出門，眾人一齊上前，爭呼陳勝小字，陳勝聽著，低頭一瞧，都是貧賤時的好朋友，倒也不好怠慢，便命眾人盡載後車，一同入宮。鄉曲窮氓，驟充貴客，所見所聞，統是稀罕得很，不由的大呼小叫，滿口喧嘩。或說殿屋有這麼高大，或說帷帳有這般新奇，又大眾依著楚聲，伙頤伙頤，道個不絕。楚人謂多為伙，頤語助聲，即多咦之意。宮中一班役吏，實在瞧不過去，只因他們是陳王故人，不便發作，但把那好酒好肉，取供大嚼。眾人吃得高興，越加胡言亂道，往往拍案喧呼道：「陳涉陳涉，不料汝竟有此日！沈沈王府，由汝居住。」還有幾個湊趣的愚夫，隨口接著道：「我想陳涉傭耕時，衣食不週，吃盡苦楚，為何今日這般顯耀，交此大運呢？」隨後你一句，我一語，各將陳勝少年的故事，敘述出來，作為笑史。誰知談笑未終，刀鋸已伏，這種鄙俚瑣褻的言論，早有人傳入陳王耳中，且請陳王誅此愚夫，免得損威。陳勝老羞成怒，依了吏議，竟把幾個多說多話的農人，傳將進去，一體縛，砍下頭顱。酒肉太吃得多了，應該把頭顱賠償。大眾不防有此奇禍，驀聽得這個消息，頓嚇得魂飛天外，情願回去吃苦，不願在此殺頭，遂陸續告辭，踉蹌趨歸。勝有妻父妻兄，尚未知勝如此薄情，貿然進見。勝雖留居王宮，惟懲著前轍，當作家奴看待。妻父怒說道：「怙勢慢長，怎能長久！我不願居此受累！」即不別而行，妻兄亦去。為此種種情跡，他人都知陳勝刻薄，相率灰心，不肯效力。勝尚不以為意，命私人朱房為中正，胡武為司過主司，專察將吏小疵，濫加逮捕，妄用嚴刑。甚至將吏無辜，惟與朱胡有嫌，即被他囚系獄中，任情刑戮。於是將吏等越加離心，到了秦軍入境，個個冷眼相看，誰願為勝致死，拚命殺敵。勝悔恨無及，只因大敵當前，沒奈何自去督戰。行至汝陰，已有敗兵逃回，報稱張賀陣亡，全軍覆沒。賀死用虛寫，筆法一變。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-005', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-006', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 6, 'narrative', 'carried', '[]'::jsonb, '陳勝一想，去亦無益，徒自送死，不若逃回城中，再作後圖，遂命御人速即回車。御夫叫作莊賈，依言返奔，途中略一遲緩，便被勝厲聲呼叱，罵不絕口。莊賈當然銜恨，驅車至下城父，索性停車不進，自與從吏附耳密談。勝焦急異常，連叫數聲，賈竟反唇相譏，惡狠狠的仇視陳勝。結果是掣劍在手，沒頭沒腦，劈將過去，可憐六個月的張楚王，竟被一介車夫，砍成兩段！賈不顧勝屍，馳入陳縣，草起降書，遣人往投秦營。去使尚未回報，將軍呂臣已從新陽殺入，為勝復仇，誅死莊賈。當即收勝屍首，禮葬碭山。後來漢沛公平定海內，追念勝為革命首功，特命地方官修治勝墓，且置守冢三十家，俾得世祀。若大傭夫，得此食報，也算是不虛此一生了。原還值得。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-006', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-007', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 7, 'narrative', 'carried', '[]'::jsonb, '先是陳令宋留，奉勝軍令，率兵往略南陽，西指武關，至勝已被殺，秦軍復將南陽奪去，截住宋留歸路。留進退失據，奔還新蔡，又遭秦軍邀擊，苦不能支，只好乞降。章邯以宋留本為陳令，不能死難，反為陳勝攻秦，罪無可恕，因將留捆縛起來，囚解進京。二世向來苛酷，命處極刑，車裂以徇。各郡縣官吏，得此風聲，引為大戒，既已叛秦自主，不得不堅持到底，誓死拒秦。秦嘉等聞陳勝已死，求得楚族景駒，奉為楚王，自引兵略方與城，攻下定陶，且遣公孫慶往齊，欲與齊王田儋，合兵御秦。田儋尚未知陳勝死狀，遂向慶詰責道：「我聞陳王戰敗，生死未卜，怎得另立楚王，且何不向我請命，竟敢擅立呢！」慶不肯少屈，也大聲對答道：「齊未嘗向楚請命，自立為王，楚何必向齊請命，方得立王呢！況楚首先起兵，西攻暴秦，諸侯應該服從楚令，奈何反欲楚聽齊命呢？」田儋聽他言語不遜，勃然怒起，竟命將慶推出斬首，不肯發兵助楚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-007', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-007', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-008', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 8, 'narrative', 'carried', '[]'::jsonb, '那呂臣既據陳縣，也假楚字為名，號令人民。秦將章邯，連下各地，軍威大震，又收得趙將李良，自往邯鄲，徙趙民至河內，毀去城郭，隨處部署，無暇親攻二楚。回應前回李良降秦事。但遣左右校秦官名。引兵擊陳。呂臣出戰敗績，引兵東走，途次遇見一彪人馬，為首一員猛將，面有刺文，生得威風凜凜，相貌堂堂，麾下兵士，統用青布包頭，不似秦軍模樣。料知他是江湖梟桀，乘亂起事，與秦抗衡，當下停住下馬，拱手問訊。來將卻也知禮，在馬上欠身相答，彼此各通姓名，才知來將叫做黥布。如聞其聲。呂臣從未聞有黥姓，不禁相訝，及黥布詳敘本末，方得真相。當由呂臣邀布為助，反攻秦軍。布慨然樂允，因與呂臣一同北行。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-008', 'handan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-008', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-009', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 9, 'narrative', 'carried', '[]'::jsonb, '看官欲知黥布履歷，待小子演述出來。布系六縣人氏，本來姓英，少時遇一相士，諦視布面，許為豪雄，且與語道：「當先受黥刑，然後得王。」布半疑半信，唯恐他日受黥，特改稱黥布，謀為厭解。偏偏厭解無效，過了數載，年已及壯，竟至犯法論罪，被秦吏捉入獄中，讞定黥刑，就布面上刺成數字，且充發驪山作工。布欣然笑道：「相士謂我當刑而王，莫非我就要做王了！」旁人聽了，都相嘲諷，布毫不動怒，竟啟行到了驪山。驪山役徒，不下數十萬名，有幾個驍悍頭目，材技過人，布盡與交好，結為至友。當即密謀逃亡，乘隙偕行，輾轉遁入江湖，做了一班亡命奴。及陳勝發難，也想起應，只因朋輩寥寥，不過三五十人，如何舉事！聞得番陽番音婆，即今之鄱陽縣。令吳芮，性情豪爽，喜交賓客，隨即隻身往謁，勸他起兵。吳芮見他舉止不凡，論斷有識，不覺改容相待，留居門下。嗣復面試技藝，又是拳棒精通，弓馬純熟，引得吳芮格外器重，願招布為快婿，諏吉成禮。一個是壯年俊傑，出色當行，一個是仕女班頭，及時許嫁，兩人做了並頭蓮，真個是郎才女貌，無限歡娛。豔語奪目。惟布具有大志，怎肯在溫柔鄉中，消磨歲月，當下招引舊侶，並集番陽，即向吳芮借兵，出略江北，可巧碰著了楚將呂臣，互談心曲，布毫不躊躇，願助呂臣一臂之力，奪還陳縣。呂臣喜出望外，便合兵還陳，再與秦軍交戰，秦軍無戰不勝，無攻不克，偏遇了這位黥將軍，執槊飛舞，無論如何勇力，不敢進前，並且黥布麾下的弁目，亦無一弱手，東衝西突，殺人如麻，呂臣也麾眾繼進，立將秦陣踹破，掃將過去，趕得一個不留。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-009', 'chen', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-010', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 10, 'narrative', 'carried', '[]'::jsonb, '秦左右校統已竄去，由呂臣收還陳城，邀入黥布，置酒高會。歡宴了好幾天，布不屑安居，便與呂臣作別，率徒眾東去。適項梁叔姪，渡江西指，聲威傳聞遠近，布亦樂得相從，遂逕詣項氏營中，願為屬將。項梁方招攬英雄，那有不收納的道理，惟項氏西向的原因，卻也有一人引他出來。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-010', 'chen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-011', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 11, 'narrative', 'carried', '[]'::jsonb, '當時有一廣平人召平，曾為陳勝屬將，往攻廣陵，旬月未下。會接陳勝死耗，自知孤軍難恃，恐為秦軍所乘，乃渡江東下，偽稱陳王尚在，矯命拜項梁為上柱國，且傳語道：「江東已定，請即西向擊秦！」梁信為真言，就帶了八千子弟，逾江西行。沿途有許多難民，扶老攜幼，向前急趨。梁未識何因，遂命左右追捉數人，問明意見。難民答道：「現聞東陽縣令，為眾所戕，另立令史陳嬰。陳公素來長厚，體恤民艱，小民等所以前往，求他保護，免得受殃。」梁不禁驚歎道：「東陽有這般賢令史麼？我當先與通問，邀他同往攻秦，方為正當辦法。」說罷，遂將難民縱去，自命屬吏繕就一書，招致陳嬰，派人持去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-012', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 12, 'narrative', 'carried', '[]'::jsonb, '嬰平日循謹，為邑人所推重，自經東陽亂起，避居家中，不欲與聞。偏東陽少年，聚積至數千人，殺死縣令，公議立嬰，統至嬰門固請，定要他出來統眾。嬰固辭不獲，只得出詣縣署，妥為約束。並將縣令遺屍埋葬。遠近聞嬰賢名，爭先趨附，越數日即得二萬人。眾又欲推嬰為王，嬰不敢遽允，立白老母，母搖首道：「自從我為汝家婦，從不聞汝家先代出一貴人，可見汝家向來寒微，沒有聞望。今汝投效縣中，又不過一尋常小吏，徒靠著平生忠厚，與人無忤，方得大眾信從。但忠厚二字，只能勉強自守，不能突然興國，若驟得大名，非但不能享受，轉恐惹出禍殃，況且天下方亂，未知瞻烏所止，汝斷不可行險僥倖，自取後悔！我為汝計，不如擇主往事，有所依附，事成可得封賞，事敗容易逃亡，省得被人指名，這還是處亂知幾的方法呢！」如此審慎，才不愧為母教。嬰唯唯而出，決意不受王號，但自稱東陽縣長。適項梁遣使到來，遞入梁書，由嬰展閱一周，便召集屬吏部兵，開言曉諭道：「今項氏致書相招，欲我與他連和，合兵西向，我想項氏世為楚將，素有威名，項梁叔姪，又是英武絕倫，不愧將種，我等欲舉大事，非與他叔姪連合，終恐無成。看來不如依書承認，徙倚名族，然後西向攻秦，不患不能成事了！」眾人聽得嬰言，頗有至理，且聞項氏叔姪，英名蓋世，勢難與敵，還是先機趨附，保全城池為是。乃齊聲稱善，各無異言。嬰就寫好復書，先遣來使返報。旋即持了軍籍，赴項梁營，願率部眾相依，悉聽指揮。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-013', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 13, 'narrative', 'carried', '[]'::jsonb, '項梁大喜，受嬰軍籍，仍令嬰自統部眾。不過出兵打仗，總要稟承項氏，方好遵行。這乃是主權所關，不足深怪。項梁遂與嬰合兵渡淮，並得黥布相從，已約有四五萬人。嗣復來了一位蒲將軍，也有一二萬部眾，投附項梁。史記不載蒲將軍姓名，故本書亦從闕略。於是項梁屬下的兵士，差不多有六七萬名，一古腦兒會齊下邳，探聽前途消息，再定行止。忽有探卒走報，乃是秦嘉駐兵彭城，不容大軍過去。項梁聽說，遂召諭將士道：「陳王首先起事，攻秦失利，未即死亡，秦嘉乃遽背陳王，擅立景駒，這便叫做大逆不道，諸君當為我努力，往誅此賊！」道言未絕，各將士已齊聲應令，便排好隊伍，執定兵械，一聲炮響，好似潮水奔赴，爭向彭城殺去。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-014-013', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-014', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 14, 'narrative', 'carried', '[]'::jsonb, '八千子弟渡江來，一鼓便將偽楚摧﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-015', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 15, 'aside', 'carried', '[]'::jsonb, '若使到頭無誤事，聲威原足挾風雷。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-016', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 16, 'aside', 'carried', '[]'::jsonb, '欲卻勝負如何，待至下回詳敘。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-014-017', '前漢演義', 14, 208, '第14回·秦二世二年了', '', 17, 'commentary', 'carried', '[]'::jsonb, '歷朝革命，首事者往往無成，而勝廣之名為益著，即其敗亡也亦甚速。廣不足道耳。陳勝以隴上耕傭，一呼而起，集眾數萬，據陳稱王，何興之暴也？厥後各軍連敗，秦兵相逼，勝不能一戰，竟死於御者之手，又何其憊也！史稱其濫殺故人，苛待屬吏，遂至眾叛親離，以底於亡，此固不可謂非陳勝之定評，然自來真主出現，必有首事者為之先驅，首事者死，而真主乃得收功，項氏且不能據有海內，遑論一陳勝乎？若陳嬰母其知此道矣，誡嬰稱王，囑使依人，寧辭大名，免遭大禍。莫謂巾幗中必無智者，嬰母固前事之師也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-001', '前漢演義', 15, 208, '第15回·秦二世二年了', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說項梁帶領部眾，殺奔彭城，仗著一股銳氣，衝入秦嘉營壘，殺的殺，砍的砍，利害得很。嘉自起兵以來，從未經過大敵，驟然遇了項家兵隊，勇悍異常，叫他如何抵擋？沒奈何棄營逃去。項梁驅兵追趕，直至胡陵，逼得秦嘉無路可奔，只好收集敗兵，還身再戰。奮鬥多時，究竟強弱不敵，終落得兵敗身亡。殘眾進退兩難，統皆棄械投降。秦嘉所立的楚王景駒，孤立無依，出奔梁地，後來也一死了事。項梁進據胡陵，復引兵西進，適值秦將章邯，南下至栗，為梁所聞，乃使別將朱雞石餘樊君等，往擊秦軍。餘樊君戰死，朱雞石逃還。梁憤殺雞石，驅兵東出，攻入薛城。忽由沛公劉邦，到來乞師，梁與沛公本不相識，兩下晤談，見沛公英姿豪爽，卻也格外敬禮，慨然借兵五千人，將吏十人，使隨沛公同行。沛公謝過項梁，引兵自去。回應第十二回。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-001', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-001', 'xue', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-002', '前漢演義', 15, 208, '第15回·秦二世二年了', '', 2, 'narrative', 'carried', '[]'::jsonb, '惟沛公何故乞師，應該就此補敘。沛公前居母喪，按兵不動，偏秦泗川監官名來攻豐鄉，乃調兵與戰，得破秦兵。泗川監遁還，沛公命裡人雍齒居守，自引兵往攻泗川，泗川監平，及泗川守北，出戰敗績，逃往薛地，又被沛公軍追擊，轉走戚縣。沛公左司馬曹無傷，從後趕去，殺死泗川守，只泗川監落荒竄去，不知下落。沛公既得報怨，乃還軍亢父，不意魏相周市，遣人至豐，招誘雍齒，啖以侯封。雍齒素與沛公不恊，竟背了沛公，舉豐降魏。沛公聞報，急引兵還攻雍齒，偏雍齒築壘固守，屢攻不下。豐鄉為沛公故里，父老子弟，本已相率畏服，不生貳心，乃被雍齒脅迫，反抗沛公，沛公如何不憤！自思頓兵非計，不如另借大兵，再來決鬥，乃撤兵北向，擬至秦嘉處乞師。道出下邳，巧與張良相遇。張良伏處有年，聞得四方兵起，也欲乘勢出頭，特糾集同志百餘人，擬往從楚王景駒。會見沛公過境，因乘便求見，沛公與語一切兵機，良應對如流，大得沛公賞識，授為廄將。最奇怪的是張良所言，無人稱賞，獨沛公一一體會，語語投機。良因歎息道：「沛公智識，定由天授，否則我所進說，統是太公兵法，別人不曉，為何沛公獨能神悟呢？」良得太公兵法，見前文第四回。嗣是良遂隨著沛公，不復他去。會秦嘉為項梁所殺，景駒走死，沛公乃竟造項梁營門，乞師攻豐。既得項軍相助，便亟返豐鄉，再攻雍齒。雍齒保守不住，出投魏國去了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-002', 'feng', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-003', '前漢演義', 15, 208, '第15回·秦二世二年了', '', 3, 'narrative', 'carried', '[]'::jsonb, '沛公逐去雍齒，馳入豐鄉，傳集父老子弟，訓責一番。大眾統皆謝過，乃不復與較，但改豐鄉為縣邑，築城設堡，留兵扼守，再向薛城告捷，送還項軍。旋接項梁來書，特邀沛公至薛商議另立楚王。沛公方感他厚惠，當然應召，帶同張良等趨至薛城。適值項羽戰勝班師，因得與羽相見，詢明戰狀，乃是羽拔襄城，盡坑敵兵，方才告歸。羽一出師，便盡坑襄城敵兵，其暴可知。惺惺惜惺惺，兩人一見如故，聯成為萍水交。劉項相交自此始。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-003', 'feng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-003', 'xue', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-004', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 4, 'narrative', 'event_keyword', '[]'::jsonb, '過了一宵，項氏屬將，一齊趨集。當由項梁升帳議事，顧語大眾道：「我聞陳王確已身死，楚國不可無主，究應推立何人？」大眾聽了，一時也不便發言，只好仍請項梁定奪。有幾個乘機獻媚的將吏，竟要項梁自為楚王，梁方欲承認下去，忽帳外有人入報，說是居鄛人范增，前來求見。鄛一作巢，即今巢縣。梁即傳令入帳。少頃見一個老頭兒，傴僂進來，趨至座前，對梁行禮。死多活少，何苦再來干進！梁亦拱手作答，延坐一旁，並溫顏與語道：「老先生遠來，必有見教，願乞明示！」范增答道：「增年已老朽，不足談天下事，但聞將軍禮賢下士，捨己從人，所以特來見駕，敬獻芻言。」項梁道：「陳王已逝，新王未立，現正籌議此事，尚無定論，老成人想有高見，幸即直談！」增又道：「僕正為此事前來，試想陳勝本非望族，又乏大才，驟欲據地稱王，談何容易！此次敗亡，原不足惜。自從暴秦併吞六國，楚最無罪，懷王入秦不反，楚人哀思至今。僕聞楚隱士南公，深通術數，嘗謂楚雖三戶，亡秦必楚，照此看來，三戶尚足亡秦，今陳勝首先起事，不知求立楚後，妄自稱尊，怎得不敗！怎得不亡！將軍起自江東，渡江前來，故楚豪傑，爭相趨附，無非因將軍世為楚將，必立楚後，所以竭誠求效，同復楚國。將軍誠能俯順輿情，扶植楚裔，天下都聞風慕義，投集尊前，關中便一舉可下了。」增言亦似是而非。項梁喜道：「我意也是如此，今得老先生高論，更無疑義，便當照行。」增聞言稱謝，梁又留與共事，增亦不辭。此時增年已七十，他本家居不仕，好為人設法排難，謀無不中。既居項梁幕下，當然做了一個參謀。梁遂派人四出，訪求楚裔，可巧民間有一牧童，替人看羊，查問起來，確是楚懷王孫，單名是個心字，當即報知項梁。梁即派遣大吏數人，奉持輿服，刻日往迎。說也奇怪，那牧童得了奇遇，倒也毫不驚慌，就將破布衣服脫下，另換法服，居然象個華貴少年，辭別主人，出登顯輿，一路行抵薛城。項梁已率領大眾，在郊迎接，一介牧童，不知從何處學得禮節，居然不亢不卑，與梁相見。梁遂導入城中，擁他高坐，就號為楚懷王，自率僚屬謁賀。牧童為王，雖後來不得令終，總有三分奇異。行禮既畢，復與大眾會議，指定盱眙為國都，命陳嬰為上柱國，奉著懷王，同往盱眙。梁自稱武信君，又因黥布轉戰無前，功居人上，封他為當陽君。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-005', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 5, 'narrative', 'carried', '[]'::jsonb, '布乃復英原姓，仍稱英布。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-006', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 6, 'narrative', 'carried', '[]'::jsonb, '張良趁此機會，謀復韓國，遂入白項梁道：「公已立楚後，足副民望，現在齊趙燕魏，俱已復國，獨韓尚無主，將來必有人擁立，公何不求立韓後，使他感德﹔名雖為韓，實仍屬楚，免得被人占了先著，與我為敵呢。」語有分寸。項梁道：「韓國尚有嫡派否？」良答道：「韓公子成，曾受封橫陽君，現尚無恙，且有賢聲，可立為韓王，為楚聲援，不致他變。」梁依了良議，遂使良往尋韓公子成。良一尋便著，返報項梁。梁因命良為韓司徒，使他往奉韓成，西略韓地。良拜辭項梁，又與沛公作別，逕至韓地，立韓成為韓王，自為輔助，有兵千人，取得數城。從此山東六國，並皆規復，暴秦號令，已不能遠及了。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-007', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 7, 'narrative', 'carried', '[]'::jsonb, '獨秦將章邯，自恃勇力，轉戰南北，飄忽無常，竟引兵攻入魏境。魏相周市，急向齊楚求救，齊王田儋，親自督兵援魏，就是楚將項梁，亦命項它領兵赴援。田儋先至魏國，與周市同出御秦，到了臨濟，正與秦軍相遇，彼此交戰一場，殺傷相當，不分勝負。儋與市擇地安營，為休息計，總道夜間可以安寢，不致再戰。那知章邯狡黠得很，竟令軍士銜枚夜走，潛來劫營。時交三鼓，齊魏各軍，都在營中高臥，沈沈睡著，驀地裡一聲怪響，方才從夢中驚醒，開眼一瞧，那營內已被秦軍搗入。急忙爬起，已是人不及甲，馬不及鞍，如何還能對敵？秦軍四面圍殺，好似砍瓜切菜一般，齊魏兵無路可奔，多被殺死。田儋周市，也死於亂軍中，同至枉死城頭，掛號去了。章邯踏平齊魏各營，遂驅兵直壓魏城。魏王咎自知不支，因恐人民受屠，特遣使至章邯營，請邯毋戮人民，便即出降。邯允如所請，與定約章，遣使回報。魏王咎看過約文，心事已了，當即縱火自焚，跟著祝融氏祝融，火神名。同去，卻是一個賢王，可惜遭此結果。弟魏豹縋城出走，巧遇楚將項它，與述國破君亡等事，項它知不可救，偕豹還報項梁。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-008', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 8, 'narrative', 'carried', '[]'::jsonb, '梁方出攻亢父，聞得魏都破滅，項它還軍，正擬自往敵秦，賭個輸贏。適值齊將田榮，差來急足，涕泣求援。經梁問明底細，才知田儋死後，齊人立故齊王建弟田假為王，田角為相，田間為將。獨田儋弟榮不服田假，收儋餘兵，自守東阿，秦兵乘勢攻齊，把東阿城圍住。城中危急萬分，因特遣使求救，項梁奮然道：「我不救齊，何人救齊！」遂撇了亢父，立偕齊使同赴東阿。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-008', 'donge', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-009', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 9, 'narrative', 'carried', '[]'::jsonb, '秦將章邯，方督兵攻東阿城，限期攻入，忽聞楚軍前來救齊，乃分兵圍攻，自率精銳去敵項梁。一經交鋒，覺得項梁兵力，與各國大不相同，當下抖擻精神，率兵苦鬥，偏項軍都不怕死，專從中堅殺來，無人敢當，章邯持刀獨出，攔截楚軍，兜頭碰著一個楚將，橫槊相迎，刀槊並交，不到數合，殺得章邯渾身是汗，只好拋刀敗退。看官道楚將為誰？就是力能扛鼎的項羽。邯生平未遇敵手，乃與項羽爭鋒，簡直是強弱懸殊，不足一戰。自思楚軍中有此健將，怎能抵敵？不如趕緊收軍，走為上計，於是揮眾急走，奔回東阿，索性將攻城人馬，一律撤去，向西馳還。田榮引兵出城，會合楚軍，追擊秦兵至十里外，望見章邯去遠，榮托詞告歸。獨項梁尚不肯捨，再追章邯，逐節進兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-009', 'donge', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-010', '前漢演義', 15, 208, '第15回·繫於「立楚懷王孫心」', '', 10, 'narrative', 'carried', '[]'::jsonb, '既而田假逃至，報稱為榮所逐，乞師討榮，項梁未許，但促田榮會師攻秦。榮方驅逐田假，及田角田間，另立兄儋子市為齊王，自為齊相，弟橫為將，出徇齊地，無暇發兵攻秦。及楚使到來，榮與語道：「田假非前王子弟，不應擅立，今聞他逃入楚營，楚應為我討罪。田角田間，與假同惡，現皆奔往趙國﹔若楚殺田假，趙殺田角田間，我自當引兵來會，煩汝回報便了。」田假系齊王建弟，豈必不可為王？榮為是言，無非強詞奪理。楚使還見項梁，具述榮言，項梁道：「田假已經稱王，今窮來投我，怎忍殺他？田榮不肯來會，由他去罷。」一面說，一面使沛公項羽，往攻城陽。羽親冒矢石，首先登城，入城以後，又將兵民盡行屠戮。沛公亦無法勸阻，俊羽屠城畢事，同歸告捷。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-011', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 11, 'narrative', 'event_keyword', '[]'::jsonb, '項梁復率眾西追章邯，再破秦軍，邯敗入濮陽，乘城固守。梁攻城不克，移攻定陶。定陶城內亦有重兵守著，兀自支撐得住。梁自駐定陶城下，指揮軍事，另命沛公項羽，往西略地。兩人行至雍邱，卻遇秦三川守李由引兵迎敵，項羽一馬當先，突入秦陣，李由不知好歹，仗劍來迎，被項羽手起一槊，挑落馬下，眼見是一命告終了。秦兵失了主將，自然大亂，逃去一半，死了一半。惟李由為秦丞相李斯長子，戰死沙場，總算是為秦盡忠，那知秦廷還說他謀反，竟把乃父李斯，拘入獄中！李由死無對證，李斯冤枉坐罪，這真叫做不明不白，生死含冤呢。也是李斯造孽太深，故有此報。說將起來都是趙高一人的狡計。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-011', 'puyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-015-011', 'dingtao', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-012', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 12, 'narrative', 'carried', '[]'::jsonb, '秦二世寵任趙高，不親政務，及四方亂起，警報頻聞，卻不向趙高歸罪，但去責成丞相李斯。李斯是個貪戀祿位的佞臣，只恐二世加譴，反要迎合上意，請二世講求刑名，嚴行督責，且雲督責加嚴，臣民自然畏懼，不敢生變。這數語正合二世心理，遂大申刑威，不論有罪無罪，孰貴孰賤，每日總要刑戮數人，總算實做那督責的事情。官民慄慄危懼，各有戒心，趙高平日，恃恩專恣，往往報復私仇，擅殺無辜，此次恐李斯等從旁訐發，禍及己身，乃先行設法，入白二世道：「陛下貴為天子，亦知天子稱貴的原因麼？」二世茫然不解，轉問趙高，高答說道：「天子所以稱貴，無非是高拱九重，但令臣下聞聲，不令臣下見面。從前先皇帝在位日久，臣下無不敬畏，故得日見臣下，臣下自不敢為非，妄進邪說。今陛下嗣位，才及二年，春秋方富，奈何常與群臣計事？倘或言語有誤，處置失宜，反使臣下看輕，互相誹議，這豈不是有玷神聖麼？臣聞天子稱朕，朕字意義，解作朕兆，朕兆便是有聲無形，使人可望不可近，願陛下從今日始，不必再出視朝，但教深居宮禁，使臣與二三侍中，或及平日學習法令諸吏員，日侍左右，待有奏報，便好從容裁決，不致誤事。大臣見陛下處事有方，自不敢妄生議論，來試陛下，陛下才不愧為聖主了。」好似哄騙小兒。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-013', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 13, 'narrative', 'carried', '[]'::jsonb, '二世聞言甚喜，樂得在宮安逸，恣意淫荒。從前尚有視朝的日子，至此杜門不出，唯與宦官宮妾，一淘兒尋歡取樂，所有誥命出納，統委趙高辦理。趙高便往訪李斯，故意談及關東亂事，李斯皺眉長歎，唏噓不已。高便進說道：「關東群盜如毛，警信日至，主上尚恣為淫樂，徵調役夫，修築阿房宮，採辦狗馬無用等物，充斥宮廷，不知自省。君侯位居丞相，不比高等服役宮中，人微言輕，奈何坐視不言，忍使國家危亂哩！」哄騙李斯又另用一番口脗。李斯道：「非我不願進諫，實因主上深居宮中，連日不出視朝，叫我如何面奏？」趙高道：「這有何難，待我探得主上閒暇，即來報知君侯，君侯便好進諫了。」李斯聽著，還道趙高是個忠臣，懷著好意，當即欣然允諾。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-014', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 14, 'narrative', 'carried', '[]'::jsonb, '過了一二日，果由趙高遣一閹人，通知李斯促令進諫。李斯忙穿了朝服，匆匆至宮門外，求見二世。二世正在宮中宴飲，左抱右擁，快樂無比的時候，忽見內官趨入，報稱丞相李斯求見，不由的艴然道：「有何要事，敗我酒興？快叫他回去罷！明日也好進來。」內官出去，依言拒斯，斯只好回去。明日再往求見，又被二世傳旨叱回，斯乃不敢再往。偏趙高又著人催促，說是主上此刻無事，正好進諫，不得再誤。斯尚以為真，急往求見，又受了一碗閉門羹。斯白跑三次，倒也罷了，那知二世動了懊惱，趙高乘勢進讒，說是沙邱矯詔，斯實與謀，他本望裂地封王，久不得志，因與長子由私下謀反。近日屢來求見，定有歹意，不可不防！二世聽了，尚在沈吟，趙高又加說道：「楚盜陳勝等人，統是丞相旁縣子弟，斯為上蔡人，與陳勝陽城相近，故雲旁縣。為甚麼得橫行三川，未聞李由出擊？這就是真憑實據了。請陛下速拘丞相，毋自貽患！」二世仍沈吟多時，究因案情重大，不好草率，特先使人按察三川，是否有通盜實跡，再行問罪。趙高不敢再逼，只好聽二世派人出去，暗中賄囑使臣，叫他誣陷李斯父子。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-015', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 15, 'narrative', 'carried', '[]'::jsonb, '偏李斯已知中計，且聞有查辦李由等情，因上書劾奏趙高，歷陳罪惡。二世略閱斯書，便顧語左右道：「趙君為人，清廉強乾，下知人情，上適朕意，朕不任趙君，將任誰人？丞相自己心虛，還來誣劾趙君，豈不可恨！」李斯越弄越糟。說著，即將原奏擲還。李斯見二世不從，又去邀同右丞相馮去疾，將軍馮劫，聯名上書，請罷修阿房宮，請減發四方傜役，並有隱斥趙高的語意。惹得二世越加動怒，憤然作色道：「朕貴為天子，理應肆意極欲，尚刑明法，使臣下不敢為非，然後可制御海內。試看先帝起自侯王，兼並天下，外攘四夷，所以安邊境，內築宮室，所以尊體統，功業煌煌，何人不服。今朕即位二年，群盜並起，丞相等不能禁遏，反欲舉先帝所為，盡行罷去，是上不能報先帝，次又不能為朕盡忠，這等玩法的大臣，還要何用呢？」趙高在旁，連忙湊趣，請即將三人一並罷官，下獄論罪。二世當即允准，遂由趙高派出衛士，拿下李斯馮去疾馮劫，囚系獄中。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-016', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 16, 'narrative', 'carried', '[]'::jsonb, '去疾與劫，倒還有些志趣，自稱身為將相，不應受辱，慨然自殺。獨李斯還想求生，不肯遽死，再經趙高奉旨訊鞫，硬責他父子謀反，定要李斯自供。斯怎肯誣服？極口呼冤，被趙高喝令役隸，搒掠李斯，直至一千餘下，打得李斯皮開肉爛，實在熬受不住，竟至昏暈過去。若得就此畢命，也免身受五刑。小子有詩歎道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-017', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 17, 'aside', 'carried', '[]'::jsonb, '嚴刑峻法任君施，禍報臨頭悔已遲，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-018', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 18, 'aside', 'carried', '[]'::jsonb, '家族將夷猶惜死，桁楊況味請先知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-019', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 19, 'aside', 'carried', '[]'::jsonb, '畢竟李斯性命如何，且看下回續敘。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-015-020', '前漢演義', 15, 208, '第15回·繫於「項梁敗死定陶」', '', 20, 'commentary', 'carried', '[]'::jsonb, '范增之請立楚後，與張耳陳餘之進說陳勝，其說相同。此第為策士之詐謀，無足深取。丈夫子邁跡自身，豈必因人成事？試觀酈食其請立六國後，而張良借箸以籌，促銷刻印，漢卒成統一之功，是可知范增之謀，不足圖功，反足貽禍。項氏之亡，實亡於弒義帝，謂非增貽之禍而誰貽之乎？或謂張良亦嘗請立韓公子成，夫良之請立韓後，不過為韓存祀而已，其與范增之借楚為名，亦安可同日語者。蘇子瞻資議范增，猶目之為人傑，毋乃尚重視范增歟！彼夫李斯之下獄，原屬冤誣，然試思殘刻如斯，寧能令終？坑儒生者李斯，殺扶蘇蒙恬者亦李斯，請行督責者亦李斯，斯殺人多矣，安保不為人殺乎？故殺斯者為趙高，實不啻斯自殺之耳，冤云乎哉！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-001', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說李斯受了刑訊，搒掠至千餘下，竟至昏暈不醒。趙高令左右取過冷水，噴上斯面，斯才甦醒轉來。再經高喝令供實，斯恐重遭搒掠，不得已當堂誣服，隨即牽還獄中。斯且忍痛作書，自敘前功，尚望二世從輕發落，特浼獄吏呈將進去，偏又為趙高所聞，呼吏入責道：「囚犯怎得上書？汝莫非受他賄托麼？」說得獄吏魂魄飛揚，慌忙自稱不敢，叩謝而出。斯書當然毀去，不得上聞。趙高復使心腹人偽為御史，及侍中謁者等官，私往按驗，至再至三，斯一呼冤，便即笞杖交下，不令翻供，嗣經二世派人復審，斯以為徒受笞杖，無從明冤，不如拚了一死，誣供了事。復審員還報二世，二世喜說道：「若非趙君，幾為李斯所賣！」於是斯遂讞成死罪。及三川查辦員還都，先向趙高處陳明，說是李由陣亡，死無對證，正好捏造反詞，構成大獄。趙高喜甚，遂令他捏詞奏報。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-002', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 2, 'narrative', 'carried', '[]'::jsonb, '二世益怒，竟令斯備受五刑，並誅三族。應有此報。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-003', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 3, 'narrative', 'carried', '[]'::jsonb, '可憐李斯家內，所有子弟族黨，一古腦兒拿到法庭，與李斯一同捆縛，推出市曹。斯顧次子嗚咽道：「我欲與汝再牽黃犬，出上蔡東門，趕捕狡兔，已不能再得了！」說著，大哭不止，次子亦哭，家屬無一不哭。俄而監刑官至，先命將李斯刺字，次割鼻，次截左右趾，又次梟首，又次斬為肉泥。五刑用畢，斯魂早入阿鼻地獄。餘外子弟族黨等，一並誅死，真落得陰風慘慘，冤魄沈沈。總計李斯一門，除長子由為三川守外，諸男多尚秦公主，諸女多嫁秦公子，顯貴無比。李斯也嘗歎物極必衰，終因貪戀祿位，倒行逆施，害得這般結果，可見貴富二字，最足誤人，願後世看作榜樣，切勿貪心不足呢！暮鼓晨鐘，無此異響。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-004', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 4, 'narrative', 'event_keyword', '[]'::jsonb, '且說趙高既害死李斯，遂得代斯後任，做了一個中丞相，凡軍國大事，都歸他一人包攬，二世似傀儡一般，毫無主權。高因禍亂日亟，特致書章邯，責成平盜。章邯困守濮陽，也想出奇制勝，建立戰功，每日派遣偵騎，探聽項梁軍情，以便乘隙定計。項梁駐兵定陶城下，適值霪雨兼旬，不便力攻。沛公項羽，自雍邱還攻外黃，亦為雨所阻，但把外黃城圍住，為持久計。項梁屢勝而驕，既不將兩軍召回，又復逐日寬懈，但在營中飲酒消遣，所有軍紀軍律，幾乎擱起一邊，不復過問，全營將士，亦樂得逍遙自在，快活幾天。這種情形，早被秦探窺知，往報章邯，邯尚恐兵力未足，不敢輕出，但向各處徵調兵馬。待至各軍趨集，方圖大舉，與項梁決一雌雄。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-004', 'puyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-004', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-005', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 5, 'narrative', 'carried', '[]'::jsonb, '項梁麾下，有一謀士宋義，察知秦兵日增，引以為懮，遂入帳諫項梁道：「公渡江到此，屢破秦軍，威名日盛，可喜無過今日，可懼亦無過今日，大約戰勝以後，將易驕，卒易惰，驕惰必敗，不如不勝。試看各營將士，已漸驕了，已稍惰了，秦兵雖敗，秦將章邯，究竟是經過百戰，不可輕視。近聞他屢次添兵，必將與我決一死鬥﹔若我軍不先戒備，一旦被他襲擊，如何抵敵！所以義日夜擔懮，為公增懼呢。」項梁道：「君亦太覺多心。章邯屢次敗退，那裡還敢再來！就使他逐日添兵，也不過守著濮陽罷了﹔況天公連日下雨，路上泥泞得很，怎能攻我，一俟天晴，我即當攻克此城，去殺那章邯，看他逃往何處！」說至此，掀髯大笑。驕態如繪。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-005', 'puyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-006', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 6, 'narrative', 'carried', '[]'::jsonb, '宋義尚欲有言，項梁先接入道：「我前擬征集齊師，同去攻秦，偏田榮有懷私怨，忘我大惠，我本想遣使詰責，只因一時無暇，延誤多日，今若慮章邯增兵，與我為難，不如再召田榮，率師來會。榮若仍然不至，我卻要移兵攻齊了。」宋義見梁語益支離，料難再諫，眉頭一皺，計上心來，即向項梁說道：「公如欲使齊，臣願一往。」梁欣然許諾，義即起身辭行，出營東去。越快越妙。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-007', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 7, 'narrative', 'carried', '[]'::jsonb, '走至半途，適遇齊使高陵君顯，免不得互相接談。義便問顯道：「君將往見武信君麼？」顯答聲稱是。義又與說道：「我受武信君差遣，出使貴國，一是為兩國修和，二是為一己避禍，願君亦不可速進，免受災殃。」顯不禁詫異，詳問原因，義答道：「武信君屢戰屢勝，已致驕盈，士卒亦多懈怠，恐難再戰。我聞秦將章邯，連日增兵，志在報復，武信君輕視秦軍，拒諫不納，將來必為所乘，不敗何待？君今前去，未免受累，看來還是徐徐就道，方可無虞。我料這旬日內，武信君就要失敗了！」顯似信非信，乃與義拱手揖別，各走各路。自思義為楚臣，有此關照，不為無因，今何妨遲遲吾行，較為妥當。遂囑咐輿夫，緩緩前進。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-008', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 8, 'narrative', 'event_keyword', '[]'::jsonb, '果然高陵君未到楚營，武信君已經敗亡。原來項梁遣去宋義，仍然寬弛得很，不但軍中未曾戒嚴，就是斥堠巡卒，也聽他散處，不加檢查。時當秋季，淒風苦雨，連宵不止，把定陶城下的幾座楚營，直壓得黑氣瀰漫，不見天日。便是不祥之兆。楚軍也無人占候，但知晝餐夜宿，蹉跎過去。一夕俱安睡營中，忽聞營外喊殺連天，好似千軍萬馬，奔殺進來。楚軍方才驚起，但見四面統是火光，照徹內外，一隊隊的敵軍，統向營門中突入，見人便砍，遇馬便刺，嚇得楚軍倒躲不及。勉強持了軍械，上前攔阻，那裡是敵軍對手，徒斷送了許多頭顱。最利害的是後面大將，金盔鐵甲，躍馬舞刀，鋒刃所及，血肉橫飛，越使楚人喪膽，只恨自己未生羽翼，不能飛上天空，逃脫性命。還有這位武信君項梁，倉皇出帳，單穿著一身常服，執著一把短劍，要想衝出大營，覓路逃生。冤家碰著狹路，正與敵軍中大將相值，被他攔住。兩下裡爭起鋒來，一個是長刀亂劈，光燄逼人，一個是短劍難支，心膽已落。才閱片時，即由敵帥一刀剁下，劈作兩段。敵帥為誰？就是秦將章邯。邯既招集兵馬，夤夜冒著風雨，來劫楚營，項梁毫不預備，自然中了邯計，一死不足，還要害及全軍，這便叫做驕兵必敗，應了宋義的前言呢。前回述章邯劫營，是順敘而下，此回卻用倒筆，愈見突兀。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-008', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-009', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 9, 'narrative', 'carried', '[]'::jsonb, '楚營中失了主帥，沒頭亂跑，當被秦兵掩殺一陣，多半斃命。只有幾個命不該死的兵士，溜出營外，逃往外黃，報知沛公項羽。項羽不聽猶可，聽了叔父陣亡，不由的悲從中來，放聲大哭。沛公亦為淚下，待羽停住哭聲，方與羽商議道：「武信君已死，軍心不免搖動，此處斷難再駐了。我等只好東歸，保衛懷王，抵禦秦軍。」羽也以為然，乃撤外黃圍，引兵東還。道出陳縣，復邀同呂臣軍，共至江左，擇地分駐。呂臣軍駐彭城東，項羽軍駐彭城西，沛公軍駐碭郡，彼此列成犄角，約為聲援。嗣恐懷王居住盱眙，為秦所攻，因請他移都彭城。懷王依議遷都，至彭城後，命將項羽呂臣兩軍，並作一處，自為統帥。牧童能作統帥，卻是不凡。惟沛公軍仍使留碭，授為碭郡長，封武安侯。號項羽為魯公，封長安侯，進呂臣為司徒，且使呂臣父青為令尹。部署已定，專待章邯到來，與他廝殺。偏章邯不來攻楚，反去攻趙，他道是項梁已死，楚無能為，所以北去。懷王聞秦軍北行，料知魏地空虛，即使魏豹往略魏地。魏豹奔楚見前回。給兵千人，即日出發。豹卻也順手，竟得平定二十餘城，派人報捷。懷王乃命豹為魏王，使作屏藩，這且慢表。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-009', 'chen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-009', 'pengcheng', 4);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-010', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 10, 'narrative', 'carried', '[]'::jsonb, '且說齊使高陵君顯，在途中緩行數日，果得項梁死耗，才服宋義先見，幸得避災。只因使命尚未交卸，不便回齊，且在途中探聽楚人消息，再定行止。嗣聞楚懷王遷都彭城，劉項等同心夾輔，兵威復震，乃改道轉趨彭城，入見懷王，傳達使命。懷王依禮接見，賜座與談。顯問及宋義使齊，有無回來，懷王答稱尚未。顯又述及途次相遇，幸得宋義指示，不至及禍等情，懷王愕然道：「義何以知項君必敗？」顯答道：「據宋使言，武信君志驕氣滿，已露敗象，後來不到數日，竟如所料。試想兵未交戰，先見敗征，豈不是特別知兵麼？」懷王點頭稱是。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-010', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-011', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 11, 'narrative', 'event_keyword', '[]'::jsonb, '事有湊巧，正值宋義回來，即由懷王立刻召見，問明使齊情形，義據實復陳，無非說是齊願修和，只因國內未定，所以暫緩出師。懷王復與語項梁敗狀，義答道：「臣早知有此禍變，武信君不肯聽臣，因致敗亡。」懷王乃更商及拒秦政策，義仍主張西進，謂必須擇一良將，剿撫兼施，進止有法，方可成功。懷王大喜，遂留宋義居侍左右，隨時與議。一面遣回齊使，令他復命。俟齊使去後，乃遍召諸將，會議攻秦。懷王首先開口道：「秦始皇暴虐人民，海內交怨，今二世尤為無道，自速危亡，前武信君西向進攻，所過皆克，不幸中道失計，忽遭敗挫，現擬再接再厲，誓滅暴秦，還問何人敢當此任？」說至此，即顧視兩旁，見諸將瞠目結舌，無一應命。懷王復朗聲道：「諸君聽著，今日無論何人，但能麾兵西向，首先入關，便當立為秦王。」言未已，即有一人應聲道：「末將願往！」是懷王激勵出來。往字方才說畢，又有一人厲聲道：「我亦願往！須當讓我先去。」兩人口脗，便有區別。懷王瞧著，第一個應聲的乃是沛公，第二個厲聲的就是項羽，兩人統要西行，反弄得懷王左右為難，俯首沈吟。項羽又進說道：「叔父梁戰死定陶，仇尚未報，末將誼關子姪，誓不甘休！今願請兵數千，搗入秦關，復仇雪恥，就使劉季願往，末將亦決與同行，前驅殺賊。」懷王聽著，方徐聲道：「兩將能同心滅秦，尚有何言？現且部署兵馬，擇日啟行。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-011', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-012', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 12, 'narrative', 'carried', '[]'::jsonb, '沛公項羽，奉令趨出。尚有老將數人，未曾告退，續向懷王進言道：「項羽為人，慓悍殘忍，前次往攻襄城，月餘才得破入，他因日久懷恨，縱兵屠戮，直把襄城百姓，殺得一個不留。嗣復轉攻城陽，又將全城人民，任情殘殺。此外所過地方，無不酷待，如此兇暴，怎好令他統軍？況楚兵起義以來，陳王項梁，統皆無成，這都為了以暴易暴，不足服人，所以終歸敗死。今既定議攻秦，不應單靠武力，須得一忠厚長者，仗義西行，沿途約束軍士，慰諭父老，非至萬不得已，不可加誅，彼秦地百姓，苦秦已久，若得義師前去，除暴救民，自然簞食相迎，無思不服。故為大王計，項羽決不可遣，寧可獨遣沛公！沛公寬大有名，必不至如項羽的殘暴呢。」懷王道：「我知道了！」諸老將方興辭而出。懷王返入內室，免不得大費躊躇，自思羽若不遣，是自背前言﹔若遣令同往，必至所過殘掠，大拂民意。想了多時，究竟是不遣為佳。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-013', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 13, 'narrative', 'carried', '[]'::jsonb, '次日升堂議事，沛公項羽，都來稟請出兵的日期。懷王顧語項羽，叫他暫留彭城，不必與沛公同行。項羽不禁暴躁起來，正要與懷王辯論，可巧外面有人入報，說是趙國使臣，前來求見。懷王正恐項羽多言，樂得打斷了他，急命左右召入趙使。趙使踉蹌進來，行過了禮，便將國書呈上。懷王雖做過牧童，究竟幼時讀書識字，未嘗忘卻，況且天資聰敏，一習便熟，所以看到來書，就知趙使來楚乞援。原來秦將章邯，移兵攻趙，趙王歇使將軍陳餘，出兵抵敵，吃了一個大敗仗，退至巨鹿。趙相張耳，亟奉趙王歇入巨鹿城，令陳餘屯營城北，保護城池。章邯在城南下寨，就棘原築起甬道，兩面迭牆，俾通糧路，自督兵士攻城，晝夜不輟。城中當然危急，不得不遣使四出，分道求援。懷王將來書閱畢，傳示諸將，惹得項羽雄心勃勃，又想去攻殺章邯，替叔報仇。當下請命欲行，懷王說道：「此行正要煩君，但須有人同去，方慰我心！」無非防他殘虐。遂即命宋義為上將，加號卿子冠軍，卿子系時人褒美之辭，即與公子相類。冠讀去聲，有統軍之意。作為統帥，項羽為次將，范增為末將，率兵數萬，前往救趙。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-013', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-013', 'julu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-014a', '前漢演義', 16, 208, '第16回·繫於「項梁敗死定陶」', '', 14, 'narrative', 'carried', '[]'::jsonb, '趙使先歸，宋義等隨後出發，行至安陽，頓兵不進。懷王深信宋義，不欲遙制，由他自定行止，惟另遣沛公西行。沛公別過懷王，出都就道，遇著陳勝項梁散卒，一並收集，約得萬人。復至碭郡招領舊部，共同西進，過了成陽槓裡二縣，連破秦軍二戍，擊走秦將王離，因向昌邑進發。時已為');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-014a', 'dang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-014b', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 14, 'narrative', 'marker', '[]'::jsonb, '秦二世三年了。是年為秦亡之歲，不能從略。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-015', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 15, 'narrative', 'carried', '[]'::jsonb, '秦將王離，敗走河北，投章邯軍，邯令他助攻巨鹿，巨鹿守兵，越加恟懼，日望楚軍入援。偏宋義逗留安陽，不肯進兵，甚至趙使一再敦促，仍然不行。接連住了四十六日，部將等俱莫名其妙，項羽更忍耐不住，入帳語義道：「秦兵圍趙甚急，我軍既已來援，應該速渡黃河，與秦交戰，我為外合，趙為內應，秦兵便可破滅，為甚麼久駐此間，坐失時機呢？」宋義搖首道：「公言錯了！古諺有言，當搏牛虻，不當破蟣蝨，虻大蝨小，我等應從大處下手，方得大功。今秦兵攻趙，就使戰勝，兵亦必疲，我可乘敝進攻，無慮不破。若秦兵不能勝趙，我便鼓行西進，直入秦關，還要去顧甚麼章邯？我所以按兵不進，專待秦趙兩軍，決一勝負，方定進止，公亦何必性急，且住為佳。總之披堅執銳，我不如公﹔運籌決策，公尚不如我哩。」言已，鼓掌大笑。義能知梁，不能知羽，想是命已該絕了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-016-015', 'julu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-016', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 16, 'narrative', 'carried', '[]'::jsonb, '羽忿忿而出。少頃有軍令傳出道：「猛如虎，狠如羊，貪如狼，強不可使，俱應處斬！」這數語明明是指著項羽，氣得項羽三屍暴炸，七竅生煙，恨不得手刃宋義，立即渡河。那宋義全然不睬，且遣子襄往做齊相，親送至無鹽地方，飲酒高會，自鳴得意。會值天氣嚴寒，雨雪紛飛，士卒且凍且饑，不得一餐，獨宋義堂皇高坐，與諸將豪飲大嚼，談笑生風。看官試想！如此行為，能令眾人心服麼？將卒須共嘗甘苦，義號為知兵，奈何不曉。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-017', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 17, 'narrative', 'carried', '[]'::jsonb, '項羽雖然列席，胸中卻說不出的煩躁，但借酒澆愁，喝乾了數大觥。待至酒闌席散，宋襄東去，宋義歸營，約莫是夜餐時候，士卒都一齊會食，羽獨無心下膳，自出巡行，聽得士卒且食且談，互有怨言，不由的激起宿憤，乘機欲發。一俟大眾食畢，即趨入宣言道：「我等冒寒前來，實為救趙破秦起見，為何久留此地，不聞進行？方今歲饑民貧，士卒食芋菽，軍營無現糧，乃尚飲酒高會，不思引兵渡河，往就趙粟，合攻秦兵，反說要乘他疲敝。試想秦兵強悍，攻一新立的趙國，勢如摧枯，趙滅秦且益強，何敝足乘？況我國新遭敗衄，主上坐不安席，盡發境內兵士，屬諸上將軍，國家安危，在此一舉，今上將軍不恤士卒，但顧私謀，這還好算得社稷臣麼？」大眾聽了，雖未敢高聲響應，但已是全體贊成。項羽窺透眾意，方才歸寢。宋義已經酒醉，回營便睡，一些兒沒有知曉。竟變做糊塗蟲。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-018', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 18, 'narrative', 'carried', '[]'::jsonb, '到了翌日早起，羽借進謁為名，大踏步馳入義帳，義方在盥洗，被羽走近身旁，拔劍砍義，砉的一聲，已將義首級劈落帳下。小子有詩歎道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-019', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 19, 'aside', 'carried', '[]'::jsonb, '漫言智識果超群，一死何殊武信君！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-020', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 20, 'aside', 'carried', '[]'::jsonb, '才識恃才徒速禍，可憐身首已中分。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-021', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 21, 'narrative', 'carried', '[]'::jsonb, '羽既殺死宋義，復梟了他的首級，提出帳前，舉示大眾。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-022', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 22, 'aside', 'carried', '[]'::jsonb, '欲知大眾是否服羽，且看下回便知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-016-023', '前漢演義', 16, 207, '第16回·秦二世三年了', '', 23, 'commentary', 'carried', '[]'::jsonb, '項梁之死，失之於驕，宋義之死，亦未始非驕所致。義知項梁之驕兵必敗，而果為其所料，詡詡然自誇先見之明，蓋亦驕矣。及懷王召入幕中，寵信日深，更足釀成義之驕態。及擢為上將軍，給以美號，畀以重權，而義之驕乃益甚。夫救兵如救火然，豈可中道逗留，月餘不進乎？況行兵以銳氣為主，銳氣一衰，何足禦敵？義嘗以此譏項梁，而不知自蹈此轍，即使項羽無殺義之舉，亦安在而不致敗也！視人則明，處己則昏，吾於宋義亦雲。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-001', '前漢演義', 17, 207, '第17回·秦二世三年了', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說項羽殺死宋義，攜首出帳，舉示大眾，且號令軍中道：「宋義與齊私通，謀叛楚國，我奉楚王命令，已把他斬首了。」眾將士已多怨義，更見羽奮髯如戟，振喉如雷，彷彿與黑煞神相似，頓令人人生畏，莫敢枝梧。當有數將士應命道：「首立楚國，原出將軍家中，今將軍誅亂有功，應該代任上將軍，統轄全營。」羽接入道：「這也須稟明我王，靜候旨意。」將士復道：「軍中不可無主，將軍何妨攝行職務，再候王命未遲。」羽便允諾，大眾便同聲推立，稱羽為假上將軍。羽想出一條斬草除根的法子，索性派遣心腹將弁，趕上宋襄，一刀殺死，然後使屬將桓楚，報命懷王，詭言宋義父子，謀叛不道，已由大眾公同議決，誅死了事。懷王亦明知項羽奪權，但又不能制服項羽，只好將錯便錯，遣使傳命，就使項羽為上將軍。懷王之不得其死，已在此處伏案。一朝權在手，就把令來行，便遣當陽君英布，及蒲將軍等，領兵二萬人，渡河前進，自為後應，徐徐進行。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-002', '前漢演義', 17, 207, '第17回·秦二世三年了', '', 2, 'narrative', 'carried', '[]'::jsonb, '趙將陳餘，自為秦軍所敗，不敢與秦爭鋒，惟征集常山兵數萬人，屯駐巨鹿城北，虛張聲勢。秦兵得王離為助，餉足兵多，急攻巨鹿。巨鹿城內，日夜不安，守兵逐日傷亡，糧草又逐日減少，急得趙相張耳，焦灼異常，屢使人縋城夜出，往促陳餘進戰。餘只畏戰不進，耳越加惶急，又使張黶陳澤二將，往責陳餘，傳述己言道：「耳本與君為刎頸交，誓同生死，今王與耳困坐圍城，朝不保暮，所望惟君，君乃擁兵數萬，不肯相救，豈非有負前盟！如果誠心踐約，何不亟赴秦軍，拚同一死！死中或可求生，十分危險中，未必無一二分僥倖，請君細思。」陳餘喟然道：「我非不欲相救，但兵力未足，冒昧前進，有敗無勝，有亡無存，且餘所以不敢輕死，實欲為趙王張君，破秦報怨，今若同去拚死，譬如舉肉喂虎，有何益處！」語雖近是，終由怯戰。張黶陳澤道：「事已萬急，總須誓死全信，後事也無暇顧慮了。」餘又道：「據我意見，同死終歸無益，兩君必欲盡忠，何勿先去一試？」黶澤齊聲道：「公如撥兵相助，雖死何辭！」原是要你去死。餘乃撥兵五千人，使隨二人進戰。還要斷送五千人性命。黶澤也嫌兵少，因未便申請，就把死生置諸度外，引著五千兵士，逕向秦營殺去。秦軍開壁與戰，擁出千軍萬馬，來鬥黶澤，黶澤雖拚命力爭，怎奈秦兵越來越多，部兵越鬥越少，終落得全軍覆沒，一並歸陰。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-002', 'julu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-003', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '秦兵益振，巨鹿益危。燕齊諸國，為了趙使一再乞援，各派兵赴救。張耳子敖，也從代郡招兵萬餘，入援巨鹿。惟皆憚秦兵威，只遠遠的駐紮兵馬，未敢輕試。陳餘也為加懮，因聞楚兵已發，多日不至，乃更使人敦促，直至項羽營中。羽正擬進兵，復得英布蒲將軍兵報，前驅尚稱得利，惟請後軍接應等語，羽遂與趙使約定軍期，先使歸報，一面驅動大隊，悉數渡河。既至對岸，便下令沈船，破釜甑，燒庐舍，但令軍士持三日糧，與秦兵決一死戰，不求生還。將士等到了絕地，也曉得有進無退，個個懷著必死的念頭，向前馳去。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-003', 'julu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-004', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '行了半日有餘，即與英布蒲將軍相遇。兩人見了項羽，謂已與秦兵交戰數次，殺死多人，不過秦兵氣勢尚盛，糧運不絕，須先斷彼糧道，方可制秦云云。項羽點頭道：「斷截糧道，原是要策﹔但秦將章邯王離等人，豈有不防？且待我直救巨鹿，殺他一陣，再作計較。」說著，復麾兵急進，趨向巨鹿。途次遇著秦兵攔阻，但教項羽橫槊一掃，都已東倒西歪，抱頭竄去。及望見巨鹿城，城上雖有守兵列著，已是殘缺不全，城下的秦營，好似圍棋一般，四面密布，殺氣騰騰。羽毫不畏縮，仍然撥馬當先，率兵前進。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-004', 'julu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-005', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '秦將王離等，聽得楚軍遠來，竟敢進戰，也料他有些膽力，不敢輕視，且又接得敗兵回報，具述楚將厲害，於是調動兵馬，自往接仗，留他將涉閒圍城，命裨將蘇角守住甬道，放心大膽，去敵楚軍。離城僅及里許，已碰著楚軍前隊，慌忙佈陣，那知前隊的統帥，就是項羽，舉槊一揚，楚將楚兵，便向秦陣擁入。羽亦躍馬入陣，王離麾兵攔截，俱被殺退。再加羽一桿長槊，神出鬼沒，不可捉摸，秦陣裡面，只見他一道槊影，七上八下，戳倒人馬無數。離料不可當，回馬便退，羽步步進逼，不肯少緩。惹得王離性起，仗著人多勢旺，翻身再戰，偏項羽越戰越勇，餘外將士，亦越鬥越奮，直殺到山搖地動，天日無光。離三進三卻，只好奔回本營。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-006', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 6, 'narrative', 'carried', '[]'::jsonb, '章邯見王離戰敗，親來援應，再與楚軍對壘。這時候的各國援軍，統在自己營中，踞壁觀戰。遙見秦楚兩方的將士，漸漸接近，秦兵甲仗整齊，人馬雄壯，差不多如泰山一般，聚成一堆。楚軍是衣服簡陋，步伐粗疏，三三五五，各自成隊，也沒有甚麼陣式，但向秦壘中衝來。各國將士，還道楚軍沒有紀律，一味蠻觸，必敗無疑，徒觀皮相，曉得甚麼！那知項羽是殺星下降，但令兵士向前奮鬥，不管甚麼形式。況且楚兵不多，比秦兵要少一半，若要將對將，兵對兵，配搭均勻，方好動手，簡直是不夠分派，只好罷休。所以羽申令將士，使他各自為戰，不必相顧，違令立斬。一班楚軍，統是拚著性命，上前爭殺，一當十，十當百，呼聲動天地，怒氣衝鬥牛。不但秦兵在場交手，擋不住這種勁敵，嚇得膽戰心驚，就是壁上旁觀的將士，也不禁目瞪口呆，不寒自栗。章邯本已在項羽手中，經過敗仗，此次見楚軍越加利害，料難久持，連忙引兵退下，十成中已喪失了三五成。項羽見章邯退去，才令部眾下營休息，到了夜間，仍然嚴裝待著。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-007', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '好容易過了一宵，令軍士飽食乾糧，再行進攻。羽且下令道：「今日若不掃盡秦兵，糧要絕了，彼死我活，就在今日，大眾務要努力！」眾將士齊稱得令，就從營中擁出，直奔秦軍。秦將章邯，不得已再來接戰，這次交鋒，邯亦鼓勵將士，誓決雌雄。無如部下已經膽落，任你章邯如何激勵，總是不能敵楚。章邯屢令前進，部眾進一步，退兩步，進兩步，退四步，直至五進五退，已是不能成軍了。計自項羽至巨鹿城下，與秦兵先後大戰，已經九次，秦兵無一不敗，章邯逃回城南大營，王離涉間，勉強守住本寨，不敢出頭。項羽乃得使英布蒲將軍，往堵甬道，自攻王離涉間。搗將進去，營門立破，王離想奪路逃生，兜頭碰著項羽，只得持槍抵敵，戰不三合，被羽用槊一撥，那王離手中的槍桿，陡向天空中飛了上去，奇語。離只剩一雙空手，回頭欲跑，楚兵一齊趕上，把離打倒，活擒出寨。涉間見王離被擒，自知死在眼前，索性放起火來，把營盤燒個淨盡，連自身也葬入火窟，變做一段黑炭團。造語亦新。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-007', 'julu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-008', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 8, 'narrative', 'carried', '[]'::jsonb, '羽見秦營火起，倒也一驚，忙令軍士少退。俄而火勢漸衰，秦營已成焦土，秦兵非死即降。各國軍將，方陸續趨集，求見項羽，願共擊章邯軍，羽獰笑道：「嘻，此時才來見我麼？」得意語，亦奚落語。說罷，復命各國軍將，往候自己營前，準備傳見。羽整轡回營，升帳上坐，才召見各國軍將。各軍將正要入營，驀見有一彪人馬，擁著兩員大將，踴躍前來。一將手持長槍，槍上挑著一個血淋淋的首級，可驚可怖。既至營前，兩將一同下馬，命部兵留站營外，且將槍械交付弁目，但攜首級進去。須臾即有一人持出首級，懸示營門。各國軍將，越覺驚惶，問明楚軍，方知進營兩將，就是英布蒲將軍，所攜首級，乃是秦將蘇角，為布所殺，故特來報功。殺蘇角用虛寫法，比實寫尤有神采。各國軍將聽了，恐慌愈甚，不由的跪倒營門，膝行而入，至項羽座前，俯伏報名，不敢仰視。丑。羽故意遲慢，好一歇才命起身，刁。各軍將又叩頭稱謝，慢慢兒的立起。經羽囑令旁坐，略問了兩三語，但聽各人齊聲道：「上將神威，古今罕有，末將等願聽指揮！」羽也不多讓，即答說道：「既承諸公見推，我有僣了！諸公且回營靜守，俟有戰事，自當通報。」各軍將乃一律告退。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-009', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 9, 'narrative', 'carried', '[]'::jsonb, '既而趙王歇及趙相張耳，也出城至項羽營，表明謝意，羽始下座相迎，與趙王歇等分坐左右。歇拱手稱謝，羽略略謙遜，談了數語，歇與耳亦起座辭去。耳尚私恨陳餘，不及回城，便往陳餘營中，責他坐視不救。又問及張黶陳澤二人，陳餘道：「張黶陳澤勸餘拚死，餘以為徒死無益，他兩人定要出戰，餘乃撥遣五千人隨他同往，果致全軍覆沒，兩人俱死，真正可惜！」張耳變色道：「恐怕不是這般。」陳餘道：「餘與兩人無仇無怨，想不至暗中加害，況兩將出兵，萬人注目，亦非餘一人可以捏造，請公休疑。」兩人雖非餘所殺，但餘也不能無咎。張耳總是不信，還要問他如何戰死，如何不去救應，嘮嘮叨叨，說個不休，餘不覺動怒道：「公何怨餘至此！餘情願繳出將印罷了！」說著，便將印綬解下，交與張耳，耳不意陳餘決裂，倒也未敢接受。餘將印綬置諸案上，出外如廁，當由張耳隨員，私下語耳道：「古人有言，天與不取，反受其咎。今陳將軍解印與公，公若不受，恐違天不祥，何必多辭！」耳乃取過印綬，佩諸身上。及陳餘復入，見張耳居然佩印，越有慍色，不復再言。竟出與親卒數百人，悻悻自去，散居河上澤中，捕魚獵獸，自尋生活，待後再表。餘若從此不出，卻是一個高人。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-010', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 10, 'narrative', 'carried', '[]'::jsonb, '且說陳餘既去，張耳身兼將相，收攬陳餘部曲，仍奉趙王歇還居信都，自復引兵隨從項羽，一同攻秦。項羽遂進逼章邯，邯在棘原固壘自守，部眾尚有二十餘萬人，羽又欲麾兵猛攻，還是這位老將范增，主張緩戰，待他糧盡勢蹙，自然溃退，省得多費兵力。羽乃就漳南下寨，與邯相持。邯也不敢出戰，惟奏報咸陽，具陳敗狀，請旨定奪。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-010', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-011', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 11, 'narrative', 'carried', '[]'::jsonb, '趙高獨攬大權，竟將邯奏報擱著，概不呈入，二世當然無聞。偏有一班宦官宮妾，交頭接耳，互談章邯敗耗，致被二世聞知。二世乃召入趙高，詰問軍事，高復奏道：「現在朝廷兵馬，多歸章邯一人調遣，臣忝為內相，不能遠察軍情，章邯亦沒有甚麼軍報，不過近日傳來風聞，說他損兵折將，究竟如何情狀，尚未詳悉。臣正擬奏聞，不意陛下燭照四方，先已週知，臣想關東群盜，多系烏合，為何章邯手擁重兵，不亟蕩平，請陛下降詔切責，免致玩延。」二世聽著，仍以趙高為忠，囑使頒詔出去。其實趙高是疑忌章邯，還道他暗通內線，稟聞二世，所以將縱盜玩寇的罪名，一古腦兒推在章邯身上，即令文吏繕就嚴詔，派人馳遞邯營。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-012', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 12, 'narrative', 'carried', '[]'::jsonb, '邯接讀詔書，且憤且懼，又使長史司馬欣速詣咸陽，面奏一切。欣不敢怠慢，星夜入都，趨至朝門，急求進謁。那知二世久不視朝，殿內只有趙高作主，聽得章邯差人到來，故意不見，但使他在外伺候。欣只好耐心待著，一住三日，仍不聞有召見消息。不得已賄托門吏，探問底細，凡事非錢不行。門吏才為告知，無非說是丞相趙高，陰忌章邯等語。欣吃了一驚，且恐自己受累，急向朝門逃出，上馬離都，從小路奔還棘原。待趙高聞欣出走，遣人追捕，但從官道趕去，杳無影跡，白跑了數十里，只好返報。那司馬欣奔回本營，便向章邯報明情跡，且皇然道：「趙高居中用事，不利將軍，將軍有功亦誅，無功亦誅，請將軍自圖良策。」章邯聽到欣言，自然加懮，一時也想不出方法，但悶坐營中，嗟歎不已。忽帳外傳入一書，當即取過展閱，但見上面寫著：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-012', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-013', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 13, 'narrative', 'carried', '[]'::jsonb, '章大將軍麾下：僕聞白起為秦將，南征鄔郢，皆楚地。北坑馬服，趙括嗣父官爵，號馬服君，為白起所殺。攻城略地，不可勝計 而竟賜死。蒙恬為秦將，北逐戎人，開榆中地數千里，竟斬陽周。何者？功多秦不能盡封，因以法誅之，今將軍為秦將三歲矣，所亡失以十萬數，而諸侯並起，今且益多，彼趙高但知阿諛，今事急，亦恐二世誅之，故欲以法誅將軍以塞責，使人更代將軍以脫其禍。夫將軍居外日久，必多內隙，無功固誅，有功亦誅。且天之亡秦，無論智愚，並皆知之，今將軍內不能直諫，外為亡國將，孤持獨立，而欲常存，豈不哀哉！將軍何不還兵，與諸侯合縱連盟，約共攻秦，分王其地，南面稱孤，豈不癒於身伏釜鑕，妻子為戮乎？惟將軍圖之！故趙將陳餘再拜。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-014', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 14, 'narrative', 'carried', '[]'::jsonb, '章邯閱了又閱，反覆數周，頗為感動，乃使候官始成，詣項羽營中請和。羽拍案大怒道：「章邯殺我叔父，仇恨未消，我方欲梟邯首級，祭我叔父，乃還敢來請和麼？本該將汝先斬，今暫借汝口還報，叫章邯速來受死，還可赦汝全軍！」說罷，喝令左右將始成驅出營門。始成踉蹌回報，邯愁上加愁。正在進退兩難的時候，突有探騎入稟道：「楚兵已渡三戶津，由蒲將軍帶領過來，想是要來攻營了。」邯忙說道：「休教他進逼我營！」一面說，一面即派令偏師，出去堵截。才越半日，便有敗兵跑入道：「楚兵甚銳，我軍敵他不過，只好退回，請主帥速即濟師。」章邯一想，項羽不來總還可當，不如自去抵敵為是。當下披掛上馬，麾兵逕行，才至汗水岸旁，便已接著楚軍，彼此毫不答話，立即交戰，約有一兩個時辰，不分勝負。驀聽得楚軍後面，喊聲震地，鼓角喧天，乃是項羽引著大隊人馬，親自殺到。寫得有聲有色。邯不禁心慌，秦兵越覺膽怯，紛紛倒退。說時遲，那時快，楚軍已突過戰線，衝破秦兵陣腳，秦兵登時大亂，四散奔逃﹔章邯亦顧命要緊，回馬便走。好容易逃入本營，已亡失了無數士卒，還幸楚軍趕了數里，便即停住，尚得徐收溃兵，勉守大寨。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-015', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 15, 'narrative', 'carried', '[]'::jsonb, '邯至此窮極沒法，都尉董翳，又勸邯向楚乞降，邯皺眉道：「項羽記念前仇，不肯收納，奈何？」董翳道：「可教司馬欣前去，便無他慮。」邯乃召入司馬欣，叫他齎書降楚，欣竟不推辭，索書即去。未幾便得欣復報，說是項羽已肯收容，不念舊怨了。看官，你道司馬欣投詣楚營，何故一說便妥？原來欣曾充過櫟陽獄掾，救免項梁，與項氏本有交情，小子於十二回中，也已敘及。此次往見項羽，便把前情說起，且勸羽舍私圖公。羽尚不肯遽允，由范增從旁解勸，並言兵多糧少，未易支持，還是收降章邯，較為得計，羽乃允欣所請，與欣訂約，決不害邯。總不免有負叔父。於是邯與司馬欣董翳等人，至洹水南岸，候著項羽，解甲乞降。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-015', 'yueyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-016', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 16, 'narrative', 'carried', '[]'::jsonb, '掃盡雄威作楚奴，男兒志節太卑汙﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-017', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 17, 'aside', 'carried', '[]'::jsonb, '洹南立約雖逃死，終愧昂藏七尺軀！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-018', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 18, 'aside', 'carried', '[]'::jsonb, '欲知羽與邯相見等情，待至下回再表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-017-019', '前漢演義', 17, 207, '第17回·繫於「鉅鹿之戰」', '', 19, 'commentary', 'carried', '[]'::jsonb, '項羽之救巨鹿，為秦史上第一大戰，秦楚興亡之關鍵，實本於此。蓋章邯為秦之驍將，邯不敗，即秦不亡。且山東各國，無敢敵邯，獨羽以破釜沉舟之決心，與拔山扛鼎之大力，一往直前，九戰皆勝，虜王離，殺蘇角，焚涉間，卒使能征善戰之章邯，一蹷不振，何其勇也！然使秦無趙高之奸佞，二世之昏愚，則邯猶不至降楚，或尚能反攻為守，亦未可知。天意已嫉秦久矣，故特使趙高以亂其中，復生項羽以撓其外，章邯一去而秦無人，安得不亡！誰謂冥冥中無主宰乎？');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-017-019', 'julu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-001', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說章邯等行至洹南，向羽請降，羽引著許多將士，及各國軍帥，昂然前來，旌旗嚴整，甲仗鮮明，威武的了不得，既至洹南，才一簇兒停住。洹南在安陽縣北，商朝盤庚遷殷，就是此處，故號為殷墟。章邯等見羽到來，慌忙下馬，長跪道旁。羽傳令免禮，方起立道：「邯為秦臣，本思效忠秦室，無如趙高用事，二世信讒，秦亡只在旦夕，邯不能隨他俱亡。今仰將軍神威，無戰不克，此去除暴安良，入關稱王，舍將軍外，尚有何人。邯早欲擇主而事，不過前時奮不顧私，觸犯將軍，自知負罪，未敢遽投。現蒙將軍寬宥，恩同再造，誓當竭力圖效，借報深恩。」說至此，嗚咽流涕。想亦怕羞起來。羽乃出言撫慰道：「君也不必多心，既知去逆效順，我亦不便因私廢公﹔若得乘此滅秦，富貴與共，決不食言。」章邯拜謝，秦將士並皆叩首。俟項羽一一登錄，方敢起立，羽即命司馬欣為上將軍，令他帶領秦兵二十餘萬，充作前驅，立章邯為雍王，留置營中。全是專擅行事，已不知有楚懷王了。自己引著楚軍，及各國將士，約得四十萬人，按程前進，關中大震。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-002', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '還有一位趕先走著的沛公，已經向西直入，一路順風，逕指秦關。說將起來，也有一番事跡，自從沛公道出昌邑，守將據城不下，只好督兵進攻。適有昌邑人彭越，領了徒眾，來見沛公，沛公甚喜，即令越一同攻城。城上矢石如雨，反傷了幾百攻城兵，沛公飭令暫停，且與彭越另商他法。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-003', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '越小字為仲，向在巨鹿澤中，捕魚為業，膂力過人，澤中少年，推為漁長。及陳勝發難，項梁繼起，海內鼎沸，相率叛秦，越黨也欲起事，勸越據地自立。獨越未肯遽發，說是兩龍方鬥，少待為佳。轉眼間又過一年，澤中有百餘少年，往從彭越，定要舉他為長，定期舉事。越辭無可辭，乃與諸少年預約，翌晨會議，後期即斬。諸少年應聲而去。到了次日，越早起待著，諸少年陸續到來，或先至，或後至，最後的竟遲至日中。越忿然作色道：「我原不欲為諸君長，諸君乃按年推立，必欲長我，應該聽我指揮。昨與諸君立約，日出會議，今已差不多日中了，違約遲來，共計有十餘人，本當一律處斬，但念人數太多，不可盡誅，只有將最後一人，斬首號令。」諸少年不待說完，便都笑說道：「何至如此！後當遵約便了。」那知越已令校長，竟將後至的少年，推出外面，剁成兩段。一面設壇祭神，懸首示眾。也是一個殺星下凡。諸少年始相驚畏，不敢違越。越遂招集各地散卒，得千餘人，一聞沛公過境，遂來助戰。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-003', 'julu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-004', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '沛公見昌邑難下，意欲改道進兵，與越相商。越謂改從高陽，亦無不可。沛公乃與越作別，但以後會為期，自率部兵逕往高陽。敘彭越事，為後文封王張本。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-005', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '高陽有一老儒，家貧落魄，無以為生，但充當裡中監門吏，姓酈名食其。食音異，其音幾。項梁等起兵楚中，嘗遣將吏過高陽，先後約數十人。酈食其問明姓氏，統以為齷齪小才，不足成事，免不得背地揶揄。旁人笑他滿口狂言，因呼為狂生。酈之不得令終，亦由多言取禍。至沛公到瞭高陽，有一麾下騎士為酈生同裡子弟，與酈生素來認識，彼此相見，當然有一番扳談。酈生語騎士道：「我聞沛公性情倨傲，不肯下人，究竟是否屬實？」騎士道：「這種傳說，不為無因﹔但卻喜求豪俊，所過必問，如果有智士與談，倒也極表歡迎，未嘗輕視。」沛公之所長在此。酈生道：「照汝說來，沛公確有大略，與眾不同。我卻願與從游，汝肯為我先容否？」騎士半晌無言，酈生道：「汝疑我老不中用麼？汝可去見沛公，但言同裡中有個酈生，年六十餘，身長八尺，素號大言，裡人都目為狂生，他卻自謂非狂，讀書多智，能助大業呢。」騎士搖首道：「沛公最不喜儒生，遇有儒冠文士，前來求見，沛公便命他免冠，作為溺器，就是平日談論，亦常謂儒生迂腐，笑罵不休，公奈何欲以儒生名義，往說沛公？」酈生道：「汝試為我進言，我料沛公必不拒我。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-006', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 6, 'narrative', 'carried', '[]'::jsonb, '騎士欲試酈生智識，乃逕見沛公，如酈生言。沛公也不多說，但令騎士往召。及酈生進謁時，沛公方在驛館中，踞坐牀上，使兩女子洗足。酈生瞧著，故意徐進，從容至沛公前，長揖不拜。沛公仍然不動，好似未曾看見一般。酈生朗聲道：「足下引兵到此，欲助秦攻各國呢？還是與各國攻秦呢？」沛公見他儒服儒冠，已覺惹厭，並且舉動粗疏，語言唐突，不由的動了怒意，開口罵道：「豎儒！尚不知天下苦秦麼？諸侯統欲滅秦，難道我獨助秦不成！」酈生接口道：「足下果欲伐秦，為何倨見長者！試想行軍不可無謀，若慢賢傲士，還有何人再來獻計呢！」無非戰國時說士口脗。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-007', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '沛公聽了，才命罷洗，整衣而起，延他上坐。兩下問答，酈生具述六國成敗，口若懸河，滔滔不絕。沛公很是佩服，便與商及伐秦計策。酈生道：「足下兵不滿萬，乃欲直入強秦，這真是驅羊入虎，但供虎吻罷了。據僕愚見，不如先據陳留，陳留當天下要衝，四通八達，進可戰，退可守，且城中積粟甚多，足為軍需，僕與該縣令相識有年，願往招安，倘若該令不從，請足下引兵夜攻，僕為內應，城可立下。既得陳留，然後招集人馬，進破關中，這乃是今日的上計。」沛公大悅，即請酈生先行，自率精兵繼進。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-007', 'chenliu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-008', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 8, 'narrative', 'carried', '[]'::jsonb, '酈生到了陳留，投刺進見，當由該令迎入。敘過幾句寒暄套話，酈生便將利害得失的關係，說了一遍，偏該令不為所動，情願與城俱亡。酈生乃改變論調，佯與縣令議守，一直談到日昃時候，縣令甚為合意，設宴相待。酈生本是酒徒，百杯不醉，那縣令飲了數大觥，卻已爛醉如泥，自去就寢，令酈生留宿署中。酈生待至夜半，竟靜悄悄的混出縣署，開了城門，放入沛公軍，復導至縣署左右。一聲鼓噪，大眾擁入，縣署中能有幾個衛隊，一古腦兒逃之夭夭。縣令尚高臥未醒，被軍士突至榻前，用刀亂砍，便即身死。當下大開城門，迎入沛公，揭榜安民，秋毫無犯。城中百姓，統皆帖服，毫無異言。沛公檢查穀倉，果然貯粟甚多，益信酈生妙算，封號廣野君。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-008', 'chenliu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-009', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 9, 'narrative', 'carried', '[]'::jsonb, '酈生有弟名商，頗有智勇，由酈生薦諸沛公，召為裨將，使他招募士卒，得四千人，沛公遂命他統帶，隨同西進，圍攻開封。數日未下，驀聞秦將楊熊，前來救應，沛公索性麾兵撤圍，竟去截擊楊熊。行至白馬城旁，正值楊熊到來，便即衝殺過去。熊未及防備，慌忙退軍，前隊兵馬，已傷亡多人，及退至曲遇東偏，地勢平曠，熊因就地佈陣，準備交戰。沛公引兵進擊，兩陣對圓，各不相讓。正殺得難解難分，忽有一支生力軍趕到，竟向楊熊陣內，橫擊過去，把熊軍衝作兩段。熊軍前後截斷，自然溃亂！再經沛公乘勢驅殺，哪裡還能支持？楊熊奪路奔走，逃入滎陽，手下各軍，傷失殆盡。惟沛公此次交兵，幸虧有人夾攻楊熊，有此大捷。正要派員道謝，來將已到面前，滾鞍下馬，向沛公低頭便拜。沛公也下馬答禮，親自扶起，當頭一瞧，乃是韓司徒張良，突如其來，回應第十五回。故人重聚，喜氣洋洋，當即擇地安營，共敘契闊。良自言拜別以後，與韓王成往略韓地，取得數城。可恨秦兵屢來騷擾，數城乍得乍失，不得已在潁川左右，往來出沒，作為游兵。今聞沛公過此，特來相助云云。沛公道：「君來助我，我亦當助君且去取了潁川，再攻滎陽。」說罷，便麾動人馬，南攻潁川。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-009', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-010', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 10, 'narrative', 'carried', '[]'::jsonb, '潁川守兵，登陴抵禦，高聲辱罵。沛公大怒，親自督攻，好幾日才得破入，盡將守兵殺死，乃復議進兵滎陽。會有探騎來報，秦將楊熊，已由秦廷遣使加誅了。沛公喜道：「楊熊已死，近地可無他患，我等且把韓地奪還，再作計較。」張良亦以為然。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-010', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-011', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 11, 'narrative', 'carried', '[]'::jsonb, '會聞趙將司馬卬，也欲渡河入關，沛公恐自己落後，乃北攻平陰，急切不能得手，改趨雒陽。雒陽頗多秦戍，攻不勝攻，因移就轘轅進軍。轘轅乃是山名，嶺路崎嶇，共計有十二曲，須要盤旋環行，故名轘轅。秦人以地勢迂險，不必扼守，遂使沛公暢行無阻。一過轘轅，勢如破竹，連下韓地十餘城。適韓王成來見沛公，沛公即令居守陽翟，自與張良等南趨陽城，奪得馬千餘頭，配充馬隊，令作前驅，直向南陽進發。南陽郡守名齮，史失其姓。出兵至犨縣東，攔截沛公，被沛公迎頭痛擊，靦軍大敗，走保宛城。沛公追至城下，望見城上已列守卒，不願圍攻，便從城西過兵，迤邐而去。約行數十里，張良叩馬進諫道：「公不欲攻宛，想是急欲入關，但前途險阻尚多，秦戍必眾，若不下宛城，恐滋後患，秦擊我前，宛塞我後，進退失據，豈非危迫！不如還攻宛城，掩他不備，幸得攻下，方可後顧無懮了。」沛公依議施行，復由良詳為畫策，傳令各軍繞道回宛，偃旗息鼓，夤夜疾行。靜悄悄的到了城下，天色尚是未明，便將宛城圍住，環繞三匝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-011', 'luoyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-011', 'yangzhai', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-011', 'wan', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-012', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 12, 'narrative', 'carried', '[]'::jsonb, '佈置已定，方放起號炮，響徹城中。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-013', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 13, 'narrative', 'carried', '[]'::jsonb, '南陽守齮，總道沛公已去，不至再回，樂得放心安膽，鼾睡一宵。及城外炮聲大震，方才驚起，登城俯視，見敵軍環集如蟻，嚇得魂飛天外，躊躇多時，除死外無他法，不由的淒然道：「罷！罷！」說到第二個罷字，便拔出佩劍，意欲自刎。忽後面有人急呼道：「不必，不必，死時尚早呢！」救星來了。齮聞言回顧，乃是舍人陳恢，便驚問道：「君叫我不死，計將安出？」陳恢道：「沛公寬厚容人，公不如投順了他，既可免死，且可保全祿位，安定人民。」齮半晌方答道：「君言也是有理，肯為我往說否？」恢一口應承，便縋城下來，當被攻城兵拘住。恢自稱願見沛公，軍士便押至沛公座前。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-014', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 14, 'narrative', 'carried', '[]'::jsonb, '沛公問他來意，恢進說道：「僕聞楚王有約，先入關中，便可封王。今足下留攻宛城，宛城連縣數十，吏民甚眾，自知投降必死，不得不乘城固守，足下雖有精兵猛將，未必一鼓就下，反恐士卒多傷﹔若舍宛不攻，仍然西進，宛城必發兵追躡，足下前有秦兵，後有宛卒，方且腹背受敵，勝負難料，如何驟能進關？為足下計，最好是招降郡守，給他封爵，使得仍守宛城，通道輸糧，一面帶領宛城士卒，一同西行，將見前途各城，聞風景慕，無不開門迎降，足下自可長驅入關，毫無阻礙了。」沛公一再稱善，且語陳恢道：「我並非拒絕降人，果使郡守出降，自當給他封爵，煩君還報便了。」恢即馳回城中，報知郡守。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-014', 'wan', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-015', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 15, 'narrative', 'carried', '[]'::jsonb, '郡守齮開城相迎，引導沛公入城。沛公封齮為殷侯，恢為千戶，官名。仍然留守宛城。隨即招集宛城人馬，引與俱西，果然沿途城邑，無不迎降。嗣是經丹水，出胡陽，下析酈，嚴申軍禁，毋得擄掠。秦民安堵如常，統皆喜躍，王師原宜如此。沛公遂得直抵武關。關上非無守將，只因沛公兵長驅直進，忽然掩至，急得倉皇無措，不及徵兵，但令老弱殘卒數千人，開關迎敵，不值沛公一掃，守將抱頭竄去，好好把一座關城，讓與沛公。沛公安然入關，咸陽一夕數驚，訛言四起，人多逃亡﹔那陰賊險很的趙高，至此也惶急起來。惡貫已將滿了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-015', 'wan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-015', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-015', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-016', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 16, 'narrative', 'carried', '[]'::jsonb, '趙高威權日重，已把二世騙入宮中，好似軟禁一般，不得過問。還恐朝上大臣，或有反對等情，因特借獻馬為名，入報二世。二世道：「丞相來獻，定是好馬，可即著人牽來。」趙高遂令從吏牽入。二世瞧著，並不是馬，乃是一鹿。便笑說道：「丞相說錯了！如何誤鹿為馬？」高尚說是馬，二世不信，顧問左右，左右面面相覷，未敢發言。再經二世詰問，方有幾個大膽的侍臣，直稱是鹿。不料趙高竟忿然作色，掉頭逕去。不到數日，高竟將前時說鹿的侍臣，誘出宮禁，一並拿住，硬派他一個死罪，並皆斬首。二世全然糊塗，竟不問及，一任趙高橫行不法。惟宮內的近侍，宮外的大臣，從此越畏憚趙高，沒一個稍敢違慢，自喪生命。及劉項兩路兵馬，東西並進，趙高還想瞞住二世，不使得聞。到了沛公陷入武關，遣人入白趙高，叫他趕緊投降，高方才著急。一時想不出方法，只好詐稱有病，數日不朝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-016', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-017', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 17, 'narrative', 'carried', '[]'::jsonb, '二世平日，全仗趙高侍側，判決政務，偏趙高連日不至，如失左右兩手，未免驚惶。日間心亂，夜間當然多夢，朦朦朧朧，見有一隻白虎，奔到駕前，竟將他左驂馬齧死，還要跳躍起來，嚇得二世狂叫一聲，頓時醒悟，心下尚突突亂跳，才知是一個惡夢。死兆已見。翌日起牀，越想越慌，乃召太卜入宮，令占夢兆。太卜說是涇水為祟，須由御駕親祭水神，方可禳災。敢問他如何依附上去？二世信為真言，遂至涇水岸旁的望夷宮，齋戒三日，然後親祭。惟二世既離開趙高，總不免有左右侍臣，報稱外間亂事，且雲楚軍已入武關。二世大驚，忙使人責問趙高，叫他趕緊調兵，除滅盜賊。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-017', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-018', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 18, 'narrative', 'carried', '[]'::jsonb, '高不文不武，徒靠著一種刁計，竊攬大權，此次叫他調兵御亂，簡直是無能為力，況且敵軍逼近，大勢已去，無論如何智勇，也難支持。高欲保全身家，想出一條賣主的法兒，意欲嫁禍二世，殺死了他，方得借口有資，好與楚軍講和。當下召入季弟趙成，及女婿閻樂，秘密定計。趙高閹人，如何有女，想是一個乾女婿。成為郎中令，樂為咸陽令，是趙高最親的心腹。高因與二人密語道：「主上平日，不知弭亂，今事機危迫，乃欲加罪我家，我難道束手待斃，坐視滅門麼？現在只有先行下手，改立公子嬰。嬰性仁儉，人民悅服，或能轉危為安，也未可知。」毒如蛇蠍，可惜也算錯了一著。成與樂唯唯聽命。高又道：「成為內應，樂為外合，不怕大事不成！」閻樂聽了，倒反遲疑道：「宮中也有衛卒，如何進去？」高答道：「但說宮中有變，引兵捕賊，便好闖進宮門了。」樂與成受計而去。高尚恐閻樂變心，又令家奴至閻樂家，劫得樂母，引置密室，作為抵押。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-018-018', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-019', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 19, 'narrative', 'carried', '[]'::jsonb, '樂乃潛召吏卒千餘人，直抵望夷宮。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-020', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 20, 'narrative', 'carried', '[]'::jsonb, '宮門裡面，有衛令僕射守著，驀見閻樂引兵到來，忙問何事。樂竟麾令左右，先將他兩手反绑，然後開口叱責道：「宮中有賊，汝等尚佯作不知麼？」衛令道：「宮外都有衛隊駐紮，日夜梭巡，哪裡來的劇賊，擅敢入宮！」樂怒道：「汝尚敢強辯麼？」說著，便順手一刀，把衛令梟了首級，隨即昂然直入，飭令吏卒射箭，且射且進。內有侍衛郎官，及閹人僕役，多半驚竄，剩下幾個膽力稍壯的衛士，向前格鬥，畢竟寡不敵眾，統皆殺死。趙成復自內趨出，招呼閻樂，同入內殿，樂尚放箭示威，貫入二世坐帳。二世驚起，急呼左右護駕，左右反向外逃去，嚇得二世莫名其妙，轉身跑入臥室。回顧左右，只有太監一人隨著，因急問道：「汝何不預先告我，今將奈何！」太監道：「臣不敢言，尚得偷生至今，否則，早已身死了！」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-021', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 21, 'narrative', 'carried', '[]'::jsonb, '答語未完，閻樂已經追入，厲聲語二世道：「足下驕恣不道，濫殺無辜，天下已共叛足下，請足下速自為計！」二世道：「汝由何人差來？」閻樂答出丞相二字。二世又道：「丞相可得一見否？」閻樂連稱不可。二世道：「據丞相意見，料必欲我退位，我願得一郡為王，不敢再稱皇帝，可好麼？」閻樂不許。二世又道：「既不許我為王，就做一個萬戶侯罷！」樂又不許。二世嗚咽道：「願丞相放我一條生路，與妻子同為黔首。」樂瞋目道：「臣奉丞相命，為天下誅足下，足下多言無益，臣不敢回報。」說著，麾兵向前，欲弒二世。二世料不可免，便橫著心腸，拔劍自刎。總計在位三年，年二十三歲。小子有詩歎道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-022', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 22, 'narrative', 'carried', '[]'::jsonb, '虎父由來多犬兒，況兼閹禍早留貽﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-023', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 23, 'aside', 'carried', '[]'::jsonb, '望夷求免終難免，為問祖龍知不知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-024', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 24, 'aside', 'carried', '[]'::jsonb, '閻樂既殺死二世，當即返報趙高。欲知趙高後事，且至下回表明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-018-025', '前漢演義', 18, 207, '第18回·繫於「鉅鹿之戰」', '', 25, 'commentary', 'carried', '[]'::jsonb, '沛公素不喜儒，乃獨能禮遇酈生，雖由酈生之語足動人，而沛公之甘捐己見，易倨為恭，實非常人所可及。厥後從張良之計，用陳恢之言，何一非捨己從人，虛心翕受乎！古來大有為之君，非必真智勇絕倫，但能從善如登，未有不成厥功者，沛公其前師也。彼趙高窮凶極惡，玩二世於股掌之上，至於敵軍入境，不惜賣二世以保身家，逆謀弒主，橫屍宮中，此為有史以來，宦官逞凶之首例。漢唐不察，復循復轍，何其愚耶！顧不有二世父子，何有趙高。始皇貽之，二世受之，一趙高已足亡秦，劉項其次焉者也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-001', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說閻樂返報趙高，高聞二世已死，自然大喜，立即趨入宮中，搶得傳國玉璽，懸掛身上。本想自己篡位，因恐中外不服，且將公子嬰抬舉上去，俟與楚軍講定和議，再作後圖。主見已定，乃召集一班朝臣，及宗室公子，當眾曉示道：「二世不肯從諫，恣行暴虐，天下離畔，人人怨憤，今日已自刎了。公子嬰仁厚得眾，應該嗣立。惟我秦本一王國，自始皇統馭天下，乃稱皇帝，現在六國復興，海內分裂，秦地比前益小，不應空沿帝號，可仍照前稱王為是。」大眾聞言，心中統皆反對，因為積威所制，未敢異議，只好勉強作答，聽憑裁奪。趙高便令子嬰齋戒，擇日廟見，行受璽禮。一面收拾二世屍首，視作尋常百姓一般，草草棺殮，藁葬杜南宜春苑中。三年皇帝，求生不得，死且不許服袞冕，也覺可憐！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-002', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '公子嬰雖被推立，自思趙高弒主，大逆不道，倘非設法加誅，將來必致篡位。旁顧大臣公子，無一可與同謀，只有膝下二兒，系是親生骨肉，不妨密商，乃喚入與語道：「趙高敢弒二世，豈尚畏我！不過佈置未妥，暫借我做個傀儡，徐圖廢立。我不先殺趙高，趙高必且殺我了。」二子聽著，不禁泣下。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-003', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '正密議間，忽有一人踉蹌趨入道：「可恨丞相趙高，遣使往楚營求和，將要大殺宗室，自稱為王，與楚軍平分關中了。」子嬰一瞧，乃是心腹太監韓談，可與密商，因低聲囑咐道：「我原料他不懷好意，今使我齋戒數日，入廟告祖，明明是欲就廟中殺我，我當托病不行，免遭毒手。」韓談答道：「公子但言有病，尚非善策。」子嬰道：「我若不去告廟，高必自行來請，汝可與我二子，先伏兩旁，俟他進見，突出刺高，大患便可永除了。」談欣然領命，與子嬰二子預先準備，專等趙高進來，一同下手。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-004', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '高正遣人詣沛公營，欲分王關中，偏沛公不肯允許，叱還高使。高不得逞計，且恐人心益散，急欲子嬰告廟，鎮定一時，因此定了日期，派人往報子嬰，子嬰並不推辭。屆期這一日，高先至廟中，待了多時，竟不見子嬰到來。一再差人催促，回稱公子有疾，不能親臨。高憤然道：「今日何日，尚好不至麼？我當親往速駕。」今日是汝死期，汝尚不知麼？說畢，即匆匆馳赴齋宮。下馬入門，遙見子嬰伏案假寐，便大聲呼道：「公子今已為王，速宜入廟告祖，奈何不行！」道言未絕，兩旁趨出三人，持刃至前，喝聲弒君亂賊，還敢胡言！趙高不及答話，已被韓談手起刀落，砍倒地上，再經子嬰二子，雙刃並舉，連下二刀，當即送命。也有此日。子嬰見趙高已誅，亟召群臣入宮，指示高屍，曆數罪惡。群臣爭頌子嬰英明，且言高死不足蔽辜，應夷三族。從前何皆無言？子嬰點首，便令衛隊往捕趙高家屬，並及趙成閻樂一並拿到，俱處死刑，於是往告祖廟，嗣登大位，徵兵遣將，往守嶢關。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-005', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '探報至沛公營，具述底細，沛公即欲引兵進擊，張良進言道：「秦兵尚強，未可輕攻。良聞守關秦將，系一屠家子，必然貪利，願公暫留營中，但使人齎著金寶，往啖秦將，一面就嶢關四近，登山張旗，作為疑兵，秦將內貪重賂，外怯強兵，還有甚麼不降？」沛公依議施行，命酈食其齎寶入關，招誘秦將，且撥部兵數千，悄悄上山，遍列旗幟。秦將登關東望，但見高低上下，統是楚幟豎著，不由的膽裂心寒。可巧酈生叩關入見，送上多珍，引得秦將心花怒開，看一樣，愛一樣，便問沛公何故厚遺？酈生道：「沛公素仰大名，所以備物致意，通告將軍，將軍試想事至今日，秦朝尚能長存麼？將軍若孤守關中，願為秦死，沛公有精兵數十萬，當與將軍相見。惟聞將軍明察事機，熟知利害，所以先禮後攻，敢請將軍明示。」秦將不待聽畢，便已一口應承，願與沛公連和，同攻咸陽。所謂利令智昏。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-005', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-006', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 6, 'narrative', 'carried', '[]'::jsonb, '酈生當即告別，還報沛公。沛公甚喜，復欲令酈生入關訂約，旁有一人出阻道：「不可！句。不可！」沛公把頭回顧，就是前日獻計的張良。不覺動了疑心，問為何意？我亦要疑。張良道：「這不過秦將一人，貪利輕諾，料他部下未必盡從。我若驟與連和，入關同行，萬一彼眾生變，潛襲我軍，可危孰甚！最好是乘他不備，即日掩擊，定獲全勝。」是從假途滅虢的遺計變化出來。沛公連聲稱善，便令部將周勃，引步兵潛逾蕢山，繞出嶢關後面，逕襲秦營。秦將方以為酈生去後，必來續約，安心待著。猛聽得一聲喊起，即有許多敵兵，從營後殺來，秦兵茫無頭緒，還道是做夢一般，紛紛驚溃，秦將不識何因，親至營後察看，不防一大將持刀突入，直至面前，刀光閃處，已把秦將劈開頭顱，腦漿迸流，死於非命。實是該死！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-007', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '這大將就是周勃。勃系沛邑貧民，少時學織蠶箔，賺錢餬口，又因他善能吹簫，常往喪家充役，列入樂工。既而漸屆壯年，身長力大，學習弓馬，無不具精。沛令聞他技勇，引為中涓。官名。及沛公起兵入城，勃即投效麾下，戰必先驅，所向有功。沛公為碭郡長，拜勃為虎賁令，及隨軍西向，尤多戰績。至是復殺死秦將，踏平秦營，關上守卒，亦皆遁去。沛公又引軍入關，接應周勃，追殺秦兵。到了藍田縣南境，遇有戍將攔截，便痛擊一陣。戍將大敗，逃回咸陽。嗣是沿途無阻，直抵霸上。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-007', 'lantian', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-007', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-007', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-008a', '前漢演義', 19, 207, '第19回·繫於「鉅鹿之戰」', '', 8, 'narrative', 'carried', '[10]'::jsonb, '是年適為夏正十月間，秦王子嬰沿秦舊例，方在改元，交相慶賀，是年為');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-008b', '前漢演義', 19, 206, '第19回·漢元年，故特', '', 8, 'narrative', 'marker', '[]'::jsonb, '漢元年，故特提明。不意敗將溃兵，陸續逃回，報稱沛公軍已逼都下。子嬰聞報，惶急失措，忙集大臣計議。好多時來了三五人，統皆束手無策，莫敢發言。子嬰越加焦灼，俄有軍書遞入，取過一閱，乃是沛公招降書。子嬰想了一會，既不能戰，又不能守，只好依書出降。乃駕著素車，乘著白馬，用帶套頸，捧著傳國玉璽，流淚出城，至軹道旁，守候沛公。沛公領著全軍，整隊馳入，戈鋋並耀，徒御無驚。既至子嬰面前，子嬰不得不屈膝就跪，俯首請降。始皇子孫，出丑至此，當是始皇在日百思不到。沛公接了玉璽，命他起身，偕入咸陽，眾將中或請殺子嬰，免滋後患，沛公道：「懷王遣我入秦，正因我寬容大度，不為已甚，況人已投降，還要殺他，也是不詳，君等幸勿多言！」說著，遂召過屬吏叫他看管子嬰，自率將佐入殿去了。總計子嬰為王，只有四十六日，便把秦室江山，雙手奉獻。這並非子嬰誤國，實由始皇二世，造孽太深，所以有此慘象呢。評斷的確。話休敘煩。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-008b', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-009', '前漢演義', 19, 206, '第19回·漢元年，故特', '', 9, 'narrative', 'carried', '[]'::jsonb, '且說沛公既入殿中，與眾休息，將士等乘隙取財，各去打開府庫，攜出金銀寶貝，大家分用。獨蕭何自往丞相府，特覓秦朝圖籍一並收藏，好待日後檢查，得知海內情形，凡關塞險要，戶口多寡等事，都可按圖尋索，一目了然。這就是蕭何特別精細，與他人不同。不愧為佐漢元勛。沛公也趁著閒暇，入宮探視，但見雕樓畫棟，曲榭迴廊，一步步的引人入勝，一層層的換樣生新，到了內外便殿，端的是規模宏麗，構築精工，所有花花色色的帷帳，奇奇怪怪的珍玩，羅列四圍，目不勝睹。最可憐的是一班美人兒，嬌怯怯的前來迎接，有的是蛾眉半蹙，有的是蝤領低垂，有的是粉臉生紅，有的是雲鬟嚲翠，有的是帶雨海棠，盈盈欲淚，有的是迎風楊柳，裊裊生姿，沛公左顧右盼，不禁惹動那好色心腸，一面傳諭免禮，一面步入正寢，將身坐定，好多時不見出來。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-010', '前漢演義', 19, 206, '第19回·漢元年，故特', '', 10, 'narrative', 'carried', '[]'::jsonb, '突有一將趨入道：「沛公欲有天下呢？還是做個富家翁，便算滿志呢？」沛公看是樊噲，默然不答，但呆呆的坐著。癡了。噲又道：「沛公一入秦宮，難道就受迷不成！試看秦宮有此奢麗，所以致亡，沛公何需此物，請速還軍霸上，毋留宮中！」沛公仍然不動，徐徐答道：「我自覺困倦，今夕便在此一宿罷！」看中一班美人了。噲不覺動惱，又恐出言唐突，反致觸怒，便轉身趨出，去尋那智士張良。可巧張良進來，即與語沛公情形，浼他進諫。良點頭逕入，與沛公說道：「秦為無道，故公得至此，公為天下除殘去暴，首宜反秦敝政，力與更新。今始入秦都，便想居此為樂，恐昨日秦亡，明日公亡，何苦為了一時安佚，自敗垂成？古人有言：良藥苦口利於病，忠言逆耳利於行，願公聽樊噲言，勿自取禍。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-010', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-011', '前漢演義', 19, 206, '第19回·繫於「子嬰降，約法三章」', '', 11, 'narrative', 'event_keyword', '[]'::jsonb, '沛公聽了良言，倒也翻然自悟，起身趨出，幸有此爾。封府庫，閉宮室，竟回霸上。召集父老豪傑，慨然與語道：「父老苦秦苛法，不為不久，誹謗受族誅，偶語便棄市，使諸父老痛苦至今，如何得為民上？今我奉懷王命令，伐暴救民，懷王曾有約語，先入秦關，便可稱王，今我已入關中，當為秦王。從此與諸父老等約法三章：殺人處死，傷人及盜抵罪，外如亡秦苛法，一律除去，凡官吏人民，統可安枕，不必驚惶，我所以還軍霸上，不過待別軍到來，共定約束，餘無他意。」父老豪傑，當然心喜，拜謝而去。沛公即傳令大小三軍，不得騷擾居民，違令立斬。又使人會同秦吏，安撫郡縣，秦民歡欣鼓舞，惟恐沛公不為秦王，沛公因在霸上駐紮，聽候項羽消息。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-011', 'bashang', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-012', '前漢演義', 19, 206, '第19回·繫於「新安坑卒」', '', 12, 'narrative', 'event_keyword', '[]'::jsonb, '項羽自收服章邯，由東入西，行至新安，驀聞秦兵有謀變消息，又惹動項羽一片殺機。原來秦朝盛時，各處吏卒，徵調入都，往往為秦兵所虐待，此次聯同項羽，戰勝攻取，做了上手，那秦兵反為降虜，自然受著報復，被他凌辱。秦兵遂私相告語道：「章將軍無端投楚，教我等一同歸降，我等被他哄騙，自入羅網，充做各國奴隸。如楚軍得乘勝入關，我等尚得一見骨肉，死也甘心﹔否則，各國吏卒，把我等擄掠東歸，秦必殺我父母妻子，奈何奈何！」這種議論，漸漸的傳到各國軍中，各國軍將，便去告知項羽。項羽道：「我自有計！」說著，即召英布蒲將軍入帳，與他面語道：「秦兵雖然投降，聞他私下謀議，心甚不服，若我軍到了秦關，降兵不肯聽我號令，猝然生變，作為內應，我軍尚能生還麼？看來只有先行下手，夤夜圍擊，把他一並殺死，只留章邯司馬欣董翳三人，同他入秦，方可無虞。」一語殺死二十萬人，羽心何毒！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-012', 'xinan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-013', '前漢演義', 19, 206, '第19回·繫於「新安坑卒」', '', 13, 'narrative', 'event_keyword', '[]'::jsonb, '英布蒲將軍，受了面命，就去預備妥當，待到夜半，趁著月色無光，引兵出營，往襲降兵。降兵在新安城南，靠山立寨，沈沈夜睡。英布指麾部眾，把他三面圍住，單留後面山路，故意縱他逃走。又分兵與蒲將軍，令他上山伏著，待有秦兵入山，便用矢石拋發，不使遺留。蒲將軍分頭自去，英布與兵士休息片時，大約蒲將軍已可上山，乃驅動兵士，破營直入。降兵方才驚起，睡眼模糊，不知外兵從何處殺到，就是司馬欣亦未知秘計，慌忙出來，兜頭遇著英布，英布道：「君為全營統領，奈何營中謀變，尚安然睡著哩！虧得我軍已偵破逆謀，前來剿殺，君可速往項上將營，自去聲辯，免得連坐呢。」司馬欣中了布計，急覓得一馬，將身躍上，加鞭逕去。英布放出司馬欣，便將營門堵住，秦兵逃出一個，殺死一個，逃出兩個，殺死一雙。可憐秦兵前無去路，只得向後逃生，後面都是山谷，七高八低，就是日間行走，也防失足，況且天色又暗，心內又急，忙不擇路，多半墮入谷中。忽見山上火炬齊明，還道是遇著救星，誰知卻是催命使，或放箭，或擲石，一班逃兵，不受箭傷，就遭石壓。到了雞聲遠起，曙色微明，二十萬人，已經死完，簡直是一個不留了！慘乎不慘！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-013', 'xinan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-014', '前漢演義', 19, 206, '第19回·繫於「新安坑卒」', '', 14, 'narrative', 'carried', '[]'::jsonb, '英布蒲將軍，坑盡降兵，返報項羽。項羽早已接見司馬欣，好言慰諭，留置本營，自己坐待消息。及兩將復命，才得放心進兵，拔營西指。途中已無秦壘，如入無人之境，一口氣跑至函谷關，關門卻是緊閉，上面列著守卒，也是楚軍，只隨風蕩漾的旗幟，當中都有劉字寫著。羽在途中，已微聞沛公入關音信，至此見有劉字旗幟，越覺心中著忙，便仰呼守卒道：「汝等替何人守關？」守卒答道：「奉沛公令，在此守著。」羽復道：「沛公已入咸陽否？」守卒又答道：「沛公早破咸陽，現在霸上駐紮。」羽急說道：「我率大軍前來，汝等快快開關，使我入見沛公。」守卒道：「沛公有命，無論何軍，不准放入！」羽大怒道：「劉季無禮，竟敢拒我麼？」便令英布等努力攻關，自在後面監督，退後立斬。英布等揮兵猛攻，沿關駕起雲梯，冒險上登。守兵不過數千，顧左失右，顧右失左，如何禁遏得住。不到一日，便被英布等躍登關上，殺散守兵，隨即開關迎入項羽，進至戲地。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-014', 'hangu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-014', 'xianyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-014', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-015', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 15, 'narrative', 'event_keyword', '[]'::jsonb, '時已天暮，就在戲地西首，紮下營盤。這地方叫作鴻門，羽在營中設宴，大饗士卒，且與將佐商議，對付沛公。有主張決裂的，有主張從緩的，羽亦不能自決，忽來了一個使人，說是沛公左司馬曹無傷，有機密事傳報。羽即召他入帳，那人上前跪稟，謂由曹無傷差來。羽問為何事？那人道：「沛公欲王關中，用秦子嬰為相，秦宮府中一切珍寶，都想據為己有了。」羽不禁躍起，拍案大罵道：「可恨劉邦，目無他人，我明日定要滅他！」范增在旁進言道：「沛公居山東時，貪財好色，今入秦關，聞他不取財物，不近婦女，先後若出兩人，這定是具有大志，不可小覷！且增已令望氣人士，遙觀彼營，據言營上有龍虎形，迭成五彩，就是天子氣。若此時不除，還當了得！請將軍號令將士，急擊勿失！」增既知有天子氣，應該捨此就彼，才算智士，奈何尚欲逆天行事呢？羽悍然道：「我破一劉邦，如摧枯朽，有何難處！今日大眾飲宴，時又昏夜，且讓他活著一宵，明晨進擊便了。」說罷，遣回來使，囑他還報曹無傷，明日進兵，請作內應，來使應聲自去。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-015', 'hongmen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-016', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 16, 'narrative', 'event_keyword', '[]'::jsonb, '看官聽說！項羽有眾四十萬，號稱百萬，氣燄無比。沛公只有兵十萬人，比那項羽部下，四成中僅得一成。並且鴻門霸上，相距止四十里，又沒有甚麼險阻，羽兵一發即至，如何遮攔？眼見得一強一弱，一眾一寡，沛公生死關頭，就在旦夕間了。那知人有千算，天教一算，天意已屬沛公，當然有救星出現，化險為夷。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-016', 'hongmen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-019-016', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-017', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 17, 'aside', 'carried', '[]'::jsonb, '到底天心是好生，雲龍獨護沛公營，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-018', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 18, 'aside', 'carried', '[]'::jsonb, '任他亞父多謀算，怎及蒼穹視聽明？');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-019', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 19, 'aside', 'carried', '[]'::jsonb, '欲知何人往救沛公，下文自當說明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-019-020', '前漢演義', 19, 206, '第19回·繫於「鴻門宴」', '', 20, 'commentary', 'carried', '[]'::jsonb, '子嬰不動聲色，能誅趙高，未始非英明主﹔假使秦尚可為，子嬰得在位數年，興利除害，救衰起弊，則秦亦不至遽亡。然如始皇之暴虐，二世之愚頑，豈尚得傳諸久遠？子嬰不幸，為始皇之孫，賢而失位，且為項羽所殺，祖宗不善，貽禍子孫，報應其果不爽歟！項羽以暴易暴，坑死秦降卒二十萬人，無道若此，寧能久存？沛公雖弱，獨能除暴救民，約法三章，且財物無所取，婦女無所幸，一變至道，天命攸歸，項羽豈能加害乎？范增於項羽之暴，並不進諫，且激項羽之怒，欲害沛公。人謂其智，吾謂其愚，如增者何足道焉！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-001', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說項羽有個叔父，叫做項伯，為楚左尹。他在秦朝時候，因怒殺人，自知不免死罪，逃往下邳，幸虧遇著張良，與他同病相憐，引同居處，方得避禍。嗣是記念舊恩，常欲圖報，時正在項羽營中，聞知范增計策，不免為張良擔懮。暗思沛公被攻，與我無涉，惟張良跟著沛公，一同受禍，豈不可惜！當下乘夜出營，單騎加鞭，直至沛公營前，求見張良。好在沛公營內，聞得項羽入關，駐紮鴻門，也恐他夜來襲擊，所以格外戒嚴，不敢安睡。張良也憑燭坐著，聽說項伯來會，料有密事，急忙出迎。項伯入見張良，即與悄語道：「快走快走！明日便要遇禍了！」良驚問原委，由項伯略述軍情。良沈吟道：「我不能急走！」項伯道：「同死何益，不如隨我去罷！」良又道：「我為韓王送沛公，沛公今有急難，我背地私逃，就是不義。君且少坐，待我報知沛公，再定行止。」說著，抽身便去，項伯禁止不住，又未便擅歸，只好候著。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-001', 'hongmen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-002', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 2, 'narrative', 'carried', '[]'::jsonb, '張良匆匆入沛公營，可巧沛公亦尚未寢，即向沛公說道：「明日項羽要來攻營了！」沛公愕然道：「我與項羽並無仇隙，如何就來攻我？」良答道：「何人勸公守函谷關？」沛公道：「鯫生前來語我！鯫生即小生，或謂姓鯫。謂當派兵守關，毋納諸侯，方可據秦稱王。我乃依議照行，莫非我誤聽了麼？」自知有誤，便是聰明。良便問道：「公自料部下士卒，能敵項羽否？」沛公徐說道：「只怕未必。」良接口道：「我軍只十萬人，羽軍卻有四十萬，如何敵得！今幸項伯到此，邀良同去，良怎敢負公？不得不報。」沛公頓足道：「今且奈何？」良又道：「看來只好情懇項伯，叫他轉告項羽，只說公未嘗相拒，不過守關防盜，請勿誤會。項伯乃是羽叔，當可止住羽軍。」沛公道：「君與項伯何時相識？」良答道：「項伯嘗殺人坐罪，由良救活，今遇著急難，故來告良。」沛公道：「比君少長如何？」良答言項伯年長。沛公道：「君快與我呼入項伯，我願以兄禮相事。如能代為轉圜，決不負德！」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-002', 'hangu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-003', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 3, 'narrative', 'carried', '[]'::jsonb, '良乃出招項伯，邀他同見沛公。項伯道：「這卻未便。我來報君，乃是私情，怎得逕見沛公？」良急說道：「君救沛公，不啻救良，況天下未定，劉項二家，如何自相殘殺？他日兩敗俱傷，與君亦屬不利，故特邀君入商，共議和平。」娓娓動人。項伯尚要推辭，再經良苦勸數語，方偕良入見沛公。沛公整衣出迎，延他上坐，一面令軍役擺出酒肴，款待項伯，自與良慇懃把盞，陪坐一旁。酒至數巡，沛公開言道：「我入關後，秋毫不敢私取，封府庫，錄吏民，專待項將軍到來。只因盜賊未靖，擅自出入，所以遣吏守關，不敢少忽，何嘗是拒絕將軍？願足下代為傳述，但言我日夜望駕，始終懷德，決無二心。」項伯道：「君既見委，如可進言，自當代達。」張良見項伯語尚支吾，又想出一法，問項伯有子幾人，有女幾人？想入非非。項伯一一具答，良乘間說道：「沛公亦有子女數人，好與伯結為姻好。」沛公畢竟心靈，連忙承認下去。項伯尚是遲疑，托詞不敢攀援，良笑說道：「劉項二家，情同兄弟，前曾約與伐秦，今得入咸陽，大事已定，結為婚姻，正是相當，何必多辭！」好一個撮合山。沛公聞言遽起，奉觴稱壽，遞與項伯，項伯不好不飲，飲盡一觴，也酌酒相酬。良待沛公飲訖，即從旁笑談道：「杯酒為盟，一言已定，他日二姓諧歡，良亦得叨陪喜席。」項伯沛公，亦皆歡洽異常，彼此又飲了數杯。項伯起身道：「夜已深了，應即告辭。」沛公復申說前言，項伯道：「我回去即當轉告，惟明日早起，公不可不來相見！」沛公許諾，親送項伯出營。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-003', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-004', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 4, 'narrative', 'carried', '[]'::jsonb, '項伯上馬亟馳，返入本營，差不多有三四更天氣了。營中多已就寢，及趨入中軍，見項羽還是未睡，因即進見。羽問道：「叔父何來？」項伯道：「我有一故友張良，前曾救我生命，現投劉季麾下，我恐明日往攻，破滅劉季，良亦難保，因此往與一言，邀他來降。」項羽素來性急，即張目問道：「張良已來了麼？」項伯道：「良非不欲來降，只因沛公入關，未嘗有負將軍，今將軍反欲加攻，良謂將軍未合情理，所以不敢輕投，竊恐將軍此舉，未免有失人心了。」羽憤然道：「劉季乘關拒我，怎得說是不負？」項伯道：「沛公若不先破關中，將軍亦未能驟入，今人有大功，反欲加擊，豈非不義！況沛公守關，全為防備盜賊起見，他卻財物不敢取，婦女不敢幸，府庫宮室，一律封鎖，專待將軍入關，商同處置，就是降王子嬰，也未嘗擅自發落。如此厚意，還要遭擊，豈不令人失望麼？」力為沛公解說，全是張良之力。羽遲疑半晌，方答說道：「據叔父意見，莫非不擊為是？」項伯道：「明日沛公當來謝罪，不加好為看待，借結人心。」羽點頭稱是。項伯方才退出，略睡片刻，便即天曉。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-005', '前漢演義', 20, 206, '第20回·繫於「子嬰降，約法三章」', '', 5, 'narrative', 'event_keyword', '[]'::jsonb, '營中將士，都已起來，吃過早餐，專候項羽命令，往擊沛公。不料羽令未下，沛公卻帶了張良樊噲等人，乘車前來。到了營前，即下車立住，先遣軍弁通名求謁。守營兵士，入內通報，項羽即傳請相見，沛公等走入營門，見兩旁甲士環列，戈戟森嚴，繞成一團殺氣，不由的忐忑不安。獨張良神色自若，引著沛公，徐步進去。既至中軍營帳，始讓沛公前行，留樊噲守候帳外，自隨沛公趨入。項羽高坐帳中，左立項伯，右立范增，待沛公已到座前，才把身子微動，總算是迓客的禮儀。沛公身入虎口，不能不格外謙恭，便向羽下拜道：「邦未知將軍入關，致失迎謁，今特踵門謝罪。」羽冷笑道：「沛公亦自知罪麼？」沛公道：「邦與將軍，同約攻秦，將軍戰河北，邦戰河南，雖是兩路分兵，邦卻遙仗將軍虎威，得先入關破秦。為念秦法暴酷，民不聊生，不得不立除苛禁，但與民約法三章，此外毫無更改，靜待將軍主持，將軍不先示邦，說明入關期間，邦如何得知？只好派兵守關，嚴備盜賊。今日幸見將軍，使邦得明心跡，尚復何恨？惟聞有小人進讒，使將軍與邦有隙，這真是出人意外，還求將軍明察！」這一席話，想是張良教他。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-006', '前漢演義', 20, 206, '第20回·繫於「子嬰降，約法三章」', '', 6, 'narrative', 'carried', '[]'::jsonb, '項羽本是個粗豪人物，胸無城府，喜怒靡常，一聞沛公語語有理，與項伯所說略同，反覺自己薄情，錯恨沛公。因即起身下座，握沛公手，和顏直告道：「這是沛公左司馬曹無傷，使人來說，否則籍何至如此！」沛公復婉言申辯，說得項羽躁釋矜乎，歡暱如舊，便請沛公坐下客位。張良亦謁過項羽，侍立沛公身旁。羽在主位坐定，命具酒肴相待，才閱片時，已將筵宴陳列，由羽邀沛公入席。沛公北向，羽與項伯東向，范增南向，各就位次坐定，張良西向侍坐，帳外奏起軍樂，大吹大打，侑觴勸酒。沛公素來善飲，至此卻提心吊膽，不敢多喝。羽卻真情相勸，屢與沛公賭酒，你一杯，我一觥，正在高興得很。偏范增欲害沛公，屢舉身上所佩玉玦，目示項羽。一連三次，羽全然不睬，盡管喝酒。增不禁著急，托詞趨出，召過項羽從弟項莊，私下與語道：「我主外似剛強，內實柔懦，沛公自來送死，偏不忍殺他，我已三舉玉玦，不見我主理會，此機一失，後患無窮。汝可入內敬酒，借著舞劍為名，刺殺沛公，我輩才得安枕了！」何苦逞刁。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-007', '前漢演義', 20, 206, '第20回·繫於「子嬰降，約法三章」', '', 7, 'narrative', 'carried', '[]'::jsonb, '項莊聽罷，遂撩衣大步，闖至筵前。先與沛公斟酒，然後進說道：「軍中樂不足觀，莊願舞劍一回，聊助雅興。」羽也不加阻，一任項莊自舞。莊執劍在手，運動掌腕，往來盤旋。良見莊所執劍鋒，近向沛公，慌忙顧視項伯。項伯已知良意，也起座出席道：「劍須對舞方佳。」說著，即拔劍出鞘，與莊並舞，一個是要害死沛公，一個是要保護沛公，沛公身旁，全仗項伯一人擋住，不使項莊得近，因此沛公不致受傷。但沛公已驚慌得很，面色或紅或白，一刻數變。張良瞧著，亦替沛公著急，即托故趨出帳外。見樊噲正在探望，便與語道：「項莊在席間舞劍，看他意思，欲害沛公。」噲躍起道：「依此說來，事已萬急了！待我入救罷！」張良點首。噲左手持盾，右手執劍，闖將進去。帳前衛士，看了樊噲形狀，還道他要去動武，當然出來攔住。噲本來力大，再加此時拚出性命，不管甚麼利害，但向前亂撞亂推，格倒衛士數人，得了一條走路，竟至席前，怒髮上衝，瞋目欲裂。項莊項伯，見有壯士突至，都停住了劍，呆呆望著。項羽倒也一驚，便問噲道：「汝是何人？」噲正要答言，張良已搶步趨入，代噲答道：「這是沛公參乘樊噲。」項羽隨口贊道：「好一個壯士！可賜他巵酒彘肩。」左右聞命，便取過好酒一斗，生豬蹄一隻，遞與樊噲。噲橫盾接酒，一口喝乾，復用刀切肉，隨切隨食，頃刻亦盡。屠狗英雄，自然能食生肉。乃向羽拱手稱謝。項羽復問道：「可能再飲否？」噲朗聲答道：「臣死且不避，巵酒何足辭！」羽又問道：「汝欲為誰致死？」噲正色道：「秦為無道，諸侯皆叛，懷王與諸將立約，先入秦關，便可稱王。今沛公首入咸陽，未稱王號，獨在霸上駐紮，風餐露宿，留待將軍，將軍不察，乃聽信小人，欲殺功首，這與暴秦何異？臣竊為將軍不取呢！惟臣未奉傳宣，遽敢突入，雖為沛公訴枉而來，究竟是冒瀆尊嚴，有乾禁令，臣所以謂死且不避，還請將軍鑒原！」羽無言可答，只好默然。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-007', 'xianyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-007', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-008', '前漢演義', 20, 206, '第20回·繫於「子嬰降，約法三章」', '', 8, 'narrative', 'carried', '[]'::jsonb, '張良又目視沛公，沛公徐起，偽說如廁，且叱樊噲出外，不必在此絮聒。噲因即隨同出帳。既至帳外，張良也即出來，勸沛公速回霸上，勿再停留。沛公道：「我未曾辭別，怎得遽去？」張良道：「項羽已有醉意，不及顧慮，公此時不走，尚待何時？良願代公告辭。惟公隨身帶有禮物，請取出數件，留作贈品便了。」沛公乃取出白璧一雙，玉鬥一雙，交與張良，自己另乘一馬，帶了樊噲，及隨員三人，改從間道行走，馳回霸上。獨張良一人留著，遲遲步入，再見項羽。真好大膽。羽據席坐著，但覺得醉眼朦朧，似寐非寐，好一歇方才旁顧道：「沛公到何處去了？如何許久不回！」他已去遠，不勞費心。良故意不答。項羽因使都尉陳平，出尋沛公。既而陳平入報，謂沛公車從尚在，只沛公不見下落。羽乃問張良道：「沛公如何他去？」良答道：「沛公不勝酒力，未能面辭，謹使良奉上白璧一雙，恭獻將軍，還有玉鬥一雙，敬獻范將軍！」說著，即將白璧玉鬥取出，分頭獻上。項羽瞧著一雙白璧，確是光瑩奪目，毫無瘢點，不由的心愛起來，便即取置席上，且顧問張良道：「沛公現在何處？」良直說道：「沛公自恐失儀，致被將軍督責，現已脫身早去，此時已可還營了。」羽愕問道：「為何不告而去？」良又道：「將軍與沛公情同兄弟，諒不致加害沛公﹔惟將軍部下，或與沛公有隙，想將沛公殺害，嫁禍將軍。將軍今日，初入咸陽，正應推誠待人，下慰物望，為何要疑忌沛公，陰謀設計？沛公若死，天下必譏議將軍，將軍坐受惡名，諸侯樂得獨立。譬如卞莊刺虎，一計兩傷，沛公不便明言，只好脫身避禍，靜待將軍自悟。將軍英武天縱，一經返省，自然瞭解，豈尚至責備沛公麼？」好似為項羽畫策，妙甚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-008', 'bashang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-008', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-009', '前漢演義', 20, 206, '第20回·繫於「子嬰降，約法三章」', '', 9, 'narrative', 'carried', '[]'::jsonb, '項羽躁急多疑，聽了張良說話，反致疑及范增，向他注視。增因計不得行，已是說不出的懊惱，再見項羽顧視，料他起了疑心，禁不住怒上加怒，氣上加氣，當即取過玉鬥，擲置地上，拔劍砍破，且目視項莊，恨恨說道：「唉！豎子不足與謀！將來奪項王天下，必是沛公，我等將盡為所虜哩！」項羽見增動怒，不欲與較，起身拂袖，向內竟入。范增等也即趨出，只項伯張良，相顧微笑，徐徐引退。到了營外，良謝過項伯，召集隨從人員，一逕回去。是時沛公早回霸上，喚過左司馬曹無傷，責他賣主求榮，罪在不赦。無傷不能抵賴，垂首無言，當被沛公喝令推出，梟首正法。待張良等還營報聞，沛公喜懼交並，且再駐紮霸上，徐作計較。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-009', 'bashang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-010', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 10, 'narrative', 'event_keyword', '[1]'::jsonb, '過了數日，項羽自鴻門入咸陽，屠戮居民，殺死秦降王子嬰，及秦室宗族，所有秦宮婦女，秦庫貨幣，一古腦兒劫取出來，自己收納一半，餘多分給將士。最可怪的是將咸陽宮室，付諸一炬，無論什麼信宮極廟，及三百餘里的阿房宮，統共做了一個火堆。今日燒這處，明日燒那處，煙燄蔽天，連宵不絕，一直過了三個月，方才燒完。可憐秦朝數十年的經營，數萬人的構造，數萬萬的費用，都成了眼前泡影，夢裡空花！秦固無謂，項羽尤覺無謂。羽又令兵士三十萬名，至驪山掘始皇墓，收取壙內貨物，輸運入都，足足搬了一月。只剩下一堆枯骨，聽他拋露，此外搜刮淨盡，毫不遺留。厚葬何益。本來咸陽四近，是個富庶地方，迭經秦祖秦宗，創造顯庸，備極繁盛。此次來了一個項羽，竟把他全體殘破，弄得流離滿目，荒穢盈途。羽為了一時意氣，任意妄行，及見咸陽已成墟落，也覺沒趣，不願久居，便欲引眾東歸。適有韓生入見，勸羽留都關中，且向羽說道：「關中阻山帶河，四塞險阻，地質肥饒，真是天府雄國，若就此定都，便好造成霸業了。」羽搖首道：「富貴不歸故鄉，好似衣錦夜行，何人知曉？我已決計東歸哩！」韓生趨出，顧語他人道：「我聞裡諺有言，楚人沐猴而冠，今日果然相驗，才知此言不虛了。」那知為了這語，竟有人傳報項羽，羽即命將韓生拿到，剝去衣服，擲入油鍋，用了烹燔的方法，把韓生炙成燒烤。看官試想，慘不慘呢！羽之暴且過亡秦。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-010', 'hongmen', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-010', 'xianyang', 4);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-011', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 11, 'narrative', 'carried', '[]'::jsonb, '羽既烹韓生，便想起程，轉思沛公尚在霸上，我若一走，他便名正言順的做了秦王，如何使得？看來不如報知懷王，請他改過前約，方好將沛公調徙遠方，杜絕後患。於是派使東往，囑他密請懷王，毋如前約。待使人去後，眼巴巴的望著復報，好容易盼到回音，乃是懷王不肯食言，仍將如約二字，作了復書。羽頓時動惱，召集諸將與議道：「天下方亂，四方兵起，我項家世為楚將，所以權立楚後，仗義伐秦。但百戰經營，全出我叔姪兩人，及將相諸君的勞力。懷王不過一個牧豎，由我叔父擁立，暫畀虛名，毫無功業，怎得自出主見，分封王侯？今我不廢懷王，也算是始終盡道，若諸君披堅執銳，勞苦三年，怎得不論功行賞，裂土分封？諸君可與我同意否？」諸將皆畏項羽，且各有王侯希望，當然齊聲答應，各無異詞。項羽又道：「懷王究係我主子，應該尊他帝號，我等方可為王為侯。」何必尊牧兒為帝，不如廢去了他，較為直捷。眾又同聲稱是。羽遂決稱懷王為義帝，另將有功將士，按次加封。惟第一個分封出去，已覺有些為難，先不免躊躇起來。正是：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-011', 'bashang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-012', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 12, 'aside', 'carried', '[]'::jsonb, '隻手難遮天下目，分封要費個中思。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-013', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 13, 'aside', 'carried', '[]'::jsonb, '畢竟項羽欲封何人，須待躊躇，小子且暫停一停，俟至下回發表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-020-014', '前漢演義', 20, 206, '第20回·繫於「鴻門宴」', '', 14, 'commentary', 'carried', '[]'::jsonb, '沛公身入鴻門，為生平罕有之危機，項羽令焚秦宮，為史冊罕有之大火，於此見劉項之成敗，即定楚漢之興亡，鴻門一宴，沛公已在項氏掌握，取而殺之，反手事耳。乃有項伯為之救護，有張良樊噲為之扶持，卒使項羽不能逞其勇，范增不能施其智，雖曰人事，豈非天命！天不欲死沛公，羽與增安得而殺之？若羽之焚秦宮，愚頑實甚，秦宮之大，千古無兩，材料無不值錢，散給民生，正足嘉惠黎庶，焚之果何為者？武王滅紂，不聞舉紂宮而盡焚之，越王沼吳，又不聞舉吳台而盡焚之，羽果何心，付諸一炬？甚且殺子嬰，屠咸陽，掘始皇塚，烹韓生，以若所為，求若所欲，安往而不敗亡耶？秦之罪上通於天，羽且過之，故秦尚能傳至二世，而羽獨及身而亡。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-020-014', 'hongmen', 2);
