INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-001', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說項羽欲分封諸將，想了多時，自己不能決定，只好仍請范增商議。范增雖為了鴻門一役，有些懊惱，但總不忍遽去，尚為項氏效忠。血氣既衰，戒之在得，增何不三復斯言，潔身早去。既聞項羽召請，便即入帳相見。項羽與增密議道：「我欲按功加封，別人都不難處置，只有劉季一人，封他何處，請君為我一決。」增答道：「將軍不殺劉季，實是錯著，今日又把他加封，是更留遺患了。」項羽道：「他未嘗有罪，無故殺他，必致人心不服，且懷王又欲照原約，種種為難，君亦應該諒我。並非我不肯從君！」增又答道：「既經如此，不如封他王蜀，蜀地甚險，易入難出，秦時罪人，往往發遣蜀中，便是此意。且蜀亦關中餘地，使為蜀王，也好算是依照舊約了。」項羽點首稱善。增又道：「章邯、司馬欣、董翳三人，皆秦降將，最好令他分王關中，使他阻住蜀道，他必感恩效力，堵截劉季，就是將軍東歸，亦可無虞。後來偏不如所料，奈何！羽喜說道：「此計甚妙，應即照行。」說罷，復與增妥議各將封地，及所有名稱，一一決定，增始退出。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-021-001', 'hongmen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-002', '前漢演義', 21, 206, '第21回·繫於「還定三秦（陳倉）」', '', 2, 'narrative', 'event_keyword', '[]'::jsonb, '適由沛公遣人探信，至項伯處詳問一切，項伯已聞項羽定議，封沛公為蜀王，乃即告知大略。來人忙去回報沛公，沛公大怒道：「項羽無禮，竟敢背約麼？我願與他決一死戰。」樊噲周勃灌嬰等，亦皆摩拳擦掌，想去廝殺。獨蕭何進諫道：「不可，不可！蜀地雖險，總可求生，不至速死。」沛公道：「難道去攻項羽，便至速死麼？」蕭何道：「彼眾我寡，百戰百敗，怎能不死？湯武嘗服事桀紂，無非因時機未至，不得不因屈求伸。今誠能先據蜀地，愛民禮賢，養精蓄銳，然後還定三秦，進圖天下，也未為遲哩。」沛公聽了，怒氣稍平，因轉問張良。良亦如蕭何言，但請沛公厚賂項伯，使他轉達項羽，求漢中地。為暗渡陳倉伏案。沛公乃取出金幣，派人遣遺項伯，乞將漢中地加封。項伯已陰助沛公，且有金幣可取，樂得代為說情。項羽竟依了項伯，把漢中地加給沛公，且改封沛公為漢王。於是頒發分封諸王的命令，列記如下：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-021-002', 'nanzheng', 3);
