INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-003', '前漢演義', 21, 206, '第21回·繫於「還定三秦（陳倉）」', '', 3, 'narrative', 'carried', '[]'::jsonb, '沛公為漢王，得巴蜀漢中地，都南鄭。 秦降將章邯為雍王，得咸陽以西地，都廢邱。 司馬欣為塞王，得咸陽以東地，都櫟陽。 董翳為翟王，得上郡地，都高奴。 魏王豹徙封河東，號西魏王，都平陽。 趙王歇徙封代地，仍號趙王，都代郡。 趙將張耳為常山王，得趙故地，都襄國。司馬卬為殷王，得河內地，都朝歌。 申陽張耳嬖臣先下河南迎楚。 為河南王，得河南地，都洛陽。 楚將英布為九江王，都六。 楚柱國共敖曾擊南郡有功。為臨江王，都江陵。燕王韓廣徙封遼東，改號遼東王，都無終。 燕將臧荼從楚救趙，且隨項羽入關。為燕王，得燕故地，都薊。 番君吳芮芮為英布婦翁，曾由布招芮，從羽入關。為衡山王，都邾。 齊王田市徙封膠東，改號膠東王，都即墨。 齊將田都從楚救趙，隨羽入關。為齊王，得齊故地，都臨淄。 田安故齊王建孫，下濟北數城，引兵降楚！為濟北王，都博陽。韓王成封號如舊，仍都陽翟。');
