INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-004', '前漢演義', 21, 206, '第21回·繫於「項羽分封十八王」', '', 4, 'narrative', 'event_keyword', '[]'::jsonb, '項羽自稱西楚霸王，擬還都彭城，據有梁楚九郡。一面派遣將士，迫義帝遷往長沙，定都郴地。郴音琛。郴地僻近南嶺，比不得彭地繁庶。羽欲自去建都，怎肯使義帝久住，所以將他逼徙，好似遷錮一般。另撥部兵三萬人，托詞護送沛公，即令西往就國。此外各國君臣，皆一律還鎮。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-021-004', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-005', '前漢演義', 21, 206, '第21回·繫於「項羽分封十八王」', '', 5, 'narrative', 'carried', '[]'::jsonb, '沛公既為漢王，此後敘述，應該以漢王相呼。漢王就從霸上起行，因念張良功勞，賜金百鎰，珠二斗。良拜受後，卻去轉贈項伯，並與項伯作別，還送漢王出關。就是各國將士，或慕漢王仁厚，也盡願跟隨西去，差不多有數萬人，漢王並不拒絕，一同登程。好容易到了褒中，張良意欲歸韓，即向漢王說明，漢王乃遣良東歸。兩下告別，統是依依不捨。良復請屏左右，獻上一條密計，漢王也即依從。良即拜辭而去，漢王仍然西進。不料後隊人馬，統皆喧嚷起來。當下問為何因？有軍吏入報道：「後面火起，烈燄沖天，聞說棧道都被燒斷了！」漢王絕不回顧，但促部眾西行，說是到了南鄭，再作後圖，部眾不敢違慢，只好前進。旋聞棧道為張良所燒，免不得咒罵張良，說他斷絕後路，永不使回見父老，真是一條絕計，太覺忍心。那知張良燒絕棧道，卻是寓著妙算，與庸眾思想不同。一是計給項羽，示不東歸，好教他放心安膽，不作準備﹔二是計御各國，杜絕出入，好教他知難而退，不敢入犯。當時拜別漢王，與漢王秘密定謀，便是這條計策。良之決送漢王，也是為此。漢王已經接洽，自然不致驚惶，一心一意的馳赴南鄭去了，既至南鄭，拜蕭何為丞相，此外將佐亦皆授職有差，不必細述。');
