INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-006', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 6, 'narrative', 'event_keyword', '[]'::jsonb, '惟張良拜別漢王，轉身東行，過一路，燒一路，已將棧道燒盡，方向陽翟進發，等候韓王成歸國。原來項羽入關，韓王成未曾相隨，嗣經羽進駐鴻門，號令諸王，韓王成方才往見。羽雖嫌他無功，終究是無罪可加，不得不許復舊封。只有一語相囑，叫他召回張良。及韓王成與良接洽，良亦知項羽加忌，不令事漢，所以有此要約，當時答復韓王，俟送漢王出境，然後還韓。韓王不便相強，因即應諾。偏偏項羽借口有資，責成違命縱良，將他留住，不令歸國，但使隨軍東行。成無拳無勇，怎能拗得過項羽，沒奈何跟著羽軍，出發秦關。羽把秦宮中所得金銀，及子女玉帛等類，一古腦兒載入後車，啟程東歸，到了彭城，復將韓王成貶爵，易王為侯。過了數月，索性把他殺死了事。還有燕王韓廣，不願遷往遼東，被臧荼引兵逐出，追至無終，一鼓擊死。韓廣了。乃使人報知項羽，羽不咎臧荼擅殺，反說荼討廣有功，令他兼王遼東。就是齊王田市，本由齊將田榮擁立，田榮前不願從項氏攻秦，為羽所憎，見第十六回。故羽徙封田市，改封田都田安，獨將田榮擱起不提。全是私心用事。榮秉性倔強，不服羽命，竟羈留田市，拒絕田都，待田都將到臨淄，竟發兵邀擊中途，把都殺敗，都逃往彭城。田市聞田都敗卻，恐他向羽求救，復來攻齊，因此潛身脫走、馳詣膠東。偏田榮恨他私逃，自領兵追殺田市，榮亦太覺猖狂。再西向襲擊濟北，刺死田安，便自稱齊王，並有三齊。是時彭越尚在巨野，彭越見前文。有眾萬人，無所歸屬，田榮給與將軍印綬，使他略奪梁地，越遂為榮效力，攻下數城。趙將陳餘，自去職閒游後，羈居南皮，仍然留意外務，常欲出山。陳餘事見前文，但餘既歸隱，何必再尋煩惱。他本與張耳齊名，項羽封耳為常山王，卻有人進說項羽，請封陳餘。羽因餘未嘗從軍，但封他南皮附近的三縣。餘怒說道：「餘與張耳，功業相同，今耳封常山王，餘乃只得三縣地方，充個邑侯，豈非不公！我要這三縣地何用呢？」當下使黨徒張同夏說，往見田榮道：「項羽專懷私意，不顧公道，所有部將，盡封善地，獨將舊王徙封，使居僻境，如此不公，何人肯服？今大王崛起三齊，首先拒羽，威聲遠震，東海歸心。趙地與齊相近，素為鄰國，現趙王被徙至代，也覺不平，臣餘本趙舊將，願大王撥兵相助，往攻常山，若得將常山攻破，仍迎趙王還國，當世為齊藩，永不背德！」田榮聽了，立即應允，因派兵往助陳餘。陳餘盡發三縣士卒，會同齊兵，星夜馳擊常山。張耳未曾預防，倉猝拒敵，竟被殺敗，向西遁走。陳餘遂迎趙王歇還國，遣還齊兵。趙王號餘為成安君，兼封代王。餘因趙王初定，不便遽離，仍然留輔趙王，但命夏說為代相，令往守代，事且慢表。');
