INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-008', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 8, 'narrative', 'carried', '[]'::jsonb, '到了項梁渡淮，為信所聞，便仗劍過從，投入麾下。梁亦不以為奇，但編充行伍，給以薄秩。至項梁敗死，又屬項羽，羽使為郎中。信屢次獻策，偏不見用，於是棄楚歸漢，從軍至蜀。漢王亦淡漠相遭，惟給他一個尋常官職，叫做連敖。連敖系楚官名，大約與軍中司馬相類。信仍不得志，未免牢騷，偶與同僚十三人，敘飲談心，到了酒後忘情，竟發出一種狂言，大有獨立自尊的志願。適被旁人聞知，報告漢王，漢王疑他謀變，即命拿下十三人，並及韓信，立委夏侯嬰監斬。嬰將眾犯驅往法場，陸續梟首，已有十三個頭顱，滾落地上。猛聽得一人狂呼道：「漢王不欲得天下麼？奈何殺死壯士！」這是命中注定，應有一番作為，故脫口而出。嬰不禁詫異，便命停斬，引那人至面前，見他狀貌魁梧，便動了憐才的念頭。及驗過斬條，乃是韓信，便問他有甚麼經略？信將腹中所藏的材具，一一吐露出來，大為嬰所歎賞。就與語道：「十三人皆死，唯汝獨存，看汝將來當為王佐，所以漏出刀下，我便替汝解免罷！」說著，遂命將信釋縛，自去返報漢王，極稱信才，不應處死，且當升官。漢王是個無可無不可的人物，一聞嬰言，即宥信死罪，命為治粟都尉。治粟都尉一官，雖比連敖加升一級，但也沒甚寵異。獨有丞相蕭何，留意人才，隨時物色。聞得夏侯嬰器重韓信，也召與共語，果然經綸滿腹，應對如流，才知嬰言不謬，即面許他為大將才。信既得何稱許，總道是相臣權重，定當保薦上去，不致長屈人下。偏偏待了旬月，毫無影響，自思漢王終不能用，不如見機引去，另尋頭路，乃收拾行裝，孑身出走，並不向丞相署內報聞。及有人見信自去，告知蕭何，何如失至寶，忙揀了一匹快馬，聳身躍上，加鞭疾馳，往追韓信。差不多跑了百餘里，才得追及，將信挽住。信不願再回，經何極力敦勸，且言自己尚未保薦，因此稽遲。信見他詞意誠懇，方與何仍回原路。既入漢都，由何稟報漢王，與漢王問答多詞，決意拜為大將。語見上文。因即命禮官選定吉日，築壇郊外。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-009', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 9, 'narrative', 'carried', '[]'::jsonb, '漢王齋戒三日，才屆吉期，清晨早起，即由丞相蕭何，帶領文武百官，齊集王宮，專候漢王出來。漢王也不便遲慢，整肅衣冠，出宮登車。蕭何等統皆隨行，直抵壇下。當由漢王下車登壇，徐步而上。但見壇前懸著大旗，迎風飄揚，壇下四圍，環列戎行，靜寂無嘩，容止不素，天公都也做美，一輪紅日，光照全壇，尤覺得旌旄變色，甲杖生威，頓令漢王心中，倍加欣慰。這是興漢基礎，應該補敘數語。丞相何也即隨登，捧上符印斧鉞，交與漢王。一班金盔鐵甲的將官，都翹首佇望，不知這顆斗大的金印，應該屬諸何人？就中如樊噲周勃灌嬰諸將，身經百戰，積功最多，更眼巴巴的瞧著，想總要輪到己身。忽由丞相何代宣王命，請大將登壇行禮，當有一人應聲趨出，從容步上。大眾眼光，無不注視，裝束卻甚端嚴，面貌似曾相識，仔細看來，乃是治粟都尉韓信，不由的出人意外，全軍皆驚！小子有詩詠道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-010', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 10, 'narrative', 'carried', '[]'::jsonb, '胯下王孫久見輕，誰知一躍竟成名﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-011', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 11, 'aside', 'carried', '[]'::jsonb, '古來將相本無種，庸眾何為色不平！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-012', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 12, 'aside', 'carried', '[]'::jsonb, '欲知韓信登壇情形，容至下回再表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-021-013', '前漢演義', 21, 206, '第21回·繫於「鴻門宴」', '', 13, 'commentary', 'carried', '[]'::jsonb, '本回敘述，可作為三杰合傳，張良之燒絕棧道，一奇也，蕭何之私追逃人，二奇也，韓信之驟拜大將，三奇也。有此三奇，而漢王能一一從之，尤為奇中之奇。乃知國家不患無智士，但患無明君，漢王雖倨慢少禮，動輒罵人，然如張良之燒棧道而不以為怪，蕭何之追逃人而不以為嫌，韓信之拜大將而不以為疑，是實有過人度量，固非齊趙諸王，所得與同日語者。有漢王而後有三杰，此良臣之所以必擇主而事也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-001', '前漢演義', 22, 206, '第22回·繫於「子嬰降，約法三章」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說韓信上登將壇，向北立著，便有樂工奏起軍樂，鳴鐃擊鼓，響遏行雲。既而弦管悠揚，變成細曲，當由贊禮官朗聲宣儀，第一次授印，第二次授符，第三次授斧鉞，俱由漢王親自交代，韓信一一拜受。漢王復面諭道：「閫外軍事，均歸將軍節制，將軍當善體我意，與士卒同甘苦，無胥戕，無胥虐，除暴安良，匡扶王業。如有藐視將軍，違令不從，盡可軍法從事，先斬後聞！」說到末句，喉嚨格外提響，故意使大眾聞知。大眾聽了，果皆失色。韓信拜謝道：「臣敢不竭盡努力，仰報大王知遇隆恩。」漢王大喜，因命信旁坐，自己亦即坐下，開口問道：「丞相屢言將軍大材，將軍究有何策，指教寡人？」信答道：「大王今欲東向爭衡，豈非與項王為敵麼？」漢王說了一個是字。信又道：「大王自料勇悍仁強，能與項王相比否？」漢王沈吟道：「寡人恐不如項王。」信應聲道：「臣亦謂大王不如項王，但臣嘗投項王麾下，素知項王行為。項王喑嗚叱咤，千人皆驚，獨不能任用良將，這乃所謂匹夫之勇，不足與語大謀。有時項王亦頗仁厚，待人敬愛，言語溫和，遇人疾病，往往涕泣分食，至見人有功，應該加封，他卻把玩封印，未肯遽授，這乃所謂婦人之仁，不足與成大事。此兩節，實不如漢王。今日項王雖稱霸天下，役使諸侯，乃不都關中，往都彭城，明明是自失地利﹔況違背義帝原約，任性妄行，甚且放逐義帝，專把私人愛將，分封善地，諸侯亦皆效尤，各將舊王驅逐，據國稱雄，試想山東諸國，倏起倏僕，爭奪不休，如何致治？且項王稱兵以來，所過地方，無不殘滅，天下多怨，百姓不親，不過眼前威勢，總要算項王最強，所以被他劫制，不敢俱叛，將來各國勢力，逐漸養足，何人肯再服項王？可見項王雖強，容易致弱。今大王誠能遵道而行，與彼相反，專任天下謀臣勇將，何敵不摧？所得天下城邑，悉封功臣，何人不服？率領東歸將士，仗義東征，何地不克？三秦諸王，雖似扼我要塞，犄角設防﹔但彼皆秦朝舊將，帶領秦士卒數年，部下死亡，不可勝計，到了智盡能索，復脅眾歸降項王，項王又起了殺心，詐坑秦降卒二十餘萬，只剩章邯司馬欣董翳三人，生還秦關。秦父老怨此三人，痛入骨髓，恨不得將三人食肉寢皮，今項王反立此三人為王，秦民當然不服，怎肯誠心歸附？惟大王首入武關，秋毫無犯，除秦苛法，與秦民約法三章，秦民無不欲大王王秦，且義帝原約，無人不知，大王被迫西行，不但大王怨恨項王，就是秦民亦無不懷憤！大王若東入三秦，傳檄可定，三秦既下，便好進圖天下了！」看似平常計議，但已如兵法所云，知己知彼，百戰百勝。漢王喜甚，即慰諭道：「寡人悔不早用將軍！今得親承指導，如開茅塞。此後全仗將軍調度，指日東征！」信復答道：「將非練不勇，兵非練不精，項王雖有敗象，終究是百戰經營，未可輕視，現須部署諸將，校閱士卒，約過旬月，方可啟行。」漢王稱善，乃與信下壇回朝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-001', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-001', 'wuguan', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-002a', '前漢演義', 22, 206, '第22回·繫於「子嬰降，約法三章」', '', 2, 'narrative', 'carried', '[]'::jsonb, '越日即由信升帳閱兵，定出軍律數條，號令帳外。大小將士，因他兵權在手，只好勉遵約束。信遂親自督操，口講指畫，如何排列陣勢，如何整齊步伐，如何奇正相生，如何首尾相應，如何可合可分，如何可常可變，種種法制，都是樊噲周勃灌嬰等人，未曾詳曉，既得韓信訓示，才知信確有抱負，不等尋常，於是相率敬畏，各聽信命。操演部曲，甫經數日，已是軍容不振，壁壘一新。乃擇定');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-002b', '前漢演義', 22, 206, '第22回·漢王元年八月', '', 2, 'narrative', 'marker', '[8]'::jsonb, '漢王元年八月吉日，出師東征。特標年月，點清眉目。是時棧道已經燒絕，不便行軍。漢王卻早由張良定計，叫他明修棧道，暗渡陳倉。當下召入韓信，問明出路，信所言適與張良相合。漢王鼓掌道：「英雄所見，畢竟略同。」遂派了兵士數百人，佯去修築棧道，自與韓信率領三軍，悄悄的出發南鄭。但使丞相蕭何居守，徵稅收糧，接濟軍餉。');
