INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-002b', 'nanzheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-003', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '時當仲秋，天高氣爽，將士等各願東歸，日夜趲程，由故道直達陳倉。雍王章邯，本奉項王密囑，堵住漢中，作為第一重門戶，平時亦派兵巡察，但恐漢王出來。不過他算差一著，總道漢王東出，必須經過棧道，棧道未曾修築，縱有千家萬馬，也難通行，所以章邯安心坐待，一些兒不加防備。旋經探卒走報，漢兵已有數百人，修理棧道，章邯微笑道：「棧道甚長，燒燬時原是容易，修築時卻是萬難，區區數百人，怎能濟事？漢王既欲東來，當時何必燒絕棧道，呆笨如此，真正可笑極了！他並不獃，你卻獃甚！既而又有人傳入邯耳，謂漢已拜韓信為大將。邯尚不知韓信為何人，復派幹員探明履歷，及返報後，聞說韓信屈身胯下，毫無志節，遂又大笑道：「胯下庸夫，也配做大將麼？漢王如此糊塗，怪不得他行為乖謬，前燒棧道，已是失策，今修棧道，又只派了數百人，看他至何年何月，方將棧道修竣哩！」嗣是愈加輕視，毫不為意。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-003', 'chencang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-003', 'nanzheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-004', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 4, 'narrative', 'event_keyword', '[8]'::jsonb, '到了八月中旬，忽有急報傳到，乃是漢兵已抵陳倉。章邯尚疑是說謊，顧語左右道：「棧道並未修好，漢兵從何處出來，難道真能插翅高飛麼？」話雖如此，但也不得不再派幹員，探聽明白。未幾果有陳倉逃兵，走至廢邱，報稱漢王親率大軍，據住陳倉，殺死戍將，不日就要進攻了。章邯才覺有些著忙，自思漢兵未經棧道，如何通路，莫非另有小徑，可出陳倉！今不如親領兵隊，前往邀擊為是。乃引兵數萬，逕赴陳倉，邀截漢軍。一路行去，但見逃兵，不見難民。原來漢兵經過的地方，絲毫不准侵掠，所以民皆安堵，不致流離。章邯將逃兵收集，急急的趕到陳倉，正值漢兵整隊東來。兩下相遇，便即交戰，漢兵是積憤已深，奮身不顧，一經對壘，好似猛虎離山，無論甚麼刀兵水火，統是不怕，只管向前殺去。章邯部下的兵士，本是懷恨未銷，勉強隸屬，怎肯為邯拚著死力，自傷生命？所以戰不多時，已經四溃。章邯只得回走，奔往好畤，漢兵從後追殺，不肯罷休。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-004', 'chencang', 6);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-005', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 5, 'narrative', 'carried', '[]'::jsonb, '究竟章邯是個慣戰人員，也不願為了一敗，甘心歇手。且看部兵喪失一半，還有一半隨著，不若回頭再戰，出敵不意，返戈奮鬥，或能轉敗為勝，亦未可知，因此號令軍中，再與漢兵賭個死活。那知韓信早已防著，囑令前驅小心追趕，免為所乘，自己居中調度，隨時策應，待至章邯還軍拚命，漢兵前隊，毫不慌亂，仍然照前廝殺，無懈可擊，邯見漢兵整肅如故，自知所謀不遂，添了一種懊惱，沒奈何支撐一陣，偏漢中軍又調出左右兩翼，策應前驅，前鋒就是樊噲，左翼主將，就是灌嬰，右翼主將，就是周勃。這三人系著名大將，夾攻一個章邯，叫邯如何抵敵！徒然斷送了許多士卒，去做一班冤死鬼。邯卻乘間溜脫，使長子平一說平為邯弟。入守好畤，自引敗卒遁還廢邱。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-005', 'nanzheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-006', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 6, 'narrative', 'carried', '[]'::jsonb, '漢軍兩獲勝仗，即進攻好畤，章平已知漢兵利害，怎敢出頭？只有召集兵民，乘城拒守。漢將樊噲等率兵圍城，竭力攻撲，約閱兩日，見城上守兵稍懈，噲即令兵士架起雲梯，督令登城。城上尚有矢石，陸續放擲，兵士未敢遽上，惱動樊噲性子，左擁盾，右執刀，首先登梯。此公慣用兩般兵器。梯級尚未畢登，那城上已是大嘩，亂放硬箭，亂擲巨石，噲竟用盾格開，覷著城上空隙，一躍而上，用刀亂掠，剁落頭顱好幾個。守兵措手不迭，再經漢兵蜂擁登城，殺散守兵，立即下城開門，放入餘軍。章平忙從後門逃出，落荒竄去。縣令縣丞，不及出奔，盡被殺死。城中百姓，無一反抗，情願降漢。漢兵不殺一民，當即平定。韓信也即入城，敘噲首功，報知漢王。漢王已封噲為臨武侯，至此復加授郎中騎將。噲與周勃灌嬰等，分徇下郿槐裡柳中諸地，俱皆略定。乘勢攻入咸陽，擊走守將趙賁。惟廢邱為章邯所守，往攻不下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-006', 'xianyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-007', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 7, 'narrative', 'carried', '[]'::jsonb, '韓信得報，親至廢邱城外，周覽地勢，已得破城方法，遂召樊噲等授以密計，囑他分頭往辦。章邯因漢兵攻城，日夜防守，很是留意。長子章平，已從好畤逃至廢邱，與乃父相助為理，竭力抵禦，所以漢兵雖盛，急切未能攻入。一日到了夜間，忽聞城中兵民，大噪起來。章邯父子，慌忙巡視，但見平地上面，水深數尺，卻不知從何處湧來。未幾水勢更漲，彷彿似萬馬奔騰，不可控遏。轉眼間竟漲至丈許，漂沒民庐，外面偏喊聲大震，駭人聽聞。章邯料不能守，急同長子平帶領家小，及所有將士，從北門水淺處衝出，奔往桃林。最奇的是章邯一走，城中水勢，便即退下。看官道是何因？原來廢邱城兩面環水，自西北流向東南，韓信令樊噲等，壅住下流，使水不得順下，水無可歸，當然泛濫，湧入城中。況當秋季水漲，奔流湍急，單靠一座城牆，如何阻得住急流。章邯名為大將，徒知浪戰，不知預防，正中了韓信的秘計。敘得明白。樊噲等既逐章邯，便將下流宣泄，水自瀉去，城中就點滴不留。漢兵陸續入城，安民已畢，復去追擊章邯，章邯父子，無路可奔，再戰再敗，章平被擒，章邯自刎而亡。始終難免一死，不若前時死於漳南，免為貳臣。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-008', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 8, 'narrative', 'carried', '[1]'::jsonb, '雍地盡為漢有，乃移兵轉攻翟塞二王。翟王董翳，塞王司馬欣，本來是章邯手下的屬將，勇武遠不及章邯。邯敗走後，曾遣人向二王求救，二王恐漢兵入境，不敢發兵救雍。及聞章邯敗死，更嚇得膽戰心驚。再加民心不服，一聞漢兵殺到，多去降漢。董翳先知不敵，向漢請降，司馬欣越加孤立，也只有低首下心，降漢了事。三秦地方，不到一月，都歸漢王，項霸王第一著計策，是完全失敗了。趙相張耳，西行入關，正值漢兵平定三秦，也即投順漢王。漢王兵力，因此益強。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-009', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 9, 'narrative', 'carried', '[]'::jsonb, '項王前聞齊趙皆叛，已是忿恨，此次又聞關中失去，三秦都為漢屬，不由的大肆咆哮，急欲西向擊漢。一面令故吳令鄭昌為韓王，牽制漢兵，一面使蕭公角率兵數千，往攻彭越。蕭公當是官號，角為蕭公名。越擊敗蕭角，項羽更為動怒，自思彭越小丑，何能為力，無非仗著田榮聲勢，有此猖狂，欲除彭越，不得不先除田榮。於是既欲攻漢，又欲攻齊。可巧來了一封書函，接過一閱，乃是張良署名。他本深忌張良，偏這番看了良書，竟要依他行事，是又墮入張良計中了。張良書中，略言漢王失職，但得收復三秦，如約即止，不再東進。惟有齊梁蠢動，連同趙國，要想滅楚等語，這明明是良為漢計，使項王北向擊齊，不急攻漢，好教漢王乘隙東來。那項王有勇無謀，竟被張良一激便動，先去攻齊。良復歸入漢，為漢王畫策東行。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-010a', '前漢演義', 22, 206, '第22回·繫於「還定三秦（陳倉）」', '', 10, 'narrative', 'carried', '[]'::jsonb, '漢王使韓庶子信領兵圖韓，許俟韓地平定後，封為韓王，信即受命去訖。張良又欲從信東去，因由漢王挽留，乃居住幕下，受封為成信侯。漢王復遣酈商等往取上郡北地，俱皆得手，再使將軍薛歐王吸，引兵前往南陽，會同王陵徒眾，東入豐沛，迎取眷屬入關。陵亦沛人，素與漢王相識，頗有膽略，漢王因陵年較長，事以兄禮。及起兵西進，路過南陽，適值陵亦集黨數千人，在南陽獨立一幟，漢王因遣人招陵，陵尚不甘居漢王下，托詞不往。至此次薛王二將，復來邀同王陵，陵聞漢王已得三秦，聲威遠著，乃決擬歸漢。且有老母在沛，正好乘此迎接，脫離危機，於是合兵東行。到了陽夏，卻被楚兵攔住，不得前進，只好暫時停駐，派人報告漢王，時已為');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-010a', 'feng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-010b', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 10, 'narrative', 'marker', '[]'::jsonb, '漢王二年了。漢王得薛王二將報告，本思即日東略，只因項王兵威未挫，正是一個勁敵，不便輕率發兵，所以大加簡閱，廣為號召，待籌足三五十萬兵馬，方好啟行。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-011', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 11, 'narrative', 'carried', '[]'::jsonb, '那項王卻已親率大眾，向齊進攻，臨行時候，徵召九江王英布，一同會師。英布獨稱病不赴，但遣偏將往會。項王也不加詰責，另有一道密囑，寄與英布，叫他即日照行，不得再違。布接著密令，明知事關重大，易受惡名，惟不好屢次違拗，開罪項王，沒奈何叫過心腹，示以項王密書，令他前去照辦。心腹將士，奉令承教，便去改扮裝束，乘了快船，急向長江上流，星夜馳去。約莫趕了數百里，望見前面有大小船隻，鼓棹西行，料知辦事目的，已在眼前，當即搶前速駛，追行數里，已得與前船相並，可巧天日已暮，夜色朦朧，一班改裝的九江兵，竟跳上前船倉中，拔出利刃，順手剁去，前船也有軍人，一時不及對敵，只好伸著頭顱，由他屠戮。還有一位身穿龍袍的主子，無從奔避，也落得一命嗚呼，死得不明不白。究竟此人為誰？就是前號懷王，後號義帝的楚王孫心。畫龍點睛。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-012', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 12, 'narrative', 'carried', '[]'::jsonb, '自從項王回都彭城，遷徙義帝，義帝不能不行。但左右群臣，依戀故鄉，未肯速徙，義帝也須整頓行李，慢慢兒的啟程。至項王將到彭城，不願再見義帝，屢使人催促西行。義帝不得已出都就道，所有從吏，陸續逃去，就是舟夫水手，也瞧不起義帝，沿途延挨，今日駛了五十里，明日駛了三十里，因此出都多日，尚不能到郴地，終被九江兵追及，假扮強盜，弒死義帝。舟中人夫，不做刀頭面，就做江中鬼。九江兵既經得手，樂得將舟中財物，搬取一空，飽載而回。途次又遇著好幾艘來船，彼此問訊，乃是衡山王吳芮，臨江王共敖。兩處遣派的兵士，也是受了項王密命，來弒義帝，及見九江兵已佔先著，不煩再進，遂各分路回去。九江兵還報英布，布自然轉達項王。項王方自喜得計，誰知被人做了話柄，反好聲罪致討了！小子有詩歎道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-012', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-013', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 13, 'aside', 'carried', '[]'::jsonb, '敢將故主弒江中，如此兇殘怎望終？');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-014', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 14, 'aside', 'carried', '[]'::jsonb, '沒道陰謀人未覺，須知翹首有蒼穹。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-015', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 15, 'aside', 'carried', '[]'::jsonb, '欲知何人聲討項羽，容待下回說明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-022-016', '前漢演義', 22, 205, '第22回·漢王二年了。', '', 16, 'commentary', 'carried', '[]'::jsonb, '不識地理者，不足以為將﹔章邯為將有年，乃於棧道以外，未知漢中之可出陳倉，是實顢頇糊塗，毫無將略，無惑乎其敗死也。漢王還定三秦，為項羽計，正宜大舉攻漢，杜其侵軼，乃因張良一書，不攻漢而攻齊，尤為誤事。良書所言，不足以欺他人，而項羽乃墮其計中，全是有勇無謀之弊。且敢冒天下之大不韙，弒義帝於江中，夫亂臣賊子，人人得誅，自羽弒義帝，為天下所不容，而漢乃得起而乘之，故羽之失道，莫甚於弒義帝，而羽之失計，亦莫過於弒義帝。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-016', 'nanzheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-022-016', 'chencang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-001', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說漢王整繕兵馬，志在東略，且聞項羽攻齊，相持未決，正好乘間出師，遂與大將韓信等，出關至陝郡。關外父老，相率歡迎，漢王傳令慰撫，眾皆喜悅，額手稱慶。河南王申陽，望風輸款，由漢王復書許降，惟改置河南郡，仍令申陽鎮守。會接韓地捷音，乃是韓庶子信擊敗鄭昌，昌窮蹙乞降，韓地大定，漢王乃實授信為韓王。鄭昌當然失位，不過做了一個韓王的屬員，苟全性命罷了。項羽第二著拒漢計謀，又復失敗。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-002', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 2, 'narrative', 'carried', '[]'::jsonb, '是時已值隆冬，雨雪紛飛，途中多阻。漢尚沿秦正朔，故雖已改年，尚在隆冬。漢王因未便遠征，重還關中，暫都櫟陽。開放秦時苑囿，令民耕作，改秦社稷為漢社稷，赦罪人，減賦稅，凡民年五十以上，具有善行，得選為三老，每鄉一人﹔復就鄉三老中，採擇一人，令為縣三老，輔助縣令丞尉，興教施仁，關中大安。待至春回寒盡，漢王乃復引兵東出，從臨晉關渡過黃河，直抵河內。河內為殷王司馬卬居守，聞知漢兵入境，不得不發兵迎敵。一場交戰，哪裡敵得過漢軍，徒折傷了好幾千人，敗回朝歌。漢將樊噲等進逼城下，麾眾圍攻，司馬卬自然督守，不敢少懈。一面遣人馳報項王，乞求援兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-002', 'yueyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-002', 'zhaoge', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-003', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 3, 'narrative', 'carried', '[]'::jsonb, '項王方攻入齊地，所向無敵，進迫城陽，齊王田榮，未嫻兵略，徒靠那一股悍氣，橫行青齊，但欲與項羽賭決雌雄。究竟強弱不同，主客懸絕，所以田榮屢戰屢敗，連城陽都不能守，只帶了殘卒數百，走入平原。平原百姓，未嘗實受榮惠，榮反叫他輸糧納芻，不准遲延，頓時惱動眾意，糾合至萬餘人，圍住田榮，榮手下只敵百殘兵，如何抵擋，眼見得眾怒難犯，坐被那平原百姓，擊斃了事。軍閥家其鑒諸。項王乘勢直入，縱兵焚殺，毀城郭，壞庐舍，坑死降兵，拘系老弱婦女，一些兒沒有仁恩。惟復立田假為齊王，總算不絕齊後。田假為榮所逐，亡入楚軍，事見前文。齊人不願奉假，情願擁戴田榮弟田橫，橫得收集餘燼，得眾數萬，逐走田假，再據城陽。假又走入楚營，項王說他庸弱無才，不能自立，索性賞他一刀，結果性命，自領兵猛撲城陽，總道田橫新立，容易鏟滅，誰知田橫卻得人心，合力拒守，齊人又皆憚羽凶威，自知難免一死，不如拚出性命，堅持到底，因此楚兵雖盛，終不能攻破城陽，項王又未肯捨去，總想把城陽蕩平，方足泄恨。接連數旬，仍然相持不下。及河內求救，不過分撥將士若干名，作為援應，且令使人先歸，虛張聲勢，但言楚軍將移動全隊，來援朝歌。只是誤事。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-003', 'zhaoge', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-004', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 4, 'narrative', 'carried', '[]'::jsonb, '司馬卬得了複音，越覺抖擻精神，乘城拒敵，忽見漢兵逐漸撤圍，一日一夜，竟皆撤盡，不留一人。他想漢兵無故退去，定由項王親自到來所以致此，此時正好追擊一陣，乾些功勞。遂不待躊躇，立率城中將士，開門追趕。約跑了五六十里，未見動靜，天色卻已薄暮，四面又盡是山林，司馬卬也防有埋伏，吩咐收兵。道言未絕，林中一聲炮響，閃出兩員漢將，各帶精兵，來攻司馬卬。司馬卬不敢戀戰，往後便退，部眾慌亂，多半棄甲拋戈，隨卬奔回。卬策馬先奔，只恐漢兵趕來，恨不得一步入城，好容易到了城下，突遇一猛將據住吊橋，大聲喝道：「司馬卬往哪裡走？快快下馬受縛，免得一死！」卬魂飛天外，欲想竄避，又慮後面追兵到來，越覺難敵。沒奈何硬著頭皮，挺槍與戰，才經三合，已被猛將用刀格槍，輕舒左臂，把卬擒住，及卬眾奔還，卬已早作俘囚。又經猛將厲聲呼降，還有何人再敢交鋒，落得匍匐橋邊，乞降求生。究竟這猛將是誰？就是漢先鋒樊噲，還有埋伏林中的兩將，就是周勃灌嬰，這三將分頭伏著，都是韓信所授的密計。他料司馬卬敗還城中，必向項王外求援，倘或援兵驟至，裡應外合，反不勝防，因特用了誘敵的方法，佯為撤圍，使樊噲退伏城隅，周勃灌嬰退伏林間，專誘司馬卬來追，便好前後截殺，把他擒捉，果然司馬卬貪功中計，被樊噲活捉到手，獻至漢王面前。漢王令即解縛，慰諭數語，卬拜伏地上，自稱願降，當由漢王帶領將士，偕卬入城，城中兵民，見卬已歸順漢王，自然全體投誠。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-005', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 5, 'narrative', 'carried', '[]'::jsonb, '漢兵復出略修武，適有一美貌丈夫，前來投謁，當由軍吏問過姓名，便是楚都尉陳平，名見前文。自稱陽武縣人，與漢王部將魏無知，素來相識。至說明履歷，即有人入報魏無知，無知便出營迎入。班荊道故，相得益歡，且為陳平設宴接風，私下問道：「聞足下已事項王，為何今日到此？」陳平道：「險些兒不能見君，還虧平具有小智，方得脫險前來。」無知驚問原因，陳平道：「平自往事項王，受官都尉，雖未得項王寵信，卻還不見薄待。前因殷王司馬卬，謀叛項王，項王遣平往討，平不欲勞兵，只與殷王說明利害，殷王總算謝罪了事。平還報項王，項王卻賜平金二十鎰。近日漢王攻殷，由項王撥兵救應，行至中途，聞殷王已經降漢，因即折回。項王見救兵還營，問明情形，登時大怒，便欲將平加罪。平只好封還金印，脫身西走，是以到此。」陳平棄楚投漢，借他口中敘出，且將司馬卬前時叛楚，及楚兵救司馬卬中道折還等情，一並敘過，省卻許多轉折。無知道：「漢王豁達大度，知人善任，遠近豪傑，相率歸心。今足下棄暗投明，無知當即為薦舉，俾展大才！」陳平道：「故人高誼，很是可感，但平尚有一種危險的情事，容待說明。平逃出楚營，還幸無人知覺，得離大難。乃到了黃河，僱舟西渡，舟子卻有四五人，統是粗蠻大漢，平急不暇擇，只好下船坐著，催他速駛。偏舟子一面搖船，一面只管向我注目，還道我懷珍寶，要想謀財害命。我身旁只有一劍，並且不習武事，怎能敵得過數人？君想這般情景，豈不是危險萬分麼？」無知道：「這卻如何脫難？」平笑道：「我想舟子動疑，無非利我財物，我索性脫下衣服，赤著身體，幫他搖船。他看我空無所有，也就罷休，一到對岸，我仍將衣服穿好，付與船錢，跳上河岸，一口氣跑到此間，還算是天大的造化哩。」又借平口中自述，以見平之急智。無知道：「如足下的聰明，真是一時無兩了。」說著，復與平暢飲多時，待至日暮更深，即留平住宿營中。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-005', 'xiuwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-006', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 6, 'narrative', 'carried', '[]'::jsonb, '翌日早起，無知便往見漢王，面薦陳平。漢王遂召平入見。平從容進謁，行過了禮，未蒙漢王問及，只好站立一旁。時當午餐，漢王即顧令左右，引平至側廂就食。同席共有七人，俱是因事進見，留賜午膳，及彼此食畢，平又欲入白漢王，使中涓石奮代請，適漢王飲酒微醺，不願見平，只令他往就館中。石奮出語陳平，平答道：「臣為要事前來，今日便當詳告，不能再延。」奮因再報漢王，漢王乃復召入，問有何謀，平進言道：「大王誠欲討楚，何不乘項王伐齊時，迅速東行，搗破巢穴，若得入彭城，截彼歸路，那時楚軍心亂，容易溃散，項王雖勇，也無能為了。」漢王大喜，復問及進軍方略。平具陳路徑，瞭如指掌，說得漢王眉飛色舞，欣慰異常，便問平在楚時，受何官職？平答言曾為都尉。漢王道：「我亦任汝為都尉，何如？」平當然拜謝。漢王道：「且慢！我還要使汝參乘，兼掌護軍。」平亦即受命，再拜而出。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-006', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-007', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 7, 'narrative', 'carried', '[]'::jsonb, '帳下諸將，見陳平驟得貴官，不禁大嘩，你一言，我一語，無非說是陳平初至，心跡未明，如何得引為親近，不辨賢奸！這種私議，傳入漢王耳中，漢王不以為意，且待平加厚。這便是漢王過人處。一面整頓兵馬，指日東行。平代為部署，急切籌備，限令甚嚴。眾將故意試平，向平行賄，乞稍展限，平亦未嘗峻拒，每得賄金，往往直受不辭。於是眾將得隙攻平，並推周勃灌嬰出頭，進白漢王道：「陳平雖美如冠玉，恐徒有外貌，未具真才。臣等聞他家居時，逆倫盜嫂，今掌護軍，又多受諸將賄金，如此淫黷，實為不法亂臣，請大王熟察，毋為所惑！」漢王聽了此言，也不免疑心起來，遂召入魏無知，當面詰責道：「汝薦陳平可用，今聞他盜嫂受金，行止不端，豈不是薦舉非人麼？」無知道：「臣舉陳平，但重平才，大王乃責及行誼，實非今日要務，今日楚漢相距，全仗奇謀，不尚細行，就使信若尾生，古信士，與女子期於橋下，女子不來，水至不去，抱橋柱而死，語見《莊子》。賢如孝己，殷高宗子事親至孝，高宗惑於後妻之言，放之而死。有何效用？大王但當察平計劃，曾否可彩，不必詳究盜嫂受金等事。倘平實無智能，臣甘坐罪！」無知所言，亦未免落偏。漢王聽著，尚是半信半疑，待無知退後，又召平入責問。平直答道：「臣本為楚吏，項王不能用臣，故棄楚歸漢，沿途受盡艱難，只剩得孑然一身，來歸大王，若不受金，即無自取資，如何展策！大王今日，如以為臣言可用，不妨聽臣行事，否則原金具在，盡當輸官，請恩賜骸骨便了！」必受金，方可行事，平之言毋乃太過。漢王乃改容謝平，更加厚賜。嗣且遷任護軍中尉，監護諸將，諸將乃不敢復言。惟受金一事，平既自認不諱，毋庸擬議，獨盜嫂事關係曖昧，平不自辯，無知亦未嘗代為洗刷，迄今猶傳為疑案。其實事屬子虛，應該剖白，免致誤傳。平少喪父母，惟與兄伯同居，兄已娶妻，務農為業，獨平喜讀書，手不釋卷。兄見他誠心好學，遣使從師，情願獨身耕稼，勉力持家，但兄妻是女流見識，很滋不悅。一日陳平在家，有裡人看他面色豐腴，便戲語道：「君家素來貧乏，君食何物，乃這般豐肥？」平尚未及答，忽伊嫂遽出來對答道：「我叔有何美食，無非吃些糠粞罷了，有叔如此，不如無有！」此婦亦與漢王嫂相類，但庸婦局量，往往如此，能有幾個漂母慧眼識人？這數語明寓譏嘲，急得陳平面紅耳赤，幾乎無地自容。可巧乃兄進來，亦有所聞，怒責彼婦，說他離間兄弟，立刻休回母家。平慌忙解勸，乃兄決計不從，竟將彼婦攆逐。好一位賢兄。照此看來，嫂叔絕對不和，何有私通情事？況且陳平後來，又得了一個美妻，乃是同裡富翁張負的孫女。平不事生產，年逾弱冠，尚未娶妻，富家不肯與平聯姻，貧家亦為平所不願。適張負孫女，五次許字，五次喪夫，遂致無人過問。獨平見張宅多財，張女又貌美如花，暗暗豔羨，只苦無人替他作伐。事有湊巧，裡人舉辦大喪，浼平襄理，平先往後歸，格外出力。張負亦在喪家弔唁，見平丰儀出眾，辦事精勤，不由的大加賞識，記在胸中。嗣復往視平家，雖是陋巷貧居，門外卻有貴人車轍，當下趨回家中，召子仲與語道：「我欲將孫女嫁與陳平。」仲愕然道：「陳平系一介貧儒，邑人統笑他寒酸，不願聯姻，奈何我家獨遣女往嫁呢？」張負拈髯笑道：「世上豈有美秀如陳平，尚至長久貧賤麼！」也是別具青眼。仲尚是不欲，入問伊女，伊女卻無違言。想是平日亦見過陳平，兩心相悅之故。再經張負遣媒定約，上下相迫，任他張仲如何不樂，也只好籌辦妝奩，嫁女出門。張負又陰出財帛，給與陳平，使得諏吉成禮。平大喜過望，指日完娶。親迎這一日，張負且叮囑孫女，叫她謹守婦道，勿得倚富壓貧。孫女唯唯登輿，到了平家，青庐交拜，綠酒諧歡，可意郎君，得了如花美眷，真個是情投意合，我我卿卿，一夜夫妻百夜恩，無論甚麼外緣，總奪不去兩人恩愛，就使乃兄再娶後妻，亦不過鄉村俗女，怎及得張女纖穠，是可知盜嫂情事，定屬虛誣。自從平娶得張女，用度既充，交遊益廣，就是裡人亦另眼相待。會遇裡中社祭，公推平為社宰，分肉甚均，父老交口稱贊道：「好一個陳孺子，不愧社宰。」平聞言歎息道：「使我得宰天下，也當如分肉一般，秉公辦事呢！志趣不凡，平佐漢王定天下，後為丞相，故補敘獨詳。既而陳勝起兵，使部將周市徇魏，立魏咎為魏王，見前文。平就近往謁，得為太僕。未幾有人構平，平乃走投項羽，從羽入關，受官都尉。至此復西歸漢王，言聽計從，指揮如意，遂得與漢家三杰，並傳不朽了。這且慢表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-008', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 8, 'narrative', 'carried', '[]'::jsonb, '且說漢王傳集人馬，統率東征，渡過平陰津，進抵洛陽。途次遇一龍鍾老人，叩謁馬前，漢王詢明姓氏，乃是新城三老董公，年已八十有二。當即命他起立，問有何言？董公道：「臣聞順德必昌，逆德必亡，師出無名，如何服人？敢問大王出兵，究討何人？」漢王道：「項王不道，所以往討。」董公又道：「古語有言，明其為賊，敵乃可服，項羽原是不仁，但逆天害理，莫如弒主一事。大王前與羽共立義帝，北面臣事，今義帝被弒江中，遺骸委地，雖說江畔居民，撈屍藁葬，終究是陰靈未瞑，逆惡未彰。為後文建立義帝祠冢張本。為大王計，果欲東討項羽，何不為義帝發喪，全軍縞素，傳檄諸侯，使人人知義帝凶信，罪由項羽，然後師出有名，天下瞻仰，三王盛舉，亦不過如是了。」漢王聽說，很覺有理，遂向董公答道：「好極！好極！若非先生，寡人幾不得聞此正論了。」足愧三杰。當下欲留住董公，使參軍政。董公自稱老病，不求仕進，告辭而去。漢王乃為義帝舉哀，令三軍素服三日，分遣使人，齎著檄文，佈告各國。文中說是：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-008', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-009', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 9, 'narrative', 'carried', '[]'::jsonb, '天下共立義帝，北面事之，今項羽放殺義帝於江南，大逆無道，寡人親為發喪，諸侯皆縞素，悉發關內兵，收三河士，南浮江漢以下，願從諸侯王擊楚之殺義帝者！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-010', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 10, 'narrative', 'carried', '[]'::jsonb, '這檄文傳報各國，魏王豹復書請從，漢王當然作答，叫他發兵相助。魏王豹如約而來，惟漢使至趙，趙相陳餘，卻要漢王殺死張耳，方肯聽命。使人返報漢王，漢王不忍殺耳，偏從兵中尋出一人，面貌與耳相類，竟將他割下首級，仍遣原使持示陳餘。殺一無辜而得天下，仁者不為，漢王此舉，毋乃傷仁！餘舉首審視，已是血肉模糊，未能細辨，不過大略相似，遽以為真，因也撥兵從漢。漢得塞翟韓魏殷趙河南各路大兵，共計五十六萬人，浩浩蕩蕩，殺奔彭城。又恐項羽乘虛襲秦，特使韓信留駐河南，扼要防守，自引大兵東出。路過外黃，正值彭越進謁，報告殺敗楚將，收取魏地十餘城。見前回。漢王道：「將軍既得魏地，應該仍立魏後，魏王豹可以復位，將軍即為魏相便了。」越領命自去，漢王逕至彭城。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-010', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-011', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 11, 'narrative', 'carried', '[]'::jsonb, '彭城裡面，守兵寥寥，所有精兵猛將，都隨項王伐齊，單剩老弱數千人，留守城中，如何抵敵數十萬大兵，當下聞風遁去，聽令漢兵入城。漢兵魚貫而進，即將彭城占住，漢王攬轡徐入，檢查項王宮中，美人具在，珍寶雜陳，不由的故態復萌，就在宮中住下，朝飲醇酒，暮擁嬌娃，享受那溫柔滋味。就是部下將士，亦皆置酒高會，歡呼暢飲，快活異常。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-011', 'pengcheng', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-012', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 12, 'narrative', 'carried', '[]'::jsonb, '此時張良樊噲想亦從軍，奈何不復進諫！小子有詩歎道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-013', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 13, 'aside', 'carried', '[]'::jsonb, '樂極悲生本古箴，如何一得便驕淫！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-014', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 14, 'aside', 'carried', '[]'::jsonb, '彭城置酒尋歡夜，錦帳沈沈禍已深。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-023-014', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-015', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 15, 'aside', 'carried', '[]'::jsonb, '漢王正在縱樂，不料項王已回馬殺來。欲知兩軍勝負，且待下回敘明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-023-016', '前漢演義', 23, 205, '第23回·漢王二年了。', '', 16, 'commentary', 'carried', '[]'::jsonb, '司馬卬之反覆無常，宜為項王所痛恨，然不能責及陳平。平之說降司馬卬，已為盡職，若卬之戰敗降漢，平亦安能預料。乃項羽無端遷怒，擬加平以連坐之罰，卒使平畏罪走漢，是何異於為叢毆爵，為淵毆魚乎？漢得陳平，卒賴其六出奇計，以成王業，故本回特詳敘履歷，代為表揚。至若盜嫂一事，卻一再辨誣，所以維持風化，杜後人之口實，意至深也。然陳平主議東征，而未及縞素發喪之大義，反使新城遺老，叩馬進辭，是可知策士遺風，但尚詭謀，不知正道，王跡亡而亂賊興，綱常或幾乎息矣，得董公以規正之，未始非末流之砥柱也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-001', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說彭城溃卒，奔至城陽，往報項羽。羽聞彭城失守，氣得暴跳如雷，留下諸將攻齊，自率精騎三萬人，倍道回援。由魯地出胡陵，逕抵蕭縣。蕭縣東南，有漢兵數營扎住，本由漢王遣使防羽，營中亦不甚戒備。誰知項王夤夜到來，時正黎明，全營將士，方才睡起，竟被項王麾軍突入，任意蹂躪。漢兵除被殺外，逃避一空，項王長驅直進，奔向彭城。漢王日耽酒色，宴臥遲起，眾將亦連宵醉臥，不知早晚。忽聞楚兵已臨城下，統嚇得形色倉皇，心神慌亂。當由漢王擦開倦眼，出宮升帳，調齊大隊人馬，開城迎戰。遙見項王跨著烏騅，穿著鐵甲，當先開道，挾怒前來。一聲大吼，激成異響，已令人膽戰心寒，再加楚兵楚將，都是兇悍得很，要來與漢軍拚命，奪還家室。這般毒氣，不堪逼近，漢將亦曉得厲害，不得已向前爭鋒。戰一合，敗一合，戰十合，敗十合，那項王復親自動手，執著一竿火尖槍，左右亂搠，無人可當。突然間衝入漢陣，挑落數將，竟向漢王馬前，狂殺過來。樊噲等慌忙攔截，統不是項王對手，紛紛倒退。漢王也覺心慌，但恐項王殺到，只好拍馬返奔，才走數步，回顧大纛，已被項王槍尖撥倒。大纛為全軍耳目，一經倒地，軍士自然亂竄，漢王不暇顧及，只好落荒奔去，沒命亂跑。眾將亦各走各路，無心保護漢王。項王從後追擊，殺得昏天黑地，日色無光，漢兵都從谷泗二水旁，逃將過去，前走的自相踐踏，後走的都遭屠戮，慘死至十餘萬人。還有三四十萬人馬，南竄入山，又為楚兵所追，殺斃了好幾萬。餘眾至靈璧縣東，競渡睢水，水中溺死了許多，岸上擠落了許多，約莫有十多萬人，隨波漂積，睢水為之不流。前日喝得好酒，今日要他去吸清流了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-001', 'pengcheng', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-001', 'lingbi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-002', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '漢王逃了一程，竟被楚兵追及，圍至三匝。自顧隨身士卒，止數百騎，如何衝突得出？不禁仰天長歎道：「我今日死在此地了！」語尚未畢，忽天上狂風大作，飛砂走石，拔木揚塵，自西北吹向東南，遍地昏冥，好似夜間一般。楚兵既站立不住，又咫尺不辨爾我，只得退回。漢王乘間脫圍，覓路再走。行了數里，後面又有楚兵追來，回望楚將面目，很是熟識，便高聲呼道：「兩賢何必相厄？不若放我逃生！」說罷，又掉頭急奔，卻好後面的楚將，停住不追，竟自回去。這楚將叫做丁公，聞得漢王稱為賢人，就樂得賣個人情，收兵還營。誰知後來竟致隕首！因此漢王復得脫走。自思距家不遠，不如趁便回家，搬取老父嬌妻，免落楚兵毒手，當下馳至豐鄉，走近家門，但見雙扉緊閉，外加封鎖，禁不住吃了一驚，慌忙查問四鄰，俱雲不知去向。那時孑影徘徊，躊躇了好多時，諒想無從追尋，只好縱轡自去。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-002', 'feng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-003', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '行行復行行，倏已走了數十里，日色已經西沈，漸覺得饑寒交迫，疲乏不堪。本擬下馬休息，又恐楚兵追來，未便小憩，沒奈何垂頭喪氣，向前再走。又過了好幾里，遙聞有犬吠聲，料知前面定有村洛，及抬頭一望，果見前面有一樹林，從林隙處露出燈光，隱隱有村落出現，摹寫有致。當即策馬前進，想到村中借宿。事有湊巧，適與村內老人相遇，不得不慇懃問訊，求宿一宵。老人見漢王容止，不同凡人，因就引至家中，延令上坐，叩明姓氏，漢王也不諱言，講明實跡。老人說道：「老朽不知駕到，有失遠迎！今因裡中有喜慶事，夜宴歸來，得遇大王尊駕，不勝榮幸。」說著，便向漢王下拜。漢王忙即扶起，且轉問老人家世，老人道：「老朽姓戚，系定陶縣人，前因秦項交兵，避亂至此，當時妻子流離，俱皆喪失，現只小女隨著，權借此地寓居，亂世為人，不如太平為犬，說也可憐。」言下甚是慘沮。漢王已饑腸轆轆，急欲求食，向老人說道：「此處有無酒飯可沽？」老人道：「此地乃是僻鄉，並無市鎮，大王如不嫌簡褻，寒家尚有薄酒粗肴，可以上供。」漢王不待說畢，連忙說好。老人即傳聲入內，叫他女兒整備酒飯。約閱一時，便有一個二九佳人，攜著酒食，姍步來前，漢王瞧著，雖是衣衫樸陋，卻也體態輕盈，免不得稱羨起來。老人命女放下酒肴，便向漢王行禮。漢王起身相答，那戚女盈盈拜畢，轉身返入。老人遂與漢王酌飲，漢王連飲數觥，愁腸漸放，娓娓言情，且問戚女曾否字人。老人道：「小女尚未許字。前有相士談及，謂小女頗有貴相，今日大王到此，莫非前緣注定，應侍大王巾櫛，未知大王尊意如何？」漢王道：「寡人逃難到此，得蒙留宿，已感盛情，怎好再屈令媛為姬妾哩？」也要做作。老人道：「只怕小女不配侍奉，大王何必過謙！」漢王乃說道：「既承老丈美意，我即領情便了。」當下解交玉帶，作為聘禮。老人復喚女出拜，女腼腆出來，含羞襝衽，受了玉帶。並由老人叫她斟酒，捧獻漢王，漢王一飲而盡。至戚女斟至第二杯，漢王就命戚女酬飲，戚女也不固辭，慢慢兒的喝乾，這便算做合巹酒了。既而戚女復入內取飯，出供漢王，漢王又吃了一飽。夜色已闌，老人卻甚知趣，便令該女陪著漢王，入室安寢。漢王趁著酒興，挽女同宿。戚女年已及笄，已解雲情雨意，且終身得侍漢王，可望富貴，不如曲意順承，由他寬衣解帶，擁入衾中。兩情繾綣，一索得男，居然是結下珠胎，不虛此樂了。為生子如意張本，戚女想做妃嬪，誰知後來竟為人彘！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-003', 'dingtao', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-004', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '詰旦起牀，出見戚公，吃過早膳，漢王即欲辭行。戚公父女，苦留漢王再住數日，漢王道：「我軍敗溃，將士等不知所在，我何能在此久留？且容我往收散卒，待有大城可住，當來迎接老丈父女，決不爽約！」戚公乃不好強留，送別漢王，只有戚女格外生感，僅得了一宵恩愛，偏即要兩地分離，怎得不蹙損眉尖，依依惜別！漢王到了此時，也未免兒女情長，英雄氣短，臨歧絮語，握著戚女的柔荑，戀戀不捨。結果是硬著心腸，囑咐了一聲珍重，出門上馬，揚鞭逕去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-005', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '走了多時，忽見塵頭起處，約有數百騎馳來，他恐防是楚兵，急忙藏入林中，偷眼窺著。待來騎已近，方認得是自己人馬，當先一員將弁，不是別人，就是部將夏侯嬰。時嬰已受封滕公，兼職太僕，常奉王車。彭城一戰，嬰亦隨著，惟因戰敗以後，漢王舍車乘馬，倉皇走脫，所以與嬰相失。嬰保著空車，突出楚圍，四處找尋漢王，走了一夜有餘，方得與漢王相遇。漢王見是夏侯嬰，自然放膽出來，嬰即下馬拜見，具述經過情形，且請漢王換馬登車。漢王依了嬰言，改坐車上，由嬰跨轅隨行。沿途見有難民，紛紛奔走，就中有一幼童，一幼女，狼狽同行，屢顧車中，夏侯嬰眼光靈警，一經瞧見，似曾相識，便語漢王道：「難民中有兩個孩兒，好似大王的子女，究竟是與不是，請大王鑒察！」漢王方張目外顧，果然兩孩非別，乃是親生的子女，便命嬰叫他過來。嬰下車招呼，抱登車上，當由漢王問明情由，兩孩謂與祖父母親等，避難出奔，想來尋訪我父，途次被亂兵衝散，遂致分離，今祖父母親，已不知何處去了。漢王又驚又喜，更問及昨宵情狀，兩孩答道：「兒等已離家兩日，夜間統借宿別村。今日出門行路，偏偏撞著亂兵，祖父失散，母親等又忽然不見，幸虧遇著父親！」說到親字，淚下不止。你的父親，昨夜卻快活得很。漢王也為動容。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-005', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-006', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 6, 'narrative', 'carried', '[]'::jsonb, '正敘談間，夏侯嬰忽驚報道：「那邊有旗幟飄揚，莫非楚兵追來麼？」漢王急著道：「快走罷！」嬰也覺著忙，自至漢王車後，親為漢王推車，向前飛奔。後面果有楚兵追至，首將叫做季布，前來趕拿漢王。漢王走一程，季布追一程，一走一追，看看將及。漢王恐車重行遲，竟將子女推墮車下。夏侯嬰見了，仍然左提右挈，把兩孩抱置車中。俄而漢王又將兩孩推落，夏侯嬰再把兩孩扶載，接連有好幾次，惹得漢王怒起，顧叱夏侯嬰道：「我等危急萬分，難道還要收管兩孩，自喪性命麼？」嬰抗答道：「這是大王親生骨肉，奈何棄去？」漢王更加懊惱，拔出劍來，欲殺夏侯嬰。何以粗暴乃爾！嬰閃過一旁，見兩孩復被漢王踢下，索性令別將御車疾馳，自己伸展左右兩腋，輕輕挾住兩孩，一躍上馬，隨王走免。楚將季布，追趕不及，也只好領兵回去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-007', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '漢王見追兵去遠，稍稍放心，夏侯嬰亦策馬馳至，兩下會敘，決向下邑投奔。下邑在碭縣東，曾由漢王妻兄呂澤，帶兵駐紮。漢王與夏侯嬰挈了子女，從間道行至下邑，呂澤正派兵探望，見了漢王，當然迎入，漢王方得了一個安身的地方。已而漢將等聞王所在，陸續趨集，勢又漸振。惟調查各路諸侯消息，殷王司馬卬已經陣亡，塞王司馬欣，與翟王董翳，又復降楚。韓趙河南各路殘兵，亦皆散歸。這雖是關係不小，但尚隨合隨離，不足深恨。最關緊要的，乃是漢王父太公，及妻呂氏等人，好多日不聞音信。仔細探聽，已被楚軍擄掠去了。原來太公帶領家眷，避楚奔難，子婦孫女以外，尚有舍人審食其相從。食其亦讀為異基。大家扮做難民，鬼鬼祟祟，從僻路潛行出去，首二日還算平安，晝行夜宿，不過稍受一些辛苦。至第三日早起，又復啟行，約越數里，適來了許多楚兵，慌忙避開。偏偏楚兵隊裡，有幾個認識太公，及漢王妻呂氏，竟一哄過來，把他兩人拘住。審食其不肯捨去，也為所拘，餘皆走散。漢王僅得子女二人，所有兄弟親族，又俱未見，更聞得老父嬌妻，為敵所虜，生死未卜，忍不住號啕起來。旋經諸將解勸，勉強收淚，乃引眾轉趨碭縣，再著偵騎往探，尋問太公呂氏音信。後來接得確音，才知二人在楚軍中，尚幸未死，只項羽視為奇貨，留作抵押，要想漢王往降。漢王怎肯身入虎口，只得暫從割捨，徐圖良策。妻子可以割捨，老父亦可割捨嗎？');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-007', 'xiayi', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-008', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 8, 'narrative', 'carried', '[]'::jsonb, '過了數日，復接王陵哀報，乃是老母被掠，伏劍身亡，現願奉母遺命，事漢無二，誓報大仇云云。漢王聽著，悲喜交並，當下復書勸慰，叫他節哀順變，恊力復仇。一面啟節西行，道出梁地，復得楚軍進攻消息，且懼且忿，特召集將佐，商議退敵方法。將佐等甫經敗衄，未敢主戰，彼此相覷，不發一言。漢王勃然道：「我情願棄去關東，分授豪傑，但不知何人肯為效力，破楚立功，得享受此關東土地呢！」道言甫畢，即有一人接口道：「九江王英布，與楚有隙，彭越助齊據梁，兩人皆有大材，可以招致，使為我用。若大王部下，莫如韓信，大王果將關東土地，分給英布彭越韓信三人，彼必感激思奮，願出死力，項羽雖強，也容易破滅了。」漢王見獻計的人，就是張良，便連聲稱善，並顧問左右道：「何人能為我往說九江王，使他背楚從我？」旁有謁者隨何，謁者二字，系秦官名，漢亦仍之。挺身出應，自願前往。漢王乃派吏二千人，與何偕行，何即領命去訖。漢王復向韓彭兩軍，派使求援，自引兵由梁至虞，由虞至滎陽。滎陽為河右要衝，不得不就此扼住，阻楚西進。漢王命部眾屯駐城外，自入城中安歇。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-008', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-009', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 9, 'narrative', 'carried', '[]'::jsonb, '才閱一宵，忽來了一員將弁，素衣素服，踉蹌趨入，拜倒漢王座前，嗚咽不止。漢王急忙審視，見是沛中故友王陵，當即離座扶起，延令旁坐。陵且泣且語道：「臣與逆賊項羽，不知有何宿世冤仇，既逼我母自殺，還要將我母遺骸，付諸鼎烹，臣憤不欲生，願大王撥助雄師，與臣偕行，若不將賊羽碎屍萬段，誓不甘休！」漢王愕然道：「項羽竟這般殘忍麼？不但君欲報仇，就是我與君多年故交，亦當替君出力。況我的衰父弱妻，亦陷沒羽軍，存亡難料，怎好不前去救應？只恨我軍新敗，還須搜乘補闕，募兵添將，方好前去爭鋒，一鼓破賊。否則彼強我弱，彼眾我寡，再若一敗，不堪收拾了！」王陵仍然流涕，又由漢王慰諭一番，擬俟韓信等兵馬到來，便當出發。陵亦無可奈何，只好含淚拜謝。惟陵母也是個女中豪傑，何故自殺，何故被烹，小子應該補敘大略，表明烈婦情形。補筆斷不可少。陵母為羽所虜，羽留置軍營，脅她招降王陵，陵母不肯作書，由羽使人馳往陽夏，假傳陵母遺命，囑陵棄漢歸楚。陵料有詐謀，且亦不願降羽，乃遣歸楚使，另派心腹往楚省母，探明虛實。陵使到了彭城，無從與陵母相見，不得已進謁項羽，傳述陵言，願見陵母，羽即喚陵母出見，使他東向坐著，面諭陵使，叫陵即日來降，保全母命。陵母對著項羽面前，不便直述己見，只得支吾對付，敷衍數語。及陵使辭歸，陵母假送使為名，步出轅門。直至使人將要登車，向母拜別，陵母流淚與語道：「煩使人傳語陵兒，叫他善事漢王，漢王寬厚得民，將來必有天下，吾兒切勿顧念老婦，懷著二心，言已盡此，老婦當以死相送了。」使人尚不知陵母已具死意，還道是一時憤語，不足介懷，但說了尊體保重四字，匆匆上車。那知陵母袖中，取出一柄亮晃晃的匕首，向西叫了兩聲陵兒，便咬著牙關，把匕首向頸上一橫，喉管立斷，鮮血直噴，好一位志節高超的老母，撞倒車旁，一命歸陰去了！比漂母更高一倍。使人不及施救，並恐連害自身，疾馳而去。項羽正差人出視陵母，見了陵母言動等情，也為驚愕。至陵母已死，即刻入報，項羽大怒，喝令左右，舁入陵母屍首，擲置鼎鑊，用火一燒，頃刻糜爛，羽才算泄忿。但人已死去，烹亦何益？徒使王陵聞知，越加痛恨，這真叫做冤仇不解，越結越深呢。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-009', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-010', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 10, 'narrative', 'carried', '[]'::jsonb, '漢王專待韓信等來援，韓信果然率兵來會，還有丞相蕭何，也遣發關中守卒，無論老弱，悉詣滎陽，人數又至十餘萬。漢王大喜，遂使韓信統軍留著，阻住楚鋒，自引子女還櫟陽。韓信究竟能軍，出與楚兵連戰三次，統獲勝仗。一次是在滎陽附近，二次是在南京地方，南京系春秋時鄭京，與近今之江寧不同。三次是在索城境內，楚兵節節敗退，不敢越過滎陽。韓信復令軍士沿著河濱，築起甬道，運取敖倉儲粟，接濟軍糧，漸漸的兵精糧足，屹成重鎮。漢王到了櫟陽，連得韓信捷報，放心了一大半，遂立子盈為太子，大赦罪犯，命充兵戍。太子盈年只五歲，使丞相蕭何為輔，監守關中。且立宗廟，置社稷，一切舉措，俱委蕭何便宜行事。何慨然受命，願在關中轉漕輸粟，擔任兵餉，並請漢王仍往滎陽，督兵東討。漢王依議，乃與蕭何囑別，復東往滎陽去了。小子有詩贊蕭丞相道：');
