INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-011', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 11, 'aside', 'carried', '[]'::jsonb, '從龍帶甲入關中，轉粟應推第一功，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-012', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 12, 'aside', 'carried', '[]'::jsonb, '為語武夫休擊柱，發蹤指示孰如公？');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-013', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 13, 'aside', 'carried', '[]'::jsonb, '漢王再到滎陽，究竟如何東討，且看下回敘明。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-013', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-024-014', '前漢演義', 24, 205, '第24回·繫於「彭城之戰」', '', 14, 'commentary', 'carried', '[]'::jsonb, '漢王既入彭城，應該亟迎老父，乃耽戀美人寶貨，置酒高會，匪特不知有親，並且不知有敵，何其昏迷乃爾！睢水之敗，乃其自取，太公呂后之被擄，亦何莫非漢王致之？況孑身避難，一遇戚女，即興諧歡，父可忘，妻可棄，兄弟家族可不顧，將帥士卒可不計，而肉慾獨不可不償，漢王亦毋乃不經乎？惟當時項王暴虐，各諸侯亦不足有為，蒼蒼者天，乃不得不屬意漢王，大風之起，已有特徵。陵母以一婦人，獨能見微知著，拚死囑兒，是真一女中丈夫，非庸嫗所得同日語也。本回敘及戚姬，所以原人彘之禍，不沒陵母，所以揚彤幃之光，詳正史之所略，而懲勸之意寓於中，是亦一中壘之遺緒雲。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-024-014', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-001', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說漢王再至滎陽，與韓信會師進討，諸將皆踴躍從命，期雪前恥。獨魏王豹入白漢王，乞假歸視母疾。漢王見他始終相從，未嘗擅返，總道是存心不貳，可無他患。況且老母有病，理應歸省，遂慨然應諾，與約後期。豹訂約而去，回到平陽，遽將河口截斷，設兵扼守，叛漢聯楚。當有人報知漢王，漢王雖然懊恨，但尚以為待豹不薄，或可勸他悔悟，免致動兵。因即召過酈食其，令他往說魏豹，且與語道：「先生善長口才，若能勸豹回心，使我減去一敵，便是大功，我當撥出魏地萬戶，封賞先生！」酈生欣然領命，星夜馳往平陽，進見魏豹，仗著三寸不爛的舌根，反覆陳詞，曉諭禍福。偏魏豹毫不動情，淡淡的答說道：「人生世間，好似白駒過隙，若得一日自主，便是一日如願。況漢王專喜侮人，待遇諸侯群臣，不啻奴僕，今朝罵，明朝又罵，毫無君臣禮節，我不願與他再見了。」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-001', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-001', 'pingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-002', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '酈生說他不動，只得歸報。漢王大怒，即命韓信為左丞相，率同曹參灌嬰二將，統兵討魏。待韓信等已經出發，又召問酈生道：「魏豹竟敢叛我，想必有恃無恐，究竟他命何人為大將？」酈生道：「聞他大將叫做柏直。」漢王掀髯笑道：「柏直口尚乳臭，怎能擋我韓信，還有騎將為誰？」酈生又答是馮敬。漢王道：「敬系秦將馮無擇子，頗有賢名，惜少戰略，也不能擋我灌嬰，此外只有步將了。」酈生接入道：「叫做項它。」漢王大喜道：「這也不能擋我曹參，我可無慮了！」料事如見。遂放下愁腸，靜待韓信軍報。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-003', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '韓信等到了臨晉津，望見對岸統是魏兵，不便逕渡，乃擇地安營，趕辦船隻，與魏兵隔河相距，暗中卻派遣幹員，探察上流形勢。未幾即得探報，謂對河統有魏兵守著，惟上流的夏陽地方，魏兵甚少，守備空虛。韓信聽著，便已想得破敵的計策，先召曹參入帳，囑令引兵入山，採取木料，不論大小，盡可合用，但教從速為妙，參受令而去。繼又召入灌嬰，叫他派遣兵士，分往市中，購取瓦罌，每罌須容納二石，約數千具，即日候用，不得少延。灌嬰聽了，不禁疑訝起來，便問韓信道：「瓦罌有何用處？」韓信道：「將軍不必急問，但教依令往辦，自可建功。」嬰尚是莫明其妙，只因軍令難違，不得不如言辦理。才閱兩日，參與嬰先後繳令，各將木料瓦罌，一律辦齊。信又取出一函，交與兩人，命他自去展閱，兩人受函出帳，拆視函中，乃是叫他製造木罌。這木罌的造法，係用木夾住罌底，四圍縛成方格，把繩絆住，一格一罌，兩格兩罌，數十格即數十罌，合為一排，數千罌分做數十排。制成以後，再行請令。灌嬰道：「渡河須用船隻，現在船已漸集，何故要造這木罌？真正奇事！」故作疑幻，令人不測。曹參道：「想元帥總有妙用，我等且監督工兵，依法制就便了。」於是日夜趕造，不到數日，已將木罌制齊，因即請令定奪。韓信親自驗畢，待至黃昏，留兵數千，使灌嬰帶著，但准搖旗擂鼓，守住船隻，不得擅自渡河，違令斬首。灌嬰唯唯受教。這卻是個美差。信卻與曹參督同大兵，搬運木罌，夤夜行抵夏陽，即將木罌放入河中，每罌內裝載兵士兩三人，卻也四平八穩，不致傾覆。兵士就在罌內，用械划動，自然移去。信與曹參亦下馬就罌，一同渡河。好容易到了對岸，並皆躍登陸地，整隊前行。那魏將柏直等人，但扼住臨晉津，不使漢兵得渡。嗣聞漢兵陳船吶喊，越加小心防守，一步兒不敢他去。就是魏王豹亦注意臨晉，不及夏陽。因為夏陽平日，向無船隻，勢難徒涉，所以置諸度外，絕不過問。誰知韓信竟用木罌渡軍，無阻無礙，直至東張，才見有魏兵營盤，擋住大道。曹參拍馬舞刀，竟向魏營殺入，漢兵當然隨上。魏將孫遫，倉猝抵敵，終落得大敗虧輸，向北竄去。曹參乘勝直入，進薄安邑，守將王襄，出城迎戰，甫經數合，即被曹參賣個破綻，讓他劈來，輕身一閃，彼落空，此得勢，順手牽住絲縧，活擒下馬，擲付部軍。魏兵見主將被擒，何人再敢抵敵？或逃或降，安邑城空若無人，遂由曹參引兵占住。韓信也即進城，犒賞將士，再擬入攻魏都。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-004', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '魏都就是平陽，魏王豹居住都中，連接東張安邑敗耗，驚慌的了不得，遂差人追回柏直等軍，自率親兵出都，堵截漢軍。到了曲陽，剛遇漢軍殺來，當即擺開兵馬，與他交戰。漢軍已經深入，自知有進無退，奮不顧身，俗語說得好，一夫拚命，萬夫莫當，況大眾不下數萬，又有韓信曹參兩將帥，前後指麾，憑他如何勁敵，也是不能支持。魏王豹既無韜略，又乏精銳，眼見得有敗無勝，向北亂逃。漢兵用力追趕，馳抵東垣，復將魏豹圍住。豹冒死衝突，總不得出，韓信知豹窮蹙，傳語魏兵，叫他早降免死。魏兵棄甲投戈，都稱願降。魏豹窮極無奈，也顧不得面子，只好下馬伏地，束手受擒。卻不怕漢王辱罵麼？');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-004', 'pingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-005', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '韓信把豹囚入檻車，直抵平陽城下，便令曹參押豹出示，曉諭守兵，叫他出降。守兵瞠目伸舌，無心抵禦，樂得舉城奉獻，保全性命。韓信曹參，依次入城，下令兵民，一體赦宥，惟將魏豹家眷，盡行拿下，與豹一同系著。會值魏將柏直等引兵回援，途次聞得漢軍襲入，連破城邑，並魏王亦被擒去，統嚇得不知所為。可巧韓信著人招降，指示一條生路，大眾無法可施，沒奈何走到平陽，跪降了事。魏將全然無用，果如漢王所料。韓信召到灌嬰，令與曹參分徇魏地，各處城邑，無不歸附，魏地大定。信欲乘便擊趙，留兵不返，但將魏豹全家，悉數解往滎陽，聽候漢王發落。自請添兵三萬人，往平趙國，且言從趙入燕，從燕入齊，東北既平，方好專力擊楚，南下會師。卻是絕大計劃。漢王允如所請，立撥部兵三萬，使張耳帶去，會同韓信等擊趙。一面提入魏豹，拍案大罵，意欲將豹梟首，慌得豹匍匐座前，頭如搗蒜，乞貸死罪。虧他一張老臉皮。漢王轉怒為笑道：「量汝這等鼠子，有何能力！我今日不妨饒汝，權給汝首，汝若再有異心，族誅未遲。」豹又叩了幾個響頭，方才退出。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-005', 'pingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-005', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-006', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 6, 'narrative', 'carried', '[10]'::jsonb, '漢王又命將魏豹家眷，除老母年邁不能充役外，餘皆沒入為奴。豹妾薄姬，姿容最美，發往織室作工。後來被漢王瞧見，頗覺中意，又把她送入後宮。說將起來，這個薄姬卻與漢魏大有關係。姬母薄氏，本為魏國宗女，魏為秦滅，流落他鄉，與吳人薄姓私通，儼成夫婦，生下一女，出落得裊裊婷婷，齊齊整整。魏豹得立為王，薄女已經及笄，夤緣入宮，得為豹妾。時有河內老嫗許氏，具相人術，言無不中，世人稱為許負。負與婦通，注見前文。豹聞許負善相，特召她進來，遍相家屬。許負看到薄女，不勝驚愕道：「將來必生龍種，當為天子。」豹亦驚喜道：「可真麼？試看我面，應該如何結果。」許負笑說道：「大王原是貴相，今已為王，尚好說是未貴麼？」句中有眼。豹聽到此語，料知自己不過為王，惟得子為帝，勝如自為，倒也歡喜得很。當下厚贈許負，送她歸家，且格外寵愛薄女，幾與正室無二。就是興兵背漢，也為了許負一言，激成變志。他想有子為帝，必須由自身先立基業，方可造成帝系。若盡管臣事漢王，如何獨立，如何貽謀，所以決意叛漢，負嵎自雄。子尚未生，便作癡想，安得不敗，安得不亡。偏偏癡願難償，反致國亡家破，那相親相愛的薄家女，竟被漢王攫去，罰作宮妃。薄女也自傷薄命，身為罪人，充當賤役，始居織室，繼入漢宮，終不見有意外幸事，只得死心塌地，做個白頭宮人，便算了卻一生。那知過了年餘，竟得了一個夢兆，乃是蒼龍據腹，大驚而寤。默思此夢主何吉凶，一時也無從詳起。越宿起牀，並無征驗，遲至夜間，忽接內使宣召，叫她入侍，不得不略略整妝，前去應命。及見過漢王，在旁侍立，漢王方在酣飲，一雙醉眼，注視了好幾回，等到酒後撤肴，竟將她扯入內寢，要演那高唐故事，此時身不由主，任所欲為，到了交歡的時候，薄女始將昨宵夢兆，告知漢王。漢王道：「這是貴征，我今夕就與汝玉成了。」說也奇怪，薄女經過一番雨露，便得懷胎，十月滿足，果生一男，取名為恒，便是將來的漢文帝，只晦氣了一個魏王豹，求福得禍，一敗塗地。可見人生遇合，都有命數，切勿可過信術士，癡心妄想呢！喚醒世夢。閒話休表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-007', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '且說韓信寓居平陽，籌備伐趙，可巧張耳帶兵到來，與信會師，信遂合兵東行，進攻代郡。這伐趙的原因，係由趙相陳餘，本已出兵從漢，自漢王為楚所敗，趙兵散歸，報稱張耳尚存，頓時惱動陳餘，復與漢絕和。張耳詐死見二十三回。韓信援為話柄，責趙背漢，因此長驅攻代，直抵閼與。代為陳餘受封地，餘留輔趙王，用夏說為代相，使他居守。見二十一回。說聞漢兵已至閼與，距代城不過數十里，當即引兵出敵，與漢兵前隊相遇。漢先鋒將乃是曹參，躍馬持刀，直指夏說，說亦持刀相迎。戰了一二十合，參虛晃一刀，拍馬就走，漢兵亦返身同奔。明明是詐。說麾兵大進，迤邐追趕，約行了二十多里，忽兩面喊聲大起，左有灌嬰，右有張耳，兩路兵殺出，衝斷代兵，再經曹參引兵殺回，三面夾攻，代兵大敗，說慌忙遁還。偏漢兵不肯罷手，從後急追，走至鄔東，已被曹參追及，刃傷說馬後股，馬負痛倒地，把說掀翻，便為漢兵所擒。參勸說投降，說反罵漢欺人無信，激動參怒，手起刀落，把說劈下頭顱，因即攻入代城。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-007', 'pingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-008', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 8, 'narrative', 'carried', '[]'::jsonb, '安民已畢，就去迎接韓信。信立即至代，再擬移兵入趙。適有漢王使命到來，調回將士，助守敖倉，信乃使曹參南還。參道出鄔城，為趙將戚將軍所阻，一場惡鬥，力把戚將軍劈死，方得打通路徑，還詣敖倉去了。惟韓信麾下，要算參最為智勇，所領部曲，亦皆善戰。參既南下，部眾當然隨去，信不得不募兵補闕，好容易招添萬人，驅往擊趙。沿途探聽趙兵消息，先後接得探報，各稱趙兵據井陘口，差不多有二十萬人。信素知井陘口的險要，未便輕進，約距井陘口三十里外，停兵下寨，再遣細作往覘虛實，然後進兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-008', 'aocang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-008', 'jingxing', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-009', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 9, 'narrative', 'carried', '[]'::jsonb, '是時趙已知代地失守，格外嚴防，所以扼險固守，阻住漢軍。有謀士廣武軍李左車，進說陳餘道：「韓信張耳，乘勝遠鬥，鋒不可當。但臣聞千里饋糧，士有饑色，樵蘇後爨，師不宿飽，他敢遠道至此，必利在速戰。好在我國門戶，有井陘口為阻，車不得方軌，騎不得成列，彼若從此處進兵，勢難兼運糧草，所有輜重，定在後面。願假臣三萬人，由間道潛出，截取彼糧，足下但深溝高壘，勿與交鋒，彼前不得戰，後不得還，野無所掠，何從得食，不出十日，兩將首級，可致麾下！否則，雖有險阻，不足深恃，恐反為二子所擒了！」左車之計，足以守趙，若必謂足擒信耳，亦覺過誇。陳餘本是書生出身，見識迂拘，嘗自稱為義兵，不尚詐謀，因辭退李左車，屏絕勿用。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-009', 'guangwu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-009', 'jingxing', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-010', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 10, 'narrative', 'carried', '[]'::jsonb, '事為韓信所聞，暗闇心喜，遂傳入騎都尉靳歙，囑他如此如此。待靳歙去後，又召左騎將傅寬，及常山太守張蒼，亦授以密計，令他分頭去訖。自己待至夜半，拔寨起行，及抵井陘口，天色微明，只令裨將分給乾糧，叫全軍暫時果腹，且傳諭大眾道：「今日便好破趙，待成功後，會食未遲。」將士等統皆疑訝，但亦不敢細問，只好齊聲應令。卻是奇怪。信又挑選精兵萬人，叫他渡過汦水，背著河岸，列陣待著。趙軍望見背水陣，不禁竊笑，就是漢將等亦皆驚疑。只韓信平日兵謀，往往令人不測，所以依令照行，未敢有違。信復笑語張耳道：「趙兵據險立營，未見我大將旗鼓，故堅持不動。我當與君同往，親去督攻，使彼奪氣，彼自然退去了。」耳亦未以為然，勉從信言，相偕渡河。信即命軍士揚旗示眾，伐鼓助威，大模大樣的闖入井陘口。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-025-010', 'jingxing', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-011', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 11, 'narrative', 'carried', '[]'::jsonb, '早有趙卒報達陳餘，餘大開營門，麾兵出戰。兩下交綏，趙兵仗著勢眾，一擁上前，來圍韓信張耳。信呼耳急走，且令軍士拋去帥旗，擲去戰鼓，一齊返奔，馳還汦河。顯是詭謀。陳餘部眾得勝，自然並力追擊，還有居守營內的趙兵，也想乘勢邀功，竟把趙王歇都擁了出來，掠取漢軍旗鼓，揚揚得意，嘩聲如雷。那時韓信等已退到汦河，陳餘等亦皆追至，汦河上面，本有漢軍列著，納入韓信張耳，出拒陳餘。韓信下令軍中，決一死戰，退後立斬。漢兵本無退路，就使沒有號令，也只可拚死求生。當下奮力拒戰，爭先殺敵，自辰牌鬥至午牌，不分勝負，陳餘恐部眾腹饑，不能再戰，乃收軍回去。不料到了半途，遙見營中旗幟，都已變色，一張張的隨風飄動，好似紅霞散彩，燦爛異常。及仔細辨認，分明是漢軍赤幟，不由的魂馳魄喪，色沮心驚。正在慌張的時候，刺斜裡突出一軍，乃是漢左騎將傅寬，引兵殺來。餘急忙對敵，且戰且走，忽又有一路人馬，兜頭攔住，為首統將，系漢常山太守張蒼，嚇得餘不知所措，反從後面倒退。張蒼傅寬，合兵趕殺，卻故意不去夾擊，惟把餘逼回汦水，餘軍不顧前後，但教有路可逃，走了再說。餘明知汦水旁邊，駐有漢軍，此去乃是一條絕路，自往尋死，為此喝止部眾，飭令死戰，偏部眾已無鬥志，不肯聽令，只管狂奔。餘不覺怒起，命部將連殺數人，越殺越逃，越逃越亂，連餘亦只好跟著，不能獨返。看看汦水將近，心下愈急，忽來了一個冤家，驅兵亂斲，先將餘纛砍翻，繼即將餘圍住。餘沒甚武力，怎能自脫，即被來兵殺死，這來兵中的主將，究是何人？看官聽著，就是前時刎頸交張耳！殺人不殺己，想也好算是刎頸交。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-012', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 12, 'narrative', 'carried', '[]'::jsonb, '餘既被殺，趙兵除逃去外，悉數降漢。張耳還報韓信，且請往拿趙王歇，信微笑道：「公得斬陳餘，大功已立，那擒拿趙王歇的功勞，就讓與別人罷了。」言未畢，已由靳歙部下，押到一個俘虜，張耳瞧著，俘虜非他，正是趙王歇，又喜又驚。韓信令推歇至前，問了數語，歇默然不答，由信喝令斬訖。當有將士奉令，牽歇出外，梟首復命。趙君臣統皆授首，趙地自平。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-013', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 13, 'narrative', 'carried', '[]'::jsonb, '惟諸將雖得大捷，卻看了韓信用兵，好似神出鬼沒，無從捉摸，各欲向信問明。好在功成以後，應該入賀，就趁那賀捷的機會，請教玄機。正是：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-014', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 14, 'aside', 'carried', '[]'::jsonb, '欲知妙計平強敵，要待明言示暗機。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-015', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 15, 'aside', 'carried', '[]'::jsonb, '究竟韓信如何答說，且至下回再詳。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-025-016', '前漢演義', 25, 205, '第25回·繫於「彭城之戰」', '', 16, 'commentary', 'carried', '[]'::jsonb, '本回敘述韓信兵謀，說得迷離惝恍，不可究詰。迨一經揭出，始知韓信用兵，確有神出鬼沒之妙。謀固奇而筆亦奇，以視正史中之直言紀載，趣味何如！夫正史尚直筆，小說尚曲筆，體裁原是不同，而世人之厭閱正史，樂觀小說，亦即於此處分之。然或向壁虛造，與正史毫不相符，則又為荒誕無稽，何關學術。試看本回之演述木罌渡軍，背水列陣，於史事有否不同？不過化正為奇，較足奪目，能令閱者興味不窮，是即歷史小說之特長也。中插薄姬一段，更於陣雲戰雨之中，辟出風流佳話，尤足生色。且事關漢魏興亡，不可不敘，文以載事，即以道情，吾於是書亦雲。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-001', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說韓信滅趙，諸將入賀，乘便問及計謀。經韓信從頭敘明，才知前時所遣的三路人馬，都寓玄機。靳歙一路，是叫他夤夜出發，繞到趙營後面，暗暗伏著，等到趙兵空壁出戰，便乘虛劫營，拔去趙幟，改豎漢幟。傅寬張蒼兩路，是叫他向晨出發，埋伏趙營附近，等到陳餘回軍，分頭截殺，仍使陳餘退還汦上，好教張耳守候，把他送終。陳餘果然中計，徒落得身首兩分。就是趙王歇被眾擁出，一聞營塞失陷，當即回馬，巧值靳歙殺出，擊走趙兵，趙王歇走得少慢，且被勒歙趕著，活捉了來，也致畢命。這都是韓信預先佈置，好似設著天羅地網，把趙君臣二十萬人，一古腦兒罩住，無從擺脫，待至功成事就，由韓信表白出來，眾將方如夢初醒，無不佩服。說破疑團，使人醒目。惟背水列陣，乃是兵法所忌，韓信違法行兵，反得大捷，尚令諸將生疑。要想問個明白，當下齊聲問信道：「兵法有言，右背山林，前左山澤，今將軍背水為陣，竟得勝趙，究是何因？」信答說道：「這也何嘗不是兵法？諸君雖閱兵書，未得奧旨，所以生疑。兵法中曾有二語云：陷之死地而後生，置之亡地而後存，便是此意。試想我軍新舊夾雜，良窳難分，信又非善能拊循，徒叫他奮身殺敵，怎望有成？惟置諸死地，使他人自為戰，然後勇氣百倍，無人可當，這又如兵法所言，驅市人為戰，不能不用此術哩。」諸將聽了，皆下拜道：「將軍妙算，非他人可及，末將等謹受教了。」信又說道：「趙歇陳餘，雖皆擒斬，但尚有一謀士李左車，不知去向，此人不除，尚為後患，諸君能為我活擒到來，當有重賞。」諸將受命而出，四處尋捉李左車，竟無音響。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-002', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '信又明懸賞格，謂能生擒李左車，立賞千金。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-003', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '過了數日，果然有人捉住左車，解到轅門，信驗明屬實，即出千金為賞，一面召入李左車。諸將在側，總道是將他立斬，誰知左車進來，信忽下座相迎，親為解縛，延令東向坐著，自己西向陪坐，彷彿弟子見師，格外敬禮。且柔聲婉問道：「僕欲北向攻燕，東向伐齊，如何可收全功？」左車皺眉道：「亡國大夫，不足圖存，請將軍另擇高明！左車何敢參議？」信又道：「僕聞百里奚居虞，無救虞亡，及到了秦國，佐成霸業，這並非為虞計拙，為秦計巧，乃是用與不用，聽與不聽，因致先後不同。若使成安君陳餘號成安君見二十一回。聽用君計，恐僕亦束手成擒了。今僕虛心求教，幸勿推辭。」左車方才說道：「將軍涉西河，虜魏王，擒夏說，東下井陘，僅閱半日，得破趙兵二十萬眾，誅成安君，兼斃趙王，名聞海內，威震天下，農夫莫不輟耕釋耒，爭望將軍顏色，這是將軍的長處，一時無兩了。但迭經戰陣，師勞卒疲，不堪再用，今將軍若引往攻燕，燕人憑城固守，將軍欲戰不得，欲攻不克，情急勢拙，日久糧盡，燕既不服，齊又稱強，二國相持，劉項勝負，終難決定，這反變做將軍的短處，豈不可惜！古來良將用兵，須要用長擊短，切不可用短擊長。」信聽言至此，忍耐不住，連忙接問道：「君言甚是，今日究用何策？」左車道：「為將軍計，莫若安兵息甲，鎮撫趙民，百里以內，如有牛酒來獻，盡可宰饗將士，鼓勵軍心。暗中先遣一辯士，齎著尺書，曉示燕王，詳陳利害，燕懼將軍聲威，不敢不從。待燕已聽命，便好東向擊齊！齊成孤立，不亡何待！雖有智士，也無能為謀了。這就是先聲後實的兵法，請將軍採擇。」信鼓掌稱善，當即厚待左車，留居幕中。特派一個說客，持書赴燕。燕王臧荼，當然畏威乞降，復書報信。信得燕王降書，更遣人報知漢王，且請加封張耳，使他王趙。漢王聞燕趙皆平，當然心喜，因即依了信議，封張耳為趙王，另命信引兵擊齊。復使已發，復接得隨何書報，已將九江王英布說妥，指日來降。這真是喜氣重重，無求不遂了。隨何出使九江，見二十四回。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-003', 'jingxing', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-004', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '先是隨何到了九江，九江王英布，但使太宰招待，留居客館。一連三日，未許進見，何因語太宰道：「僕奉漢王使命，來謂大王，大王托故不見，迄今已閱三日。僕料大王意思，無非楚強漢弱，尚待躊躇，但亦何妨與僕相見，僕所言如果合意，大王便可聽從，倘若不合，就可將僕等二十人，梟首市曹，轉獻楚王，豈不較快！願足下轉達鄙忱。」太宰乃入白英布，布始召何入見，命坐左側。何便開口道：「漢王使何到此，敬問大王起居，且囑何轉請大王，為甚麼與楚獨親？」英布道：「寡人嘗為楚屬，北向臣事，自不得不相親了。』何又道：「大王與楚王，俱列為諸侯，今乃北向事楚，想是視楚為強，可以托國﹔但楚嘗伐齊，項王身先士卒親負版築，大王理應親率部眾，為楚先驅，奈何只撥四千人，往會楚軍，難道北面稱臣，好這般敷衍塞責嗎？且漢王入彭城時，項王尚在齊地，一時不及赴援，大王距居較近，應早統兵出救，渡淮力爭，乃不聞一卒踰淮，坐視成敗，難道托身他人，好這般袖手旁觀嗎？大王名為事楚，並無實際，將來項王動怒，定要歸罪大王，前來聲討，不知大王將如何對待呢？」英布聽了，沈吟不答，何復申說道：「大王視楚為強，必且視漢為弱，其實楚兵雖強，天下已皆嫉視，不願臣服。試想項王背盟約，弒義帝，何等不道！今漢王仗義討逆，招集諸侯，固守成臯滎陽，轉運蜀粟，深溝高壘，與楚相持，楚兵千里深入，進退兩難，勢且坐困，強必轉弱，何一可恃？就使楚得勝漢，諸侯必將團結一氣，並力御楚，眾怒難犯，怎得不敗？照此看來，楚實遠不及漢哩。今大王不肯聯漢，反向外強中乾，危亡在邇的楚國，稱臣托庇，豈非自誤！目前九江軍馬，雖未必果能滅楚，但使大王背楚與漢，項王必前來攻擊，大王能將項王絆住數月，漢王便可穩取天下，那時何與大王，提劍歸漢，漢王自然裂土分封，仍將九江歸諸大王，大王方得高枕無懮，否則大王與受惡名，必遭眾矢，恐楚尚未亡，九江先已搖動，不但項王記念前嫌，要來與大王尋釁呢！」一層逼進一層。英布被他說動，不由的起身離座，與何附耳道：「寡人當遵從來命，惟近日且勿聲張，少待數日，然後宣示便了。」何乃辭歸客館。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-004', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-004', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-005', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '守候了好幾天，仍無動靜，探問館員，才知楚使到來，促布發兵攻漢，布尚未決議，因此遲延。他就想出一法，專伺楚使行止。一日楚使入見，坐催布下動員令，何亦昂然趨入，走至楚使上首，坐定與語道：「九江王已經歸漢，汝系楚使，怎得來此徵兵？」英布還想瞞住，一經隨何道破，當然失色。楚使見有變故，也即驚起，向外走出。隨何急語英布道：「事機已露，休使楚使逃歸，不如殺死了他，速即助漢攻楚，免得再誤！」英布一想，好似箭在弦上，不得不發，索性依了隨何，立命左右追拘楚使，一刀兩段。於是宣告大眾，自即日起，與楚脫離關係，聯絡漢王，興師伐楚。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-006', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 6, 'narrative', 'carried', '[1]'::jsonb, '這消息傳到彭城，氣得項王雙目圓睜，無名火高起三丈，立飭親將項聲，與悍將龍且，領著精兵，馳攻九江。英布出兵對敵，連戰數次，卻也殺個平手，沒甚勝敗，相持了一月有餘，楚兵逐漸加增，九江兵逐漸喪失，害得布支持不住，吃了一回大敗仗，只好棄去九江，與隨何偕赴滎陽，投順漢王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-006', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-006', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-007', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 7, 'narrative', 'carried', '[]'::jsonb, '漢王傳請相見，即由隨何導布進去。到了大廳，尚不見漢王形影，再曲曲折折的行入內室，始見漢王踞坐榻上，令人洗足。恐漢王有洗足癖，故屢次如此。但前見酈生本是無心，此次見布，卻是有意，閱者休被瞞過。布不禁懊悵，但事已到此，只得向前通名，屈身行禮。漢王略略欠身，便算是待客的禮節，餘不過慰問數語，也沒有多少厚情，布因即辭出，很是愧悔。湊巧隨何也即出來，便悵然與語道：「不該聽汝誑言，驟到此地！現在懊悔已遲，不如就此自殺罷！」說至此，拔劍出鞘，即欲自刎。隨何連忙止住，驚問何因？布復說道：「我也是一國主子，南面稱王，今來與漢王相見，待我不啻奴僕，我尚有何顏為人，不如速死了事。」看到英布後來結局，原是速死為宜。隨何又急勸道：「漢王宿酒未醒，所以簡慢，少頃自有殊禮相待，幸勿性急。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-008', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 8, 'narrative', 'carried', '[]'::jsonb, '正對答間，裡面已派出典客人員，請布往寓館舍，貌極慇懃，布乃藏劍入鞘，隨同就館。但見館中陳設華麗，服御輝煌，所有衛士從吏，統皆站立兩旁，非常恭敬，儼然如謁見主子一般，既而張良陳平等人，亦俱到來，延布上坐，擺酒接風。席間肴饌精美，器皿整潔，已覺得禮隆物備，具愜心懷。到了酒過數巡，更來了一班女樂，曼聲度曲，低唱侑觴，引得布耳鼓悠揚，眼花繚亂，快活的了不得，把那前半日尋死的心腸，早已銷融淨盡，不留遺蹟了。及酒闌席散，夜靜更深，尚有歌女侍著，未敢擅去。布樂得受用，左擁右抱，其樂陶陶，一夜風光，不勝殫述。差不多似迷人館。翌日，乃入謝漢王，漢王卻竭誠相待，禮意兼優，比那昨日情形不相同。操縱庸夫，便是此術。布越覺愜意，當面宣誓，願為漢王效死。漢王乃令布出收散卒，並力拒楚。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-009', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 9, 'narrative', 'carried', '[]'::jsonb, '布受命退出，即差人潛往九江，招徠舊部，並乘便搬取家眷。好多日方得回音，舊部卻有數千人同來，獨不見妻妾子女。問明底細，才知楚將項伯，已入九江，把他全家誅戮了。布大為悲忿，立刻進見漢王，說明慘狀，原教你全家誅戮，好令死心歸漢。且欲自帶部卒，赴楚報仇。漢王道：「項羽尚強，不宜輕往，況聞將軍部曲，不過數千，怎能敷用？我當助兵萬人，勞將軍往扼成臯，一俟有機可乘，便好進兵雪恨了。」布聞言稱謝，出具行裝，即日就道。漢王亦知他情急，便派兵萬名，隨他同往，布即辭行而去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-010', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 10, 'narrative', 'carried', '[]'::jsonb, '漢王既遣出英布，擬向關中催趲軍糧，與楚兵決一大戰。可巧丞相蕭何，差了許多兄弟子姪，押著糧車，運到滎陽，漢王一一傳見，且問及丞相安否？大眾齊聲道：「丞相托大王福庇，安好如常，惟念大王櫛風沐雨，親歷戎行，恨不得橐鞬相隨，分任勞苦。今特遣臣等前來服役，願乞大王賜錄，柰籍從軍！」漢王大喜道：「丞相為國忘家，為公忘私，正是忠誠無兩了。」當下召入軍官，叫他將蕭氏兄弟子姪，量能錄用，不得有違。軍官應命，引著大眾，自去支配，無庸細說。惟丞相蕭何，派遣兄弟子姪，投效軍前，卻有一種原因。自從漢王出次滎陽，時常遣使入關，慰問蕭何，蕭何也不以為意。偏有門客鮑生，冷眼窺破，獨向蕭何進言，說是漢王在軍，親嘗艱苦，及時來慰問丞相，定懷別意。最好由丞相挑選親族，視有丁壯可用，遣使從軍，方足固寵釋疑等語。蕭何依計而行，果得漢王心喜，不復猜嫌，君臣相安，自然和洽，還有甚麼異言？');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-010', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-011', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 11, 'narrative', 'carried', '[]'::jsonb, '惟關中轉餉艱難，不能隨時接濟，全靠那敖倉積粟，取資軍食。敖倉在滎陽西北，因在敖山上面，築城儲糧，所以叫做敖倉，這是秦時留存的遺制。前由韓信遣將佔據，旁築甬道，由山達河，接濟滎陽屯兵，原是保衛滎陽的要策。回應二十四回，且足補前次所未詳。至韓信北征，敖倉委大將周勃駐守，更撥曹參為助，非常注重。項羽屢欲進攻滎陽，發兵數次，不能得手，旋聞漢王招降英布，失去一個幫手，更不禁怒髮衝冠，亟擬督軍親出，踏破滎陽。旁有范增獻議道：「漢王固守滎陽，無非靠著敖倉糧運，今欲往攻滎陽，必須先截敖倉，敖倉路斷，滎陽乏食，自然一戰可下了。」項王聽著，立遣部將鍾離昧，率兵萬人，往截敖倉糧道，連番衝突，攻破甬道好幾處，把漢兵輸運軍糧，搶去甚多。周勃雖聞信趕救，已是不及，且被鍾離昧邀擊一陣，反致敗回。鍾離昧飛書告捷，竟促項王進攻滎陽，項王遂大舉西行，直向滎陽進發。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-011', 'aocang', 8);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-011', 'xingyang', 10);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-012', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 12, 'narrative', 'carried', '[]'::jsonb, '滎陽城內，已懮乏食，剛要派兵救應敖倉，夾攻鍾離昧，不防項王統率大軍，親來奪取滎陽。這事非同小可，累得漢王寢饋難安，因召入酈食其，向他問計。酈生答道：「項羽傾國前來，銳氣正盛，未可與敵。為大王計，惟有分封諸侯，牽制楚軍，方可紓患。從前商湯放桀，仍封夏後，周武滅紂，亦封殷後，至暴秦併吞六國，不使存祀，所以速亡。今大王若分封六國後嗣，六國君民，必皆感恩慕義，願為臣妾，合力擁戴大王。大王得道多助，自可南鄉稱霸，楚成孤立，必然失勢，亦當襝衽來朝，不敢與大王抗衡了。」漢王道：「此計甚善，可即命有司刻印，齎封六國，各處都煩先生一行，為我傳命。」酈生趨出，當然代戒有司，速鑄六國王印，印尚未成，酈生已整裝待發。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-012', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-012', 'aocang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-013', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 13, 'narrative', 'carried', '[]'::jsonb, '適值張良入謁，見漢王方在午膳，趑趄不前。漢王已經瞧著，向良招呼道：「子房來得正好，可為我商決一事。」良乃趨近座前，漢王又與語道：「近日有人獻策，請封六國後人，牽制楚軍，究竟可否照行？」張良忙答道：「何人為大王出此下計？此計若行，大事去了！」漢王不覺一驚，把箸放下，就將酈生所言，轉告張良。良隨手取箸，指陳利弊道：「臣請為大王借管代籌，說明害處。從前湯武放伐桀紂，仍封後嗣，乃是能制彼死命，不妨示恩。今日大王自問，能制項羽的死命否？這就是一不可行。武王入殷，表商容閭，釋箕子囚，封比乾墓，今日大王能否為此？這就是二不可行。武王發鉅橋粟，散鹿台財，專濟貧窮，今日大王能否為此？這就是三不可行。武王勝殷回國，偃革為軒，倒載干戈，示不復用，今日大王能否為此？這就是四不可行。休馬華山，不復再乘，大王能做得到否？這就是五不可行。放牛桃林，不復再運，大王能做得到否？這就是六不可行。況且天下豪傑，拋親戚，棄墳墓，去故舊，來從大王，無非為日後成功，冀得尺寸封土，今復立六國後，尚有何地可封諸臣，豪傑統皆失望，不如歸事故主，大王得靠著何人，共取天下？這就是七不可行。楚若不強，倒也罷了，倘強盛如故，六國新王，必折服楚國，大王怎得強令稱臣？這就是八不可行。有此八害，豈不是大事盡去麼？」漢王口中含飯，仔細聽說，及張良說罷，竟將口中飯吐出，大罵酈生道：「豎儒無知，幾誤乃公大事！幸虧子房為我指明，免得錯行。」說至此，急命左右傳語有司，促令銷印，酈生一場高興，化作冰銷。但細思良言，確是有理，也覺得自己錯想，不敢瀆陳了。老頭兒太多言。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-014', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 14, 'narrative', 'carried', '[]'::jsonb, '過了數日，楚兵前鋒，竟逼至滎陽城下，城外戍兵，陸續避入城中，漢王急命大小諸將，閉城固守，自在廳室中坐著，默籌方法。適值陳平來報軍情，漢王即令他旁坐，商議破敵事宜。這一番有分教：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-026-014', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-015', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 15, 'aside', 'carried', '[]'::jsonb, '六出奇謀緣此始，七旬亞父命該終。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-016', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 16, 'aside', 'carried', '[]'::jsonb, '欲知陳平如何獻謀，且至下回再表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-026-017', '前漢演義', 26, 205, '第26回·繫於「彭城之戰」', '', 17, 'commentary', 'carried', '[]'::jsonb, '英布實一鄙夫耳！患得患失之見，橫亙胸中，故隨何怵以禍福，即為所動，背楚歸漢。及入見漢王，偶遭慢侮，便欲自刎，何其輕躁乃爾！就館以後，服御滿前，美人侍側，彩色悅目，肥甘適口，轉不禁大喜欲狂，又何其志趣之卑陋也！唐李文饒以漢王見布，深得駕馭英雄之術，吾謂此足以馭鄙夫，斷不足以馭英雄。伊尹必三聘而始至，呂尚必師事而後來，倘如漢王之踞牀洗足，已早望望然去之矣，寧如英布之易受牢籠乎？酈生之初見漢王，亦遭踞牀洗足之侮，而不復他適，其志識亦不過爾爾。請封六國，所見何左，一經張子房之駁斥，而其計謀之絀，已可概見。英布固鄙夫也，不得為英雄，酈生亦庸流耳，寧真得為智士！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-001', '前漢演義', 27, 205, '第27回·繫於「彭城之戰」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說陳平入見漢王，漢王正懮心時局，亟顧語陳平道：「天下紛紛，究竟何時得了？」平答說道：「大王所慮，無非是為著項王，臣料項王麾下，不過范亞父，項羽尊范增為亞父。鍾離昧等數人，算做項氏忠臣，替他出力。大王若肯捐棄巨金，賄通楚人，流言反間，使他自相猜疑，然後乘隙進攻，破楚自容易了。」漢王道：「金銀何足顧惜？但教折除敵燄，便足安心。」說著，即命左右取出黃金四萬斤，交與陳平，任令行事。平受金退出，提出數成，交與心腹小校，使他扮做楚兵模樣，懷金出城，混入楚營，賄囑項王左右，偏布謠言。俗語說是錢能通神，有了黃金，沒一事不能照辦，大約過了兩三日，楚軍中便紛紛傳說，無非是嫁誣鍾離昧等，說他功多賞少，不得分封，將要聯漢滅楚等語。項王素來好猜，一聞訛傳，就不禁動了疑心，竟把鍾離昧等視做貳臣，不肯信任。惟待遇范增，尚然如故。范增且請速攻滎陽，休使漢王逃走，項王遂親督將士，把滎陽城團團圍住，四面猛撲，一些兒不肯放鬆。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-001', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-002', '前漢演義', 27, 205, '第27回·繫於「彭城之戰」', '', 2, 'narrative', 'carried', '[]'::jsonb, '漢王恐不能守，姑遣人與楚講和，願畫滎陽為界，將滎陽東面屬楚，西面屬漢。項王未肯遽允，不過因漢使前來，就也遣使入城，遞一個回話手本，且借此探察城中虛實。這也由項王中氣漸枵，故願遣使入城，否則已將漢使殺斃，何用回報！那知被陳平湊著機會，擺就了現成圈套，好教楚使著迷，墮入計中。楚使未曾預防，貿然逕入，先向漢王報命。漢王已由陳平指導，佯作酒醉，模模糊糊的對付數語。楚使不便多言，即由陳平等導入客館，留他午宴。陳平等走了出去，楚使靜坐片刻，便有一班僕役，抬進牛羊雞豚，及美酒佳餚，向廚房中趨入。楚使心中暗想，莫非漢王格外優待，須要饗我太牢盛饌，所以有許多物品，扛抬進來。已而又由陳平趨進，問及范亞父起居，並詢亞父有無手書？楚使道：「我奉項王使命，為了和議而來，並非由亞父所遣。」陳平聽了，故意失色道：「原來是項王使人。」說著又去。未幾即有吏人跑入廚房，指令僕役，盡將牲餼酒肴等抬出，且聽他廚下私語道：「他不是由亞父差來，怎得配饗太牢呢？」楚使不禁驚愕，俟各物抬去後，竟好一歇不見動靜。到了日影西斜，饑腸亂鳴，才見有一兩人搬入酒飯，放在案上，來請用膳。楚使大略一瞧，無非是蔬食菜羹等類，連魚肉都不見面，不由的怒氣上衝。本想拒絕不吃，只因肚饑難熬，胡亂的吃了少許。不料菜蔬中帶著臭味，未能下咽，而且酒也是酸的，飯也是爛的，叫他如何適口？越看越惱，當時放下杯箸，大踏步走出客館，但與門吏說了一聲辭別，匆匆出城去了。分明是個飯桶。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-002', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-003', '前漢演義', 27, 205, '第27回·繫於「彭城之戰」', '', 3, 'narrative', 'carried', '[]'::jsonb, '城中守吏，並不阻擋，由他自去。他竟一口氣跑回軍營，入見項王。便一五一十的報告明白，且言亞父私通漢王，應該防著。項王怒道：「我前日早有傳聞，還道他是老成可靠，不便遽信人言，那知他果有通敵情事！這個老匹夫，想是活得不耐煩了！」說著，便欲召入范增，當面詰責。還是左右替增排解，請項王勿可過急，待有真憑實據，方可加罪，否則恐防敵人詭謀，不宜遽信云云。如陳平的反間計，尚易窺破，只因項羽躁急，乃入彀中。項王乃暫從含忍，不遽發作。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-004', '前漢演義', 27, 205, '第27回·繫於「彭城之戰」', '', 4, 'narrative', 'carried', '[]'::jsonb, '獨范增尚未得知，一心思想，要為項王設法滅漢。他見項王為了和議，又復把攻城事情，寬懈下去，免不得暗暗著急，因此再入見項王，仍請督勵將士，速下滎陽。項王已心疑范增，默默無言。范增急說道：「古人有言：當斷不斷，反受其亂。從前鴻門會宴時，臣曾勸大王速殺劉季，大王不從臣言，因致養癰貽患，挨到今日，復得了天賜機會，把他困住滎陽，若再被逃脫，縱虎離山，一旦捲土重來，必不可敵，臣恐我不逼人，人且逼我，後悔還來得及麼！」項王被他一詰，忍不住一種悶氣，便勃然道：「汝叫我速攻滎陽，我非不欲從汝，但恐滎陽未必攻下，我的性命，要被汝送脫了！」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-004', 'xingyang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-004', 'hongmen', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-005a', '前漢演義', 27, 205, '第27回·繫於「彭城之戰」', '', 5, 'narrative', 'carried', '[]'::jsonb, '范增摸不著頭腦，只對著項王雙目睃著。忽然想到項王平日，從沒有這等話說，今定是聽人讒間，故有是語。因也忍耐不下，便向項王朗聲道：「天下事已經大定，願大王好好自為，勿墮敵人狡計，臣年已衰老，原宜引退，乞賜臣骸骨，歸葬鄉里便了。」說畢，掉頭逕出。項王也不挽留，一任增回入本營。增至此已知絕望，遂將項王所封歷陽侯印綬，遣人送還項王，自己草草整裝，即日東歸。一路走，一路想，回溯近幾年來，為了項王奪取天下，費盡了無數心機，滿望削平劉漢，好教項王混一宇內，自己亦得安享榮華，聊娛暮景。偏偏項王信讒加忌，弄得功敗垂成，此後楚國江山，看來總要被劉氏奪去，一腔熱血，付諸流水，豈不可歎！於是自嗟自怨，滿腹牢騷，日間躑躅途中，連茶飯都無心吃下，夜間投宿逆旅，也是睡不得安，翻來復去，好幾夜不能合眼。從來愁最傷人，懮易致疾，況范增已年逾七十，怎經得起日夕煩悶，鬱極無聊！因此迫成疾病，漸漸的寒熱侵身，起初還是勉強支持，力疾就道，忽然背上奇痛得很，才閱一宵，便突起一個惡瘡。途次既無良醫，增亦不願求生，但思回見家人，與他永訣。所以臥在車中，催趲速行。將到彭城，背疽越痛越大，不堪收拾，增亦昏迷不醒。尚有幾個從人，見他死在目前，不得不暫停旅舍。過了兩日，增大叫一聲，背疽暴裂，流血不止，竟爾身亡，壽終七十一歲。時已為');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-005a', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-005b', '前漢演義', 27, 204, '第27回·漢王三年四月', '', 5, 'narrative', 'marker', '[4]'::jsonb, '漢王三年四月中了。急點年月。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-006', '前漢演義', 27, 204, '第27回·漢王三年四月', '', 6, 'narrative', 'carried', '[]'::jsonb, '從吏見范增已死，買棺斂屍，運回居鄛，埋葬郭東。後人因他忠事項王，被敵搆陷，死得可憐，乃為他立祠致祭，流傳不絕。並稱縣廷中井為亞父井，留作紀念。九原有知，也好從此告慰了。還算是身後幸事。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-007', '前漢演義', 27, 204, '第27回·漢王三年四月', '', 7, 'narrative', 'carried', '[]'::jsonb, '且說項王聞范增道死，反覺傷感，又未免起了悔心。自思范增事我數年，當無歹意，安知非漢王設計，害我股肱，今與劉季誓不兩立，定當踏平此城，方足泄恨。曉得遲了。乃又召入鍾離昧等，好言撫慰，且囑他用力攻城，立功候賞等語。鍾離昧等倒也感奮，拚死進攻，四面圍撲，晨夕不休。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-008', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 8, 'narrative', 'event_keyword', '[]'::jsonb, '滎陽城內的將士，連日抵禦，害得筋疲力盡，困憊得很，再加糧道斷絕，貯食將罄，眼見得危急萬分，朝不保暮。漢王亦焦灼異常，陳平張良，雖然智術過人，到此亦沒有良法，只好向眾將面前，用了各種激勵的話頭，鼓動眾志。果然有一位替死將軍，慷慨過人，情願粉骨碎身，仰報知遇。這人為誰？乃是漢將紀信。當下入見漢王，請屏左右，悄悄相告道：「大王困守孤城，已有數月，現在敵勢甚盛，城內兵少糧空，定難久守，為大王計，不如脫圍他去，方得自全。但敵軍四面圍著，毫無隙路，須要設法誑敵，把臣軀代作大王，只說是出城投降，好教敵軍無備，然後大王可以乘間出圍，不致危險了。」漢王道：「如將軍言，我雖得出重圍，將軍豈不冒險嗎？」紀信又道：「大王若不用臣言，城破以後，玉石俱焚，臣雖死亦有何益。今只死了一臣，不但大王脫禍，就是許多將士，亦得全生，是一臣可抵千萬人性命，也算是值得了！」漢王尚遲疑未決，恐也是做作出來。紀信奮然道：「大王不忍臣死，臣終不能獨生，不如就此先死罷。」說著意拔劍在手，遽欲自刎。慌得漢王連忙下座，把他阻住，且向他垂涕道：「將軍忠誠貫日，古今無二，但願天心默佑，共得保全，更為萬幸。」紀信乃收劍答說道：「臣死也得所了。」漢王更召入陳平，與語紀信替死等情。陳平道：「紀將軍果肯替死，尚有何說！但也須添設一計，方保無虞。」漢王問有何策？平與漢王附耳數語，漢王自然稱妙。便由陳平寫了降書，囑使乾吏出城，齎書往謁項王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-008', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-009', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 9, 'narrative', 'carried', '[]'::jsonb, '項王展書閱畢，便問漢使道：「汝主何時出降？」漢使道：「今夜便當出降了。」項王大喜，發放漢使，叫他復告漢王，不得誤約。否則明日屠城，漢使唯唯而去。項王便令鍾離昧等，領兵伺候，一俟漢王出來，就好將他拿下祭刀，鍾離昧等振起精神，眼巴巴的待著。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-010', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 10, 'narrative', 'carried', '[]'::jsonb, '時至黃昏，尚未見城中動靜，轉眼間已是夜半，方見東門大啟，放出多人，前後並無火炬，望將過去，好似穿著軍裝，滿身甲冑。大眾恐他詐降，忙將兵器高舉，向前攔阻。但聽得嬌聲高叫道：「我等婦女，無食無衣，只好趁著開門時候，出外求生，還望將軍們放開走路，賞我一線生機，將來當福壽雙全，公侯萬代！」想都是陳平教他。楚兵仔細一瞧，果然是婦人女子，老少不同，有的是雞皮白髮，有的是蟬鬢朱顏，隻身上都披著敝甲，扭扭捏捏，好看得很，禁不住驚異起來。又問他出城逃生，如何有這種異裝？婦女統答說道：「我等沒有衣穿，不得已將守兵棄甲，取來禦寒，幸請勿怪！」楚兵聽說，雖然釋去疑團，總不免少見多怪，暗暗稱奇。大眾分立兩旁，讓開走路，看他過去，且個個睜著饞眼，見有姿色的嬌娃，恨不將他摟抱過來，圖些快樂。更奇怪的是這種婦女，陸續不絕，過了一班，又是一班，連連絡絡，魚貫而出，一時傳為奇觀。卻是楚軍的眼福。甚至西南北三方的楚兵，亦都趨至東門，來看熱鬧。楚將也道是東門大啟，漢王總要出降，不必顧著營寨，但教趨候東門左右，不使漢王走脫，就好算得盡職，所以兵士到來，將吏等亦皆踵至。那漢王就潛開西門，帶著陳平張良，及夏侯嬰樊噲等，溜了出去，但留御史大夫周苛，裨將樅公，與前魏王豹同守滎陽，保住城池。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-010', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-011', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 11, 'narrative', 'event_keyword', '[]'::jsonb, '楚兵毫無所聞，專在東門叢集，尚見紛紛婦女出來，好多時才得走完，約莫有二三千人。天色已將黎明瞭，城中始有兵隊繼出，還執著旌旗羽葆，徐徐行動。又走了好一歇，無非推延時刻，好使漢王遠颺。方來了一乘龍車，當中端坐一位王者，黃屋左纛，前遮後擁，面目模糊難辨。楚將楚兵，總道是漢王來降，都替項王喜歡，高呼萬歲，喧聲如雷。待至龍車推近楚營，並不見漢王下車，大眾不免驚疑，入報項王。項王親自出營，張開那重瞳炬目，審視車中，那車內仍無動靜，不由的大怒道：「劉邦莫非醉死，見我親出，尚端坐如木偶麼？」說著，便喝令左右，用著火炬，環照車中。但見坐著這位人物，衣服雖似漢王模樣，面貌卻與漢王不同，因厲聲叱問道：「汝是何人，敢來冒充漢王？」車中人才應聲出答道：「我乃大漢將軍紀信。」說了一語，又復停住。一語已足千秋。項王越覺咆哮，大罵不止。紀信反呵呵笑說道：「項羽匹夫，仔細聽著！我王豈肯降汝？今已早出滎陽，往招各路兵馬，來與汝決一雌雄，料汝總要失敗，必為我王所擒，汝若知己，不若趕緊退去，尚得免死。」項王氣極，麾令軍士齊集火炬，燒燬來車。軍士應命，環車縱火，烈燄飛騰，車中麾蓋，統皆燃著。紀信在車中大呼道：「逆賊項羽，敢弒義帝，復要焚殺忠臣，我死且留名，看汝死後何如？」說至此，身上已經被火，仍然忍痛端坐，任他延燒，霎時間皮焦骨爛，全車成灰，一道忠魂，已往九霄雲外去了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-011', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-012', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 12, 'narrative', 'carried', '[]'::jsonb, '項王急欲入城，不料城門已閉，城上又滿列守卒，整備矢石，抵禦楚軍。項王督兵再攻，城中兵糧雖少，卻靠著周苛樅公兩人，誓死固守，振作士氣，連番放箭擲石，不使楚軍近城。楚軍攻撲數次，終被擊退。周苛更與樅公商議道：「我等奉了王命，留守此城。城存與存，城亡與亡，倉中尚有積粟數十石，總有旬日可以支持，但恐魏豹居心反覆，或被楚兵勾通，作了內應，那時防不勝防，難免失手，不如把他殺死，除絕內患。就使我王將來，責我擅殺，我等也好據實答復，萬一我王不肯赦宥，我也寧可完城坐罪，比那亡城死敵，好得多了！」樅公也是一個忠臣，當即贊成，惟說是欲誅魏豹，須要乘他不備，從速下手。周苛遂想出一法，托言會議軍情，召豹入商。豹未曾預料，坦然趨至，周苛樅公，迎他入座。才說數語，就被周苛拔出佩劍，砍將過去。豹不及閃避，立致受傷，還想負痛逃走，又由樅公取劍一揮，劈倒地上，了結性命。該死久矣。豹母已死，豹妾薄氏，又由漢王帶去，無人出來領屍。周苛索性陳屍軍中，聲言豹有異心，因此加誅，如有怯戰通敵等情，當與豹一同科罪。軍吏等統皆咋舌，不敢少懈。嗣是拚死拒敵，戮力同心，竟得將一座危城，兀自守住。周苛見眾心已固，方將豹屍收殮埋葬，自與樅公分陴固守。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-013', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 13, 'narrative', 'carried', '[]'::jsonb, '項王怎肯捨去？還想並力破城。會有偵騎走報，漢王向關中徵兵，馳出武關，竟向宛洛進發。說得項王驚愕失常，奮袂起座道：「劉邦詭計甚多，我中他詐降計，被他走脫，今復移兵南下，莫非又去攻我彭城？我應急往攔截為是。」隨即傳令將士，撤圍南行。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-013', 'wuguan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-013', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-014', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 14, 'narrative', 'event_keyword', '[]'::jsonb, '究竟漢王何故轉出武關，說來也有原因。漢王用陳平密計，東放婦女出城，誤人耳目，西向成臯馳去，不見楚兵追擊，幸得安抵成臯。旋聞紀信被焚，且悲且恨，遂向關中招集兵馬，再擬出救滎陽，替信報仇。可巧有一轅生，入白漢王道：「大王不必再往滎陽，但教出兵武關，南向宛洛，項王必慮大王復襲彭城，移兵攔阻，滎陽自可解圍，成臯亦不致吃緊。大王遇著楚兵，更當堅壁勿戰，與他相持數月，一可使滎陽成臯，暫時休息，二可待韓信張耳，平定東北，前來會師，然後大王再還滎陽，合軍與戰，我逸彼勞，我盈彼竭，還怕不能破楚嗎！」漢王道：「汝言頗有至理，我當依議便了。」於是出師武關。到了宛城，果聞項王引兵前來，連忙命軍士豎柵掘濠，立定營壘，待至楚軍逼近，已經預備妥當，好同他堅持過去。小子有詩詠道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-014', 'wuguan', 3);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-014', 'xingyang', 5);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-027-014', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-015', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 15, 'aside', 'carried', '[]'::jsonb, '到底行軍在運籌，尚謀尚力總難侔，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-016', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 16, 'aside', 'carried', '[]'::jsonb, '深溝高壘堅持日，不怕雄兵不逗遛？');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-017', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 17, 'aside', 'carried', '[]'::jsonb, '欲知項王曾否進攻，容待下回分解。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-027-018', '前漢演義', 27, 204, '第27回·繫於「滎陽之圍，紀信誑楚」', '', 18, 'commentary', 'carried', '[]'::jsonb, '陳平致死范增，稱為六出奇計之二，請捐金以間項王，一也，進草具以待楚使，二也。吾謂此計亦屬平常，項王雖愚，度亦不至遽為所欺，或者范增應該畢命，遂致項王動疑，迫令道死耳。夫范增事項數年，於項王之殘暴不仁，未聞諫止，而且老猶戀棧，可去不去，安知非天之假手陳平，使之用謀斃增乎？鄛人之立祠致祭，實為無名，死而有知，恐亦愧享廟食矣！彼紀信之甘代漢王，捨身赴難，脫漢王於圍城之中，而自致焚死，此為漢室之第一忠臣。及漢已定國，功臣多半封侯，而獨不聞有追恤紀信之典，漢王其真寡恩哉！范增有祠，而紀信無祠，此古今仁人智士，所以有不平之歎也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-001', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說項王移兵至宛，見漢兵固壘守著，好幾次前往挑戰，並不見漢兵迎敵。要想攻打進去，又為壕柵所阻，不能衝入。項王正暴躁得很，忽接得探馬急報，乃是魏相國彭越，渡過睢水，大破下邳駐紮的楚軍，殺死楚將薛公，氣勢甚盛。項王大憤道：「可恨彭越，這般撒野，我且去擊斃了他，再來擒捉劉邦。」說著，又拔營東去，往擊彭越。越自受漢王命，為魏相國，見二十二回。略定梁地十餘城。至漢王敗走睢水，楚兵漫山遍野，爭逐漢軍，越亦保守不住，北走河上。項王進攻滎陽，又由越往來游弋，截楚糧道，那時項王已恨越不置，此次越又陣斬楚將，叫項羽如何不憤？倍道東行，一遇越兵，便與豺虎相似，兜頭亂噬。越抵敵不住，又只得退渡睢水，仍然向北奔去。項王追趕不及，復擬往攻漢王，因即探聽漢王行蹤。時漢王已由宛城轉入成臯，與英布合兵駐守。英布往扼成臯，見二十六回中。項王接到確音，便引兵西進，順道先攻滎陽。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-001', 'wan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-001', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-002', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 2, 'narrative', 'carried', '[]'::jsonb, '滎陽城內，仍由周苛樅公住著，兩人原赤膽忠心，為漢守土，但總道項王已去，一時不致驟來，所以防備少疏，與民休息。那知楚兵大至，乘銳攻打，比前次還要凶狠。周苛樅公，連忙登城拒敵，已是不及。楚兵四面齊上，竟將滎陽城攻破，並把周苛樅公，一並擒住。項王也即入城，先召周苛至前，溫顏與語道：「汝能堅守孤城，至今才破，不可謂非將材，可惜汝誤投漢王，終為我軍所擒，若肯向我降順，我當授汝上將，封邑三萬戶，汝可願否？」周苛睜目怒叱道：「汝不去降漢，反要勸我降汝，真是怪極！汝豈是漢王敵手麼？」項王怒起，厲聲大罵道：「不中抬舉的東西！我若將汝一刀兩段，還太便宜，左右快與我取過鼎鑊來！」左右聞命，即將鼎鑊取入，由項王命烹周苛。苛毫無懼色，任他褫剝衣服，擲入鼎鑊，眼見是水火既濟，熔成一鍋人肉羹了。造語新穎。苛既烹死，樅公也被推入。項王令他顧視鼎鑊，樅公道：「我與周苛同守滎陽，苛遭烹死，我亦何忍獨生！情願受死，聽憑大王處置便了！」項王聽他說得有理，總算不使就烹，但令推出斬首，刀光一閃，魂離軀殼，隨那漢御史大夫周苛，同返太虛，這也不消細說。已極褒揚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-002', 'xingyang', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-003', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '項王遂進逼成臯，警信傳入成臯城內，漢王不免驚心。暗思滎陽已失，成臯恐亦難守，哪裡還有第二個紀信，再來替死？因此帶同夏侯嬰，潛開北門，預先出走。及至諸將得知，漢王已經去遠，彼此不願再留，遂陸續出城追去。英布獨力難支，索性也棄城北走，成臯遂被項王奪去。項王聞漢王早出，料知不及追趕，就在成臯駐下，休養兵鋒，徐圖進取。獨漢王馳出成臯，北向修武，擬往依韓信張耳等軍。原來韓信本想伐齊，只因趙地未平，乃與張耳四處剿撫，駐紮修武縣中。漢王已曾聞報，所以星夜趲程，渡河至小修武，宿了一宵，到了翌晨，清早即起，與夏侯嬰出了驛舍，逕入韓信張耳營中。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-003', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-003', 'xiuwu', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-004', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 4, 'narrative', 'carried', '[]'::jsonb, '營兵方起，出視漢王，尚是睡眼朦朧，且見漢王未著王服，不知他從何處差來，當下略回來歷，不遽放入。漢王詐稱漢使，奉命來此，有急事要報元帥。營兵聞有王命，當然不便再阻，但言元帥尚未起來，請入營待報。漢王也不與多說，搶步趨入內帳，當有中軍護衛，認識漢王，慌忙向前行禮。漢王向他擺手，不令聲張，惟使引往韓信臥室。信還在夢中，一些兒沒有知曉。漢王卻靜悄悄的走至榻旁，見案上擺著將印兵符，當即取在手中，出升外帳，命軍吏傳召諸將。諸將尚疑是韓信點兵，統來參謁，及走近案前，舉頭仰望，並不是韓元帥，卻是一位漢大王，大家統皆驚愕。但也不便細問，只好依禮下拜。漢王待他拜罷，逕自發令，把諸將改換職守，一一遣出。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-005', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 5, 'narrative', 'carried', '[]'::jsonb, '韓信張耳，至此方得人喚醒，整衣進見，伏地請罪道：「臣等不知大王駕到，有失遠迎，罪該萬死！」韓信號為國士，何竟有此失著。漢王微笑道：「這也沒有甚麼死罪，不過軍營裡應該如何嚴備，方免不測，況天已大明，亦須早起，奈何高臥未醒，連將印兵符等要件，俱未顧著！倘若敵人猝至，如何抵禦，或有刺客詐稱漢使，混入營中，恐將軍首級，亦難自保，這豈不是危險萬分麼？」韓張二人聽著，禁不住滿面羞慚，無詞可對。漢王又問韓信道：「我本煩將軍攻齊，一得齊地，即來會師攻楚。今將軍留此不往，意欲何為？」韓信乃答說道：「趙地尚未平定，若即移兵東向，保不住趙人蠢動，復為我患。就使有張耳駐守，恐兵分力薄，未足支持，況臣率士卒數萬，轉戰趙魏，勢已過勞，驟然東出，齊阻我前，趙扼我後，腹背受敵，兵不堪戰，豈非危道！故臣擬略定趙地，寬假時日，既可少紓兵力，復可免蹈危機，近正部署粗定，意欲伐齊，適值大王駕到，得以面陳。大王且屯兵此地，伺便攻復成臯，臣即當引兵東去，得仗大王威力，一鼓平齊，便好乘勝西向，與大王會師擊楚了。」漢王方和顏道：「此計甚善。將軍等可起來聽令。」兩人拜謝而起。漢王命張耳帶著本部，速回趙都鎮守，使韓信募集趙地丁壯，東往攻齊。所有修武駐紮的營兵，盡行截留，歸漢王自己統帶，再出擊楚。韓張兩人，不敢有違，只好就此辭行，分頭辦事去了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-005', 'xiuwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-006', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 6, 'narrative', 'carried', '[]'::jsonb, '韓張既去，漢王坐擁修武大營，得了許多人馬，復見成臯諸將，陸續奔集，聲勢復振。因擬再出擊楚，忽從外面遞入軍書，報稱項王從成臯發兵，向西進行。漢王忙遣得力將士，前往鞏縣，堵住楚兵西進，一面與眾商議道：「項王今欲西往，無非是窺我關中。關中乃我根本重地，萬不可失，我意願將成臯東境，一律棄去，索性還保鞏洛，嚴拒楚軍，免得關中搖動，諸君以為何如？」酈食其急忙應聲道：「臣意以為不可！臣聞君以民為本，民以食為天，敖倉儲粟甚多，素稱足食，今楚兵既拔滎陽，不知進據敖倉，這正是天意助漢，不欲絕我民命呢。願大王速即進兵，收復滎陽，據敖倉粟，塞成臯險，控太行山，距蜚狐口，守白馬津，因勢利便，阻遏敵人，敵恐後路中斷，必不敢輕向關中，關中自可無虞，何必往守鞏洛呢？」漢王乃決計復出敖倉，路經小修武，誓眾進戰。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-006', 'xiuwu', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-006', 'aocang', 4);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-028-006', 'xingyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-007', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 7, 'narrative', 'carried', '[]'::jsonb, '郎中鄭忠，卻獻了一條絕糧的計策，謂不如斷楚糧餉，使他乏食自亂，然後進擊未遲。漢王乃令部將盧綰劉賈，率領步卒二萬，騎士數百，渡過白馬津，潛入楚地，會同彭越，截楚糧草。越知楚兵輜重，屯積燕西，遂與盧劉二將，議定計策，夤夜往劫。楚兵未曾防備，被彭越等暗暗過去，放起一把火來，燒得滿地皆紅，一片嗶嗶剝剝的聲音，驚起楚兵睡夢，慌忙起身出望，已是煙燄逼人。再加彭越盧綰劉賈三將，三面殺入，鬧得一塌糊塗，楚兵除被殺外，四散竄去，霎時間逃得精光。所有輜重糧草，盡行棄下，一半被焚，一半搬散。彭越更乘勢奪還梁地，共取睢陽外黃等十七城。得失原是無常。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-008', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 8, 'narrative', 'carried', '[]'::jsonb, '項王尚在成臯，未得西軍捷報，正在愁煩，不防燕西糧餉，又被彭越等焚掠一空，惱得項王火星透頂，復要親擊彭越。因召大司馬曹咎進囑道：「彭越又劫我軍糧，可恨已極！且聞他大擾梁地，猖獗異常，看來非我親自往征，不能掃平此賊！今留將軍等守住成臯，切勿出戰，但當阻住漢王，使他不得東來，便是有功。我料此番擊越，大約十五日內，就可平定梁地，再來與將軍相會。將軍須要謹記我言，毋違毋誤！」項王此言，卻也精細，可惜任用非人。曹咎唯唯聽命，項王尚恐曹咎誤事，復留司馬欣助守，然後引兵自去。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-009', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 9, 'narrative', 'carried', '[]'::jsonb, '彭越不怕別人，但怕項王自至，怎奈冤家碰著對頭，偏又聞得項王親來，越只好入外黃城，督兵拒守。外黃在梁地西偏，項王從成臯過來，第一重便是外黃城。他已怒氣勃勃，目無全敵，一見外黃城關得甚緊，上面有守兵等列著，越覺忍無可忍，立率將士攻城。寫出項王暴躁，反襯舍人小兒。接連攻了數日，城中很是危急，彭越自知難守，等到夜靜更深的時候，開了北門，引兵衝出，得了一條走路，飛馬馳去。楚兵不及追趕，仍然留住城下。城內已無主帥，如何保守！因即開門投降。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-010', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 10, 'narrative', 'carried', '[]'::jsonb, '項王揮動三軍，魚貫入城，既至署中，當即查點百姓，凡年在十五以上，悉令前往城東，聽候號令。看官道是何故？他因百姓投順彭越，幫他守城，好幾日才得攻下，情跡可恨，意欲將十五歲以上的男子，一體坑死，方足泄憤。這號令傳示民間，人人曉得項王殘暴，定是前去送死，你也慌，我也怕，激成一片悲號聲，震響全城。就中有一個髫齡童子，發僅及肩，獨能顧全萬家，挺身出來，竟往楚軍中求見項王。楚兵瞧著，怪他年幼，不免問及履歷，小兒說道：「我父曾為縣令舍人，我年一十三歲，今有要事，前來稟報大王，敢煩從速通報。」楚兵見他口齒伶俐，愈覺稱奇，遂替他入報項王。項王聞有小兒求見，倒也詫異，便令兵士引入。小兒從容入內，見了項王，行過了拜跪禮，起立一旁。項王見他面白唇紅，眉清目秀，已帶著三分憐愛，便柔聲問道：「看汝小小年紀，也敢來見我麼？」小兒道：「大王為民父母，小臣就是大王的赤子，赤子愛慕父母，常思瞻依膝下，難道父母不許謁見麼？」開口便能動人。項王本來喜諛，更兼小兒所言，入情入理，便欣然問道：「汝既來此，定有意見，可即說明。」小兒道：「外黃百姓，久仰大王威德，只因彭越逞強，驟來攻城，城中無兵無餉，只有一班窮苦百姓，不能抵敵，沒奈何向他暫降。百姓本意，仍日望大兵來援，脫離苦厄，今幸大王駕臨，逐去彭越，使百姓重見天日，感戴何如？乃大王軍中，忽有一種訛傳，想把十五歲以上的丁口，統皆坑死，小臣以為大王德同堯舜，威過湯武，斷不忍將一班赤子，屠戮淨盡。況屠戮以後，與大王不但無益，反且有損。所以小臣斗膽進來，請大王頒下明令，慰諭大眾，免得人人危疑。」好一番說詞，恐酈生等尚恐勿如。項王道：「汝說彭越劫制人民，也還有理，但我已引兵到此，為何尚助越拒我？我所以情不甘休。且我要坑死人民，就使無益，何致有損！汝能說出理由，我便下令安民﹔否則連汝都要坑死了！」小兒並不慌忙，反正容答說道：「彭越入據城中，部兵甚多，聞得大王親征，但恐百姓作為內應，就將四面城門，各派親兵把守，百姓手無寸鐵，無從斬關出迎，只好由他守著，惟心中總想設法驅越，所有越令，均不承認，越見人心未附，所以夤夜北遁。若百姓甘心助逆，還要拚死堅守，等到全城死亡，方得由大王入城，最速亦須經過五日十日，今彭越一去，立即開城迎駕，可見百姓並不助越，實是效順大王。大王不察民情，反欲坑死壯丁，大眾原是沒法違抗，不得不俯首就死，但外黃以東，尚有十數城，聽說大王坑死百姓，何人再敢效順？降亦死，不降亦死，何如始終抗命，尚有一線希望。試想彭越從漢，必且向漢乞師，來敵大王，大王處處受敵，縱使處處得勝，也要費盡心力，照此看來，便是無益有損了。」說得明明白白，不怕項王不依。項王一想，這個小兒，卻是語語不錯，況與曹咎期約半月，便回成臯，今已過了數日，倘或前途十餘城，果如小兒所言，統皆固守，多費心力，倒也罷了﹔倘或誤過時日，成臯被漢兵奪去，關係甚大，如何使得？因面囑小兒道：「我就依汝，赦免全城百姓罷。」小兒正要拜辭，項王又令左右取過白銀數兩，賞賜小兒，小兒領謝而出。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-011', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 11, 'narrative', 'carried', '[]'::jsonb, '項王即傳出軍令，收回前命，所有全城百姓，一體免罪，部兵不准侵擾。這令一下，百姓變哭為笑，易懮為喜。起初還道由項王大發慈悲，相率稱頌，後來知是舍人兒為民請命，才得倖免，於是感念項王的情意，統移到舍人兒身上。一介黃童，竟得保全千萬蒼生，真是從古以來，得未曾有了。可惜史家不留姓名。項王復引兵出外黃城，向東進發，沿途所過郡縣，統畏楚軍聲威，不敢與抗。且聞外黃人民，毫不遭害，樂得望風投誠。彭越已向谷城奔去，把前時略定十七城的功勞，化為烏有。項王得唾手取來，行至睢陽，差不多要半個月了。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-012a', '前漢演義', 28, 204, '第28回·繫於「滎陽之圍，紀信誑楚」', '', 12, 'narrative', 'carried', '[]'::jsonb, '時已秋盡冬來，照著秦時舊制，又要過年。項王就在睢陽暫住，待將佐慶賀元旦，方才啟行。轉眼間已是元旦，即');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-012b', '前漢演義', 28, 203, '第28回·漢王四年。項', '', 12, 'narrative', 'marker', '[]'::jsonb, '漢王四年。項王就在行轅中，升帳受賀。將佐等統肅隊趨入，行過了禮，即由項王賜宴，內外列座，開懷暢飲，興會淋漓。忽有急足從成臯馳來，報稱城已失守，大司馬曹咎陣亡。項王大驚道：「我叫曹咎謹守成臯，奈何被漢兵奪去？」報子說道：「曹咎違命出戰，被漢兵截住汜水，不能退回，因致自盡。」項王又頓足道：「司馬欣呢？」報子又說道：「司馬欣也殉難了。」項王忙即起座，命左右撤去酒肴，立刻傳集三軍，西赴成臯，小子有詩歎道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-013', '前漢演義', 28, 203, '第28回·漢王四年。項', '', 13, 'aside', 'carried', '[]'::jsonb, '聖王耀德不勞兵，得國何從仗力征，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-014', '前漢演義', 28, 203, '第28回·漢王四年。項', '', 14, 'aside', 'carried', '[]'::jsonb, '試問烏騅奔命後，到頭曾否告成功！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-015', '前漢演義', 28, 203, '第28回·漢王四年。項', '', 15, 'aside', 'carried', '[]'::jsonb, '究竟成臯如何歸漢，下回再當敘明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-028-016', '前漢演義', 28, 203, '第28回·漢王四年。項', '', 16, 'commentary', 'carried', '[]'::jsonb, '自漢王起兵以來，所有軍謀，似皆出諸他人之口，幾若漢王無所用心，不過好受人言，虛懷若谷而已。然觀他馳入趙營，潛奪兵符，並不由旁人之授計，乃知漢王未嘗無謀，且謀出韓信諸人之上，此張子房之所以稱為天授也。但韓信號為名將，而防禁乃疏闊若此，豈古所謂節制之兵者？張耳更無論已。彼十三歲之外黃兒，竟能說動暴主，救出萬人生命，智不可及，仁亦有餘。昔項王坑秦降卒二十萬人，未有能進阻之者，使當時有如外黃兒之善諫，寧有不足動項王之心乎？故項王若能得人，非不足與為善，惜乎其部下將佐，均不逮一黃口小兒，范增以人傑稱，對外黃兒且有愧色，遑問其他！無惑乎項王之終亡也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-001', '前漢演義', 29, 203, '第29回·漢王四年。項', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說楚大司馬曹咎，與塞王司馬欣，統是項王故人，始終倚任。咎與欣嘗有德項梁，事見十二回。項王且封咎為海春侯，叫他堅守成臯，原是特別重委，再派司馬欣為助，總道是萬穩萬當，可無他虞。曹咎也依命守著，不欲輕動。偏漢兵屢來挑戰，一連數日，未見曹咎出兵，倒也索然無味，還報漢王，漢王與張良陳平等人，商就一計，用了激怒的方法，使兵士往誘曹咎。一面派遣各將，埋伏汜水左右，專等曹咎出擊，好教他入網受擒。佈置已定，遂由兵士再逼城下，百般辱罵，語語不堪入耳。城中守兵，都聽得懊惱異常，爭向曹咎請戰。曹咎素性剛暴，也欲開城廝殺，獨司馬欣諫阻道：「項王臨行，曾有要言囑托足下，但守毋戰，今漢兵前來挑動，明明是一條誘敵計，請足下萬勿氣忿，靜候項王到來，與他會戰，不怕不勝。」曹咎聽了，只得勉強忍耐，飭令兵士靜守，不准出戰。漢兵罵了一日，不見城中動靜，方才退出。越日天曉，又到城下喊鬧，人數越多，罵聲越高，甚至四面八方，環集痛詈。到了日已亭午，未免疲倦，就解衣坐著，取出懷中乾糧，飽食一頓，又復精神勃發，仍然叫罵不絕。直到暮色淒涼，乃復收隊回營。至第三四日間，漢兵且各持白布幡，寫著曹咎姓名，下繪豬狗畜生等類，描摹醜態，眾口中仍然一派譏嘲。曹咎登城俯望，不由的怒氣填胸，且見漢兵或立或坐，或臥或舞，手中用著兵械，亂戳土石，齊聲喧呼，當做剁解曹咎一般。若非誘敵，寧作此態。咎實不能再耐，便一聲號令，召集兵馬，殺出城來。紅曲鱔上鉤了。司馬欣不及攔阻，也只好跟了曹咎，一同出城。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-002', '前漢演義', 29, 203, '第29回·漢王四年。項', '', 2, 'narrative', 'carried', '[]'::jsonb, '漢兵不及整甲，連衣盔旗幟等類，一齊拋棄，都紛紛向北逃走。咎與欣從後追趕，但見漢兵到了汜水，陸續躍下，鳧水遁去。咎憤憤道：「我軍也能鳧水，難道怕汝賊軍不成！」遂催動人馬，趨至水濱，不管前後左右，有無埋伏，就督兵渡將過去。才渡一半，便有兩岸漢兵，搖旗吶喊，踴躍前來。左岸統將為樊噲，右岸統將為靳歙，各持長槍大戟，來殺楚兵。楚兵行伍已亂，不能抵敵，咎在水中，欣尚在岸上，兩人又無從相顧，慌張的了不得。欣心中埋怨曹咎，想收集岸上人馬，自返成臯，偏漢兵已經殺到，無從脫身，只好拚命敵住。那曹咎進退兩難，還想渡到對岸，冒死一戰，誰知對岸又來了許多兵馬，隱隱擁著麾蓋，竟是漢王帶領眾將，親來接應。咎料難再渡，不得已招兵渡回，忽聽得鼓聲一響，箭似飛蝗般射來。楚兵泅在水中，不能昂頭，多半淹斃。咎亦身中數箭，受傷甚重，慌忙登岸，又被漢兵截住，沒奈何拔出佩刀，自刎而亡。司馬欣左衝右突，好多時不能脫身，手下殘兵，只有數十騎隨著，眼見得死在目前，不如自盡，索性也舉槍自刺，斷喉畢命。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-003', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '漢王見前軍大勝，便令停止放箭，安渡汜水，會同樊噲靳歙兩軍，直入成臯。成臯已無守將，百姓都開城迎接，由漢王慰諭一番，盡命安居復業，百姓大悅。還有項王遺下的金銀財寶，一古腦兒歸入漢王。漢王取出數成，分賞將士，將士亦喜出望外，歡躍異常。休息三日，漢王命向敖侖運粟，接濟軍糧。待糧已運至，復引兵出屯廣武，據險設營，阻住項王回軍，一面探聽齊地，專望齊地得平，便可調回韓信，共同御楚。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-003', 'guangwu', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-004', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 4, 'narrative', 'carried', '[]'::jsonb, '小子敘到此處，更要補敘數語，方能前後貫通。原來韓信奉漢王命，往招趙地兵丁，東出擊齊，免不得費時需日。漢王部下的酈食其，志在邀功，獨請命漢王，自願招降齊王，省得勞兵。漢王乃遣令赴齊。是時齊王為誰？就是田橫兄子田廣，即田榮子。由田橫擁立起來，橫為齊相，佐廣守齊。齊經過城陽一役，嚴兵設戍，力拒楚兵。城陽事見二十三回。項王為了彭城失守，南歸敗漢，嗣後專與漢王戰爭，無暇顧齊。就是留攻城陽的楚將，也因齊地難下，次第調歸，所以齊地已有年餘，不遭兵革。回顧前文，筆不滲漏。至韓信募兵擊齊，頗有風聲傳入齊都。齊都便是臨淄城，齊王廣與齊相橫，由城陽還都故土，一聞韓信將要來攻，亟遣族人田解，與部將華無傷等，帶同重兵，出戍歷下。可巧酈食其馳至，求見齊王，齊王廣便即召入，兩下相見，酈生就進說道：「方今楚漢相爭，連年未解，大王可料得將來結果，究應歸屬何人？」齊王道：「這事怎能預料？」酈生道：「將來定當歸漢。」齊王道：「先生從何處看來？」酈生道：「漢楚二王，同受義帝差遣，分道攻秦。當時楚強漢弱，何人不知，乃漢王得先入咸陽，是明明為天意所歸，不假兵力。偏項王違天負約，徒靠著一時強暴，迫令漢王移入漢中，又將義帝遷弒郴地，海內人心，無不痛恨。自從漢王仗義興師，出定三秦，即為義帝縞素發喪，傳檄討賊，名正言順，天下向風。所過城邑，但教降順，悉仍舊封，所得財貨，不願私取，盡給士卒，與天下共享樂利，所以豪傑賢才，俱願為用。項王背約不信，弒主不忠，勒惜爵賞，專用私親，人民背畔，賢才交怨，怎能不敗！怎能不亡！照此看來，便可見天下歸漢，無庸疑議了。況且漢王起兵蜀漢，所向皆克，三秦既定，復涉西河，破北魏，出井陘，誅成安君，勢如破竹，若單靠人力，那有這般神速！今又據敖倉，塞成臯，守白馬津，杜太行坂，距蜚狐口，地利人和，無往不勝，楚兵不久必破。各地諸侯王，已皆服漢，惟齊國尚未歸附，大王誠知幾助順，向漢輸款，齊國尚可保全，否則大兵將至，危亡就在眼前了！」齊王廣乃答說道：「寡人依言歸漢，漢兵便可不來麼？」酈生道：「僕此來並非私行，乃由漢王顧惜齊民，不忍塗炭，特遣僕先來探問。如果大王誠心歸漢，免動兵戈，漢王自然心喜，便當止住韓信，不復進兵。盡請大王放心！」酈生此時可謂躊躇滿志，那知後來偏不如此。');
