INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-005', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 5, 'narrative', 'carried', '[]'::jsonb, '田橫在旁接入道：「這也須由先生修書，先與韓信接洽，方免他慮。」酈生毫不推辭，就索了書箋，寫明情跡，請韓信不必進兵，即差從人齎書，偕同齊使，往報韓信。信正招足趙兵，東至平原，接著酈生書信，展閱一周，即對著來使道：「酈大夫既說下齊國，還有何求？我當旋師南下便了。」隨即寫了復書，交付來使，遣還齊國。酈生接到復函，立白齊國君相，齊王廣與齊相橫，互閱來書，當然勿疑，且有齊使作證，更加相信。遂傳令歷下各軍，一律解嚴，並款留酈生數日，晝夜縱飲，不問外情。酈生本高陽酒徒，見了這杯中物，也是戀戀不捨，今日不行，明日復不行，一連數日，仍然不行，遂致一條老性命，要從此送脫了。酒能誤人，一至於此。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-006', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 6, 'narrative', 'carried', '[]'::jsonb, '自韓信發回齊使，便擬移軍南下，與漢王會同擊楚，忽有一人出阻道：「不可！不可！」韓信瞧著，乃是謀士蒯徹，徹系燕人，已見前文。就啟問道：「齊已降順，我自應改道南行，有什麼不可呢？」蒯徹道：「將軍奉命擊齊，費了若干心機，才得東指。今漢王獨使酈生先往，說下齊國，究竟可恃與否，尚難料定。況漢王並未頒下明令，止住將軍，將軍豈可徒憑酈生一書，倉猝旋師呢？還有一說，酈生是個儒生，憑三寸舌，立下齊國七十餘城，將軍帶甲數萬，轉戰年餘，才得平趙國五十餘城，試想為將數年，反不敵一豎儒的功勞，豈不是可愧可恨麼？為將軍計，不如乘齊無備，長驅直入，掃平齊境，方得將所有功績，歸屬將軍了。」韓信聞言，意亦少動，沈吟了好一歇，才向蒯徹道：「酈生尚在齊國，我若乘虛襲齊，齊必將酈生殺斃，是我反害死酈生，這事恐難使得！」韓信尚有良心。蒯徹微笑道：「將軍不負酈生，酈生已早負將軍了。若使非酈生想奪功勞，搖惑漢王，漢王原遣將軍攻齊，為什麼又遣酈生呢？」辯士之口，誠屬可畏。韓信勃然起座，即刻點齊人馬，渡過平原，突向歷下殺入。齊將田解華無傷，已接齊王解嚴的命令，毫不戒備，驟然遇著漢兵，嚇得莫名其妙，紛紛四溃。韓信麾兵追擊，斬田解，擒華無傷，一路順風，竟至臨淄城下。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-006', 'linzi', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-007', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 7, 'narrative', 'carried', '[]'::jsonb, '齊王廣聞報大驚，急召酈生詰責道：「我誤信汝言，撤除邊防，總道韓信不再進攻，誰知汝懷著鬼胎，佯勸我歸漢撤兵，暗中卻使韓信前來，乘我不備，覆我邦家，汝真行得好計，看汝今日尚有何說？」酈生也覺著忙，便答語道：「韓信不道，背約進攻，非但賣友，實是欺君！願大王遣一使臣，同僕出責韓信，信必無言可答，不得不引兵退去了。」齊王尚未及答，齊相田橫冷笑道：「先生想借此脫罪麼？我前日已經受欺，今可不必哄我了。」酈生道：「足下既疑僕至此，僕就死在此地，不復出城。但也須修書往詰，看韓信如何答復，就死未遲！」廣與橫齊聲道：「韓信如果退兵，不必說了，否則請就試鼎鑊，莫怪我君臣無情！」酈生應著，匆匆寫好書信，派人出城，遞與韓信。信拆書一閱，著墨無多，備極淒惻，也不禁激動天良，半晌答不出話來。偏蒯徹又來進言道：「將軍屢臨大敵，不動聲色，如何為一酈生，反沾沾似兒女子態，不能遽決？一人性命，顧他甚麼？畢世大功，豈可輕棄？請將軍勿再遲疑。」想是前生積有冤孽，故必欲害死酈生。韓信道：「逼死酈生，還是小事，抗違王命，豈非大罪！」蒯徹道：「將軍原奉命伐齊，得平齊地，正是為王盡力，有功無罪。若使今日退兵，使酈生得歸報漢王，從中讒間，恐真要構成大罪了！」韓信本來貪功，又恐得罪，遂聽了蒯徹言語，拒回來使，且與語道：「我是奉命伐齊，未聞諭止，就使齊君臣果然許降，安知非一條緩兵計策，今日降漢，不久復叛？我既引兵到此，志在一勞永逸，煩為我轉告酈大夫，彼此為國效死，不能多事瞻顧了。」');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-008', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 8, 'narrative', 'carried', '[]'::jsonb, '來使只好返報。齊王聞著，便令左右取過油鼎，要烹酈生。酈生道：「我為韓信所賣，自願就烹，但大王國家，亦必就滅，韓信將來，也難免誅夷，果報不爽，恨我不得親見哩！」為下文韓信夷族張本。說罷，就用衣裹首，投入油鼎，須臾畢命。也是貪功所致。齊君臣登城拒守，不到數日，竟被韓信攻破。齊王廣開了東門，當先出走，留住田橫斷後。田橫帶領齊兵，再與漢軍奮鬥數合，終致敗卻，落荒遁去。君臣先後離散，廣奔高密，橫走博陽，韓信馳入齊都，安民已畢，復擬引兵東出，追擊齊王。齊王廣得知風聲，很是惶急，不得已派使西出，奉表項王，向他求救。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-008', 'boyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-009', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 9, 'narrative', 'event_keyword', '[]'::jsonb, '項王自梁地還兵，使鍾離昧為先鋒，馳回滎陽。漢王聞楚軍到來，急命諸將出阻，諸將躍馬馳去，隨兵約有好幾萬名。行至滎陽城東，已與鍾離昧相遇，彼此無暇問答，就一齊圍裹攏來，把鍾離昧困在垓心。鍾離昧兵少難支，惶急得很，可巧項王從後驅至，一聲吶喊，殺入圍中。漢兵慌忙退回，已喪亡了數百人，項王救出鍾離昧，進逼廣武，與漢王夾澗屯軍。廣武本是山名，東連滎澤，西接汜水，形勢險阻，山中有一斷澗，分峙兩峰，漢王就西邊築壘，依澗自固。項王即就東邊築壘，與漢相拒。彼此不便進攻，各自駐守。惟漢由敖倉運粟，源源接濟，連日不絕，楚兵卻沒有這般穀倉，漸漸的糧食減少，不便久持。項王已是加懮，再經齊使馳至軍前，乞發救兵，更令項王心下躊躇。想了多時，還是發兵相救，尚好牽制韓信，免得他來會漢王。乃使大將龍且，副將周蘭，領兵二十萬東往援齊。一面向漢王索戰，漢王只是不出。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-009', 'xingyang', 2);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-009', 'guangwu', 2);
