INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-010', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 10, 'narrative', 'carried', '[]'::jsonb, '項王想出一法，命將漢王父太公，置諸俎上，推至澗旁，自在後面押住，厲聲大呼道：「劉邦聽著！汝若不肯出降，我便烹食汝父！」這數語響震山谷，漢兵無不聞知，即向漢王通報。漢王大驚道：「這……這卻如何是好！」張良在旁進說道：「大王不必著急！項王因我軍不出，特設此計，來誘大王。請大王復詞決絕，免墮詭謀！」漢王道：「倘使我父果然被烹，我將如何為子？如何為人？」張良道：「現在楚軍裡面，除項王外，要算項伯最有權力。項伯與大王已結姻親，定當諫阻，不致他虞。」漢王乃使人傳語道：「我與項羽同事義帝，約為兄弟，我翁就是汝翁，必欲烹汝翁，請分我一杯羹！」項王聽到此語，怒不可遏，就顧令左右，將太公移置俎下，付諸鼎烹。險哉太公。旁邊閃出一人道：「天下事尚未可知，還望勿為已甚，況欲爭天下，往往不顧家族，今殺一人父，有何益處？多惹他人仇恨罷了。」項王乃命將太公牽回，照前軟禁。這救護太公的楚人，就是項伯，果如張良所料。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-011', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 11, 'narrative', 'carried', '[]'::jsonb, '項王又遣吏致語道：「天下汹汹，連歲不寧，無非為了我輩兩人，相持不下。今願與漢王親戰數合，一決雌雄，我若不勝，卷甲即退，何苦長此戰爭，勞疲兵民呢！」漢王笑謝來使道：「我願鬥智，不願鬥力。」楚使回報項王，項王一躍上馬，跑出營門，挑選壯士數十騎，令作先驅，馳向澗旁挑戰。漢營中有一弁目樓煩，素善騎射，由漢王派他出壘，夾澗放箭。颼颼的響了數聲，射倒了好幾個壯士。驀見澗東來了一匹烏騅馬，乘著一位披甲持戟的大王，眼似銅鈴，須似鐵帚，一種兇悍情狀，令人生怖，再加一聲叱咤，震響山谷，好似天空中霹靂一般，嚇得樓煩雙手俱顫，不能再射，還有兩腳亦站立不住，倒退數步，索性回頭就跑，走入營中。見了漢王，心中尚是亂跳，口齒幾說不清楚。漢王著人探視敵蹤，乃是項王尚在澗旁，專呼漢王答話。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-012', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 12, 'narrative', 'carried', '[]'::jsonb, '漢王聞報，雖然有些驚心，但又不便始終示弱，因也整隊趨出，與項王夾澗對談。項王又叱語道：「劉邦，汝敢與我親鬥三合否？」專恃蠻力，實屬無謂。漢王道：「項羽休得逞強，汝身負十大罪，尚敢向我饒舌麼？汝背義帝舊約，王我蜀漢，罪一﹔擅殺卿子冠軍，目無主上，罪二﹔奉命救趙，不聞還報，強迫諸侯入關，罪三﹔燒秦宮室，發掘始皇墳墓，劫取財寶，罪四﹔子嬰已降，汝尚把他殺死，罪五﹔詐坑秦降卒二十萬人，累屍新安，罪六﹔部下愛將，分封善地，卻將各國故主，或徙或逐，罪七﹔出逐義帝，自都彭城，又把韓梁故地，多半佔據，罪八﹔義帝嘗為汝主，竟使人扮作強盜，行弒江南，罪九﹔為政不平，主約不信，神人共憤，天地不容，罪十。我為天下起義，連合諸侯，共誅殘賊，當使刑餘罪人擊汝，難道我配與汝打仗麼？」泗上亭長，居然自高位置了。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-012', 'xinan', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-029-012', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-013', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 13, 'narrative', 'carried', '[]'::jsonb, '項王氣極，並不答言，但用戟向後一揮，便有無數弓弩手，趕將上來。一陣亂射，放出許多箭鏃，躍過斷澗，防不勝防。漢王正想回馬，那胸中已中了一箭，疼痛的了不得，險些兒墮落馬下。幸虧旁列將士，上前救護，把馬牽轉，馳入營門。漢王痛不可忍，屈身伏鞍，暗暗叫苦。將佐等統皆問安，漢王佯用手捫足道：「賊……賊箭中我足趾了！」左右忙扶漢王下馬，擁至榻前安臥。當即傳召醫官，取出箭鏃，敷了瘡藥。還幸瘡痕未深，不致傷命。小子有詩詠道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-014', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 14, 'aside', 'carried', '[]'::jsonb, '一矢相遺已及胸，托詞中趾示從容，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-015', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 15, 'aside', 'carried', '[]'::jsonb, '聰明畢竟由天授，通變才能卻敵鋒。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-016', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 16, 'narrative', 'carried', '[]'::jsonb, '漢王中箭回營，項王始轉怒為喜，只因絕澗難越，不便進攻，也即收兵退歸。欲知後事，且看下回自知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-029-017', '前漢演義', 29, 203, '第29回·繫於「廣武對峙」', '', 17, 'commentary', 'carried', '[]'::jsonb, '酈生之被烹，韓信實使之，而韓信將來之受誅，亦即由酈生之烹死，暗伏禍根。酈生之說齊，固奉漢王之命而往，既得招降齊國，不辱使命，乃偏為韓信所賣，卒致焚身，漢王聞之，寧有不隱恨韓信？不過楚尚未平，恃信為輔，因含忍而未發耳。況漢王之生平，本能忍人所不能忍，乃父已置諸敵俎，猶有分我杯羹之言，對父且如此，況他人乎！至若項王索戰，夾澗與語，曆數項王十罪，雖事有可征，並無虛構，然項王罪惡之大，莫過於弒義帝，漢王置此罪於八九之間，獨以背約為罪首，重私輕公，易先為後，其心已可概見矣。彼智如韓信，獨不能察漢王之隱，猶沾沾於平齊之功績，聽蒯徹而害酈生，此所以終遭誅戮也。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-001', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說項王歸營以後，專探聽漢營動靜，擬俟漢王身死，乘隙進攻。漢營裡面的張良，早已料著，即入內帳看視漢王。漢王箭創未愈，還可勉強支持，良因勸漢王力疾起牀，巡行軍中，借鎮人心。漢王乃掙扎起來，裹好胸前，由左右扶他上車，向各壘巡視一周。將士等正在疑慮，忽見漢王乘車巡查，形容如故，方皆放下愁懷，安心守著。漢王巡行既遍，自覺餘痛難禁，索性吩咐左右，不回原帳，竟馳返成臯，權時養病去了。這也是漢王急智。項王得著探報，據稱漢王未死，仍在軍中巡行，又不禁暗暗歎惜，大費躊躇。自思進不得進，退不得退，長此屯留過去，恐糧盡兵疲，後難為繼。正在委決不下，驀地裡傳到警耗，乃是大將龍且，戰敗身亡。項王大驚失色道：「韓信有這般厲害麼？他傷我大將龍且，必要乘勝前來，與劉邦合兵攻我，韓信韓信，奈何奈何！」句法似通非通，益覺形容得妙。說罷，復著人探明虛實，再作計較。究竟韓信如何得勝？龍且如何被殺？待小子演述出來。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-002', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 2, 'narrative', 'carried', '[]'::jsonb, '龍且領著大兵，倍道東進，行入齊地，即遣急足馳報齊王，叫他前來會師。齊王廣聞楚軍大至，當然心喜，急忙收集散兵，出高密城，往迎楚軍。兩下至濰水東岸，湊巧相遇，彼此晤談以後，一同就地安營。韓信正要向高密進兵，聞得龍且兵到，也知他是個勁敵，因復遣人報知漢王，調集曹參灌嬰兩軍，方才出發，到了濰水西岸，遙見對河遍紮軍營，氣勢甚盛，乃召語曹灌兩將道：「龍且系有名悍將，只可智取，不可力敵，我當用計擒他便了。」曹灌兩將，自然同聲應令。韓信命退軍三里，擇險立寨，按兵不出。楚將龍且，還疑是韓信怯戰，便欲渡河進擊。旁有屬吏獻議道：「韓信引兵遠來，定必向我奮鬥，驟與接仗，恐不可當，齊兵已經敗衄，萬難再恃，且兵皆土著，顧念室家，容易逃散，我軍雖與異趨，免不得被他牽動，他若四溃，我亦難支。最好是堅壁自守，勿與交鋒，一面使齊王派遣使臣，招輯亡城。各城守吏，聞知齊王無恙，楚兵又大舉來援，定然還向齊王，不肯從漢。漢兵去國二千里，客居齊地，無城可因，無糧可食，怎能長久相持？旬月以後，就可不戰自破了。」龍且搖首道：「韓信鄙夫，有何能力？我曾聞他少年貧賤，衣食不週，甚至寄食漂母，受辱胯下。這般無用的人物，怕他甚麼！況我奉項王命，前來救齊，若不與韓信接仗，就使他糧盡乞降，也沒有什麼戰功，今誠一戰得勝，威震齊國，齊王必委國聽從，平分土地，一半給我，豈不是名成利就麼？」全是妄想。副將周蘭，也恐龍且輕戰有失，上前進諫道：「將軍不可輕視韓信。信助漢王定三秦，滅趙降燕，今復破齊，聞他足智多謀，機謀莫測，還望將軍三思後行。」龍且笑說道：「韓信所遇，統是庸將，故得僥倖成功，若與我相敵，管教他首級不保了。」慢說慢說，且管著自己頭顱。當下差一弁目，渡過濰水，投遞戰書。韓信即就原書後面，批了來日決戰四字，當即遣回。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-003', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 3, 'narrative', 'carried', '[]'::jsonb, '楚使既去，信命軍士趕辦布囊萬餘，當夜候用，不得有違。又要作怪。原來營中隨帶布囊，本來不少，多半是盛貯乾糧，此次軍士得了將令，但將乾糧取出，便可移用，因此不到半日，已經辦齊。延至黃昏，由信召入部將傅寬，授與密計道：「汝可領著部曲，各帶布囊，潛往濰水上流，就在水邊取了泥沙，貯入囊中，擇視河面淺狹的地方，把囊沈積，阻住流水。待至明日交戰時，楚軍渡河，我軍傳發號炮，豎起紅旗，可速命兵士撈起沙囊，仍使流水放下，至要至囑！」傅寬遵令，率兵自去。此處授計用明寫法，但非看到後文，尚未知此計之妙。信又召集眾將道：「汝等明日交戰，須看紅旗為號，紅旗豎起，急宜並力擊敵，擒斬龍且周蘭，便在此舉，今可靜養一宵，明日當立大功了。」眾將聞言，俱各歸帳安息。信但令巡兵守夜，自己亦即就寢，詰旦起來，命大眾飽餐一頓，傳令出營。信自往挑戰，帶同裨將數名，逕渡濰水，所有曹參灌嬰等軍，統叫他留住西岸，分站兩旁。濰水本來深廣，不能徒涉，此時由傅寬壅住上流，水勢陡淺，但教褰衣過去，便可渡登對岸。韓信到了岸東，擺成陣勢，正值龍且驅眾過來，信便出陣大呼道：「龍且快來受死！」龍且聽了，躍馬出營，大聲叱道：「韓信，汝原是楚臣，為何叛楚降漢？今日天兵到此，還不下馬受縛，更待何時？」信笑答道：「項羽背約弒主，大逆不道，汝乃甘心從逆，自取滅亡，今日便是汝的死期了。」龍且大怒，舉刀直取韓信，信退入陣中，當有眾將殺出，敵住龍且。龍且抖擻精神，與眾力戰，約有一二十合，未分勝負，副將周蘭，也來助陣，漢將等漸漸退卻。韓信拍馬就走，仍向濰水奔回。眾將見信馳還，也即退下，隨信同奔。龍且大笑道：「我原說韓信無能，不堪一戰呢。」說著，遂當先力趕，周蘭等從後追上，行近濰水，那漢兵卻渡過河西去了。龍且趕得起勁，還管甚麼水勢深淺，也即躍馬西渡。惟周蘭瞧著水涸，不免動疑，見龍且已經渡河，急欲向前諫阻，因此緊緊隨著，也望河西過去。無如龍且跑得甚快，轉眼間已達彼岸，周蘭不便折回，只好縱馬過河，部眾統皆落後，跟著龍且周蘭，不過二三千騎，餘兵或渡至中流，或尚在東岸。猛聽得一聲炮響，震動波流，水勢忽然增漲，高了好幾尺，既而澎湃洶湧，好似曲江中的大潮，突如其來，不可推測，河中楚兵，無從立足，多被漂去。只東岸未渡的人馬，尚在觀望，未曾遇險。還有龍且周蘭，及騎兵二三千名，已登西岸，一時免做溺死鬼。還是溺死，省得飲刀。那時漢兵中已豎起紅旗，曹參灌嬰，兩旁殺來，韓信亦領諸將殺回。三路人馬，夾擊龍且周蘭，任你龍且如何驍勇，周蘭如何精細，至此俱陷入羅網，擺脫不出。並且寡不敵眾，單靠著二三千名騎兵，濟得甚麼戰事？結果是龍且褫斬，周蘭受擒，二三千騎楚兵，掃得乾乾淨淨，不留一人。東岸的楚兵，遙見龍且等統已戰歿，不寒自栗，立即駭散。齊王廣似驚弓鳥，漏網魚，哪裡還堪再嚇，便即棄寨逃回。行至高密，因見後面塵頭大起，料有漢兵趕來，且隨身兵士，多已逃散，自知高密難守，不如走往城陽，於是飛馬再奔。將到城陽相近，漢兵已經趕到，七手八腳，把他拖落馬下，捆了去，解至韓信軍前。韓信責他擅烹酈生，太覺殘忍，便令推出斬首。總算為酈生抵命。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-004', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 4, 'narrative', 'carried', '[]'::jsonb, '復使灌嬰往攻博陽，曹參進略膠東，博陽為田橫所守，聞得田廣已死，自為齊王，出駐嬴下，截住灌嬰。嬰麾兵奮擊，殺得田橫勢窮力竭，止帶了數十騎，遁往梁地，投依彭越去了。尚有橫族田吸，與橫分路逃生，奔至千乘，被灌嬰一馬追及，戮死了事。此外已無齊兵，遂梟了首級，還營報功。適值曹參也持了一個首級，奏凱歸來，問明底細，乃是膠東守將田既，為參所殺，蕩平膠東，回來繳令。兩將並入大營，報明韓信，信登簿錄功，並將齊地所得財帛，分賞將士，不必細述。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-004', 'boyang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-005', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 5, 'narrative', 'event_keyword', '[]'::jsonb, '惟韓信既平齊地，便想做個齊王，遂繕了一封文書，使人至漢王前告捷，且要求齊王封印。漢王在成臯養病，已經告痊，復至櫟陽察視城守，勾留四日，仍馳抵廣武軍前。可巧韓信差來的軍弁，也到廣武，遂將書信呈上。漢王展閱未終，不禁大怒道：「我困守此地，日夜望他來助，他不來助我，還要想做齊王麼？」張良陳平在側，慌忙走近漢王，輕躡足趾。漢王究竟心靈，停住罵聲，即將原書持示兩人。書中大意，說是齊人多偽，反覆無常，且南境近楚，難免復叛，請暫許臣為假王，方期鎮定等語。兩人看罷，附耳語漢王道：「漢方不利，怎能禁止韓信為王？今不若使他王齊，為我守著，可作聲援。否則恐變生不測了。」幸有此說。漢王因復佯叱道：「大丈夫得平定諸侯，不妨就做真王，為何還要稱假呢！」轉風得快。隨即遣回來使，叫韓信守侯冊封，來使自去。漢王便遣張良齎印赴齊，立韓信為齊王，信得印甚喜，厚待張良。良又述漢王意見，勸信發兵攻楚，信亦滿口應承。良叨了一席盛宴，飲罷即歸。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-005', 'yueyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-005', 'guangwu', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-006', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 6, 'narrative', 'carried', '[]'::jsonb, '信擇吉稱王，大閱兵馬，準備擊楚，忽有楚使武涉，前來求見。韓信暗想，我與楚為仇敵，為何遣使到此？想必來做說客，我自有主意，何妨相見。因即顧令左右，引入武涉。武涉系盱眙人，饒有口才，素居項王幕下。項王探得齊地確信，果被韓信破滅，當然驚心，所以派遣武涉，往說韓信，為離間計。涉一見信面，便下拜稱賀，信起座答禮，且微笑道：「君來賀我做甚！無非為了項王，來作說客，盡請道來！」涉乃申說道：「天下苦秦已久，故楚漢戮力擊秦，今秦已早亡，分土割地，各自為王，正應休息士卒，與民更始，乃漢王復興兵東來，侵入地，奪入土，脅制諸侯，與楚相爭，可見他貪得無厭，志在併吞。足下明智過人，難道尚未能預察麼？且漢王前日，嘗入項王掌握中，項王不忍加誅，使王蜀漢，也算是情義兩盡。偏漢王不念舊誼，復擊項王，機詐如此，尚好親信麼？足下自以為得親漢王，替他盡力，涉恐足下他日，亦必遭反噬，為彼所擒了！試想足下得有今日，實由項王尚存，漢王不能不籠絡足下。足下眼前處境，還是進退裕如的時候，左投漢王，漢勝，右投項王，楚勝，漢勝必危及足下，楚勝當不致自危。項王與足下本有故交，時常繫念，必不相負！若足下尚不肯深信，最好是與楚連和，三分天下，鼎足稱王，楚漢兩國，都不敢與足下為難，這乃是萬全良策了。」為韓信計，卻是此策最善。韓信笑答道：「我前事項王，官不過郎中，位不過執戟，言不聽，計不用，所以背楚歸漢。漢王授我上將軍印，付我數萬兵士，解衣衣我，推食食我，我若負德，必至不祥。我已誓死從漢了！幸為我復謝項王。」武涉見他志決，只好辭歸。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-007', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 7, 'narrative', 'carried', '[]'::jsonb, '信送出武涉，有一人隨他進去，由信回頭一顧，乃是蒯徹，因即邀令入座。徹開口道：「僕近已學習相術了，相君面不過封侯，相君背乃貴不勝言。」信聽得甚奇，料他必有微意，復引徹至密室，屏人與談。徹又說道：「秦亡以後，楚漢分爭，不顧人民，專務角逐。項王起兵彭城，轉戰逐北，直下滎陽，威震遠近，今乃久困京索，連年不得再進。漢王率數十萬眾，據有鞏洛，憑借山河，一日數戰，無尺寸功，反致屢敗，這乃所謂智勇俱困呢。僕料現今大勢，非有賢聖，莫能息爭。足下乘時崛起，介居楚漢，為漢即漢勝，為楚即楚勝，楚漢兩主的性命，懸在足下手中，誠能聽僕鄙計，莫若兩不相助，三分鼎峙，靜待時機。其實如足下大才，據強齊，並燕趙，得時西向，為民請命，何人不服？何國不從？將來宰割天下，分封諸侯，諸侯俱懷德畏威，相率朝齊，豈不是霸王盛業麼？僕聞天與不取，反致受咎，時至不行，反致受殃，願足下深思熟慮，毋忽鄙言！」韓信道：「漢王待我甚厚，怎可向利背義呢？」徹又道：「從前常山王張耳，與成安君陳餘，約為刎頸交，後來為了張黶陳澤的嫌疑，竟成仇敵，汦水一戰，陳餘授首。足下自思與漢王交情，能如張陳二人否？所處嫌疑，止如黶澤一事否？乃猶欲自全忠信，見好漢王，豈非大誤！越大夫文種，存亡越，霸勾踐，立功成名，尚且被戮，獸死狗烹，已成至論，足下的忠信，想亦不過如大夫種罷了。且僕聞勇略震主，往往自危，功蓋天下，往往不賞，今足下已蹈此轍，歸漢漢必懼，歸楚楚不信，足下將持此何歸呢？」語雖近是，但蒯徹與漢無仇，何故唆人叛主。韓信不免動疑，因即語徹道：「先生且休，待我細思，更定進止。」徹乃辭退。過了數日，杳無動靜，乃復入見韓信，請他決機去疑，慎勿失時。信終不忍背漢，又自恃功高，總道漢王不致變卦，決將蒯徹謝絕。徹恐久居被禍，假作瘋癲，竟向別處作巫去了。信聞徹他去，也不著人挽留，惟心下忐忑不定，且將兵馬停住，再聽漢王消息。既已拒徹，應即發兵擊楚，偏又停住不進，真是何意。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-007', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-007', 'xingyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-008', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 8, 'narrative', 'event_keyword', '[]'::jsonb, '漢王固守廣武，又是數旬，日望韓信到來，信終不至。乃立英布為淮南王，使他再赴九江，截楚後路。一面貽書彭越，仍侵入梁地，斷楚糧道。佈置已定，尚恐項王糧盡欲回，又取出太公，挾制多端，或乘怒將太公殺死，更覺可危。當下與張良陳平，商議救父的方法。兩人齊聲道：「項王乏糧，必將退歸，此時正好與他講和，救回太公呂后了。」漢王道：「項王情性暴戾，一語不合，便至動怒，欲要遣使議和，必須選擇妥人，方可無虞。」言未畢，有一人應聲閃出道：「臣願往。」漢王一瞧，乃是洛陽人侯公，從軍有年，素長應對，因即准如所請，囑令小心從事。侯公遂馳赴楚營，求謁項王。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-008', 'guangwu', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-008', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-009', '前漢演義', 30, 203, '第30回·繫於「廣武對峙」', '', 9, 'narrative', 'carried', '[]'::jsonb, '項王得武涉歸報，甚是愁煩，又見糧食將盡，越覺愁上加愁，忽聞漢營中遣到使臣，乃仗劍高坐，傳令入見。侯公徐徐步入，見了項王，毫無懼色，從容向前，行過了禮。項王瞋目與語道：「汝主既不出戰，又不退去，今差汝到來，有何話說？」侯公道：「大王還是欲戰呢？還是欲退呢？」項王道：「我願一戰！」侯公道：「戰是危機，勝負難料﹔況相持已久，兵力皆疲，臣今為罷兵息爭而來，故敢進見大王。」項王不覺脫口道：「據汝來意，是欲與我講和麼？」侯公道：「漢王並不欲與大王爭鋒，大王如為保國安民起見，易戰為和，敢不從命。」項王意已稍平，把劍放下，問及議和約款。侯公道：「使臣奉漢王命，卻有二議，一是楚漢兩國，劃定疆界，彼此相安，不再侵犯。二請釋還漢王父太公，及妻室呂氏，使他骨肉團圓，久感聖德。」項王掀髯獰笑道：「汝主又來欺我麼？他想保全骨肉，故令汝詭詞請和。」侯公道：「大王知漢王東出的意思否？人情無不念父母，顧妻子，漢王西居蜀漢，離家甚遠，免不得懷念在心，前次潛至彭城，無非欲搬取家眷，嗣聞為大王所拘，急不暇擇，遂至與大王為敵，累戰不休。今大王無意言和，原是不必說了，既商和議，何不將兩人釋還，不但使漢王從此感德，誓不東行，就是天下諸侯，亦且爭慕大王，無不歌頌。試想大王不殺人父，就是明孝，不污人妻，就是明義，已經拘住，又復放歸，所以明仁，三德俱備，聲名洋溢，如恐漢王負約，是曲在漢王，直在大王，古人有言：師直為壯，曲為老，大王直道而行，天下無敵，何論一漢王呢！」');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-009', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-010a', '前漢演義', 30, 203, '第30回·繫於「鴻溝議和」', '', 10, 'narrative', 'event_keyword', '[]'::jsonb, '項王最喜奉承，聽了侯公一番言語，深愜心懷，遂復召入項伯，與侯公商議國界。項伯本是袒漢，樂得賣個人情，兩下議決，就滎陽東南二十里外的鴻溝，劃分界限，溝東屬楚，溝西屬漢。當由項王遣使，與侯公同報漢王，訂定約章，各無異言。所有迎還太公呂后的重差，仍然要勞煩侯公，侯公再偕楚使同行，至楚營請求如約，項王毫不遲疑，便放出太公呂后，及從吏審食其，使與侯公同歸。漢王聞知，當然出營迎接，父子夫婦，復得相見，正是悲喜交集，慶賀同聲。漢王嘉侯公功，封他為平國君，是為');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-010a', 'xingyang', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-030-010a', 'honggou', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-010b', '前漢演義', 30, 203, '第30回·漢四年九月間', '', 10, 'narrative', 'marker', '[9]'::jsonb, '漢四年九月間事。越日，即聞項王拔營東歸，漢王亦欲西返，傳令將士整頓歸裝，忽有兩人進諫道：「大王不欲統一天下麼？奈何歸休！」這一語有分教：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-011', '前漢演義', 30, 203, '第30回·漢四年九月間', '', 11, 'aside', 'carried', '[]'::jsonb, '壇坫方才休玉帛，疆場又復啟兵戈。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-012', '前漢演義', 30, 203, '第30回·漢四年九月間', '', 12, 'aside', 'carried', '[]'::jsonb, '欲知兩人為誰，待至下回報明。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-030-013', '前漢演義', 30, 203, '第30回·漢四年九月間', '', 13, 'commentary', 'carried', '[]'::jsonb, '兵法有言：驕兵必敗，龍且未勝先驕，即非韓信之善謀，亦無不敗之理。項王以二十萬眾，委諸龍且，何用人之不明歟？然項王同一有勇無謀之暴主，而龍且即為有勇無謀之莽將，同氣相求，故有是失。龍且死而項王亦將敗亡，此徒勇之所以無益也。武涉之說韓信，各為其主，原不足怪。蒯徹並非楚臣，何為唆信叛漢，使之君臣相猜，他時鐘室之禍，非徹致之而誰致之乎？若漢之遣使請和，得歸太公呂后，雖由侯生之善言，實出一時之僥倖，假使項王不允，加刃太公，則漢王雖得天下，終不免為無父之罪人而已，貪天幸以圖功，君子所勿取焉。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-001a', '前漢演義', 31, 203, '第31回·漢四年九月間', '', 1, 'narrative', 'carried', '[]'::jsonb, '卻說漢王欲西還關中，有兩人進來諫阻，兩人為誰？就是張良陳平。漢王道：「我與楚立約修和，彼已東歸，我尚留此做甚。」良平齊聲道：「臣等請大王議和，無非為了太公呂后二人。今太公呂后，已得歸來，正好與他交戰，況天下大勢，我已得了大半，四方諸侯，又多歸附，彼項王兵疲食盡，眾叛親離，乃是天意亡楚的時候，若聽他東歸，不去追擊，豈不是養虎遺患麼？」專知趨利，如信義何！漢王深信二人，遂復變計，再擬向東進攻。只因孟冬已屆，照了前秦舊制，又要過年，乃就營中備了酒席，宴飲大小三軍，自與呂后陪著太公，在內帳奉觴稱壽，暢飲盡歡。太公呂后，從未經過這種樂事，此次父子完聚，夫婦團圓，白髮紅顏，相偕醉月，金樽玉斝，合宴連宵，真個是苦盡甘回，不勝欣慰了。恐此時呂后心中，尚恨審食其不得在座。元旦這一日，就是');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-001b', '前漢演義', 31, 202, '第31回·漢王五年，大', '', 1, 'narrative', 'marker', '[]'::jsonb, '漢王五年，大書特書，是為漢王滅楚稱帝之歲。漢王先向太公祝釐，然後升座外帳，受了文武百官的謁賀。禮已粗畢，即與張良陳平，商議軍事，決定分路遣使，往約齊王韓信，及魏相國彭越，發兵攻楚，中道會師，當下派員去迄。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-002', '前漢演義', 31, 202, '第31回·漢王五年，大', '', 2, 'narrative', 'carried', '[]'::jsonb, '過了一日，又差車騎數百人，送太公呂后入關，漢王遂親率大隊，向東進發，沿路不復耽延，一直馳至固陵。前驅早有偵騎派出，探得楚兵相去不遠，回報漢王。漢王乃擇險安營，專待韓彭兩軍到來，便好合擊楚軍。偏韓彭兩軍，杳無音信，那項王已得了消息，恨漢負約，竟驅動兵馬，驟向漢營殺來。漢王恐楚兵踹營，反覺不妙，不如督兵出戰，較為得勢，乃麾眾出營，與楚接仗。兩下相遇，漢兵尚未成列，項王已拍動烏騅，挺戟當先，專向漢軍中堅，鼓勇衝入，尋殺漢王。漢將見項王到來，慌忙攔阻，怎禁得項王一股怒氣，把手中戟飛舞起來，任憑漢軍中有許多勇將，沒有個是他敵手，有幾個命中帶晦，不是被他刺死，就是被他戳傷，於是漢將俱紛紛倒退。漢王見不可支，還是拍馬奔回，避開危險。主帥一動，全軍皆散，項王樂得大殺一陣，把漢兵驅回營中，然後收兵自去。漢王狼狽還營，檢點兵士，喪失了好幾千名，將佐亦傷亡了好幾十名，不由的垂頭喪氣，悶坐帳中。可巧張良進來，因即顧問道：「韓彭失約，我軍又遭敗挫，如何是好！」張良道：「楚兵雖勝，盡可勿慮，只是韓彭不至，卻是可懮。臣料韓彭二人，必由大王未與分地，所以觀望不前。」漢王道：「我封韓信為齊王，拜彭越為魏相國，怎得說是沒有分地？」良答道：「齊王信雖得受封，並非大王本意，信亦當然不安，彭越曾略定梁地，大王命他往佐魏豹，所以移兵，今魏豹已死，越亦望封王，乃大王未嘗加封，不免觖望。今若取睢陽北境，直至谷城，封與彭越，再由陳以東，直至東海，封與韓信，信家在楚，嘗想取得鄉土，大王今日慨允，兩人明日便來了。」窺透兩人志願。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-002', 'guling', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-003', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 3, 'narrative', 'event_keyword', '[]'::jsonb, '漢王不得已依議，再遣使人飛報韓彭，許加封地，果然兩人滿望，即日發兵。還有淮南王英布，與漢將劉賈，進兵九江，招降守將楚大司馬周殷，一些兒不勞兵革，反得了九江許多人馬，會同英布劉賈，接應漢王。三路大兵，陸續趨集，漢王自然放膽行軍。項王聞漢兵大至，兵食又盡，巴不得急回彭城，所以固陵雖獲勝仗，仍然不願久留，引軍再退。路上恐漢兵追襲，用了步步為營的兵法，依次退去。好容易到了垓下，遙聽得後面一帶，鼓聲馬聲吶喊聲，非常震響。當下登高西望，見漢兵踴躍追來，差不多與螞蟻相似，不禁仰天歎道：「好多漢兵，我悔前日不殺劉邦，養成他這番氣燄哩！」話雖如此，還仗著自己勇力，並手下將士，尚有十萬名左右，倒也不甚著忙。遂就垓下紮營，準備對敵。漢王已會齊三路兵馬，共至垓下，人數不下三十餘萬，復用韓信為大將，調度諸軍。韓信素知項王驍勇，無人敢當，特將各軍分作十隊，各派統將帶領，分頭埋伏，迴環接應，請漢王守住大營，自率三萬人挑戰。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-003', 'pengcheng', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-003', 'guling', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-003', 'gaixia', 3);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-004', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 4, 'narrative', 'event_keyword', '[]'::jsonb, '項王單靠勇力，不尚兵謀，一聞敵兵逼營，立即怒馬突出，迎敵漢軍。楚兵亦一齊出寨，隨著項王，奮勇向前。兩軍相接，交戰了好幾合，項王橫戟一揮，部眾統不管生死，專望漢軍中殺入。韓信且戰且走，誘引項王入網。項王平日，所向無敵，全不把韓信放在眼中，就使有人諫阻項王，叫他不可輕追，他亦不甘罷休，定要殺奔前去。約莫追了好幾里，已入漢軍伏中，一味莽撞，總要遭禍。韓信便鳴放號炮，喚起伏兵。先有兩路殺出，與項王交戰一次，項王全不退怯，鏖鬥了好多時，衝開漢軍，還要追趕韓信。但聽第二次炮聲復發，又有兩路伏兵殺出，截住項王，再加廝殺，好多時又被衝破。項王殺得性起，仍舊有進無退，接連是炮聲迭響，伏兵迭起。項王殺開一重，又復一重，殺到第七八重時候，部眾已零落了，將弁多傷亡了，項王也自覺力疲，漸漸的退卻下來。那知韓信放完號炮，十面埋伏，一齊發出，都向項王馬前，圍裹攏來。所有楚兵，好似雞犬一樣，紛紛四竄，但靠項王一枝畫戟，究竟擋不住百般兵器。項王悔己無及，只得令鍾離昧季布等斷後，自己當先開路，猛喝一聲，已足嚇退漢兵，再加長戟縱橫，一經觸著，無不立斃，因此漢兵左右避開，讓出一條血路，得使項王走脫，馳回垓下大營。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-004', 'gaixia', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-005', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 5, 'narrative', 'carried', '[]'::jsonb, '自從項王起兵以來，向未經過這般挫辱，此次已該數盡，偏碰著漢元帥韓信，用著十面埋伏的計策，殺敗項王，把楚營十萬銳卒，擊斃了三四成，趕走了三四成，只剩得兩三萬殘兵，跟回營中，叫項王如何不惱，如何不懮！他有一個寵姬虞氏，秀外慧中，知書識字，雖遇項王出兵打仗，也嘗乘車隨行，形影不離。名姬陪著悍王，似覺不甚相配。此番也在營間，守候項王歸來。項王戰敗入營，當由虞姬迎著，見他形容委頓，神色倉皇，也覺驚異得很。待至項王坐定，喘息稍平，才問及戰爭情狀。項王唏噓道：「敗了！敗了！」虞姬勸慰道：「勝負乃兵家常事，願大王不必懮勞。」項王道：「怪不得汝等婦女，未識利害，連我也不曾遇此惡戰哩。」虞姬本已囑咐行廚，整備酒肴，想為項王接風。此時因項王敗還，更欲替他解悶，便即令廚役搬出，陳列席間，請項王上坐小飲。項王已無心飲酒，但為了寵姬情意，未便遽卻，乃向席間坐下，使虞姬旁坐相陪。才飲了三五杯，就有帳外軍弁趨入，報稱漢兵圍營。項王道：「汝去傳諭將士，小心堅守，不可輕動，待我明日再決一戰罷！」軍弁應聲退出。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-006', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 6, 'narrative', 'carried', '[]'::jsonb, '時已天晚，項王復與虞姬並飲數觥，燈紅酒綠，眉黛鬟青，平時對此情景，何等愜意，偏是夕反成慘劇，越飲越愁，越愁越倦，頓時睡眼模糊，斂肱欲寐。還是虞姬知情識意，請項王安臥榻中，休養精神。項王才就榻睡下，虞姬坐守榻旁，一寸芳心，好似小鹿兒亂撞，甚覺不寧。耳近又聽得淒風颯颯，觱栗嗚嗚，俄而車馳馬驟，俄而鬼哭神號，種種聲浪，增人煩悶。旋復有一片歌音，遞響進來，如怨如慕，如泣如訴，一聲高，一聲低，一聲長，一聲短，彷彿九臯鶴唳四野鴻哀。虞姬是個解人，禁不住悲懷戚戚，淚眥熒熒。從虞姬一邊敘入楚歌，尤覺淒切。回顧項王，卻是鼻息如雷，不聞不知，急得虞姬有口難言，淒其欲絕。究竟這歌聲從何而來？乃是漢營中張子房，編出一曲楚歌，教軍士至楚營旁，四面唱和，無句不哀，無字不慘，激動一班楚兵，懷念鄉關，陸續散去。就是鍾離昧季布等人，隨從項王好幾年，也忽然變卦，背地走了。甚至項王季父項伯，亦悄悄的往投張良，求庇終身。樹未倒而猢猻先散。單剩項王親兵八百騎，守住營門，未曾離叛。正想入報項王，卻值項王酒意已消，猛然醒寤。起聞楚歌，不禁驚疑，出帳細聽，那歌聲是從漢營傳出，越加詫異道：「漢已盡得楚地麼？為何漢營中有許多楚人呢？」說著，便見軍弁稟報，謂將士皆已逃散，只有八百人尚存。項王大駭道：「有這等急變嗎？」當即返身入帳，見虞姬站立一旁，已變成一個淚人兒，也不由的泣下數行。旁顧席上殘肴，尚未撤去，壺中酒亦頗沈重，乃再令廚人燙熱，喚過虞姬，再與共飲。飲盡數觥，便信口作歌道：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-007', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 7, 'narrative', 'carried', '[]'::jsonb, '力拔山兮氣蓋世！時不利兮騅不逝！騅不逝兮可奈何！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-008', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 8, 'narrative', 'carried', '[]'::jsonb, '虞兮虞兮奈若何！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-009', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 9, 'narrative', 'event_keyword', '[]'::jsonb, '項王生平的愛幸，第一是烏騅馬，第二是虞美人，此番被圍垓下，已知死在目前，惟心中實不忍割捨美人駿馬，因此悲歌慷慨，嗚咽欷歔！虞姬在旁聽著，已知項王歌意，也即口占一詩道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-009', 'gaixia', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-010', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 10, 'aside', 'carried', '[]'::jsonb, '漢兵已略地，四面楚歌聲。大王意氣盡，賤妾何聊生！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-011', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 11, 'narrative', 'carried', '[]'::jsonb, '虞姬吟罷潸潸淚下，項王亦陪了許多眼淚。就是左右侍臣，統皆情不自禁，悲泣失聲。驀聽得營中更鼓，已擊五下，乃顧語虞姬道：「天將明瞭，我當冒死出圍，卿將奈何！」虞姬道：「妾蒙大王厚恩，追隨至今，今亦當隨去，生死相依﹔倘得歸葬故土，死也甘心！」項王道：「如卿弱質，怎能出圍？卿可自尋生路，我當與卿長別了。」虞姬突然起立，豎起雙眉，喘聲對項王道：「賤妾生隨大王，死亦隨大王，願大王前途保重！」說至此，就從項王腰間，拔出佩劍，向頸一橫頓時血濺珠喉，香銷殘壘。閱書至此，雖鐵石心腸，亦當下淚。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-012', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 12, 'narrative', 'carried', '[]'::jsonb, '項王還欲相救，已是不及，遂撫屍大哭一場，命左右掘地成坑，將屍埋葬。至今安徽省定遠縣南六十里，留有香冢，傳為佳話。文人墨客，且因虞姬貞節可嘉，譜入詞曲，竟把虞美人三字，作為曲名，美人千古，足慰芳魂。比後來人彘何如？惟項王已看虞姬葬訖，勉強收淚，出乘烏騅，趁著天色未明的時候，帶了八百騎親兵，銜枚疾走，偷過楚營，向南遁去。及漢兵得知，急報韓信，已是雞聲報曉，晨光熹微了。韓信聞項王溃圍，急令將軍灌嬰，率領五千兵馬，往追項王。項王也防漢兵追來，匆匆至淮水濱，覓船東渡，部騎又散去大半，只剩了一二百人。行至陰陵，見路有兩歧，不知何道得往彭城，未免躊躇。適有老農在田間作工，因向他訪問行逕，老農卻有些認識項王，素來恨他暴虐，竟用手西指道：「向這邊去！」項王信是真話，策馬西奔，約跑了好幾里，撲面寒風，很是凜冽，前途流水澌澌，隨風震響，仔細瞧著，乃是一個大湖，擋住去路。至此方知受欺，慌忙折回，再到原處，重向東行。為了這番盤旋，遂被漢將灌嬰追及，一陣衝擊，又喪失了百餘騎。還是項王坐下的烏騅，跑走甚快，當先馳脫。後面陸續跟上，寥寥無幾，到了東城，經項王回頭察看，只有二十八騎，尚算隨著。那四面的金鼓聲，吶喊聲，仍然不住，漸漸相逼。項王自知難脫，引騎至一山前，走登崗上，擺成圓陣，慨然顧騎士道：「我自起兵到今，倏已八年，大小七十餘戰，所擋必靡，所擊必破，未嘗一次敗北，因得霸有天下。今日乃被困此間，想是天意已欲亡我，並非我不能與戰呢。我已自決一死，願為諸君再決一戰，定要三戰三勝，為諸君突圍，斬將搴旗，使諸君知我善戰，今實天意亡我，與我無干，免得向我歸罪了！」善戰必亡，奈何至死不悟。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-012', 'pengcheng', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-013', '前漢演義', 31, 202, '第31回·繫於「垓下之圍」', '', 13, 'narrative', 'carried', '[]'::jsonb, '道言甫畢，漢兵已四面趕集，把山圍住。項王乃分二十八騎為四隊，與漢兵相向。東首有一漢將，不知死活，驅兵登崗，想來活捉項王。項王語騎士道：「君等看我刺殺此將！」說著縱轡欲走，又回頭顧語道：「諸君可四面馳下，至東山下取齊，再作三處駐紮罷。」於是奮聲大呼，挺戟馳下，一遇漢將，便猛力戳去。漢將不及躲避，陡被刺落，骨轆轆滾下山去，霎時畢命。漢兵見了，統皆逃還，項王便縱馬下山。山下的漢將，仗著人多勢旺，團團圍繞，竟至數匝，都被項王殺退。漢騎將楊喜，上前追趕，由項王回頭一喝，人馬辟易，倒退了一兩里。就是項王部下的二十八騎，亦皆馳集，先與項王打個照面，然後三處分馳。漢兵又從後趕來，未知項王所在，也分兵三路，追圍項王。項王左手持戟，右手仗劍，或劈或刺，斬一漢都尉，剁斃漢兵數十百人，仍得殺透重圍，再救出兩處部騎，重聚一處，檢點數目，只少了兩個騎兵。便笑向部騎道：「我的戰仗如何？」部騎皆拜伏道：「如大王言！」統計項王自山上殺下，一連九戰，漢兵遇著項王，無不溃散，故後人稱是山為九頭山，亦號四溃山。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-014', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 14, 'narrative', 'event_keyword', '[]'::jsonb, '項王既得脫圍，走至烏江，卻值烏江亭長，泊船岸旁，請項王渡江過去。且敦促道：「江東雖小，地方千里，尚足自王，現惟臣有一船，願大王急渡！」項王聽了，笑對亭長道：用兩笑字，比哭尤慘。「天已亡我，我何必再渡！且籍與江東子弟八千人，渡江西行，今無一生還，就使江東父老，見我生憐，再肯王我，我有何面目相見哩？」說著，後面塵頭又起，料知漢兵復到，亭長又出言催促，項王喟然道：「我知公為忠厚長者，厚情可感，我無以為報，惟坐下的烏騅馬，隨我五年，日行千里，臨陣無敵，今我不忍殺此馬，特地賜公，見馬猶如見我呢。」一面說，一面跳下馬來，令部卒牽付亭長，又命部騎皆下馬步行，各持短刀，轉身待著漢兵。漢兵一齊趕至，項王又鼓勇再戰，亂削亂劈，連斃漢兵數百人，自身亦受了十餘創。驀見有數騎將馳至，認得一人是呂馬童，淒聲與語道：「汝不是我舊友嗎？」呂馬童不敢正視，但向項王望了一面，便旁顧僚將王翳道：「這位就是項王。」項王又說道：「我聞漢王懸有賞格，得我首級，賜千金，封邑萬戶，我今日就賣情與汝罷！」說畢，便用劍自刎，年終三十一歲。小子記得前人詠項王詩，曾有二絕，特錄述如下云：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-014', 'wujiang', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-015', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 15, 'aside', 'carried', '[]'::jsonb, '爭帝圖王勢已傾，八千兵散楚歌聲，');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-016', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 16, 'aside', 'carried', '[]'::jsonb, '烏江不是無船渡，恥向東吳再起兵。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-016', 'wujiang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-017', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 17, 'aside', 'carried', '[]'::jsonb, '不修仁政枉談兵，天道如何尚力爭？');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-018', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 18, 'aside', 'carried', '[]'::jsonb, '隔岸故鄉歸不得，十年空負拔山名。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-019', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 19, 'aside', 'carried', '[]'::jsonb, '項王已死，所餘二十六騎，亦皆逃亡。欲知項王屍首如何，待至下回續表。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-031-020', '前漢演義', 31, 202, '第31回·繫於「項羽自刎烏江」', '', 20, 'commentary', 'carried', '[]'::jsonb, '韓信之十面埋伏計，史策未詳，但相傳已久，度非無因。況當時漢兵競集，為特一無二之大舉，人數不下三十萬，分作十隊，綽有餘裕，非行此計以困項王，則項王之勇悍，無人敢敵，幾何而不蹈固陵之復轍也。虞姬之別，烏江之刎，最為項氏慘史，經著書人依次寫來，尤覺得情節蒼涼，令人悲咽。且虞姬守貞，何如呂后戚姬之穢辱？慨然決死，何如韓信彭越之誅夷？美人英雄，名播千秋，泉下有知，其亦足以自慰乎？惟觀於項王之坑降卒，殺子嬰，弒義帝，種種不道，死有餘辜，彼自以為非戰之罪，罪固不在戰，而在殘暴也。彼殺人多矣，能無及此乎！天亡天亡，夫復誰尤！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-020', 'guling', 1);
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-031-020', 'wujiang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-001', '前漢演義', 32, 202, '第32回·繫於「項羽自刎烏江」', '', 1, 'narrative', 'event_keyword', '[]'::jsonb, '卻說項王自刎以後，漢將爭奪項王屍骸，甚至自相殘殺，死了好幾十人，結果是王翳得了頭顱，呂馬童與楊喜呂勝楊武等四將，各得一體，持向漢王前報功。漢王命將五體湊合，果然相符，遂即分封五人，命呂馬童為中水侯，王翳為杜衍侯，楊喜為赤泉侯，楊武為吳防侯，呂勝為涅陽侯。楚地望風請降，獨魯城堅守不下，漢王大怒，引兵攻魯，恨不得立刻入城，一體屠戮，蕩成平地。不意到了城下，覺有一種弦誦的聲音，悠揚入耳，因不禁轉念道：「魯國素知禮義，今為主守節，不得為非，我不如設法招撫為是。」只一轉念，便是興王氣象。乃將項王首級，令將士挑在竿上，舉示城上守兵，且傳諭降者免死，於是魯城吏民，開門迎降。先是楚懷王嘗封項羽為魯公，至是魯最後降，漢王因命用魯公禮，收葬項王屍身，就在谷城西隅，告窆築墳，親為發喪。並命文吏繕成一篇祭文，無非說是前同兄弟，本非仇讎，拘太公不殺，虜呂后不犯，三年留養，尤見盛情，死後有知，應視此觴等語。及臨祭讀文，漢王亦不禁悲泣，淚下潸潸。恐非真情。將士等都為動容，祭畢乃還。呂馬童為項王故人，到此亦知感否？今河南省河陽縣有項羽墓，就是項羽自刎的地方，便系今日的烏江浦，在安徽省和縣東北，留有祠宇，號為西楚霸王廟，這且不必細述。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-001', 'wujiang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-002', '前漢演義', 32, 202, '第32回·繫於「項羽自刎烏江」', '', 2, 'narrative', 'carried', '[]'::jsonb, '漢王命赦項氏宗親，一律免罪，且聞項伯已在張良營中，特別召見，封為射陽侯，賜姓劉氏。賣主求榮，項伯不能無慚。還有項襄項佗等，亦皆封侯賜姓，如項伯例。結婚一節，史中未曾提及，想由漢王賴去。各路諸侯，都附勢輸誠，奉書稱賀。惟臨江王共敖子尉，嗣爵為王，尚記念項王舊恩，不肯從漢。經漢王派遣劉賈等人，率兵往討，才閱旬日，便將共尉擒歸，江陵亦平。臨江王都江陵，見前文。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-002', 'jiangling', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-003', '前漢演義', 32, 202, '第32回·繫於「項羽自刎烏江」', '', 3, 'narrative', 'carried', '[]'::jsonb, '漢王還至定陶，與張良陳平二人，密議多時，即趨入韓信營中。信亟起相迎，奉王就座，但聽得漢王面諭道：「將軍屢建大功，得平強項，寡人當始終不忘。今應休兵息民，不復勞師，將軍可繳還軍符，仍就原鎮便了！」此時信無詞可拒，只好把印信取出，交還漢王。漢王得了印信，便即持去。俄而又傳出一令，說是楚地已定，義帝無後，齊王信生長楚中，習楚風俗，可改封楚王，鎮定淮北，定都下邳。魏相國越，勤撫魏民，屢破楚軍，今即將魏地加封，號稱梁王，就都定陶云云。彭越是加授封爵，當然心喜，便至漢王前拜謝，受印而去。惟韓信易齊為楚，明知漢王記著前嫌，不願再令王齊，但自思衣錦還鄉，也足顯揚故土，計不如遵著命令，就此榮歸為是。乃亦繳出齊王印，改領楚王印起行。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-003', 'dingtao', 2);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-004', '前漢演義', 32, 202, '第32回·繫於「項羽自刎烏江」', '', 4, 'narrative', 'carried', '[]'::jsonb, '到了下邳，即差人尋訪漂母，及受辱胯下的惡少年。漂母先至，信下座慰問，特賜千金，漂母拜謝去訖。可謂一登龍門，飯價百倍。既而惡少年到來，面無人色，俯伏請罪。信笑說道：「我豈小丈夫所為，睚眥必報？汝可不必恐懼，我且授汝為中尉官。」少年叩首道：「小人愚蠢，曾誤犯尊威，今蒙赦罪不誅，恩同再造，怎敢再邀封賞？」信又說道：「我願授汝為官，汝何必多辭！」少年乃再拜稱謝，起身退出。信顧語左右道：「這也是個壯士，他辱我時，我豈不能拚死與爭？但死得無名，所以忍耐至此，得有今日。」左右都服信大度，交口稱賢。信復與梁王彭越，淮南王英布，韓王信，故衡山王吳芮，趙王張敖，是年張耳病歿，子敖嗣爵。燕王臧荼等，聯名上疏，尊漢王為皇帝。疏中略云：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-005', '前漢演義', 32, 202, '第32回·繫於「項羽自刎烏江」', '', 5, 'narrative', 'carried', '[]'::jsonb, '先時秦為無道，天下誅之，大王先得秦王，定關中，於天下功最多，存亡定危，救敗繼絕，以安萬民，功盛德厚，又加惠於諸侯王，有功者使得立社稷。地分已定，而位號比擬，無上下之分，是大王功德之著，於後世不宜。謹昧死再拜上皇帝尊號，伏乞准行！');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-006', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 6, 'narrative', 'event_keyword', '[]'::jsonb, '漢王得疏，召集群裡，與語道：「寡人聞古來帝號，只有賢王可當此稱，虛名無實，殊不足取。今諸侯王乃推高寡人，寡人乏德，如何敢當此尊號？」群臣都齊聲道：「大王起自細微，誅不義，立有功，平定海內，功臣皆得裂土分封，可見大王本無私意。今大王德加四海，諸侯王不足與比，實至名歸，應居帝位，天下幸甚！」漢王還要推讓，再由內外臣僚，合詞申請，乃命太尉盧綰及博士叔孫通等擇吉定儀，就在汜水南面，郊天祭地，即漢帝位。文武百官，一齊朝賀，頒詔大赦，追尊先妣劉媼為昭靈夫人，立王後呂氏為皇后，王太子盈為皇太子。接連有諭旨二道，分封長沙閩粤二王，文云：');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-007', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 7, 'narrative', 'carried', '[]'::jsonb, '故衡山王吳芮，與子二人，兄子一人，從百粤之兵，以佐諸侯，誅暴秦，有大功，為衡山王。項羽侵奪之，降為番君，今其以長沙豫章象郡桂林南海諸郡，立番君芮為長沙王，欽哉惟命！吳芮傳國最久，故特錄此詔。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-008', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 8, 'narrative', 'carried', '[]'::jsonb, '故粤王無諸，越勾踐後，姓騶氏。世奉越祀，秦侵奪其地，使其社稷，不得血食，諸侯伐秦，無諸身率閩中兵，以佐滅秦。項羽廢而勿立，今以為閩粤王，王閩中地，勿使失職，以酬王庸。此詔並錄，為後文閩越不靖張本。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-009', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 9, 'narrative', 'carried', '[]'::jsonb, '是時諸侯王受地分封，共計八國，就是楚韓淮南梁趙燕及長沙閩粤二王。此外仍為郡縣，各置守吏，如秦制相同，漢王命諸侯王皆罷兵歸國，所有部下士卒，除量能授職外，亦俱遣令還家，本身免輸戶賦。一面啟蹕入洛，即以洛陽為國都。特派大臣赴櫟陽奉迎太公呂后及太子盈，又遣使至沛邑故里，召入次兄劉仲，從子劉信，並同父異母的少弟劉交。想是太公繼室所生。還有微時外婦曹氏，暨定陶人戚氏父女，亦乘便接入。曹女生子名肥，戚女生子名如意，當然挈同至都。曹氏見第十一回，戚氏見第二十四回。父子兄弟，妻妾子姪，陸續到齊，歡聚皇宮，沒一個不喜出望外，額手稱慶，漢帝亦樂不勝言。看官聽說！漢帝後來廟號叫做高皇帝，並因他為漢朝始祖，就稱為漢高祖，史家統是這般紀述，小子此後敘錄，也沿例呼為漢高祖了。特筆提清。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-009', 'luoyang', 1);
