INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-010', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 10, 'narrative', 'carried', '[]'::jsonb, '高祖既平定海內，籌畫政治，卻也忙亂了好幾月。由春及夏，諸事粗有頭緒，方得少閒，因就洛陽南宮，大開筵宴，遍召群臣入內，一同會飲。酒行數巡，高祖乃對眾宣言道：「列侯諸將，佐朕得有天下，今日一堂宴會，君臣同聚，最好是直言問答，不必忌諱。朕卻有一問，朕何故得有天下？項氏何故致失天下？」當有兩人起座，同聲答道：「陛下平日待人，未免侮慢，不及項羽的寬仁。但陛下使人攻城略地，每得一城，即作為封賞，能與天下共利，所以人人效命，得有天下。項羽妒賢忌能，多疑好猜，戰勝不賞功，得地不分利，人心懈體，乃失天下，這便是得失的辨別呢。」高祖聽了，瞧著兩人，乃是高起王陵，便笑說道：「公等知一不知二，據我想來，得失原因，須從用人上立說。試想運籌帷幄，決勝千里，我不如子房，鎮國家，撫百姓，運餉至軍，源源不絕，我不如蕭何，統百萬兵士，戰必勝，攻必取，我不如韓信。這三人系當今豪傑，我能委心任用，故得天下。項羽只有一范增，尚不能用，怪不得為我所滅了！」群臣聞言，各下座拜伏，稱為至言。高祖大悅，又令大眾歸座，續飲多時，興盡始散。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-010', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-011', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 11, 'narrative', 'carried', '[]'::jsonb, '過了數日，有人入報高祖，說是故齊王田橫，避匿海島，有徒黨五百餘人，一同居住。高祖不免加懮，即派朝臣，齎了詔書，前往招安。橫自被灌嬰擊敗，投奔彭越，見第三十回。留居月餘，聞越起兵從漢，自恐被禍，因潛身奔赴東海，尋得一個島嶼，作為枝棲。他本來疏財好士，廣結豪俠，此次投奔海島，有同時隨行的，有聞風趨集的，因此人數得五百有餘。及漢使到了島中，交付詔書，由橫閱畢，便向漢使說道：「我前時曾烹酈食其，今雖蒙天子赦罪，召令入都，但聞食其弟酈商，方為上將，怎肯不為兄報仇？因此不敢奉詔。」漢使聽說，當即告辭，還都復命。高祖道：「這有何妨？橫亦不免多慮，」因召入衛尉酈商，當面囑咐道：「齊王田橫，將要來朝，汝不得懷著兄仇，私下陷害！如若有違，罪當夷族。」酈商心雖不服，但未敢辯駁，只好應聲退出。高祖再遣原使召橫，叫他不必懮懼，且令傳諭道：「田橫來，大可封王，小亦封侯，倘再違詔不至，朕將發兵加誅，毋貽後悔！」這數語傳入橫耳，橫不得已隨使動身，徒黨五百餘人，俱請相從。橫與語道：「我非不願與諸君同行，惟人數過多，反招疑忌，不如留居此地，聽候消息。我若入都受封，自當來召諸君。」大眾乃止。橫但與門客二人，同了漢使，航海登岸，乘馹赴都。行至屍鄉驛，距洛陽約三十里，橫顧語漢使道：「人臣入朝天子，應該沐浴表誠，此處幸有驛舍，可許我就館洗沐否？」漢使不料他有別意，當然應諾，遂入驛小憩，聽令沐浴。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-011', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-012', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 12, 'narrative', 'carried', '[]'::jsonb, '橫既得避開漢使，密喚二客近前，喟然與語道：「橫與漢王皆南面稱孤，本不相屬，今漢王得為天子，橫乃降為亡虜，要去北面朝謁漢帝，豈不可恥！況我曾烹殺人兄，乃欲與伊弟並肩事主，就使他震懾主威，不敢害我，我難道就好無愧麼？漢帝必欲召我，無非欲見我一面，汝可割下我首，速詣洛陽，此去不過三十里，形容尚可相認，不致腐敗。我已國破家亡，死也罷了！」二客大驚，方欲勸阻，那知橫已拔劍在手，刎頸喪生。總之是不肯降漢。漢使坐在外面，並未聞知，及聽到二客哭聲，慌忙趨過一看，見二客撫著橫屍，正在悲慟。當下問明原委，由二客泣述橫言。漢使也覺沒法，只好將橫首割下，令二客捧著，帶同入都，報知高祖。高祖即傳令二客入見，二客捧呈橫首，高祖約略一瞧，面目如生，尚餘英氣，不由的歎息道：「我知道了！田橫等兄弟三人，起自布衣，相繼稱王，好算是當今賢士。今乃慷慨就死，不肯屈節，可惜可惜！」說罷也為流涕。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-012', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-013', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 13, 'narrative', 'carried', '[]'::jsonb, '二客尚跪在座前，高祖命他起來，各授都尉。二客雖然稱謝，卻沒有甚麼喜容，怏怏退出。高祖又遣發士卒二千人，為橫築墓，並令收殮橫屍，將首縫上，即用王禮安葬，送窆墓中。二客送至葬處，大哭一場，就在墓旁挖穿二穴，拔劍自刺，僕入穴中。當有人再行報聞，高祖越加驚歎，復遣有司馳詣墓所，出屍棺殮，妥為營葬。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-014', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 14, 'narrative', 'carried', '[]'::jsonb, '待葬畢報命，高祖道：「田橫自殺，二客同殉，卻是一種異事。但聞得海島中，尚有五百多人，若統似二客忠賢，為橫效死，豈不是一大隱患麼？」乃復遣使馳赴海島，詐稱田橫已受封爵，特來相招。漢高但知使詐，無怪田橫等寧死不降。島中五百餘人，信為真言，一齊起行，同至洛陽。既入漢都，才知橫及二客死耗，免不得涕淚交橫，遂共至田橫墓前，且拜且哭，並湊成一曲薤露歌，聊當哀詞。歌哭以後，統皆自殺。至今河南省偃師縣西十五里，尚存田橫墓，就是薤露歌，亦流傳千古。薤露二字的意義，謂人生如薤上露，容易晞滅。後世常稱是歌為挽逝歌，這且擱過不提。');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-014', 'luoyang', 1);
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-015', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 15, 'narrative', 'carried', '[]'::jsonb, '且說漢使既與五百人同來，本擬引他入朝，偏五百人自去謁墓，同時殉主，不得不據實入奏。高祖且驚且喜，仍令吏役一律掩埋。繼思田橫門客，尚且如此忠義，那項王手下的遺將，保不住暗中號召，與我反對，仔細記憶，想到季布鍾離昧二人，嗣復回思睢水戰敗時，季布追趕甚急，險些兒遭他毒手，現在要將他緝獲，醢為肉醬，方足泄恨。因再懸賞千金，購拿季布，如有藏匿不報，罪及三族。這道命令申行出去，那一個不思得賞，那一個還敢窩留。究竟季布遁往何處？原來是在濮陽周家。周家與季布交好多年，所以將布收留。旋聞漢廷懸賞緝拿，並有罪及三族的厲禁，也不覺慌急起來。當下想出一法，令布薙去頭髮，套環入頸，偽充髡鉗刑犯，引至魯朱家處，賣做奴僕。髡鉗為奴，是秦朝遺制，漢仍之。朱家是個著名大俠，向與周氏相識，明知他不是販奴，特欲保全此人，有意轉托。若非依言收買，怎好算得濟困扶危？於是將季布看了一番，問明身價，立即交付，送出周氏，然後再盤問季布數語。季布閱人已多，見他英姿豪爽，與眾不同，已料是一位義士，可以求救，因也吞吞吐吐，說了一篇悲婉的吁詞。朱家不待說明，便知除季布外，別無他人，因即買置田舍，使布經營，自己扮做商人模樣，逕往洛陽，替布設法去了。小子有詩贊道：');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-015', 'puyang', 1);
