INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-016', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 16, 'narrative', 'carried', '[]'::jsonb, '挺身入洛救人危，智勇深沈世獨推﹔');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-017', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 17, 'narrative', 'carried', '[]'::jsonb, '「游俠傳」中膺首席，大名留與後生知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-018', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 18, 'aside', 'carried', '[]'::jsonb, '欲知朱家如何救布，待看下回便知。');
INSERT INTO passages (id, work, juan, year_bce, year_label, ganzhi, entry_no, kind, date_source, months, text) VALUES ('yy-032-019', '前漢演義', 32, 202, '第32回·繫於「劉邦即皇帝位」', '', 19, 'commentary', 'carried', '[]'::jsonb, '韓信身為大將，能挫項王於垓下，而不能防一漢高，前在修武，被奪軍符，至定陶駐軍，復由漢高馳入軍營，片語相傳，立取帥印，何其易也！且易齊為楚，倉猝改封，而韓信不能不去，此由漢高能用善謀，操縱有方，故信無從反抗耳。及汜水稱尊，信實為勸進之領袖，前此懷疑而不來，後此獻媚而不恤，自相矛盾，皆入漢祖之術中，漢祖其真雄主哉！獨田橫自居海島，不肯事漢，應詔起行，所以保眾，入驛自剄，所以全名，至若二客同殉，五百人亦並捐軀，其平日信義之相孚，更可知矣。大丈夫雖忠不烈，視死如歸，若田橫諸人，其庶幾乎！');
INSERT INTO passage_places (passage_id, place_id, mentions) VALUES ('yy-032-019', 'gaixia', 1);
