INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('dazexiang', '大澤鄉起義', 209, 7, -208.25, 'dazexiang', '戍卒九百人屯大澤鄉，遇雨失期，陳勝、吳廣斬尉起事。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'tj-007-209-03', '…陽城人陳勝、陽夏人吳廣起兵於蘄。是時，發閭左戍漁陽，九百人屯大澤鄉，陳勝、吳廣皆為屯長。會天大雨，道不通，度已失期。失期，法皆斬。陳勝、吳廣因天下之愁怨，乃殺將尉，召令徒屬曰；「公等皆失期當斬，假令毋斬，而…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'sj-048-002', '二世元年七月，發閭左適戍漁陽，九百人屯大澤鄉。陳勝、吳廣皆次當行，為屯長。會天大雨，道不通，度已失期。失期，法皆斬。陳勝、吳廣乃謀曰：「今亡亦死，舉大計亦死，等死，死國可乎？」陳勝曰：…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'sj-048-003', '…，稱大楚。為壇而盟，祭以尉首。陳勝自立為將軍，吳廣為都尉。攻大澤鄉，收而攻蘄。蘄下，乃令符離人葛嬰將兵徇蘄以東。攻銍、酇、苦、柘、譙皆下之。行收兵。比至陳，車六七百乘，騎千餘，卒數萬人。攻陳，陳守令皆不在，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'yy-009-007', '好幾日到了大澤鄉，距漁陽城尚數千里，適值天雨連綿，沿途多阻。江南北本是水鄉，大澤更為低窪，一望瀰漫，如何過去？沒奈何就地駐紮，待至天色晴霽，方可啟程。偏偏雨…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'yy-009-009', '…料他待旦出售，便將帛書塞入魚口。待魚汲入腹中，勝乃悄悄回營。大澤鄉本乏市集，自經屯卒留駐，各漁家得了魚蝦，統向營中兜銷，所以這魚即被營兵買著，得中勝計。至若狐嗥一節，也是陳勝計劃，囑令吳廣乘夜潛出，帶著燈籠…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dazexiang', 'yy-009-012', '檄文既發，就率眾出略大澤鄉。鄉中本有三老，又有嗇夫，見第二回。聽得陳勝造反，早已逃去。勝即把大澤鄉占住，作為起事的地點。居民統皆散走，家中留有耜頭鐵耙等類，俱被大眾掠…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('zhangchu', '陳勝稱王，號張楚', 209, 7, -208.25, 'chen', '陳勝據陳，自立為王，國號張楚。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'tj-007-209-03', '…帝業成矣。今獨王陳，恐天下懈也。」陳涉不聽，遂自立為王，號「張楚」。當是時，諸郡縣苦秦法，爭殺長吏以應涉。謁者使從東方來，以反者聞。二世怒，下之吏。後使者至，上問之，對曰：「群盜鼠竊狗偷，郡守、尉方逐捕…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'sj-008-009', '秦二世元年秋，陳勝等起蘄，至陳而王，號為「張楚」。諸郡縣皆多殺其長吏以應陳涉。沛令恐，欲以沛應涉。掾、主吏蕭何、曹參乃曰：「君為秦吏，今欲背之，率沛子弟，恐不聽。願君召諸亡在外者，可得數…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'sj-048-003', '…無道，誅暴秦，復立楚國之社稷，功宜為王。」陳涉乃立為王，號為張楚。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'yy-010-004', '…安身，再作計較，乃留住陳勝麾下，充作參謀。勝竟自立為王，國號張楚，隱寓張大楚國的意思。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'yy-010-006', '…疆，一見如故，竟不待勝命，擅立襄疆為楚王。嗣得陳勝文書，內有張楚王字樣，始知勝已稱王，不能另立襄疆，自悔一時鹵莽，潛圖變計。湊巧陳勝命令，又復頒到，叫他領兵還陳，他越恐陳勝動疑，竟將襄疆殺死，持首還報。果…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'yy-013-001', '卻說陳勝為張楚王，曾遣魏人周市，北略魏地。見前文第十回。市引兵至狄城，狄令擬嬰城固守。適有故齊王遺族田儋，充當城守，獨與從弟田榮田橫等，潛謀自立。當即想出…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('zhangchu', 'yy-014-001', '…罷休，仍然追殺過來。文勢窮力竭，無可奈何，便即拚生自刎，報了張楚王的知遇。士為知己者死，還算不負。');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('pei_rise', '劉邦起兵於沛', 209, 9, -208.08333333333334, 'pei', '沛中父老殺沛令，迎劉季，立為沛公。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'tj-007-209-03', '…〔巖石〕之間，數有奇怪；沛中子弟聞之，多欲附者。及陳涉起，沛令欲以沛應之。掾、主吏蕭何、曹參曰：「君為秦吏，今欲背之，率沛子弟，恐不聽。願君召諸亡在外者，可得數百人，因劫眾，眾不敢不聽。」乃令樊噲召劉季…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'sj-008-009', '…等起蘄，至陳而王，號為「張楚」。諸郡縣皆多殺其長吏以應陳涉。沛令恐，欲以沛應涉。掾、主吏蕭何、曹參乃曰：「君為秦吏，今欲背之，率沛子弟，恐不聽。願君召諸亡在外者，可得數百人，因劫眾，眾不敢不聽。」乃令樊噲…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'sj-008-010', '於是樊噲從劉季來。沛令後悔，恐其有變，乃閉城城守，欲誅蕭、曹。蕭、曹恐，踰城保劉季。劉季乃書帛射城上，謂沛父老曰：「天下苦秦久矣。今父老雖為沛令守，諸侯并起，今屠…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'yy-011-009', '…字，單名為雉。呂媼聞言動怒道：「君謂此兒生有貴相，必配貴人，沛令與君交好，求婚不允，為何無端許與劉季？難道劉季便是貴人麼？」呂公道：「這事非兒女子所能知，我自有慧鑒，斷不致誤！」呂媼尚有煩言，畢竟婦人勢力…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'yy-012-004', '…，故叫他召邦。果然噲已知邦住處，竟至芒碭山中，與邦相見，具述沛令情意。邦在山中已八九月，收納壯士，約有百人，既聞沛令相招，便帶領家屬徒眾，與噲同詣沛縣。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'yy-012-006', '天下苦秦久矣！今沛縣父老，雖為沛令守城，然諸侯並起，必且屠沛。為諸父老計，不若共誅沛令，改擇子弟可立者以應諸侯，則家室可完！不然，父子俱屠無益也。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pei_rise', 'yy-012-008', '邦集眾會議，商及善後方法，眾願推邦為沛令，背秦自主。邦慨然道：「天下方亂，群雄並起，今若置將不善，一敗塗地，悔何可追？我非敢自愛，恐德薄能鮮，未能保全父老子弟，還請另擇賢能，方足圖…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('wu_rise', '項梁、項籍起兵於吳', 209, 9, -208.08333333333334, 'wu', '項梁斬會稽守殷通，得精兵八千。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wu_rise', 'tj-007-209-03', '…略知其意，又不肯竟學。籍長八尺餘，力能扛鼎，才器過人。會稽守殷通聞陳涉起，欲發兵以應涉，使項梁及桓楚將。是時，桓楚亡在澤中。梁曰：「桓楚亡，人莫知其處，獨籍知之耳。」梁乃誡籍持劍居外，復入，與守坐，曰：「…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wu_rise', 'yy-012-013', '到了陳勝發難，東南擾攘，梁正思起應，忽由會稽郡守殷通，差人前來，召梁入議。梁奉召即往，謁見郡守，殷通下座相迎，且引入密室，低聲與語道：「蘄陳失守，江西皆叛，看來是天意亡秦，不可禁止了。我聞先發…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wu_rise', 'yy-012-014', '…。並申誡道：「毋得有誤！」話裡藏刀。籍唯唯如命。梁即入見郡守殷通，報稱姪兒已到，聽候公命。殷通道：「現在何處？」梁答道：「籍在門外，非得公命，不敢擅入。」殷通聞言，忙呼左右召籍。籍在外佇候傳呼，一聞內召，…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('huaiwang', '立楚懷王孫心', 208, 6, -207.33333333333334, 'xue', '項梁從范增之計，求得楚懷王孫心於民間，立為楚懷王。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('huaiwang', 'tj-008-208-14', '…，以君世世楚將，為能復立楚之後也。」於是項梁然其言，乃求得楚懷王孫心於民間，為人牧羊。夏，六月，立以為楚懷王，從民望也。陳嬰為上柱國，封五縣，與懷王都盱眙。項梁自號為武信君。張良說項梁曰：「君已立楚後，而韓…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('huaiwang', 'sj-007-006', '…者，以君世世楚將，為能復立楚之後也。」於是項梁然其言，乃求楚懷王孫心民間，為人牧羊，立以為楚懷王，從民所望也。陳嬰為楚上柱國，封五縣，與懷王都盱台。項梁自號為武信君。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('huaiwang', 'sj-008-012', '…月餘，項羽已拔襄城還。項梁盡召別將居薛。聞陳王定死，因立楚後懷王孫心為楚王，治盱臺。項梁號武信君。居數月，北攻亢父，救東阿，破秦軍。齊軍歸，楚獨追北，使沛公、項羽別攻城陽，屠之。軍濮陽之東，與秦軍戰，破之。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('huaiwang', 'sj-048-018', '…君黥布之兵相收，復擊秦左右校，破之青波，復以陳為楚。會項梁立懷王孫心為楚王。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('huaiwang', 'yy-015-004', '…人四出，訪求楚裔，可巧民間有一牧童，替人看羊，查問起來，確是楚懷王孫，單名是個心字，當即報知項梁。梁即派遣大吏數人，奉持輿服，刻日往迎。說也奇怪，那牧童得了奇遇，倒也毫不驚慌，就將破布衣服脫下，另換法服，居然…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('dingtao', '項梁敗死定陶', 208, 9, -207.08333333333334, 'dingtao', '章邯夜襲楚軍於定陶，項梁戰死。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'tj-008-208-15', '…復與章邯戰，又破之。章邯復振，守濮陽，環水。沛公、項羽去，攻定陶。八月，田榮擊逐齊王假，假亡走楚，田角亡走趙。田間前救趙，因留不敢歸。田榮乃立儋子市為齊王，榮相之，田橫為將，平齊地。章邯兵益盛，項梁數使…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'tj-008-208-17', '項梁已破章邯於東阿，引兵西，北至定陶，再破秦軍。項羽、沛公又與秦軍戰於雍丘，大破之，斬李由。項梁益輕秦，有驕色。宋義諫曰：「戰勝而將驕卒惰者，敗。今卒少惰矣，秦兵日益，臣為君畏…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'sj-007-007', '…別攻城陽，屠之。西破秦軍濮陽東，秦兵收入濮陽。沛公、項羽乃攻定陶。定陶未下，去，西略地至雝丘，大破秦軍，斬李由。還攻外黃，外黃未下。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'sj-007-008', '項梁起東阿，西，（北）［比］至定陶，再破秦軍，項羽等又斬李由，益輕秦，有驕色。宋義乃諫項梁曰：「戰勝而將驕卒惰者敗。今卒少惰矣，秦兵日益，臣為君畏之。」項梁弗聽。乃使宋義使於…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'sj-008-014', '…秦軍，有驕色。宋義諫，不聽。秦益章邯兵，夜銜枚擊項梁，大破之定陶，項梁死。沛公與項羽方攻陳留，聞項梁死，引兵與呂將軍俱東。呂臣軍彭城東，項羽軍彭城西，沛公軍碭。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'yy-015-011', '…眾西追章邯，再破秦軍，邯敗入濮陽，乘城固守。梁攻城不克，移攻定陶。定陶城內亦有重兵守著，兀自支撐得住。梁自駐定陶城下，指揮軍事，另命沛公項羽，往西略地。兩人行至雍邱，卻遇秦三川守李由引兵迎敵，項羽一馬當先…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'yy-016-004', '…建立戰功，每日派遣偵騎，探聽項梁軍情，以便乘隙定計。項梁駐兵定陶城下，適值霪雨兼旬，不便力攻。沛公項羽，自雍邱還攻外黃，亦為雨所阻，但把外黃城圍住，為持久計。項梁屢勝而驕，既不將兩軍召回，又復逐日寬懈，但…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'yy-016-008', '…巡卒，也聽他散處，不加檢查。時當秋季，淒風苦雨，連宵不止，把定陶城下的幾座楚營，直壓得黑氣瀰漫，不見天日。便是不祥之兆。楚軍也無人占候，但知晝餐夜宿，蹉跎過去。一夕俱安睡營中，忽聞營外喊殺連天，好似千軍萬…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('dingtao', 'yy-016-011', '…行，反弄得懷王左右為難，俯首沈吟。項羽又進說道：「叔父梁戰死定陶，仇尚未報，末將誼關子姪，誓不甘休！今願請兵數千，搗入秦關，復仇雪恥，就使劉季願往，末將亦決與同行，前驅殺賊。」懷王聽著，方徐聲道：「兩將能…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('julu', '鉅鹿之戰', 207, 12, -206.83333333333334, 'julu', '項羽渡河，沈船破釜，九戰大破秦軍於鉅鹿。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('julu', 'tj-008-207-05', '…章邯甬道，王離軍乏食。陳餘復請兵。項羽乃悉引兵渡河，皆沈船，破釜、甑，燒廬舍，持三日糧，以示士卒必死，無一還心。於是至則圍王離，與秦軍遇，九戰，大破之，章邯引兵卻。諸侯兵乃敢進擊秦軍，遂殺蘇角，虜王離；涉…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('julu', 'sj-007-012', '…渡河，救鉅鹿。戰少利，陳餘復請兵。項羽乃悉引兵渡河，皆沈船，破釜甑，燒廬舍，持三日糧，以示士卒必死，無一還心。於是至則圍王離，與秦軍遇，九戰，絕其甬道，大破之，殺蘇角，虜王離。涉閒不降楚，自燒殺。當是時，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('julu', 'yy-017-003', '…期，先使歸報，一面驅動大隊，悉數渡河。既至對岸，便下令沈船，破釜甑，燒庐舍，但令軍士持三日糧，與秦兵決一死戰，不求生還。將士等到了絕地，也曉得有進無退，個個懷著必死的念頭，向前馳去。');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('bashang', '子嬰降，約法三章', 206, 10, -206.0, 'bashang', '沛公至霸上，秦王子嬰降；還軍霸上，與關中父老約法三章。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('bashang', 'tj-009-206-01', '…老苦秦苛法久矣！吾與諸侯約，先入關者王之，吾當王關中。與父老約法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法，諸吏民皆案堵如故。凡吾所以來，為父老除害，非有所侵暴，無恐。且吾所以還軍霸上，待諸侯至而定約束耳。…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('bashang', 'tj-009-206-08', '…三人，秦民莫愛也。大王之入武關，秋毫無所害；除秦苛法，與秦民約法三章；秦民無不欲得大王王秦者。於諸侯之約，大王當王關中，民鹹知之；大王失職入漢中，秦民無不恨者。今大王舉而東，三秦可傳檄而定也。」於是漢王大喜，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('bashang', 'yy-019-011', '…，先入秦關，便可稱王，今我已入關中，當為秦王。從此與諸父老等約法三章：殺人處死，傷人及盜抵罪，外如亡秦苛法，一律除去，凡官吏人民，統可安枕，不必驚惶，我所以還軍霸上，不過待別軍到來，共定約束，餘無他意。」父老…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('bashang', 'yy-020-005', '…得先入關破秦。為念秦法暴酷，民不聊生，不得不立除苛禁，但與民約法三章，此外毫無更改，靜待將軍主持，將軍不先示邦，說明入關期間，邦如何得知？只好派兵守關，嚴備盜賊。今日幸見將軍，使邦得明心跡，尚復何恨？惟聞有小…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('bashang', 'yy-022-001', '…服，怎肯誠心歸附？惟大王首入武關，秋毫無犯，除秦苛法，與秦民約法三章，秦民無不欲大王王秦，且義帝原約，無人不知，大王被迫西行，不但大王怨恨項王，就是秦民亦無不懷憤！大王若東入三秦，傳檄可定，三秦既下，便好進圖…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('xinan', '新安坑卒', 206, 11, -205.91666666666666, 'xinan', '楚軍夜擊坑秦降卒二十餘萬人於新安城南。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xinan', 'tj-009-206-02', '…獨與章邯、長史欣、都尉翳入秦。」於是楚軍夜擊坑秦卒二十餘萬人新安城南。或說沛公曰：「秦富十倍天下，地形強。聞項羽號章邯為雍王，王關中，今則來，沛公恐不得有此。可急使兵守函谷關，無內諸侯軍；稍征關中兵以自…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xinan', 'tj-009-206-08', '…王為秦將，將秦子弟數歲矣，所殺亡不可勝計；又欺其眾降諸侯，至新安，項王詐坑秦降卒二十餘萬，唯獨邯、欣、翳得脫。秦父兄怨此三人，痛入骨髓。今楚強以威王此三人，秦民莫愛也。大王之入武關，秋毫無所害；除秦苛法，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xinan', 'sj-007-015', '到新安。諸侯吏卒異時故繇使屯戍過秦中，秦中吏卒遇之多無狀，及秦軍降諸侯，諸侯吏卒乘勝多奴虜使之，輕折辱秦吏卒。秦吏卒多竊言曰：「章將軍等詐吾屬降諸…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xinan', 'yy-019-012', '項羽自收服章邯，由東入西，行至新安，驀聞秦兵有謀變消息，又惹動項羽一片殺機。原來秦朝盛時，各處吏卒，徵調入都，往往為秦兵所虐待，此次聯同項羽，戰勝攻取，做了上手，那秦兵反為降…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xinan', 'yy-019-013', '…預備妥當，待到夜半，趁著月色無光，引兵出營，往襲降兵。降兵在新安城南，靠山立寨，沈沈夜睡。英布指麾部眾，把他三面圍住，單留後面山路，故意縱他逃走。又分兵與蒲將軍，令他上山伏著，待有秦兵入山，便用矢石拋發，…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('hongmen', '鴻門宴', 206, 12, -205.83333333333334, 'hongmen', '沛公從百餘騎見項羽於鴻門，范增舉玦，項莊舞劍。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'tj-009-206-02', '…饗士卒，期旦日擊沛公軍。當是時，項羽兵四十萬，號百萬，在新豐鴻門；沛公兵十萬，號二十萬，在霸上。范增說項羽曰：「沛公居山東時，貪財好色。今入關，財物無所取，婦女無所幸，此其志不在小。吾令人望其氣，皆為龍虎…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'sj-007-016', '…：「旦日饗士卒，為擊破沛公軍！」當是時，項羽兵四十萬，在新豐鴻門，沛公兵十萬，在霸上。范增說項羽曰：「沛公居山東時，貪於財貨，好美姬。今入關，財物無所取，婦女無所幸，此其志不在小。吾令人望其氣，皆為龍虎，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'sj-007-018', '沛公旦日從百餘騎來見項王，至鴻門，謝曰：「臣與將軍戮力而攻秦，將軍戰河北，臣戰河南，然不自意能先入關破秦，得復見將軍於此。今者有小人之言，令將軍與臣有郤。」項王曰：「此沛公…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'sj-007-019', '…其怒，不敢獻。公為我獻之」張良曰：「謹諾。」當是時，項王軍在鴻門下，沛公軍在霸上，相去四十里。沛公則置車騎，脫身獨騎，與樊噲、夏侯嬰、靳彊、紀信等四人持劍盾步走，從酈山下，道芷陽閒行。沛公謂張良曰：「從此…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'sj-008-023', '…活張良，夜往見良，因以文諭項羽，項羽乃止。沛公從百餘騎，驅之鴻門，見謝項羽。項羽曰：「此沛公左司馬曹無傷言之。不然，籍何以生此！」沛公以樊噲、張良故，得解歸。歸，立誅曹無傷。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-019-015', '時已天暮，就在戲地西首，紮下營盤。這地方叫作鴻門，羽在營中設宴，大饗士卒，且與將佐商議，對付沛公。有主張決裂的，有主張從緩的，羽亦不能自決，忽來了一個使人，說是沛公左司馬曹無傷，有機密事傳…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-019-016', '…燄無比。沛公只有兵十萬人，比那項羽部下，四成中僅得一成。並且鴻門霸上，相距止四十里，又沒有甚麼險阻，羽兵一發即至，如何遮攔？眼見得一強一弱，一眾一寡，沛公生死關頭，就在旦夕間了。那知人有千算，天教一算，天…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-020-001', '…鞭，直至沛公營前，求見張良。好在沛公營內，聞得項羽入關，駐紮鴻門，也恐他夜來襲擊，所以格外戒嚴，不敢安睡。張良也憑燭坐著，聽說項伯來會，料有密事，急忙出迎。項伯入見張良，即與悄語道：「快走快走！明日便要遇…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-020-010', '過了數日，項羽自鴻門入咸陽，屠戮居民，殺死秦降王子嬰，及秦室宗族，所有秦宮婦女，秦庫貨幣，一古腦兒劫取出來，自己收納一半，餘多分給將士。最可怪的是將咸陽宮室，付…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-021-001', '…封諸將，想了多時，自己不能決定，只好仍請范增商議。范增雖為了鴻門一役，有些懊惱，但總不忍遽去，尚為項氏效忠。血氣既衰，戒之在得，增何不三復斯言，潔身早去。既聞項羽召請，便即入帳相見。項羽與增密議道：「我欲…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('hongmen', 'yy-021-006', '…發，等候韓王成歸國。原來項羽入關，韓王成未曾相隨，嗣經羽進駐鴻門，號令諸王，韓王成方才往見。羽雖嫌他無功，終究是無罪可加，不得不許復舊封。只有一語相囑，叫他召回張良。及韓王成與良接洽，良亦知項羽加忌，不令…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('xianyang_burn', '屠咸陽，燒秦宮室', 206, 12, -205.83333333333334, 'xianyang', '項羽引兵西屠咸陽，殺子嬰，燒秦宮室，火三月不滅。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xianyang_burn', 'tj-009-206-02', '…軍，立誅殺曹無傷。居數日，項羽引兵西，屠咸陽，殺秦降王子嬰，燒秦宮室，火三月不滅。收其貨寶、婦女而東。秦民大失望。韓生說項羽曰：「關中阻山帶河，四塞之地，地肥饒，可都以霸。」項羽見秦宮室皆已燒殘破，又心思東歸…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xianyang_burn', 'sj-007-020', '居數日，項羽引兵西屠咸陽，殺秦降王子嬰，燒秦宮室，火三月不滅；收其貨寶婦女而東。人或說項王曰：「關中阻山河四塞，地肥饒，可都以霸。」項王見秦宮皆以燒殘破，又心懷思欲東歸，曰：「富貴不歸故鄉…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xianyang_burn', 'yy-020-010', '…劫取出來，自己收納一半，餘多分給將士。最可怪的是將咸陽宮室，付諸一炬，無論什麼信宮極廟，及三百餘里的阿房宮，統共做了一個火堆。今日燒這處，明日燒那處，煙燄蔽天，連宵不絕，一直過了三個月，方才燒完。可憐秦朝數十…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('fenfeng', '項羽分封十八王', 206, 2, -205.66666666666666, 'pengcheng', '項羽自立為西楚霸王，都彭城，分天下王諸將。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('fenfeng', 'tj-009-206-03', '…游。」乃徙義帝於江南，都郴。二月，羽分天下王諸將。羽自立為西楚霸王，王梁、楚地九郡，都彭城。羽與范增疑沛公，而業已講解，又惡負約，乃陰謀曰：「巴、蜀道險，秦之遷人皆居之。」乃曰：「巴、蜀亦關中地也。」故立沛…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('fenfeng', 'sj-007-021', '…南皮，故因環封三縣。番君將梅鋗功多，故封十萬戶侯。項王自立為西楚霸王，王九郡，都彭城。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('fenfeng', 'sj-008-026', '正月，項羽自立為西楚霸王，王梁、楚地九郡，都彭城。負約，更立沛公為漢王，王巴、蜀、漢中，都南鄭。三分關中，立秦三將：章邯為雍王，都廢丘；司馬欣為塞王，都櫟陽；董翳為…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('fenfeng', 'yy-021-004', '項羽自稱西楚霸王，擬還都彭城，據有梁楚九郡。一面派遣將士，迫義帝遷往長沙，定都郴地。郴音琛。郴地僻近南嶺，比不得彭地繁庶。羽欲自去建都，怎肯使義帝久住，所以…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('chencang', '還定三秦（陳倉）', 206, 8, -205.16666666666666, 'chencang', '漢王從故道出，襲雍，敗章邯於陳倉。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'tj-009-206-09', '八月，漢王引兵從故道出，襲雍；雍王章邯迎擊漢陳倉。雍兵敗，還走；止，戰好畤，又敗，走廢丘。漢王遂定雍地，東至咸陽，引兵圍雍王於廢丘，而遣諸將略地。塞王欣、翟王翳皆降，以其地為渭南、河上、上…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'sj-008-029', '八月，漢王用韓信之計，從故道還，襲雍王章邯。邯迎擊漢陳倉，雍兵敗，還走；止戰好畤，又復敗，走廢丘。漢王遂定雍地。東至咸陽，引兵圍雍王廢丘，而遣諸將略定隴西、北地、上郡。令將軍薛歐、王吸出武關，因王…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'yy-021-002', '…亦如蕭何言，但請沛公厚賂項伯，使他轉達項羽，求漢中地。為暗渡陳倉伏案。沛公乃取出金幣，派人遣遺項伯，乞將漢中地加封。項伯已陰助沛公，且有金幣可取，樂得代為說情。項羽竟依了項伯，把漢中地加給沛公，且改封沛公…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'yy-022-002b', '…道已經燒絕，不便行軍。漢王卻早由張良定計，叫他明修棧道，暗渡陳倉。當下召入韓信，問明出路，信所言適與張良相合。漢王鼓掌道：「英雄所見，畢竟略同。」遂派了兵士數百人，佯去修築棧道，自與韓信率領三軍，悄悄的出…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'yy-022-003', '時當仲秋，天高氣爽，將士等各願東歸，日夜趲程，由故道直達陳倉。雍王章邯，本奉項王密囑，堵住漢中，作為第一重門戶，平時亦派兵巡察，但恐漢王出來。不過他算差一著，總道漢王東出，必須經過棧道，棧道未曾修築，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('chencang', 'yy-022-004', '到了八月中旬，忽有急報傳到，乃是漢兵已抵陳倉。章邯尚疑是說謊，顧語左右道：「棧道並未修好，漢兵從何處出來，難道真能插翅高飛麼？」話雖如此，但也不得不再派幹員，探聽明白。未幾果有陳倉逃兵…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('pengcheng', '彭城之戰', 205, 4, -204.5, 'pengcheng', '項羽以精兵三萬回擊彭城，漢卒十餘萬人入睢水，水為之不流。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pengcheng', 'tj-009-205-14', '…相隨入穀、泗水，死者十餘萬人。漢卒皆南走山，楚又追擊至靈壁東睢水上；漢軍卻，為楚所擠，卒十餘萬人皆入睢水，水為之不流。圍漢王三匝。會大風從西北起，折木，發屋，揚沙石，窈冥晝晦，逢迎楚軍，大亂壞散，而漢王乃…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pengcheng', 'sj-007-025', '…隨入穀、泗水，殺漢卒十餘萬人。漢卒皆南走山，楚又追擊至靈壁東睢水上。漢軍卻，為楚所擠，多殺，漢卒十餘萬人皆入睢水，睢水為之不流。圍漢王三匝。於是大風從西北而起，折木發屋，揚沙石，窈冥晝晦，逢迎楚軍。楚軍大…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pengcheng', 'sj-008-034', '…。項羽聞之，乃引兵去齊，從魯出胡陵，至蕭，與漢大戰彭城靈壁東睢水上，大破漢軍，多殺士卒，睢水為之不流。乃取漢王父母妻子於沛，置之軍中以為質。當是時，諸侯見楚彊漢敗，還皆去漢復為楚。塞王欣亡入楚。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('pengcheng', 'yy-024-001', '…，南竄入山，又為楚兵所追，殺斃了好幾萬。餘眾至靈璧縣東，競渡睢水，水中溺死了許多，岸上擠落了許多，約莫有十多萬人，隨波漂積，睢水為之不流。前日喝得好酒，今日要他去吸清流了。');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('xingyang', '滎陽之圍，紀信誑楚', 204, 5, -203.41666666666666, 'xingyang', '紀信乘王車出東門詐降，漢王得以出西門遁去。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'tj-010-204-05', '…王自為之，願請骸骨！」歸，未至彭城，疽發背而死。五月，將軍紀信言於漢王曰：「事急矣！臣請誑楚，王可以間出。」於是陳平夜出女子東門二千餘人，楚因而四面擊之。紀信乃乘王車，黃屋左纛，曰：「食盡，漢王降楚。」…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'sj-007-029', '漢將紀信說漢王曰：「事已急矣，請為王誑楚為王，王可以閒出。」於是漢王夜出女子滎陽東門被甲二千人，楚兵四面擊之。紀信乘黃屋車，傅左纛，曰：「城中食盡，…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'sj-008-040', '漢軍絕食，乃夜出女子東門二千餘人，被甲，楚因四面擊之。將軍紀信乃乘王駕，詐為漢王，誑楚，楚皆呼萬歲，之城東觀，以故漢王得與數十騎出西門遁。令御史大夫周苛、魏豹、樅公守滎陽。諸將卒不能從者，盡在城中。周苛…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'yy-027-008', '…死將軍，慷慨過人，情願粉骨碎身，仰報知遇。這人為誰？乃是漢將紀信。當下入見漢王，請屏左右，悄悄相告道：「大王困守孤城，已有數月，現在敵勢甚盛，城內兵少糧空，定難久守，為大王計，不如脫圍他去，方得自全。但敵…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'yy-027-011', '…汝是何人，敢來冒充漢王？」車中人才應聲出答道：「我乃大漢將軍紀信。」說了一語，又復停住。一語已足千秋。項王越覺咆哮，大罵不止。紀信反呵呵笑說道：「項羽匹夫，仔細聽著！我王豈肯降汝？今已早出滎陽，往招各路兵…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'yy-027-014', '…城，誤人耳目，西向成臯馳去，不見楚兵追擊，幸得安抵成臯。旋聞紀信被焚，且悲且恨，遂向關中招集兵馬，再擬出救滎陽，替信報仇。可巧有一轅生，入白漢王道：「大王不必再往滎陽，但教出兵武關，南向宛洛，項王必慮大王…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('xingyang', 'yy-028-003', '…內，漢王不免驚心。暗思滎陽已失，成臯恐亦難守，哪裡還有第二個紀信，再來替死？因此帶同夏侯嬰，潛開北門，預先出走。及至諸將得知，漢王已經去遠，彼此不願再留，遂陸續出城追去。英布獨力難支，索性也棄城北走，成臯…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('guangwu', '廣武對峙', 203, 10, -203.0, 'guangwu', '楚漢臨廣武之間而軍，相守數月。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'tj-010-203-02', '…玉、貨賂，咎及司馬欣皆自剄汜水上。漢王引兵渡河，復取成皋，軍廣武，就敖倉食。項羽下梁地十餘城，聞成皋破，乃引兵還。漢軍方圍鍾離昧於滎陽東，聞羽至，盡走險阻。羽亦軍廣武，與漢相守。數月，楚軍食少。項王患之…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'tj-010-203-05', '…疾愈，西入關。至櫟陽，梟故塞王欣頭櫟陽市。留四日，復如軍，軍廣武。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'sj-007-032', '…燒楚積聚。項王東擊破之，走彭越。漢王則引兵渡河，復取成皋，軍廣武，就敖倉食。項王已定東海來，西，與漢俱臨廣武而軍，相守數月。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'sj-007-034', '…。漢王使人閒問之，乃項王也。漢王大驚。於是項王乃即漢王相與臨廣武閒而語。漢王數之，項王怒，欲一戰。漢王不聽，項王伏弩射中漢王。漢王傷，走入成皋。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'sj-008-048', '楚漢久相持未決，丁壯苦軍旅，老弱罷轉馕。漢王項羽相與臨廣武之閒而語。項羽欲與漢王獨身挑戰。漢王數項羽曰：「始與項羽俱受命懷王，曰先入定關中者王之，項羽負約，王我於蜀漢，罪一。秦項羽矯殺卿子冠軍而自尊…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'sj-008-049', '…櫟陽，存問父老，置酒，梟故塞王欣頭櫟陽市。留四日，復如軍，軍廣武。關中兵益出。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'yy-029-003', '…休息三日，漢王命向敖侖運粟，接濟軍糧。待糧已運至，復引兵出屯廣武，據險設營，阻住項王回軍，一面探聽齊地，專望齊地得平，便可調回韓信，共同御楚。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'yy-029-009', '…殺入圍中。漢兵慌忙退回，已喪亡了數百人，項王救出鍾離昧，進逼廣武，與漢王夾澗屯軍。廣武本是山名，東連滎澤，西接汜水，形勢險阻，山中有一斷澗，分峙兩峰，漢王就西邊築壘，依澗自固。項王即就東邊築壘，與漢相拒。…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'yy-030-005', '…漢王在成臯養病，已經告痊，復至櫟陽察視城守，勾留四日，仍馳抵廣武軍前。可巧韓信差來的軍弁，也到廣武，遂將書信呈上。漢王展閱未終，不禁大怒道：「我困守此地，日夜望他來助，他不來助我，還要想做齊王麼？」張良陳…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('guangwu', 'yy-030-008', '漢王固守廣武，又是數旬，日望韓信到來，信終不至。乃立英布為淮南王，使他再赴九江，截楚後路。一面貽書彭越，仍侵入梁地，斷楚糧道。佈置已定，尚恐項王糧盡欲回…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('honggou', '鴻溝議和', 203, 9, -202.08333333333334, 'honggou', '項羽與漢約，中分天下，割洪溝以西為漢，以東為楚。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('honggou', 'tj-010-203-12', '…兵擊楚，羽患之。漢遣侯公說羽請太公。羽乃與漢約，中分天下，割洪溝以西為漢，以東為楚。九月，楚歸太公、呂后，引兵解而東歸。漢王欲西歸，張良、陳平說曰：「漢有天下太半，而諸侯皆附；楚兵疲食盡，此天亡之時也。今…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('honggou', 'yy-030-010a', '…。項伯本是袒漢，樂得賣個人情，兩下議決，就滎陽東南二十里外的鴻溝，劃分界限，溝東屬楚，溝西屬漢。當由項王遣使，與侯公同報漢王，訂定約章，各無異言。所有迎還太公呂后的重差，仍然要勞煩侯公，侯公再偕楚使同行，…');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('gaixia', '垓下之圍', 202, 12, -201.83333333333334, 'gaixia', '項王至垓下，兵少食盡，夜聞漢軍四面皆楚歌。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'tj-011-202-01', '…六，舉九江兵迎黥布，並行屠城父，隨劉賈皆會。十二月，項王至垓下，兵少，食盡，與漢戰不勝，入壁；漢軍及諸侯兵圍之數重。項王夜聞漢軍四面皆楚歌，乃大驚曰：「漢皆已得楚乎？是何楚人之多也？」則夜起，飲帳中，悲…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'sj-007-039b', '…曰：「請今進兵。」韓信乃從齊往，劉賈軍從壽春并行，屠城父，至垓下。大司馬周殷叛楚，以舒屠六，舉九江兵，隨劉賈、彭越皆會垓下，詣項王。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'sj-007-040', '項王軍壁垓下，兵少食盡，漢軍及諸侯兵圍之數重。夜聞漢軍四面皆楚歌，項王乃大驚曰：「漢皆已得楚乎？是何楚人之多也！」項王則夜起，飲帳中。有美人名虞，常幸從…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'sj-008-051', '…九江兵而迎（之）武王，行屠城父，隨（何）劉賈、齊梁諸侯皆大會垓下。立武王布為淮南王。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'sj-008-052', '五年，高祖與諸侯兵共擊楚軍，與項羽決勝垓下。淮陰侯將三十萬自當之，孔將軍居左，費將軍居右，皇帝在後，絳侯、柴將軍在皇帝後。項羽之卒可十萬。淮陰先合，不利，卻。孔將軍、費將軍縱，楚兵不…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'yy-031-003', '…退。路上恐漢兵追襲，用了步步為營的兵法，依次退去。好容易到了垓下，遙聽得後面一帶，鼓聲馬聲吶喊聲，非常震響。當下登高西望，見漢兵踴躍追來，差不多與螞蟻相似，不禁仰天歎道：「好多漢兵，我悔前日不殺劉邦，養成…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'yy-031-004', '…無不立斃，因此漢兵左右避開，讓出一條血路，得使項王走脫，馳回垓下大營。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('gaixia', 'yy-031-009', '項王生平的愛幸，第一是烏騅馬，第二是虞美人，此番被圍垓下，已知死在目前，惟心中實不忍割捨美人駿馬，因此悲歌慷慨，嗚咽欷歔！虞姬在旁聽著，已知項王歌意，也即口占一詩道：');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('wujiang', '項羽自刎烏江', 202, 12, -201.83333333333334, 'wujiang', '烏江亭長艤船待，項王不肯渡，自刎而死。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wujiang', 'tj-011-202-01', '…謂其騎曰：「何如？」騎皆伏曰：「如大王言！」於是項王欲東渡烏江，烏江亭長艤船待，謂項王曰：「江東雖小，地方千里，眾數十萬人，亦足王也。願大王急渡！今獨臣有船，漢軍至，無以渡。」項王笑曰：「天之亡我，我何…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wujiang', 'sj-007-042', '於是項王乃欲東渡烏江。烏江亭長檥船待，謂項王曰：「江東雖小，地方千里，眾數十萬人，亦足王也。願大王急渡。今獨臣有船，漢軍至，無以渡。」項王笑曰：「天之亡我，我何…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wujiang', 'yy-031-014', '項王既得脫圍，走至烏江，卻值烏江亭長，泊船岸旁，請項王渡江過去。且敦促道：「江東雖小，地方千里，尚足自王，現惟臣有一船，願大王急渡！」項王聽了，笑對亭長道：用兩笑…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('wujiang', 'yy-032-001', '…感否？今河南省河陽縣有項羽墓，就是項羽自刎的地方，便系今日的烏江浦，在安徽省和縣東北，留有祠宇，號為西楚霸王廟，這且不必細述。');
INSERT INTO events (id, title, year_bce, month, sort_key, place_id, summary) VALUES ('emperor', '劉邦即皇帝位', 202, 2, -201.66666666666666, 'dingtao', '二月甲午，漢王即皇帝位於汜水之陽。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('emperor', 'tj-011-202-06', '諸侯王皆上疏請尊漢王為皇帝。二月甲午，王即皇帝位於汜水之陽。更王后曰皇后，太子曰皇太子；追尊先媼曰昭靈夫人。詔曰：「故衡山王吳芮，從百粵之兵，佐諸侯，誅暴秦，有大功；諸侯立以為王，項羽侵…');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('emperor', 'sj-008-053', '…。」漢王三讓，不得已，曰：「諸君必以為便，便國家。」甲午，乃即皇帝位汜水之陽。');
INSERT INTO event_citations (event_id, passage_id, snippet) VALUES ('emperor', 'yy-032-006', '…乃命太尉盧綰及博士叔孫通等擇吉定儀，就在汜水南面，郊天祭地，即漢帝位。文武百官，一齊朝賀，頒詔大赦，追尊先妣劉媼為昭靈夫人，立王後呂氏為皇后，王太子盈為皇太子。接連有諭旨二道，分封長沙閩粤二王，文云：');
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-01', 1, 209, 7, -208.25, 'dazexiang', 'dazexiang', '大澤鄉阻雨', '秋七月，負鹽北行，阻雨大澤鄉，道不通。有戍卒九百屯此，皆言失期當斬。是夜營中火起，不敢宿，棄鹽三斗而走。', '[{"item": "蓑笠", "action": "售", "qty": "20領", "amount": "+400錢"}, {"item": "鹽", "action": "棄", "qty": "3斗", "amount": "-150錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-02', 2, 209, 8, -208.16666666666666, 'chen', 'zhangchu', '陳市易張楚錢', '至陳。陳王已立，號張楚。市中糧價日高，軍吏收鐵器甚急。以布易粟，薄有贏。', '[{"item": "布", "action": "售", "qty": "10匹", "amount": "+800錢"}, {"item": "粟", "action": "購", "qty": "5石", "amount": "-600錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-03', 3, 209, 9, -208.08333333333334, 'pei', 'pei_rise', '沛縣城門', '九月過沛。父老殺沛令，立劉季為沛公，城門晝閉夜啟。售刀二十口於子弟兵。', '[{"item": "鐵刀", "action": "售", "qty": "20口", "amount": "+1200錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-04', 4, 208, 9, -207.08333333333334, 'dingtao', 'dingtao', '定陶夜火', '九月至定陶。章邯夜襲，項梁死。楚營潰散，貨車失其一。', '[{"item": "車", "action": "失", "qty": "1乘", "amount": "-2000錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-05', 5, 207, 12, -206.83333333333334, 'julu', 'julu', '鉅鹿觀戰', '十二月北販至鉅鹿。楚軍渡河，沈船破釜，諸侯軍皆壁上觀。賣草料於諸侯軍。', '[{"item": "芻藁", "action": "售", "qty": "50束", "amount": "+500錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-06', 6, 206, 10, -206.0, 'bashang', 'bashang', '霸上約法', '冬十月，隨楚軍入關，至霸上。沛公與父老約法三章，殺人者死，傷人及盜抵罪。秦民持牛羊酒食獻軍，軍中辭而不受。商旅得安，記之。', '[{"item": "酒", "action": "售", "qty": "4甕", "amount": "+320錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-07', 7, 206, 12, -205.83333333333334, 'hongmen', 'hongmen', '鴻門之宴', '十二月，項羽兵四十萬屯新豐鴻門。聞沛公來謝，宴罷，沛公從間道走霸上。是日軍中禁市。', '[]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-08', 8, 206, 12, -205.83333333333334, 'xianyang', 'xianyang_burn', '咸陽大火', '數日後，項羽屠咸陽，燒秦宮室，火三月不滅。所藏帛盡焚，此行虧甚。', '[{"item": "帛", "action": "焚", "qty": "12匹", "amount": "-1800錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-09', 9, 205, 4, -204.5, 'pengcheng', 'pengcheng', '彭城睢水', '夏四月，漢王入彭城，置酒高會。項羽自齊回擊，漢卒入睢水者十餘萬，水為之不流。陸遷匿於民家得免。', '[]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-10', 10, 204, 5, -203.41666666666666, 'xingyang', 'xingyang', '滎陽糧道', '五月在滎陽。楚圍急，紀信乘王車出東門詐降，漢王自西門出。城中粟石萬錢，售所藏粟。', '[{"item": "粟", "action": "售", "qty": "2石", "amount": "+20000錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-11', 11, 203, 9, -202.08333333333334, 'honggou', 'honggou', '鴻溝畫界', '九月，楚漢約中分天下，割鴻溝以西為漢，以東為楚。太公、呂后歸漢。兩軍罷，鴻溝渡口復通商。', '[{"item": "鹽", "action": "購", "qty": "10斗", "amount": "-500錢"}]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-12', 12, 202, 12, -201.83333333333334, 'gaixia', 'gaixia', '垓下楚歌', '十二月，垓下。夜聞漢軍四面皆楚歌，楚卒多亡去。陸遷自此南歸。', '[]'::jsonb);
INSERT INTO ledger_entries (id, seq, year_bce, month, sort_key, place_id, event_id, title, text, goods) VALUES ('lq-13', 13, 202, 2, -201.66666666666666, 'dingtao', 'emperor', '汜水稱帝', '二月甲午，漢王即皇帝位於汜水之陽。結賬：八年之中，往返數千里，所得不償所失，然身尚存。', '[]'::jsonb);
INSERT INTO yanyi_divergences (id, type, title, passage_id, event_id, yanyi, history, sources, author_note) VALUES ('qiji_meeting', 'invented', '彭城敗走途中得戚姬', 'yy-024-003', 'pengcheng', '漢王彭城敗後夜投戚姓老人家，老人以女相許，漢王解玉帶為聘。', '《史記》只說漢王時「得定陶戚姬」，未記相遇經過。', '[{"work": "史記", "juan": 9, "title": "呂太后本紀", "quote": "及高祖為漢王，得定陶戚姬，愛幸", "passage_id": null}]'::jsonb, '本回敘及戚姬，所以原人彘之禍，不沒陵母，所以揚彤幃之光，詳正史之所略');
INSERT INTO yanyi_divergences (id, type, title, passage_id, event_id, yanyi, history, sources, author_note) VALUES ('mingxiu_zhandao', 'altered', '明修棧道，暗渡陳倉', 'yy-022-002b', 'chencang', '張良定計，派兵數百人佯修棧道迷惑章邯，主力由故道出陳倉。', '《高祖本紀》說計出韓信，只言「從故道還」，無佯修棧道之事；《留侯世家》中張良只勸燒絕棧道。', '[{"work": "史記", "juan": 8, "title": "高祖本紀", "quote": "漢王用韓信之計，從故道還，襲雍王章邯", "passage_id": "sj-008-029"}, {"work": "史記", "juan": 55, "title": "留侯世家", "quote": "王何不燒絕所過棧道，示天下無還心", "passage_id": null}]'::jsonb, NULL);
INSERT INTO yanyi_divergences (id, type, title, passage_id, event_id, yanyi, history, sources, author_note) VALUES ('shimian_maifu', 'embellished', '十面埋伏', 'yy-031-003', 'gaixia', '韓信分兵十隊埋伏，自率三萬人誘項王入伏。', '《高祖本紀》記垓下陣法為韓信居中、孔將軍居左、費將軍居右，無十面埋伏。', '[{"work": "史記", "juan": 8, "title": "高祖本紀", "quote": "淮陰侯將三十萬自當之，孔將軍居左，費將軍居右", "passage_id": "sj-008-052"}]'::jsonb, '韓信之十面埋伏計，史策未詳，但相傳已久');
INSERT INTO yanyi_divergences (id, type, title, passage_id, event_id, yanyi, history, sources, author_note) VALUES ('zhangliang_chuge', 'embellished', '張良編楚歌', 'yy-031-006', 'gaixia', '四面楚歌為張良所編，教軍士在楚營旁唱和，致楚兵散去。', '《史記》只記漢軍四面皆楚歌，未說何人所作。', '[{"work": "史記", "juan": 7, "title": "項羽本紀", "quote": "夜聞漢軍四面皆楚歌", "passage_id": "sj-007-040"}]'::jsonb, NULL);
INSERT INTO yanyi_divergences (id, type, title, passage_id, event_id, yanyi, history, sources, author_note) VALUES ('yuji_death', 'invented', '虞姬和詩、自刎', 'yy-031-011', 'gaixia', '虞姬吟「漢兵已略地」詩，拔項王佩劍自刎，葬於定遠。', '《史記》只說「歌數闋，美人和之」，不錄和詩，也不載虞姬之死；和詩見《史記正義》引《楚漢春秋》（《困學紀聞》卷十二轉引）。', '[{"work": "史記", "juan": 7, "title": "項羽本紀", "quote": "歌數闋，美人和之", "passage_id": "sj-007-040"}]'::jsonb, NULL);
